import * as THREE from "three";

/**
 * A recurring frame source. The adapter owns the platform-specific scheduling
 * primitive while LearningPathFrameLoop owns when that source may run.
 */
export interface LearningPathFrameScheduler {
  start(callback: (timestamp?: number) => void): void;
  stop(): void;
}

/** Time source kept injectable so the loop can be verified without a DOM. */
export interface LearningPathFrameClock {
  reset(): void;
  update(timestamp?: number): number;
  dispose(): void;
}

export interface LearningPathFrame {
  readonly sequence: number;
  readonly timestamp?: number;
  readonly rawDeltaSeconds: number;
  readonly deltaSeconds: number;
  readonly elapsedSeconds: number;
}

/**
 * Deliberately explicit pipeline: its declaration is the authoritative render
 * order and prevents future integrations from interleaving business work.
 */
export interface LearningPathFrameSteps {
  readonly updateSimulation: (frame: LearningPathFrame) => void;
  readonly updateCamera: (frame: LearningPathFrame) => void;
  readonly updateCharacter: (frame: LearningPathFrame) => void;
  readonly publishVisualIdleEdge: (frame: LearningPathFrame) => void;
  readonly updatePathView: (frame: LearningPathFrame) => void;
  readonly updateRuntime: (frame: LearningPathFrame) => void;
  readonly updatePerformanceMeter: (frame: LearningPathFrame) => void;
  readonly renderScene: (frame: LearningPathFrame) => void;
  readonly afterRender?: (frame: LearningPathFrame) => void;
}

export interface LearningPathFrameLoopOptions {
  readonly scheduler: LearningPathFrameScheduler;
  readonly clock: LearningPathFrameClock;
  readonly steps: LearningPathFrameSteps;
  readonly maxDeltaSeconds?: number;
}

/**
 * Owns the session's recurring frame lifecycle. start/stop/dispose are
 * idempotent, and a stale scheduler callback cannot resurrect a stopped loop.
 */
export class LearningPathFrameLoop {
  readonly #scheduler: LearningPathFrameScheduler;
  readonly #clock: LearningPathFrameClock;
  readonly #steps: LearningPathFrameSteps;
  readonly #maxDeltaSeconds: number;
  #running = false;
  #disposed = false;
  #sequence = 0;
  #elapsedSeconds = 0;

  constructor(options: LearningPathFrameLoopOptions) {
    this.#scheduler = options.scheduler;
    this.#clock = options.clock;
    this.#steps = options.steps;
    this.#maxDeltaSeconds = Math.max(0, options.maxDeltaSeconds ?? 0.1);
  }

  get running(): boolean {
    return this.#running;
  }

  get disposed(): boolean {
    return this.#disposed;
  }

  start(): void {
    if (this.#disposed || this.#running) return;
    this.#running = true;
    this.#clock.reset();
    this.#scheduler.start(this.#onFrame);
  }

  stop(): void {
    if (!this.#running) return;
    this.#running = false;
    this.#scheduler.stop();
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    this.stop();
    this.#clock.dispose();
  }

  readonly #onFrame = (timestamp?: number): void => {
    if (!this.#running || this.#disposed) return;
    const rawDeltaSeconds = Math.max(0, this.#clock.update(timestamp));
    const deltaSeconds = Math.min(rawDeltaSeconds, this.#maxDeltaSeconds);
    this.#elapsedSeconds += deltaSeconds;
    const frame = Object.freeze({
      sequence: ++this.#sequence,
      ...(timestamp === undefined ? {} : { timestamp }),
      rawDeltaSeconds,
      deltaSeconds,
      elapsedSeconds: this.#elapsedSeconds,
    });

    this.#steps.updateSimulation(frame);
    this.#steps.updateCamera(frame);
    this.#steps.updateCharacter(frame);
    this.#steps.publishVisualIdleEdge(frame);
    this.#steps.updatePathView(frame);
    this.#steps.updateRuntime(frame);
    this.#steps.updatePerformanceMeter(frame);
    this.#steps.renderScene(frame);
    this.#steps.afterRender?.(frame);
  };
}

/** Preserve Three's animation-loop integration (including its XR semantics). */
export const createThreeRendererFrameScheduler = (
  renderer: Pick<THREE.WebGLRenderer, "setAnimationLoop">,
): LearningPathFrameScheduler => ({
  start: (callback) => renderer.setAnimationLoop(callback),
  stop: () => renderer.setAnimationLoop(null),
});

/** Adapter around THREE.Timer; no timing object leaks back into the session. */
export const createThreeTimerFrameClock = (
  document: Document,
): LearningPathFrameClock => {
  const timer = new THREE.Timer();
  timer.connect(document);
  return {
    reset: () => timer.reset(),
    update: (timestamp) => {
      timer.update(timestamp);
      return timer.getDelta();
    },
    dispose: () => timer.dispose(),
  };
};
