import type {
  CharacterAnimationPhase,
  CharacterRig,
} from "../render/objects/CharacterRig";
import type { CharacterMirrorEvent } from "../statecharts/objects/characterMirrorMachine";

export type CharacterAdapterEvent = CharacterMirrorEvent;

/**
 * Low-frequency observation adapter for CharacterRig.
 *
 * It does not own animation or movement and never places CharacterRig/Three
 * objects in XState context. Call frame() after the rig update; an event is
 * emitted only when the public phase or the true visual-idle bit changes.
 */
export class XStateCharacterAdapter {
  private readonly rig: CharacterRig;
  private readonly listeners = new Set<(event: CharacterAdapterEvent) => void>();
  private lastPhase: CharacterAnimationPhase | null = null;
  private lastVisuallyIdle: boolean | null = null;
  private sequence = 0;
  private disposed = false;

  public constructor(
    rig: CharacterRig,
    onEvent?: (event: CharacterAdapterEvent) => void,
  ) {
    this.rig = rig;
    if (onEvent) this.listeners.add(onEvent);
  }

  public subscribe(
    listener: (event: CharacterAdapterEvent) => void,
  ): () => void {
    if (this.disposed) {
      throw new Error("Cannot subscribe to a disposed XStateCharacterAdapter.");
    }
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public frame(): CharacterAdapterEvent | null {
    if (this.disposed) return null;
    const phase = this.rig.getAnimationPhase();
    const visuallyIdle = this.rig.isVisuallyIdle();
    if (
      phase === this.lastPhase
      && visuallyIdle === this.lastVisuallyIdle
    ) return null;
    this.lastPhase = phase;
    this.lastVisuallyIdle = visuallyIdle;
    const event: CharacterAdapterEvent = {
      type: "CHARACTER.PHASE",
      phase,
      visuallyIdle,
      sequence: this.nextSequence(),
    };
    this.emit(event);
    return event;
  }

  public reportFailure(error: unknown): CharacterAdapterEvent | null {
    if (this.disposed) return null;
    const message = error instanceof Error ? error.message : String(error);
    const event: CharacterAdapterEvent = {
      type: "CHARACTER.FAILED",
      error: message,
      sequence: this.nextSequence(),
    };
    this.emit(event);
    return event;
  }

  /** Stops observation; CharacterRig lifecycle remains owned by the caller. */
  public dispose(): CharacterAdapterEvent | null {
    if (this.disposed) return null;
    this.disposed = true;
    const event: CharacterAdapterEvent = {
      type: "CHARACTER.DISPOSED",
      sequence: this.nextSequence(),
    };
    this.emit(event);
    this.listeners.clear();
    return event;
  }

  public getLastObservedPhase(): CharacterAnimationPhase | null {
    return this.lastPhase;
  }

  private nextSequence(): number {
    this.sequence += 1;
    return this.sequence;
  }

  private emit(event: CharacterAdapterEvent): void {
    this.listeners.forEach((listener) => listener(event));
  }
}
