import * as THREE from "three";

export interface ScenePathNode {
  readonly position: {
    readonly x: number;
    readonly z: number;
  };
  readonly initiallyVisible?: boolean;
}

export interface SceneBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
  readonly spanX: number;
  readonly spanZ: number;
  readonly center: THREE.Vector3;
  readonly corners: readonly THREE.Vector3[];
  readonly radius: number;
}

export interface SceneBoundsOptions {
  readonly floorY: number;
  readonly topY: number;
  readonly minimumHorizontalMargin?: number;
  readonly proportionalHorizontalMargin?: number;
}

/**
 * Produces a camera-ready immutable envelope from session-owned path nodes.
 * No authored path data is read here, keeping the render adapter reusable for
 * every validated JSON learning-path document.
 */
export function createSceneBounds(
  nodes: readonly ScenePathNode[],
  options: SceneBoundsOptions,
): SceneBounds {
  if (nodes.length === 0) {
    throw new Error("Learning scene requires at least one path node.");
  }

  const minimumMargin = options.minimumHorizontalMargin ?? 1.35;
  const proportionalMargin = options.proportionalHorizontalMargin ?? 0.035;
  let minX = Infinity;
  let maxX = -Infinity;
  let minZ = Infinity;
  let maxZ = -Infinity;

  nodes.forEach((node, index) => {
    const { x, z } = node.position;
    if (!Number.isFinite(x) || !Number.isFinite(z)) {
      throw new Error(`Learning scene node at index ${index} has a non-finite position.`);
    }
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minZ = Math.min(minZ, z);
    maxZ = Math.max(maxZ, z);
  });

  const horizontalMargin = Math.max(
    minimumMargin,
    (maxX - minX) * proportionalMargin,
  );
  const depthMargin = Math.max(
    minimumMargin,
    (maxZ - minZ) * proportionalMargin,
  );
  minX -= horizontalMargin;
  maxX += horizontalMargin;
  minZ -= depthMargin;
  maxZ += depthMargin;

  const center = new THREE.Vector3(
    (minX + maxX) / 2,
    (options.floorY + options.topY) / 2,
    (minZ + maxZ) / 2,
  );
  const corners: THREE.Vector3[] = [];
  for (const x of [minX, maxX]) {
    for (const y of [options.floorY, options.topY]) {
      for (const z of [minZ, maxZ]) {
        corners.push(new THREE.Vector3(x, y, z));
      }
    }
  }

  return Object.freeze({
    minX,
    maxX,
    minZ,
    maxZ,
    spanX: maxX - minX,
    spanZ: maxZ - minZ,
    center,
    corners: Object.freeze(corners),
    radius: Math.max(...corners.map((corner) => corner.distanceTo(center))),
  });
}

