import type {
  EdgeId,
  LearningPathNode,
  NodeId,
} from "../config/pathData";

export type BasePathNode = NodeId | Pick<LearningPathNode, "id">;

/** Minimal authored-logical edge contract; no render geometry is required. */
export interface BasePathAuthoredEdge {
  readonly id: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
}

export interface BasePathRoute {
  /** Both endpoints are included. */
  readonly nodeIds: readonly NodeId[];
  /** One authored logical id per leg; special legs may need runtime resolution. */
  readonly edgeIds: readonly EdgeId[];
  /** Traversal-oriented logical legs, convenient for runtime-edge resolution. */
  readonly legs: readonly BasePathRouteLeg[];
  readonly hopCount: number;
}

export interface BasePathRouteLeg {
  readonly edgeId: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
}

interface BaseAdjacencyStep {
  readonly nodeId: NodeId;
  readonly edgeId: EdgeId;
}

/**
 * Stable, unweighted routing over the authored logical topology only.
 *
 * Callers deliberately pass the authored edge collection instead of a runtime
 * graph, so generated overpasses can never reduce hop-distance eligibility or
 * feed back into later bridge planning. Logical edges are traversed as
 * undirected connections even though their authored direction is preserved in
 * the returned edge ids.
 */
export class BasePathIndex {
  private readonly adjacencyByNodeId = new Map<NodeId, BaseAdjacencyStep[]>();

  public constructor(
    nodes: readonly BasePathNode[],
    authoredEdges: readonly BasePathAuthoredEdge[],
  ) {
    const nodeIds = new Set<NodeId>();
    nodes.forEach((node, index) => {
      const nodeId = typeof node === "string" ? node : node.id;
      if (nodeId.trim().length === 0 || nodeIds.has(nodeId)) {
        throw new Error(`Base path has an invalid or duplicate node at index ${index}.`);
      }
      nodeIds.add(nodeId);
      this.adjacencyByNodeId.set(nodeId, []);
    });

    const edgeIds = new Set<EdgeId>();
    const physicalPairs = new Set<string>();
    authoredEdges.forEach((edge, index) => {
      if (edge.id.trim().length === 0 || edgeIds.has(edge.id)) {
        throw new Error(`Base path has an invalid or duplicate edge at index ${index}.`);
      }
      if (!nodeIds.has(edge.fromNodeId) || !nodeIds.has(edge.toNodeId)) {
        throw new Error(`Base path edge "${edge.id}" references a missing endpoint.`);
      }
      if (edge.fromNodeId === edge.toNodeId) {
        throw new Error(`Base path edge "${edge.id}" is a self-loop.`);
      }

      const pairKey = makeUndirectedPairKey(edge.fromNodeId, edge.toNodeId);
      if (physicalPairs.has(pairKey)) {
        throw new Error(
          `Base path repeats the physical connection between `
          + `"${edge.fromNodeId}" and "${edge.toNodeId}".`,
        );
      }

      edgeIds.add(edge.id);
      physicalPairs.add(pairKey);
      this.adjacencyByNodeId.get(edge.fromNodeId)!.push({
        nodeId: edge.toNodeId,
        edgeId: edge.id,
      });
      this.adjacencyByNodeId.get(edge.toNodeId)!.push({
        nodeId: edge.fromNodeId,
        edgeId: edge.id,
      });
    });

    this.adjacencyByNodeId.forEach((steps) => {
      steps.sort((left, right) => {
        const nodeOrder = compareStableIdentifiers(left.nodeId, right.nodeId);
        return nodeOrder !== 0
          ? nodeOrder
          : compareStableIdentifiers(left.edgeId, right.edgeId);
      });
    });
  }

  public hasNode(nodeId: NodeId): boolean {
    return this.adjacencyByNodeId.has(nodeId);
  }

  /** Returns null when either node is unknown or no authored route exists. */
  public hopDistance(fromNodeId: NodeId, toNodeId: NodeId): number | null {
    return this.shortestRoute(fromNodeId, toNodeId)?.hopCount ?? null;
  }

  /**
   * Stable breadth-first route. Neighbour node id and then edge id break ties,
   * so input-array ordering cannot change which equally short route is chosen.
   */
  public shortestRoute(
    fromNodeId: NodeId,
    toNodeId: NodeId,
  ): BasePathRoute | null {
    if (!this.hasNode(fromNodeId) || !this.hasNode(toNodeId)) {
      return null;
    }
    if (fromNodeId === toNodeId) {
      return Object.freeze({
        nodeIds: Object.freeze([fromNodeId]),
        edgeIds: Object.freeze([]),
        legs: Object.freeze([]),
        hopCount: 0,
      });
    }

    const visited = new Set<NodeId>([fromNodeId]);
    const previousByNodeId = new Map<
      NodeId,
      { readonly nodeId: NodeId; readonly edgeId: EdgeId }
    >();
    const queue: NodeId[] = [fromNodeId];
    let readCursor = 0;

    while (readCursor < queue.length) {
      const nodeId = queue[readCursor++]!;
      for (const step of this.adjacencyByNodeId.get(nodeId)!) {
        if (visited.has(step.nodeId)) {
          continue;
        }
        visited.add(step.nodeId);
        previousByNodeId.set(step.nodeId, { nodeId, edgeId: step.edgeId });
        if (step.nodeId === toNodeId) {
          return buildRoute(fromNodeId, toNodeId, previousByNodeId);
        }
        queue.push(step.nodeId);
      }
    }

    return null;
  }
}

function buildRoute(
  fromNodeId: NodeId,
  toNodeId: NodeId,
  previousByNodeId: ReadonlyMap<
    NodeId,
    { readonly nodeId: NodeId; readonly edgeId: EdgeId }
  >,
): BasePathRoute {
  const reverseNodeIds: NodeId[] = [toNodeId];
  const reverseEdgeIds: EdgeId[] = [];
  let cursor = toNodeId;

  while (cursor !== fromNodeId) {
    const previous = previousByNodeId.get(cursor);
    if (!previous) {
      throw new Error("Base path predecessor chain is incomplete.");
    }
    reverseEdgeIds.push(previous.edgeId);
    reverseNodeIds.push(previous.nodeId);
    cursor = previous.nodeId;
  }

  reverseNodeIds.reverse();
  reverseEdgeIds.reverse();
  const legs = reverseEdgeIds.map((edgeId, index) => Object.freeze({
    edgeId,
    fromNodeId: reverseNodeIds[index]!,
    toNodeId: reverseNodeIds[index + 1]!,
  }));
  return Object.freeze({
    nodeIds: Object.freeze(reverseNodeIds),
    edgeIds: Object.freeze(reverseEdgeIds),
    legs: Object.freeze(legs),
    hopCount: reverseEdgeIds.length,
  });
}

function makeUndirectedPairKey(left: NodeId, right: NodeId): string {
  return left < right ? `${left}\u0000${right}` : `${right}\u0000${left}`;
}

function compareStableIdentifiers(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}
