export type LearningPathSemanticNodeColor = "green" | "brown" | "gray";

export interface LearningPathAccessibilityNode {
  readonly id: string;
  readonly label: string;
}

export interface LearningPathAccessibilityProjection {
  readonly currentNodeId: string;
  readonly isRunning: boolean;
  readonly targetNodeId: string | null;
  readonly queuedTargetNodeId: string | null;
  readonly getNodeColor: (nodeIndex: number) => LearningPathSemanticNodeColor;
}

export interface LearningPathAccessibilityAnnouncementPort<
  TNode extends LearningPathAccessibilityNode = LearningPathAccessibilityNode,
> {
  announceKeyboardSelection(node: TNode): void;
}

export interface LearningPathAccessibilityBridgeOptions<
  TNode extends LearningPathAccessibilityNode = LearningPathAccessibilityNode,
> {
  readonly nodes: readonly TNode[];
  readonly resolveNodeIndex: (nodeId: string) => number;
  readonly resolveOptionElement: (nodeId: string) => HTMLElement | null;
  readonly onInspectRequested: (nodeIndex: number) => void;
  readonly announcements: LearningPathAccessibilityAnnouncementPort<TNode>;
}

interface BoundSemanticOption<TNode extends LearningPathAccessibilityNode> {
  readonly node: TNode;
  readonly nodeIndex: number;
  readonly option: HTMLElement;
  readonly handleClick: EventListener;
  readonly handleKeyDown: EventListener;
}

const colorLabel = (color: LearningPathSemanticNodeColor): string => (
  color === "green" ? "绿色" : color === "brown" ? "知乎蓝" : "灰色"
);

/**
 * Owns the semantic node-option bindings and their low-frequency ARIA
 * projection. The bridge deliberately receives only serializable path data
 * and callbacks; Three.js, the orchestration actor and AppUI remain outside.
 */
export class LearningPathAccessibilityBridge<
  TNode extends LearningPathAccessibilityNode = LearningPathAccessibilityNode,
> {
  readonly #options: BoundSemanticOption<TNode>[] = [];
  readonly #optionByNodeIndex = new Map<number, BoundSemanticOption<TNode>>();
  readonly #announcements: LearningPathAccessibilityAnnouncementPort<TNode>;
  #disposed = false;

  constructor(options: LearningPathAccessibilityBridgeOptions<TNode>) {
    this.#announcements = options.announcements;

    for (const node of options.nodes) {
      const option = options.resolveOptionElement(node.id);
      const nodeIndex = options.resolveNodeIndex(node.id);
      if (!option || nodeIndex < 0) continue;

      const handleClick: EventListener = () => {
        if (!this.#disposed) options.onInspectRequested(nodeIndex);
      };
      const handleKeyDown: EventListener = (event) => {
        if (this.#disposed) return;
        const key = (event as KeyboardEvent).key;
        if (key !== "Enter" && key !== " ") return;
        event.preventDefault();
        // The hidden semantic option and the canvas keyboard adapter share the
        // same document. Keep one activation key from scheduling the same
        // journey twice as it bubbles out of the accessibility listbox.
        event.stopPropagation();
        options.onInspectRequested(nodeIndex);
      };

      option.addEventListener("click", handleClick);
      option.addEventListener("keydown", handleKeyDown);
      const binding = Object.freeze({
        node,
        nodeIndex,
        option,
        handleClick,
        handleKeyDown,
      });
      this.#options.push(binding);
      this.#optionByNodeIndex.set(nodeIndex, binding);
    }
  }

  get disposed(): boolean {
    return this.#disposed;
  }

  /** Mirrors the former Session projection without taking state ownership. */
  publish(projection: LearningPathAccessibilityProjection): void {
    if (this.#disposed) return;

    for (const binding of this.#options) {
      const { node, nodeIndex, option } = binding;
      const isCurrent = !projection.isRunning && projection.currentNodeId === node.id;
      const isTarget = projection.targetNodeId === node.id
        || projection.queuedTargetNodeId === node.id;
      option.textContent = [
        node.label,
        colorLabel(projection.getNodeColor(nodeIndex)),
        isCurrent ? "当前位置" : null,
        isTarget ? "目标位置" : null,
      ].filter(Boolean).join("，");
      if (isCurrent) option.setAttribute("aria-current", "step");
      else option.removeAttribute("aria-current");
    }
  }

  /** Keeps announcements behind an explicit port instead of reaching into DOM UI. */
  announceKeyboardSelection(nodeIndex: number): void {
    if (this.#disposed) return;
    const binding = this.#optionByNodeIndex.get(nodeIndex);
    if (binding) this.#announcements.announceKeyboardSelection(binding.node);
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    for (const binding of this.#options) {
      binding.option.removeEventListener("click", binding.handleClick);
      binding.option.removeEventListener("keydown", binding.handleKeyDown);
    }
    this.#options.length = 0;
    this.#optionByNodeIndex.clear();
  }
}
