export interface BoundedAxisInput {
  readonly contentMin: number;
  readonly contentMax: number;
  readonly viewportMinOffset: number;
  readonly viewportMaxOffset: number;
  readonly proposedTarget: number;
}

export interface BoundedAxisResult {
  readonly target: number;
  readonly minimumTarget: number;
  readonly maximumTarget: number;
  readonly pannable: boolean;
}

/**
 * Clamps one camera-target axis to an endpoint-readable range. Large maps may
 * move until either authored endpoint reaches the viewport's ground-centre,
 * instead of stopping with that endpoint glued to a screen edge. This leaves
 * room for the character and its node-centred contextual card. When the
 * viewport is wider than the content, the map starts centred but retains a
 * bounded inspection range. This keeps short sample routes draggable without
 * allowing the authored content to disappear completely off-screen.
 */
export function resolveBoundedCameraTargetAxis(
  input: BoundedAxisInput,
): BoundedAxisResult {
  const values = [
    input.contentMin,
    input.contentMax,
    input.viewportMinOffset,
    input.viewportMaxOffset,
    input.proposedTarget,
  ];
  if (!values.every(Number.isFinite) || input.contentMin > input.contentMax
    || input.viewportMinOffset > input.viewportMaxOffset) {
    throw new TypeError("Viewport pan bounds require finite, ordered values.");
  }

  const contentSpan = input.contentMax - input.contentMin;
  const viewportSpan = input.viewportMaxOffset - input.viewportMinOffset;
  const viewportCenterOffset = (input.viewportMinOffset + input.viewportMaxOffset) / 2;
  if (contentSpan <= viewportSpan) {
    const contentCenter = (input.contentMin + input.contentMax) / 2;
    const centeredTarget = contentCenter - viewportCenterOffset;
    const inspectionRange = Math.max(viewportSpan * 0.18, 1);
    const minimumTarget = centeredTarget - inspectionRange;
    const maximumTarget = centeredTarget + inspectionRange;
    return Object.freeze({
      target: Math.min(maximumTarget, Math.max(minimumTarget, input.proposedTarget)),
      minimumTarget,
      maximumTarget,
      pannable: true,
    });
  }

  const minimumTarget = input.contentMin - viewportCenterOffset;
  const maximumTarget = input.contentMax - viewportCenterOffset;

  return Object.freeze({
    target: Math.min(maximumTarget, Math.max(minimumTarget, input.proposedTarget)),
    minimumTarget,
    maximumTarget,
    pannable: maximumTarget - minimumTarget > 0.000_1,
  });
}
