import * as THREE from "three";
import {
  PathInputController,
  type PathInputOptions,
  type PathKeyboardCommand,
} from "../../../input/PathInputController";

export interface LearningPathInputNode {
  readonly id: string;
  readonly navigationOrder: number;
  readonly position: Readonly<{ x: number; z: number }>;
}

export interface LearningPathInputControllerPort {
  setEnabled(value: boolean): void;
  setKeyboardIndex(nodeIndex: number): void;
  dispose(): void;
}

export interface LearningPathInputAdapterOptions {
  readonly canvas: HTMLCanvasElement;
  readonly camera: THREE.Camera;
  readonly pickTargets: readonly THREE.Object3D[];
  readonly nodes: readonly LearningPathInputNode[];
  readonly authoredAdjacencyByIndex: readonly (readonly number[])[];
  readonly entryNodeId: string;
  readonly goalNodeId: string;
  readonly initialNodeIndex: number;
  readonly keyboardSurfaceY: number;
  readonly resolveNodeIndex: (object: THREE.Object3D | null) => number | null;
  readonly isNodeInspectable: (nodeIndex: number) => boolean;
  readonly inspectNode: (nodeIndex: number) => void;
  readonly onBackgroundActivated?: () => void;
  readonly panByScreenPixels: (deltaX: number, deltaY: number) => void;
  readonly renderScene: () => void;
  readonly setHoveredNode: (nodeIndex: number | null) => void;
  readonly setPressedNode: (nodeIndex: number | null) => void;
  readonly onNodeHovered?: (nodeId: string | null) => void;
  readonly onKeyboardSelection: (node: LearningPathInputNode, nodeIndex: number) => void;
  /** Test seam; production always uses PathInputController. */
  readonly createController?: (options: PathInputOptions) => LearningPathInputControllerPort;
}

/**
 * Owns browser input wiring for one Three.js learning-path session.
 *
 * The adapter deliberately exposes only lifecycle commands. Pointer picking,
 * keyboard navigation, hover/press projection and bounded camera-pan requests
 * stay behind this boundary instead of leaking PathInputController into the
 * application/session composition root.
 */
export class LearningPathInputAdapter implements LearningPathInputControllerPort {
  private readonly controller: LearningPathInputControllerPort;
  private disposed = false;

  public constructor(options: LearningPathInputAdapterOptions) {
    const nodeIndexById = new Map(
      options.nodes.map((node, nodeIndex) => [node.id, nodeIndex] as const),
    );
    const resolveKeyboardIndex = createKeyboardIndexResolver(options, nodeIndexById);
    const createController = options.createController
      ?? ((controllerOptions: PathInputOptions) => new PathInputController(controllerOptions));

    this.controller = createController({
      canvas: options.canvas,
      camera: options.camera,
      pickTargets: options.pickTargets,
      nodeCount: options.nodes.length,
      initialNodeIndex: options.initialNodeIndex,
      resolveNodeIndex: options.resolveNodeIndex,
      resolveKeyboardIndex,
      isNodeVisible: options.isNodeInspectable,
      onActivate: options.inspectNode,
      onBackgroundActivate: options.onBackgroundActivated,
      onPanByPixels: (deltaX, deltaY) => {
        options.panByScreenPixels(deltaX, deltaY);
        options.renderScene();
      },
      onHover: (nodeIndex) => {
        options.setHoveredNode(nodeIndex);
        options.onNodeHovered?.(
          nodeIndex === null ? null : options.nodes[nodeIndex]?.id ?? null,
        );
      },
      onPress: options.setPressedNode,
      onKeyboardSelection: (nodeIndex) => {
        const node = options.nodes[nodeIndex];
        if (node) options.onKeyboardSelection(node, nodeIndex);
      },
    });
  }

  public setEnabled(value: boolean): void {
    if (!this.disposed) this.controller.setEnabled(value);
  }

  public setKeyboardIndex(nodeIndex: number): void {
    if (!this.disposed) this.controller.setKeyboardIndex(nodeIndex);
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.controller.dispose();
  }
}

function createKeyboardIndexResolver(
  options: LearningPathInputAdapterOptions,
  nodeIndexById: ReadonlyMap<string, number>,
): (fromNodeIndex: number, command: PathKeyboardCommand) => number | null {
  const fromScreen = new THREE.Vector3();
  const candidateScreen = new THREE.Vector3();
  const direction = new THREE.Vector2();
  const desired = new THREE.Vector2();

  return (fromNodeIndex, command) => {
    if (command === "home" || command === "end") {
      const nodeId = command === "home" ? options.entryNodeId : options.goalNodeId;
      const index = nodeIndexById.get(nodeId) ?? -1;
      return index >= 0 && options.isNodeInspectable(index) ? index : null;
    }

    const fromNode = options.nodes[fromNodeIndex];
    if (!fromNode) return null;
    desired.set(
      command === "left" ? -1 : command === "right" ? 1 : 0,
      command === "up" ? 1 : command === "down" ? -1 : 0,
    );
    fromScreen
      .set(fromNode.position.x, options.keyboardSurfaceY, fromNode.position.z)
      .project(options.camera);

    let bestIndex: number | null = null;
    let bestScore = -Number.POSITIVE_INFINITY;
    for (const candidateIndex of options.authoredAdjacencyByIndex[fromNodeIndex] ?? []) {
      const candidate = options.nodes[candidateIndex];
      if (!candidate || !options.isNodeInspectable(candidateIndex)) continue;
      candidateScreen
        .set(candidate.position.x, options.keyboardSurfaceY, candidate.position.z)
        .project(options.camera);
      direction.set(
        candidateScreen.x - fromScreen.x,
        candidateScreen.y - fromScreen.y,
      );
      const distance = direction.length();
      if (distance <= 0.000_01) continue;
      direction.multiplyScalar(1 / distance);
      const directionalScore = direction.dot(desired);
      if (directionalScore <= 0.08) continue;
      const score = directionalScore * 1_000 - distance;
      const prior = bestIndex === null ? null : options.nodes[bestIndex];
      const winsTie = Math.abs(score - bestScore) <= 0.000_01
        && prior !== null
        && prior !== undefined
        && candidate.navigationOrder < prior.navigationOrder;
      if (score > bestScore + 0.000_01 || winsTie) {
        bestIndex = candidateIndex;
        bestScore = score;
      }
    }
    return bestIndex;
  };
}
