import type {
  CharacterPhase,
  LearningPathDebugSnapshot,
  NavigationPhase,
  ZoneSessionPhase,
} from "../domain/orchestrationTypes";
import {
  projectNavigation,
  selectNavigationIsBusy,
  selectNavigationPhase,
  type NavigationMachineSnapshot,
  type NavigationPhase as NavigationWorkflowPhase,
} from "../../workflows/navigation";
import {
  projectZoneSession,
  type ZoneSessionSnapshot,
  type ZoneSessionStateValue,
} from "../../workflows/zone-session";
import type { LearningPathMachineSnapshot } from "./machine";

function navigationChildSnapshot(
  snapshot: LearningPathMachineSnapshot,
): NavigationMachineSnapshot | null {
  const child = snapshot.children.navigationWorkflow?.getSnapshot();
  return isNavigationChildSnapshot(child) ? child : null;
}

function isNavigationChildSnapshot(
  snapshot: unknown,
): snapshot is NavigationMachineSnapshot {
  return typeof snapshot === "object"
    && snapshot !== null
    && "machine" in snapshot
    && typeof snapshot.machine === "object"
    && snapshot.machine !== null
    && "id" in snapshot.machine
    && snapshot.machine.id === "navigation-workflow";
}

function zoneChildSnapshot(
  snapshot: LearningPathMachineSnapshot,
): ZoneSessionSnapshot | null {
  const child = snapshot.children.zoneSessionWorkflow?.getSnapshot();
  return isZoneChildSnapshot(child) ? child : null;
}

function isZoneChildSnapshot(snapshot: unknown): snapshot is ZoneSessionSnapshot {
  return typeof snapshot === "object"
    && snapshot !== null
    && "machine" in snapshot
    && typeof snapshot.machine === "object"
    && snapshot.machine !== null
    && "id" in snapshot.machine
    && snapshot.machine.id === "zone-session";
}

export function isLearningPathNavigationIdle(
  snapshot: LearningPathMachineSnapshot,
): boolean {
  const navigation = navigationChildSnapshot(snapshot);
  return navigation !== null
    ? selectNavigationPhase(navigation) === "idle"
    : snapshot.context.navigationWorkflowPhase === "idle";
}

export function isLearningPathZoneTransitional(
  snapshot: LearningPathMachineSnapshot,
): boolean {
  const zone = zoneChildSnapshot(snapshot);
  return zone !== null
    ? projectZoneSession(zone).transitionActive
    : snapshot.context.zoneTransitionActive;
}

export function isLearningPathZoneInactive(
  snapshot: LearningPathMachineSnapshot,
): boolean {
  const zone = zoneChildSnapshot(snapshot);
  return zone !== null
    ? projectZoneSession(zone).phase === "inactive"
    : !snapshot.context.zoneInitiallyActive
      && !snapshot.context.zoneTransitionActive;
}

export function isLearningPathZoneActive(
  snapshot: LearningPathMachineSnapshot,
): boolean {
  const zone = zoneChildSnapshot(snapshot);
  return zone !== null
    ? projectZoneSession(zone).phase === "active"
    : snapshot.context.zoneInitiallyActive
      && !snapshot.context.zoneTransitionActive;
}

export function isLearningPathBusy(
  snapshot: LearningPathMachineSnapshot,
): boolean {
  const navigation = navigationChildSnapshot(snapshot);
  return (navigation !== null
      ? selectNavigationIsBusy(navigation)
      : snapshot.context.navigationWorkflowPhase !== "idle")
    || isLearningPathZoneTransitional(snapshot)
    || !snapshot.context.characterVisualIdle;
}

function publicNavigationPhase(
  phase: NavigationWorkflowPhase,
): NavigationPhase {
  if (phase === "awaiting-character-settle"
    || phase === "awaiting-linked-cleanup") {
    return "awaiting-settle";
  }
  if (phase === "failed") return "planning";
  return phase;
}

function publicZonePhase(phase: ZoneSessionStateValue): ZoneSessionPhase {
  if (phase === "inactive" || phase === "active") return phase;
  if (phase === "planningRevealFromInactive"
    || phase === "planningRevealFromActive") {
    return "planning-reveal";
  }
  if (phase === "selectingRevealBeforeAction"
    || phase === "revealBeforeBridge"
    || phase === "selectingRevealStep"
    || phase === "revealing") {
    return "revealing";
  }
  if (phase === "planningDismissFromInactive"
    || phase === "planningDismissFromActive") {
    return "planning-dismiss";
  }
  return "dismissing";
}

function publicCharacterPhase(
  snapshot: LearningPathMachineSnapshot,
): CharacterPhase {
  if (snapshot.hasTag("character-settling")) return "settling";
  if (snapshot.hasTag("character-moving")) {
    return snapshot.context.arrivedNodeId === null ? "running" : "settling";
  }
  return snapshot.context.characterVisualIdle ? "idle" : "running";
}

/** A stable, renderer-free snapshot projected from the real child actors. */
export function getLearningPathDebugSnapshot(
  snapshot: LearningPathMachineSnapshot,
): LearningPathDebugSnapshot {
  const context = snapshot.context;
  const navigationSnapshot = navigationChildSnapshot(snapshot);
  const zoneSnapshot = zoneChildSnapshot(snapshot);
  const navigation = navigationSnapshot
    ? projectNavigation(navigationSnapshot)
    : null;
  const zone = zoneSnapshot ? projectZoneSession(zoneSnapshot) : null;
  const command = navigation?.command ?? context.navigationWorkflowCommand;
  const commandToken = command
    ? command.type === "CHARACTER.FORCE_SETTLE"
      ? command.attemptId
      : command.token
    : null;
  return Object.freeze({
    stateValue: snapshot.value,
    health: Object.freeze({
      status: snapshot.matches("degraded")
        ? "degraded"
        : snapshot.matches("recovering") ? "recovering" : "live",
      error: context.fatalError,
    }),
    currentNodeId: navigation?.currentNodeId ?? context.currentNodeId,
    queuedTargetNodeId: navigation?.queuedTargetNodeId
      ?? context.pendingNavigationTargetNodeId,
    character: Object.freeze({
      phase: publicCharacterPhase(snapshot),
      visualIdle: navigation?.characterVisualIdle ?? context.characterVisualIdle,
      motionToken: context.motionCommandToken,
    }),
    navigation: Object.freeze({
      phase: publicNavigationPhase(
        navigation?.phase ?? context.navigationWorkflowPhase,
      ),
      planId: navigation?.planId ?? context.navigationPlan?.id ?? null,
      stageIndex: navigation?.stageIndex ?? context.navigationStageIndex,
      beforeActionIndex: navigation?.beforeActionIndex
        ?? context.navigationBeforeActionIndex,
      afterActionIndex: navigation?.afterActionIndex
        ?? context.navigationAfterActionIndex,
      commandToken,
      commandAttempt: command?.attempt ?? context.navigationCommandAttempt,
      linkedZoneCleanupComplete: navigation?.linkedCleanupComplete
        ?? context.linkedZoneCleanupComplete,
    }),
    zoneSession: Object.freeze({
      phase: publicZonePhase(zone?.phase ?? (
        context.zoneInitiallyActive ? "active" : "inactive"
      )),
      revealPlanId: zone?.revealPlan?.id ?? context.zoneRevealPlan?.id ?? null,
      revealStepIndex: zone?.revealStepIndex ?? context.zoneRevealStepIndex,
      dismissPlanId: zone?.dismissPlan?.id ?? context.zoneDismissPlan?.id ?? null,
      dismissStepIndex: zone?.dismissStepIndex ?? context.zoneDismissStepIndex,
      commandToken: zone?.revealCommandToken
        ?? zone?.dismissCommandToken
        ?? context.zoneRevealCommandToken
        ?? context.zoneDismissCommandToken,
      commandAttempt: zone?.revealCommandToken
        ? zone.revealCommandAttempt
        : zone?.dismissCommandAttempt ?? context.zoneDismissCommandAttempt,
    }),
    recovery: Object.freeze({
      active: snapshot.matches("recovering"),
      request: context.recoveryRequest,
      lastComplete: context.lastRecovery,
    }),
  });
}
