import type {
  EdgeId,
  LearningPathEdge,
  LearningPathGraph,
  LearningPathNode,
  NodeId,
  PathKind,
  PathPosition,
} from "../config/pathData";
import {
  NODE_PATH_SURFACE_Y,
  PathGeometryRegistry,
} from "./PathGeometryRegistry";

export interface ActivePathLegSnapshot {
  readonly edgeId: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly progress: number;
  readonly length: number;
  readonly surfaceY: number;
  /** Signed deck pitch in the current direction of travel. */
  readonly surfacePitchRadians: number;
  readonly pathKind: PathKind;
}

export interface PathSimulationSnapshot {
  /** Last graph node crossed; while idle this is the occupied node. */
  readonly currentNodeId: NodeId;
  /** The user-selected final destination, never an intermediate merge node. */
  readonly targetNodeId: NodeId | null;
  readonly isRunning: boolean;
  readonly activeLeg: ActivePathLegSnapshot | null;
  /** Includes both endpoints of the active leg while running. */
  readonly remainingRouteNodeIds: readonly NodeId[];
  /** Starts with the active edge while running. */
  readonly remainingRouteEdgeIds: readonly EdgeId[];
  readonly position: PathPosition;
  readonly facing: PathPosition;
  /** Current sampled support surface; remains node height while idle. */
  readonly surfaceY: number;
  /** Signed support pitch in the current direction of travel; zero while idle. */
  readonly surfacePitchRadians: number;
  /** Null while occupying a node, otherwise the active edge geometry kind. */
  readonly pathKind: PathKind | null;
  /** Changes whenever a route is started, redirected, or teleported. */
  readonly routeRevision: number;
}

export interface ArrivalEvent {
  readonly nodeId: NodeId;
  /** Correlates the arrival with the exact explicit route that produced it. */
  readonly routeRevision: number;
}

/** Emitted when a continuous route crosses an intermediate platform. */
export interface NodeTraversedEvent {
  readonly nodeId: NodeId;
  readonly routeRevision: number;
}

export type TargetRequestResult =
  | {
    readonly accepted: true;
    readonly status: "started" | "retargeted" | "already-there";
    readonly routeNodeIds: readonly NodeId[];
  }
  | {
    readonly accepted: false;
    readonly reason: "unknown-node" | "unreachable";
  };

export interface ExplicitRouteRequest {
  readonly targetNodeId: NodeId;
  /** Must start at the occupied node and end at targetNodeId. */
  readonly nodeIds: readonly NodeId[];
  /** One runtime graph edge id for every consecutive node pair. */
  readonly edgeIds: readonly EdgeId[];
}

export type ExplicitRouteRequestResult =
  | {
    readonly accepted: true;
    readonly status: "started" | "already-there";
    readonly routeNodeIds: readonly NodeId[];
    readonly routeEdgeIds: readonly EdgeId[];
  }
  | {
    readonly accepted: false;
    readonly reason: "busy" | "unknown-node" | "unknown-edge" | "invalid-route";
    readonly message: string;
  };

type ArrivalListener = (event: ArrivalEvent) => void;
type NodeTraversedListener = (event: NodeTraversedEvent) => void;

interface RuntimeEdge {
  readonly source: LearningPathEdge;
  readonly fromNodeIndex: number;
  readonly toNodeIndex: number;
  readonly length: number;
  readonly routingCost: number;
}

interface AdjacencyStep {
  readonly nodeIndex: number;
  readonly edgeIndex: number;
  readonly length: number;
  readonly routingCost: number;
}

interface ShortestPathResult {
  readonly nodeIndices: number[];
  readonly edgeIndices: number[];
  readonly distance: number;
}

const DISTANCE_EPSILON = 0.000_01;
const COST_EPSILON = 0.000_000_1;
const MAX_DELTA_SECONDS = 0.1;

function createPhysicalPairKey(firstNodeId: NodeId, secondNodeId: NodeId): string {
  return firstNodeId < secondNodeId
    ? `${firstNodeId}\u0000${secondNodeId}`
    : `${secondNodeId}\u0000${firstNodeId}`;
}

function areEquivalentEdges(
  first: LearningPathEdge,
  second: LearningPathEdge,
): boolean {
  return first.pathKind === second.pathKind
    && first.fromNodeId === second.fromNodeId
    && first.toNodeId === second.toNodeId
    && JSON.stringify(first) === JSON.stringify(second);
}

/**
 * Pure graph traversal state. Authored ordinary edges retain directed learning-
 * progression semantics; generated overpasses are navigation overlays. Actual
 * movement treats every installed edge as an undirected physical connection.
 *
 * Route finding and snapshot publication may allocate. The frame update loop
 * only mutates scalar state, so animation remains allocation-free in steady
 * state.
 */
export class PathSimulation {
  public readonly geometryRegistry: PathGeometryRegistry;

  private readonly nodes: readonly LearningPathNode[];
  private readonly nodeIndexById = new Map<NodeId, number>();
  private readonly edgeIndexById = new Map<EdgeId, number>();
  private readonly physicalPairKeys = new Set<string>();
  private readonly runtimeEdges: RuntimeEdge[] = [];
  private readonly adjacency: AdjacencyStep[][];
  private readonly nodeTieRanks: Int32Array;
  private readonly speed: number;

  private currentNodeIndex: number;
  private targetNodeIndex: number | null = null;
  private isRunning = false;

  private readonly routeNodeIndices: number[] = [];
  private readonly routeEdgeIndices: number[] = [];
  private routeCursor = 0;
  private edgeProgress = 0;
  private routeRevision = 0;

  private positionX: number;
  private positionZ: number;
  private surfaceY = NODE_PATH_SURFACE_Y;
  private surfacePitchRadians = 0;
  private activePathKind: PathKind | null = null;
  private facingX = 0;
  private facingZ = -1;

  private readonly arrivalListeners = new Set<ArrivalListener>();
  private readonly nodeTraversedListeners = new Set<NodeTraversedListener>();

  public constructor(
    graph: LearningPathGraph,
    speed = 13.25,
    geometryRegistry = new PathGeometryRegistry(graph),
  ) {
    if (!Number.isFinite(speed) || speed <= 0) {
      throw new Error("PathSimulation speed must be a positive finite number.");
    }

    this.nodes = graph.nodes;
    this.speed = speed;
    this.geometryRegistry = geometryRegistry;
    this.adjacency = graph.nodes.map(() => []);
    this.nodeTieRanks = new Int32Array(graph.nodes.length);

    this.validateAndBuildGraph(graph);

    const initialNodeIndex = this.nodeIndexById.get(graph.initialNodeId);
    if (initialNodeIndex === undefined) {
      throw new Error(`Initial node "${graph.initialNodeId}" does not exist.`);
    }

    this.currentNodeIndex = initialNodeIndex;
    const initialPosition = this.nodes[initialNodeIndex]!.position;
    this.positionX = initialPosition.x;
    this.positionZ = initialPosition.z;
    this.surfaceY = this.nodes[initialNodeIndex]!.surfaceY;

    const firstNeighbour = this.adjacency[initialNodeIndex]?.[0];
    if (firstNeighbour) {
      this.setFacingToward(this.nodes[firstNeighbour.nodeIndex]!.position);
    }
  }

  public requestTarget(nodeId: NodeId): TargetRequestResult {
    const requestedNodeIndex = this.nodeIndexById.get(nodeId);
    if (requestedNodeIndex === undefined) {
      return { accepted: false, reason: "unknown-node" };
    }

    if (!this.isRunning) {
      if (requestedNodeIndex === this.currentNodeIndex) {
        return {
          accepted: true,
          status: "already-there",
          routeNodeIds: [nodeId],
        };
      }

      const path = this.findShortestPath(this.currentNodeIndex, requestedNodeIndex);
      if (!path) {
        return { accepted: false, reason: "unreachable" };
      }

      this.installRoute(path.nodeIndices, path.edgeIndices, 0);
      this.targetNodeIndex = requestedNodeIndex;
      this.isRunning = true;
      this.routeRevision += 1;
      this.refreshPositionAndFacing();

      return {
        accepted: true,
        status: "started",
        routeNodeIds: this.routeNodeIndices.map((index) => this.nodes[index]!.id),
      };
    }

    const activeEdgeIndex = this.routeEdgeIndices[this.routeCursor];
    const activeFromNodeIndex = this.routeNodeIndices[this.routeCursor];
    const activeToNodeIndex = this.routeNodeIndices[this.routeCursor + 1];
    const activeEdge = activeEdgeIndex === undefined
      ? undefined
      : this.runtimeEdges[activeEdgeIndex];

    if (
      activeEdgeIndex === undefined
      || activeFromNodeIndex === undefined
      || activeToNodeIndex === undefined
      || !activeEdge
    ) {
      return { accepted: false, reason: "unreachable" };
    }

    const viaFromPath = this.findShortestPath(
      activeFromNodeIndex,
      requestedNodeIndex,
    );
    const viaToPath = this.findShortestPath(
      activeToNodeIndex,
      requestedNodeIndex,
    );

    if (!viaFromPath && !viaToPath) {
      return { accepted: false, reason: "unreachable" };
    }

    const viaFromCost = viaFromPath
      ? this.edgeProgress * activeEdge.length + viaFromPath.distance
      : Number.POSITIVE_INFINITY;
    const viaToCost = viaToPath
      ? (1 - this.edgeProgress) * activeEdge.length + viaToPath.distance
      : Number.POSITIVE_INFINITY;

    // A tie deliberately keeps the current direction, avoiding a visible
    // hesitation when both endpoints offer an equally short route.
    const reverseCurrentLeg = viaFromCost + COST_EPSILON < viaToCost;
    const endpointPath = reverseCurrentLeg ? viaFromPath : viaToPath;
    if (!endpointPath) {
      return { accepted: false, reason: "unreachable" };
    }

    const currentProgress = this.edgeProgress;
    const routeNodes = reverseCurrentLeg
      ? [activeToNodeIndex, activeFromNodeIndex, ...endpointPath.nodeIndices.slice(1)]
      : [activeFromNodeIndex, activeToNodeIndex, ...endpointPath.nodeIndices.slice(1)];
    const routeEdges = [activeEdgeIndex, ...endpointPath.edgeIndices];

    // Reversing the leg while converting p -> 1-p retains the exact same
    // world-space position on the undirected segment.
    this.installRoute(
      routeNodes,
      routeEdges,
      reverseCurrentLeg ? 1 - currentProgress : currentProgress,
    );
    this.targetNodeIndex = requestedNodeIndex;
    this.isRunning = true;
    this.routeRevision += 1;
    this.refreshPositionAndFacing();

    return {
      accepted: true,
      status: "retargeted",
      routeNodeIds: this.routeNodeIndices.map((index) => this.nodes[index]!.id),
    };
  }

  /**
   * Installs one lazily materialised edge into geometry, route lookup and both
   * endpoint adjacency lists. Re-registering an equivalent edge is a no-op.
   */
  public registerEdge(edge: LearningPathEdge): boolean {
    const existingIndex = this.edgeIndexById.get(edge.id);
    if (existingIndex !== undefined) {
      const existing = this.runtimeEdges[existingIndex]?.source;
      if (existing === edge || (existing && areEquivalentEdges(existing, edge))) {
        return false;
      }
      throw new Error(`PathSimulation edge id "${edge.id}" is already registered.`);
    }
    this.validateRuntimeEdgeIdentity(edge);
    const pairKey = createPhysicalPairKey(edge.fromNodeId, edge.toNodeId);
    if (this.physicalPairKeys.has(pairKey)) {
      throw new Error(
        `Duplicate physical edge between "${edge.fromNodeId}" and "${edge.toNodeId}".`,
      );
    }
    this.geometryRegistry.registerEdge(edge);
    this.installRuntimeEdge(edge);
    this.sortAdjacencyForNode(edge.fromNodeId);
    this.sortAdjacencyForNode(edge.toNodeId);
    return true;
  }

  /**
   * Starts an exact caller-authored route while idle. Unlike requestTarget(),
   * this does no route finding, so a policy layer can deliberately combine
   * ordinary roads and any number of generated overpasses in either direction.
   */
  public requestRoute(request: ExplicitRouteRequest): ExplicitRouteRequestResult {
    if (this.isRunning) {
      return {
        accepted: false,
        reason: "busy",
        message: "An explicit route can only be installed while the character is idle.",
      };
    }

    const targetNodeIndex = this.nodeIndexById.get(request.targetNodeId);
    if (targetNodeIndex === undefined) {
      return {
        accepted: false,
        reason: "unknown-node",
        message: `Explicit route target "${request.targetNodeId}" does not exist.`,
      };
    }
    if (request.nodeIds.length === 0) {
      return {
        accepted: false,
        reason: "invalid-route",
        message: "An explicit route must contain at least the occupied node.",
      };
    }

    const currentNodeId = this.nodes[this.currentNodeIndex]!.id;
    if (request.nodeIds[0] !== currentNodeId) {
      return {
        accepted: false,
        reason: "invalid-route",
        message: `Explicit route must start at occupied node "${currentNodeId}".`,
      };
    }
    if (request.nodeIds[request.nodeIds.length - 1] !== request.targetNodeId) {
      return {
        accepted: false,
        reason: "invalid-route",
        message: `Explicit route must end at target "${request.targetNodeId}".`,
      };
    }
    if (request.nodeIds.length !== request.edgeIds.length + 1) {
      return {
        accepted: false,
        reason: "invalid-route",
        message: "Explicit route must contain exactly one edge per consecutive node pair.",
      };
    }

    if (request.edgeIds.length === 0) {
      if (targetNodeIndex !== this.currentNodeIndex) {
        return {
          accepted: false,
          reason: "invalid-route",
          message: "A zero-leg explicit route can only target the occupied node.",
        };
      }
      return {
        accepted: true,
        status: "already-there",
        routeNodeIds: Object.freeze([currentNodeId]),
        routeEdgeIds: Object.freeze([]),
      };
    }

    const nodeIndices: number[] = [];
    for (const nodeId of request.nodeIds) {
      const nodeIndex = this.nodeIndexById.get(nodeId);
      if (nodeIndex === undefined) {
        return {
          accepted: false,
          reason: "unknown-node",
          message: `Explicit route node "${nodeId}" does not exist.`,
        };
      }
      nodeIndices.push(nodeIndex);
    }

    const edgeIndices: number[] = [];
    for (let legIndex = 0; legIndex < request.edgeIds.length; legIndex += 1) {
      const edgeId = request.edgeIds[legIndex]!;
      const edgeIndex = this.edgeIndexById.get(edgeId);
      if (edgeIndex === undefined) {
        return {
          accepted: false,
          reason: "unknown-edge",
          message: `Explicit route edge "${edgeId}" does not exist.`,
        };
      }

      const fromNodeIndex = nodeIndices[legIndex]!;
      const toNodeIndex = nodeIndices[legIndex + 1]!;
      const edge = this.runtimeEdges[edgeIndex]!;
      const connectsLeg = (
        edge.fromNodeIndex === fromNodeIndex
        && edge.toNodeIndex === toNodeIndex
      ) || (
        edge.fromNodeIndex === toNodeIndex
        && edge.toNodeIndex === fromNodeIndex
      );
      if (!connectsLeg) {
        return {
          accepted: false,
          reason: "invalid-route",
          message: `Explicit route edge "${edgeId}" does not connect `
            + `"${request.nodeIds[legIndex]}" and "${request.nodeIds[legIndex + 1]}".`,
        };
      }
      edgeIndices.push(edgeIndex);
    }

    this.installRoute(nodeIndices, edgeIndices, 0);
    this.targetNodeIndex = targetNodeIndex;
    this.isRunning = true;
    this.routeRevision += 1;
    this.refreshPositionAndFacing();

    return {
      accepted: true,
      status: "started",
      routeNodeIds: Object.freeze([...request.nodeIds]),
      routeEdgeIds: Object.freeze([...request.edgeIds]),
    };
  }

  public moveImmediatelyTo(nodeId: NodeId): boolean {
    const nodeIndex = this.nodeIndexById.get(nodeId);
    if (nodeIndex === undefined) {
      return false;
    }

    const targetPosition = this.nodes[nodeIndex]!.position;
    this.setFacingToward(targetPosition);
    this.surfaceY = this.nodes[nodeIndex]!.surfaceY;
    this.routeRevision += 1;
    this.finishAt(nodeIndex);
    return true;
  }

  /**
   * Cancels an in-flight route at a confirmed safe node without publishing a
   * normal arrival. The revision bump invalidates every delayed route event.
   */
  public abortToNode(nodeId: NodeId): boolean {
    const nodeIndex = this.nodeIndexById.get(nodeId);
    if (nodeIndex === undefined) return false;
    const node = this.nodes[nodeIndex]!;
    this.routeRevision += 1;
    this.currentNodeIndex = nodeIndex;
    this.targetNodeIndex = null;
    this.isRunning = false;
    this.positionX = node.position.x;
    this.positionZ = node.position.z;
    this.surfaceY = node.surfaceY;
    this.surfacePitchRadians = 0;
    this.activePathKind = null;
    this.routeNodeIndices.length = 0;
    this.routeEdgeIndices.length = 0;
    this.routeCursor = 0;
    this.edgeProgress = 0;
    return true;
  }

  public update(deltaSeconds: number): void {
    if (
      !this.isRunning
      || this.targetNodeIndex === null
      || !Number.isFinite(deltaSeconds)
      || deltaSeconds <= 0
    ) {
      return;
    }

    let travelBudget = Math.min(deltaSeconds, MAX_DELTA_SECONDS) * this.speed;

    while (travelBudget > 0 && this.isRunning) {
      const edgeIndex = this.routeEdgeIndices[this.routeCursor];
      const toNodeIndex = this.routeNodeIndices[this.routeCursor + 1];
      const edge = edgeIndex === undefined ? undefined : this.runtimeEdges[edgeIndex];

      if (edgeIndex === undefined || toNodeIndex === undefined || !edge) {
        throw new Error("PathSimulation encountered an invalid active route leg.");
      }

      const distanceRemaining = Math.max(0, (1 - this.edgeProgress) * edge.length);
      if (travelBudget + DISTANCE_EPSILON < distanceRemaining) {
        this.edgeProgress += travelBudget / edge.length;
        travelBudget = 0;
        break;
      }

      this.edgeProgress = 1;
      // Publish the exact curve endpoint before clearing the route. This keeps
      // high-level bridge arrivals at bridge height and ground arrivals at the
      // normal node surface without an end-frame snap.
      this.refreshPositionAndFacing();
      travelBudget = Math.max(0, travelBudget - distanceRemaining);
      this.currentNodeIndex = toNodeIndex;

      const reachedFinalTarget = toNodeIndex === this.targetNodeIndex
        && this.routeCursor === this.routeEdgeIndices.length - 1;
      if (reachedFinalTarget) {
        this.finishAt(toNodeIndex);
        return;
      }

      const traversedEvent: NodeTraversedEvent = {
        nodeId: this.nodes[toNodeIndex]!.id,
        routeRevision: this.routeRevision,
      };
      this.nodeTraversedListeners.forEach((listener) => listener(traversedEvent));

      this.routeCursor += 1;
      this.edgeProgress = 0;
    }

    this.refreshPositionAndFacing();
  }

  public onArrival(listener: ArrivalListener): () => void {
    this.arrivalListeners.add(listener);
    return () => this.arrivalListeners.delete(listener);
  }

  public onNodeTraversed(listener: NodeTraversedListener): () => void {
    this.nodeTraversedListeners.add(listener);
    return () => this.nodeTraversedListeners.delete(listener);
  }

  public getSnapshot(): PathSimulationSnapshot {
    const activeLeg = this.getActiveLegSnapshot();
    const remainingRouteNodeIds: NodeId[] = [];
    const remainingRouteEdgeIds: EdgeId[] = [];

    if (this.isRunning) {
      for (
        let index = this.routeCursor;
        index < this.routeNodeIndices.length;
        index += 1
      ) {
        remainingRouteNodeIds.push(this.nodes[this.routeNodeIndices[index]!]!.id);
      }
      for (
        let index = this.routeCursor;
        index < this.routeEdgeIndices.length;
        index += 1
      ) {
        remainingRouteEdgeIds.push(
          this.runtimeEdges[this.routeEdgeIndices[index]!]!.source.id,
        );
      }
    }

    return {
      currentNodeId: this.nodes[this.currentNodeIndex]!.id,
      targetNodeId: this.targetNodeIndex === null
        ? null
        : this.nodes[this.targetNodeIndex]!.id,
      isRunning: this.isRunning,
      activeLeg,
      remainingRouteNodeIds,
      remainingRouteEdgeIds,
      position: { x: this.positionX, z: this.positionZ },
      facing: { x: this.facingX, z: this.facingZ },
      surfaceY: this.surfaceY,
      surfacePitchRadians: this.surfacePitchRadians,
      pathKind: this.activePathKind,
      routeRevision: this.routeRevision,
    };
  }

  private installRoute(
    nodeIndices: readonly number[],
    edgeIndices: readonly number[],
    initialProgress: number,
  ): void {
    if (nodeIndices.length !== edgeIndices.length + 1 || edgeIndices.length === 0) {
      throw new Error("A moving route must contain one more node than edge.");
    }

    this.routeNodeIndices.length = 0;
    this.routeEdgeIndices.length = 0;
    this.routeNodeIndices.push(...nodeIndices);
    this.routeEdgeIndices.push(...edgeIndices);
    this.routeCursor = 0;
    this.edgeProgress = Math.max(0, Math.min(1, initialProgress));
  }

  private refreshPositionAndFacing(): void {
    if (!this.isRunning) {
      return;
    }

    const fromNodeIndex = this.routeNodeIndices[this.routeCursor];
    const toNodeIndex = this.routeNodeIndices[this.routeCursor + 1];
    if (fromNodeIndex === undefined || toNodeIndex === undefined) {
      return;
    }

    const edgeIndex = this.routeEdgeIndices[this.routeCursor];
    if (edgeIndex === undefined) {
      return;
    }
    const edge = this.runtimeEdges[edgeIndex]!;
    const sample = this.geometryRegistry.sampleRoute(
      edge.source.id,
      this.nodes[fromNodeIndex]!.id,
      this.edgeProgress,
    );
    this.positionX = sample.position.x;
    this.positionZ = sample.position.z;
    this.surfaceY = sample.surfaceY;
    this.surfacePitchRadians = Math.atan2(
      sample.tangent.y,
      Math.hypot(sample.tangent.x, sample.tangent.z),
    );
    this.activePathKind = sample.pathKind;

    const horizontalTangentLength = Math.hypot(sample.tangent.x, sample.tangent.z);
    if (horizontalTangentLength > DISTANCE_EPSILON) {
      this.facingX = sample.tangent.x / horizontalTangentLength;
      this.facingZ = sample.tangent.z / horizontalTangentLength;
    }
  }

  private setFacingToward(target: PathPosition): void {
    const dx = target.x - this.positionX;
    const dz = target.z - this.positionZ;
    const length = Math.hypot(dx, dz);
    if (length > DISTANCE_EPSILON) {
      this.facingX = dx / length;
      this.facingZ = dz / length;
    }
  }

  private finishAt(nodeIndex: number): void {
    const didMove = this.isRunning || this.currentNodeIndex !== nodeIndex;
    const node = this.nodes[nodeIndex]!;

    this.currentNodeIndex = nodeIndex;
    this.targetNodeIndex = null;
    this.isRunning = false;
    this.positionX = node.position.x;
    this.positionZ = node.position.z;
    // Preserve the exact sampled arrival surface. `moveImmediatelyTo()` sets
    // this from node data before entering here.
    this.surfacePitchRadians = 0;
    this.activePathKind = null;
    this.routeNodeIndices.length = 0;
    this.routeEdgeIndices.length = 0;
    this.routeCursor = 0;
    this.edgeProgress = 0;

    if (didMove) {
      const event: ArrivalEvent = {
        nodeId: node.id,
        routeRevision: this.routeRevision,
      };
      this.arrivalListeners.forEach((listener) => listener(event));
    }
  }

  private getActiveLegSnapshot(): ActivePathLegSnapshot | null {
    if (!this.isRunning) {
      return null;
    }

    const edgeIndex = this.routeEdgeIndices[this.routeCursor];
    const fromNodeIndex = this.routeNodeIndices[this.routeCursor];
    const toNodeIndex = this.routeNodeIndices[this.routeCursor + 1];
    if (
      edgeIndex === undefined
      || fromNodeIndex === undefined
      || toNodeIndex === undefined
    ) {
      return null;
    }

    const edge = this.runtimeEdges[edgeIndex]!;
    const sample = this.geometryRegistry.sampleRoute(
      edge.source.id,
      this.nodes[fromNodeIndex]!.id,
      this.edgeProgress,
    );
    return {
      edgeId: edge.source.id,
      fromNodeId: this.nodes[fromNodeIndex]!.id,
      toNodeId: this.nodes[toNodeIndex]!.id,
      progress: this.edgeProgress,
      length: edge.length,
      surfaceY: sample.surfaceY,
      surfacePitchRadians: Math.atan2(
        sample.tangent.y,
        Math.hypot(sample.tangent.x, sample.tangent.z),
      ),
      pathKind: sample.pathKind,
    };
  }

  private findShortestPath(
    sourceNodeIndex: number,
    targetNodeIndex: number,
  ): ShortestPathResult | null {
    if (sourceNodeIndex === targetNodeIndex) {
      return {
        nodeIndices: [sourceNodeIndex],
        edgeIndices: [],
        distance: 0,
      };
    }

    const nodeCount = this.nodes.length;
    const distances = new Float64Array(nodeCount);
    const visited = new Uint8Array(nodeCount);
    const previousNodes = new Int32Array(nodeCount);
    const previousEdges = new Int32Array(nodeCount);
    distances.fill(Number.POSITIVE_INFINITY);
    previousNodes.fill(-1);
    previousEdges.fill(-1);
    distances[sourceNodeIndex] = 0;

    for (let visitCount = 0; visitCount < nodeCount; visitCount += 1) {
      let nearestNodeIndex = -1;
      let nearestDistance = Number.POSITIVE_INFINITY;

      for (let nodeIndex = 0; nodeIndex < nodeCount; nodeIndex += 1) {
        if (visited[nodeIndex] === 1) {
          continue;
        }

        const distance = distances[nodeIndex]!;
        const isCloser = distance + COST_EPSILON < nearestDistance;
        const isDeterministicTie = Math.abs(distance - nearestDistance) <= COST_EPSILON
          && nearestNodeIndex >= 0
          && this.nodeTieRanks[nodeIndex]! < this.nodeTieRanks[nearestNodeIndex]!;
        if (isCloser || isDeterministicTie) {
          nearestNodeIndex = nodeIndex;
          nearestDistance = distance;
        }
      }

      if (nearestNodeIndex < 0 || !Number.isFinite(nearestDistance)) {
        break;
      }
      if (nearestNodeIndex === targetNodeIndex) {
        break;
      }

      visited[nearestNodeIndex] = 1;
      const neighbours = this.adjacency[nearestNodeIndex]!;
      for (let index = 0; index < neighbours.length; index += 1) {
        const step = neighbours[index]!;
        if (visited[step.nodeIndex] === 1) {
          continue;
        }

        const candidateDistance = nearestDistance + step.routingCost;
        const knownDistance = distances[step.nodeIndex]!;
        const candidateWins = candidateDistance + COST_EPSILON < knownDistance;
        const existingPredecessor = previousNodes[step.nodeIndex]!;
        const candidateWinsTie = Math.abs(candidateDistance - knownDistance) <= COST_EPSILON
          && (
            existingPredecessor < 0
            || this.nodeTieRanks[nearestNodeIndex]!
              < this.nodeTieRanks[existingPredecessor]!
            || (
              this.nodeTieRanks[nearestNodeIndex]
                === this.nodeTieRanks[existingPredecessor]
              && this.runtimeEdges[step.edgeIndex]!.source.id
                < this.runtimeEdges[previousEdges[step.nodeIndex]!]!.source.id
            )
          );

        if (candidateWins || candidateWinsTie) {
          distances[step.nodeIndex] = candidateDistance;
          previousNodes[step.nodeIndex] = nearestNodeIndex;
          previousEdges[step.nodeIndex] = step.edgeIndex;
        }
      }
    }

    if (!Number.isFinite(distances[targetNodeIndex]!)) {
      return null;
    }

    const reverseNodes: number[] = [targetNodeIndex];
    const reverseEdges: number[] = [];
    let cursor = targetNodeIndex;
    while (cursor !== sourceNodeIndex) {
      const previousNode = previousNodes[cursor]!;
      const previousEdge = previousEdges[cursor]!;
      if (previousNode < 0 || previousEdge < 0) {
        return null;
      }
      reverseEdges.push(previousEdge);
      reverseNodes.push(previousNode);
      cursor = previousNode;
    }

    reverseNodes.reverse();
    reverseEdges.reverse();
    return {
      nodeIndices: reverseNodes,
      edgeIndices: reverseEdges,
      distance: distances[targetNodeIndex]!,
    };
  }

  private validateAndBuildGraph(graph: LearningPathGraph): void {
    if (graph.nodes.length < 1) {
      throw new Error("PathSimulation requires at least one graph node.");
    }

    const nodeIds = new Set<NodeId>();
    graph.nodes.forEach((node, nodeIndex) => {
      if (node.id.trim().length === 0) {
        throw new Error(`Node at index ${nodeIndex} has an empty id.`);
      }
      if (nodeIds.has(node.id)) {
        throw new Error(`Duplicate node id "${node.id}".`);
      }
      if (!Number.isFinite(node.position.x) || !Number.isFinite(node.position.z)) {
        throw new Error(`Node "${node.id}" has a non-finite position.`);
      }
      nodeIds.add(node.id);
      this.nodeIndexById.set(node.id, nodeIndex);
    });

    for (const [role, nodeId] of [
      ["initial", graph.initialNodeId],
      ["entry", graph.entryNodeId],
      ["goal", graph.goalNodeId],
    ] as const) {
      if (!this.nodeIndexById.has(nodeId)) {
        throw new Error(`Graph ${role} node "${nodeId}" does not exist.`);
      }
    }

    const sortedNodeIndices = graph.nodes
      .map((_, index) => index)
      .sort((left, right) => graph.nodes[left]!.id.localeCompare(graph.nodes[right]!.id));
    sortedNodeIndices.forEach((nodeIndex, rank) => {
      this.nodeTieRanks[nodeIndex] = rank;
    });

    graph.edges.forEach((edge) => {
      this.validateRuntimeEdgeIdentity(edge);
      const pairKey = createPhysicalPairKey(edge.fromNodeId, edge.toNodeId);
      if (this.physicalPairKeys.has(pairKey)) {
        throw new Error(
          `Duplicate physical edge between "${edge.fromNodeId}" and "${edge.toNodeId}".`,
        );
      }
      this.installRuntimeEdge(edge);
    });

    this.adjacency.forEach((steps) => {
      steps.sort((left, right) => {
        const nodeRankDelta = this.nodeTieRanks[left.nodeIndex]!
          - this.nodeTieRanks[right.nodeIndex]!;
        if (nodeRankDelta !== 0) {
          return nodeRankDelta;
        }
        return this.runtimeEdges[left.edgeIndex]!.source.id.localeCompare(
          this.runtimeEdges[right.edgeIndex]!.source.id,
        );
      });
    });

    this.validateConnectedGraph();
    this.validateDirectedAcyclicGraph();
  }

  private validateRuntimeEdgeIdentity(edge: LearningPathEdge): void {
    if (edge.id.trim().length === 0) {
      throw new Error("PathSimulation cannot register an edge with an empty id.");
    }
    if (this.edgeIndexById.has(edge.id)) {
      throw new Error(`Duplicate edge id "${edge.id}".`);
    }
    const fromNodeIndex = this.nodeIndexById.get(edge.fromNodeId);
    const toNodeIndex = this.nodeIndexById.get(edge.toNodeId);
    if (fromNodeIndex === undefined || toNodeIndex === undefined) {
      throw new Error(
        `Edge "${edge.id}" references a missing endpoint (${edge.fromNodeId} -> ${edge.toNodeId}).`,
      );
    }
    if (fromNodeIndex === toNodeIndex) {
      throw new Error(`Edge "${edge.id}" is a self-loop.`);
    }
  }

  private installRuntimeEdge(edge: LearningPathEdge): void {
    const fromNodeIndex = this.nodeIndexById.get(edge.fromNodeId)!;
    const toNodeIndex = this.nodeIndexById.get(edge.toNodeId)!;
    const compiledPath = this.geometryRegistry.get(edge.id);
    if (
      compiledPath.fromNodeId !== edge.fromNodeId
      || compiledPath.toNodeId !== edge.toNodeId
      || compiledPath.pathKind !== edge.pathKind
    ) {
      throw new Error(`Geometry registry edge "${edge.id}" does not match the graph.`);
    }
    const length = compiledPath.length;
    if (!Number.isFinite(length) || length <= DISTANCE_EPSILON) {
      throw new Error(`Edge "${edge.id}" has zero or non-finite length.`);
    }
    const routingCost = edge.pathKind === "overpass" ? edge.routingCost : length;
    if (!Number.isFinite(routingCost) || routingCost <= DISTANCE_EPSILON) {
      throw new Error(`Edge "${edge.id}" has an invalid routing cost.`);
    }
    const edgeIndex = this.runtimeEdges.length;
    this.edgeIndexById.set(edge.id, edgeIndex);
    this.physicalPairKeys.add(createPhysicalPairKey(edge.fromNodeId, edge.toNodeId));
    this.runtimeEdges.push({
      source: edge,
      fromNodeIndex,
      toNodeIndex,
      length,
      routingCost,
    });
    this.adjacency[fromNodeIndex]!.push({
      nodeIndex: toNodeIndex,
      edgeIndex,
      length,
      routingCost,
    });
    this.adjacency[toNodeIndex]!.push({
      nodeIndex: fromNodeIndex,
      edgeIndex,
      length,
      routingCost,
    });
  }

  private sortAdjacencyForNode(nodeId: NodeId): void {
    const nodeIndex = this.nodeIndexById.get(nodeId);
    if (nodeIndex === undefined) return;
    this.adjacency[nodeIndex]!.sort((left, right) => {
      const nodeRankDelta = this.nodeTieRanks[left.nodeIndex]!
        - this.nodeTieRanks[right.nodeIndex]!;
      return nodeRankDelta || this.runtimeEdges[left.edgeIndex]!.source.id.localeCompare(
        this.runtimeEdges[right.edgeIndex]!.source.id,
      );
    });
  }

  private validateConnectedGraph(): void {
    const visited = new Uint8Array(this.nodes.length);
    const queue = new Int32Array(this.nodes.length);
    let readCursor = 0;
    let writeCursor = 1;
    queue[0] = 0;
    visited[0] = 1;

    while (readCursor < writeCursor) {
      const nodeIndex = queue[readCursor++]!;
      for (const step of this.adjacency[nodeIndex]!) {
        if (visited[step.nodeIndex] === 1) {
          continue;
        }
        visited[step.nodeIndex] = 1;
        queue[writeCursor++] = step.nodeIndex;
      }
    }

    if (writeCursor !== this.nodes.length) {
      throw new Error(
        `Learning path graph is disconnected (${writeCursor}/${this.nodes.length} reachable nodes).`,
      );
    }
  }

  private validateDirectedAcyclicGraph(): void {
    const indegrees = new Int32Array(this.nodes.length);
    const directedOutgoing: number[][] = this.nodes.map(() => []);

    for (const edge of this.runtimeEdges) {
      // Generated overpasses are navigation overlays, not authored learning-
      // progression constraints. A catalog may contain every eligible bridge
      // direction at once, so only authored ordinary paths define the DAG.
      if (edge.source.pathKind === "overpass") {
        continue;
      }
      indegrees[edge.toNodeIndex] = indegrees[edge.toNodeIndex]! + 1;
      directedOutgoing[edge.fromNodeIndex]!.push(edge.toNodeIndex);
    }

    const queue = new Int32Array(this.nodes.length);
    let readCursor = 0;
    let writeCursor = 0;
    for (let nodeIndex = 0; nodeIndex < this.nodes.length; nodeIndex += 1) {
      if (indegrees[nodeIndex] === 0) {
        queue[writeCursor++] = nodeIndex;
      }
    }

    let visitedCount = 0;
    while (readCursor < writeCursor) {
      const nodeIndex = queue[readCursor++]!;
      visitedCount += 1;
      for (const nextNodeIndex of directedOutgoing[nodeIndex]!) {
        indegrees[nextNodeIndex] = indegrees[nextNodeIndex]! - 1;
        if (indegrees[nextNodeIndex] === 0) {
          queue[writeCursor++] = nextNodeIndex;
        }
      }
    }

    if (visitedCount !== this.nodes.length) {
      throw new Error("Learning path progression edges must form a directed acyclic graph.");
    }
  }
}
