export interface PathOrchestrationBindingReadiness {
  isPathOrchestrationBound(): boolean;
}

/**
 * Runs a read that requires the root-owned path actor only after that actor has
 * synchronously bound itself. Generation and character loading are allowed to
 * finish before the active experience exists, so that staging window is a
 * normal no-op rather than a runtime failure.
 */
export function runWhenPathOrchestrationBound(
  readiness: PathOrchestrationBindingReadiness,
  operation: () => void,
): boolean {
  if (!readiness.isPathOrchestrationBound()) return false;
  operation();
  return true;
}
