interface MotionDeliveryLease {
  readonly command: MotionCommand;
  expectedRouteRevision: number;
  arrived: boolean;
  progress35Observed: boolean;
}

interface DeferredPresentation {
  readonly command: PresentationCommand;
  readonly reason: "route-lease" | "occupied-overpass";
}

export interface RuntimePhysicalArrivalNotice {
  readonly command: MotionCommand;
  readonly nodeId: NodeId;
  readonly routeRevision: number;
  readonly finalStage: boolean;
}

export interface RestoredRuleProjection {
  readonly restoredZoneId: string | null;
  readonly visibleNodeIds: readonly NodeId[];
  readonly visibleStraightEdgeIds: readonly EdgeId[];
  readonly visibleOverpassIds: readonly EdgeId[];
}

export interface LearningPathRuntimeTransitionNotice {
  readonly type:
    | "presentation-command"
    | "presentation-settled"
    | "presentation-deferred"
    | "presentation-lease-released"
    | "motion-issued"
    | "motion-departed"
    | "motion-arrived"
    | "motion-visual-idle"
    | "navigation-settled"
    | "zone-transaction-settled"
    | "navigation-rejected"
    | "presentation-started"
    | "presentation-failed"
    | "presentation-timeout"
    | "motion-failed"
    | "motion-timeout"
    | "operation-retrying"
    | "recovery-started"
    | "recovery-step"
    | "recovery-complete"
    | "recovery-failed"
    | "stale-event-ignored"
    | "character-watchdog-recovered";
  readonly objectId: string;
  readonly detail?: string;
}

export interface LearningPathXStateRuntimeOptions {
  readonly coordinator: PathRuleCoordinator;
  readonly simulation: PathSimulation;
  readonly pathView: LearningPathView;
  readonly character: CharacterRig;
  readonly nodes: readonly LearningPathNode[];
  readonly edges: readonly LearningPathEdge[];
  readonly initialNodeId: NodeId;
  readonly reducedMotion?: boolean;
  readonly onPhysicalArrival?: (notice: RuntimePhysicalArrivalNotice) => void;
  readonly onPresentationSettled?: (event: PresentationSettledEvent) => void;
  readonly onNavigationSettled?: (notice: NavigationSettledNotice) => void;
  readonly onNavigationRejected?: (notice: NavigationRejectedNotice) => void;
  readonly onTransition?: (notice: LearningPathRuntimeTransitionNotice) => void;
  readonly faultInjection?: FaultInjectionPort;
  readonly presentationAckTimeoutSeconds?: number;
  readonly motionTimeoutSeconds?: number;
  readonly characterNaturalSettleTimeoutMs?: number;
  readonly characterForceSettleAckTimeoutMs?: number;
  /** @deprecated Prefer the two explicit character-settle timeout options. */
  readonly characterSettleTimeoutSeconds?: number;
  /**
   * Optional pre-bound application-root command route. Page sessions normally
   * bind this after activation through bindSceneRuntimeGateway().
   */
  readonly sceneRuntimeCommandSink?: (command: SceneRuntimeGatewayCommand) => void;
  /** Stable page-session generation used to reject late recovery ACKs. */
  readonly sessionRevision?: number;
}

export interface LearningPathRuntimeDebugSnapshot {
  readonly orchestration: ReturnType<typeof getLearningPathDebugSnapshot>;
  readonly motionDeliveryLease: Readonly<{
    readonly token: string;
    readonly fromNodeId: NodeId;
    readonly toNodeId: NodeId;
    readonly expectedRouteRevision: number;
    readonly progress35Observed: boolean;
  }> | null;
  readonly deferredPresentations: readonly Readonly<{
    readonly commandId: string;
    readonly objectId: string;
    readonly objectKind: string;
    readonly reason: DeferredPresentation["reason"];
  }>[];
  readonly presentationObjects: Readonly<{
    readonly platforms: Readonly<Record<string, unknown>>;
    readonly longRoads: Readonly<Record<string, unknown>>;
    readonly overpasses: Readonly<Record<string, unknown>>;
    readonly character: unknown;
  }>;
  readonly recoveryRuntime: Readonly<{
    readonly transactionId: string | null;
    readonly safeNodeId: NodeId | null;
    readonly journalObjectIds: readonly string[];
    readonly activeRecoveryId: string | null;
    readonly activeStepIndex: number;
    readonly activeStepCount: number;
  }>;
  readonly faultTimeline: readonly unknown[];
}

/**
 * XState is the only owner of business timing. Three.js objects stay behind
 * adapters, and PathRuleCoordinator remains a pure planner/commit ledger.
 */
export class LearningPathXStateRuntime {
  private readonly coordinator: PathRuleCoordinator;
  private readonly simulation: PathSimulation;
  private readonly pathView: LearningPathView;
  private readonly character: CharacterRig;
  private readonly edgeById: Map<EdgeId, LearningPathEdge>;
  private readonly presentation: XStatePresentationCoordinator;
  private readonly characterAdapter: XStateCharacterAdapter;
  private readonly diagnosticLedger: SceneRuntimeDiagnosticLedger;
  private readonly sceneRuntimePort: LearningPathSceneRuntimePort;
  private sceneRuntimeCommandSink: (command: SceneRuntimeGatewayCommand) => void;
  private readonly pendingCharacterSettles = new Map<string, CharacterForceSettleCommand>();
  private readonly deferredPresentations = new Map<string, DeferredPresentation>();
  private readonly onPhysicalArrival?: (notice: RuntimePhysicalArrivalNotice) => void;
  private readonly onPresentationSettled?: (event: PresentationSettledEvent) => void;
  private readonly onNavigationSettled?: (notice: NavigationSettledNotice) => void;
  private readonly onNavigationRejected?: (notice: NavigationRejectedNotice) => void;
  private readonly onTransition?: (notice: LearningPathRuntimeTransitionNotice) => void;
  private readonly faultInjection: FaultInjectionPort;
  private readonly presentationAckTimeoutSeconds: number;
  private readonly motionRouteTimeoutMs: number;
  private readonly characterNaturalSettleTimeoutMs: number;
  private readonly characterForceSettleAckTimeoutMs: number;
  private readonly recoveryBoundaryStore: RecoveryBoundaryStore<
    ReturnType<PathRuleCoordinator["createRecoveryCheckpoint"]>
  >;
  private actor: PathOrchestrationActor | null = null;
  private readonly orchestrationBinding: PathOrchestrationRuntimeBinding;
  private readonly stopArrivalSubscription: () => void;
  private readonly stopPresentationSubscription: () => void;
  private readonly stopCharacterSubscription: () => void;
  private motionDeliveryLease: MotionDeliveryLease | null = null;
  private activeRecoveryInput: RecoveryMachineInput | null = null;
  private activeRecoveryCommand: RecoveryCommand | null = null;
  private lastExecutedRecoveryAttemptId: string | null = null;
  private recoverySessionRevision: number;
  private zoneRevealFailureLatchNodeId: NodeId | null = null;
  private occupiedOverpassId: EdgeId | null = null;
  private lastVisualIdleToken: string | null = null;
  private reducedMotion: boolean;
  private lastCharacterWatchdogTimeoutCount = 0;
  private disposed = false;

  public constructor(options: LearningPathXStateRuntimeOptions) {
    this.coordinator = options.coordinator;
    this.recoveryBoundaryStore = new RecoveryBoundaryStore({
      captureCheckpoint: () => this.coordinator.createRecoveryCheckpoint(),
      restoreCheckpoint: (checkpoint) => {
        this.coordinator.restoreRecoveryCheckpoint(checkpoint);
      },
      discardPendingAfterRecovery: () => {
        this.coordinator.discardPendingTransactionsAfterRecovery();
      },
    });
    this.simulation = options.simulation;
    this.pathView = options.pathView;
    this.character = options.character;
    this.faultInjection = options.faultInjection ?? NO_FAULT_INJECTION;
    this.presentationAckTimeoutSeconds = options.presentationAckTimeoutSeconds ?? 0.8;
    this.motionRouteTimeoutMs = (options.motionTimeoutSeconds ?? 12) * 1_000;
    const legacyCharacterSettleTimeoutMs = (
      options.characterSettleTimeoutSeconds ?? 1.2
    ) * 1_000;
    this.characterNaturalSettleTimeoutMs = options.characterNaturalSettleTimeoutMs
      ?? legacyCharacterSettleTimeoutMs;
    this.characterForceSettleAckTimeoutMs = options.characterForceSettleAckTimeoutMs
      ?? legacyCharacterSettleTimeoutMs;
    this.recoverySessionRevision = options.sessionRevision ?? 1;
    if (!Number.isSafeInteger(this.recoverySessionRevision)
      || this.recoverySessionRevision < 0) {
      throw new Error("sessionRevision must be a non-negative safe integer.");
    }
    this.reducedMotion = options.reducedMotion ?? false;
    this.onPhysicalArrival = options.onPhysicalArrival;
    this.onPresentationSettled = options.onPresentationSettled;
    this.onNavigationSettled = options.onNavigationSettled;
    this.onNavigationRejected = options.onNavigationRejected;
    this.onTransition = options.onTransition;
    this.edgeById = this.createUniqueCatalog(options.edges, "edge");

    this.diagnosticLedger = new SceneRuntimeDiagnosticLedger({
      nodes: options.nodes,
      edges: options.edges,
      initialCharacterPhase: this.character.getAnimationPhase(),
      initiallyCharacterVisuallyIdle: this.character.isVisuallyIdle(),
    });
    this.characterAdapter = new XStateCharacterAdapter(this.character);
    this.stopCharacterSubscription = this.characterAdapter.subscribe((event) => {
      this.diagnosticLedger.acceptCharacterEvent(event);
      if (event.type === "CHARACTER.PHASE" && event.visuallyIdle) {
        this.settlePendingCharacterCommands();
      } else if (event.type === "CHARACTER.FAILED") {
        this.failPendingCharacterCommands(event.error);
      }
      if (event.type === "CHARACTER.PHASE") {
        if (!event.visuallyIdle || this.motionDeliveryLease === null) {
          this.actor?.send({
            type: "ORCHESTRATION.CHARACTER.VISUAL_IDLE_CHANGED",
            visuallyIdle: event.visuallyIdle,
          });
        }
        if (event.visuallyIdle) {
          this.publishVisualIdleIfReady();
          this.acknowledgeRecoveryCharacterIdle();
        }
      } else if (event.type === "CHARACTER.FAILED") {
        this.actor?.send({
          type: "ORCHESTRATION.CHARACTER.FAILED",
          error: event.error,
        });
      } else {
        this.actor?.send({
          type: "ORCHESTRATION.CHARACTER.VISUAL_IDLE_CHANGED",
          visuallyIdle: false,
        });
      }
    });

    this.presentation = new XStatePresentationCoordinator({
      view: options.pathView,
      nodes: options.nodes,
      edges: options.edges,
      reducedMotion: this.reducedMotion,
      faultInjection: this.faultInjection,
    });
    this.stopPresentationSubscription = this.presentation.subscribe((event) => {
      this.handlePresentationEvent(event);
    });

    this.sceneRuntimePort = new LearningPathSceneRuntimePort({
      executePresentation: (command) => {
        const domainCommand = this.requireDomainPresentationPayload(command);
        this.executePresentation(domainCommand);
        return {
          disposition: this.deferredPresentations.has(domainCommand.token)
            ? "deferred" as const
            : "accepted" as const,
          deferredReason: this.deferredPresentations.get(domainCommand.token)?.reason,
          cancel: () => this.cancelPresentationDelivery(command.transactionId),
        };
      },
      cancelPresentationTransaction: (command) => {
        this.cancelPresentationDelivery(command.transactionId);
      },
      executeMotion: (command) => {
        const domainCommand = this.requireMotionPayload(command);
        this.executeMotion(domainCommand);
        return {
          disposition: "accepted" as const,
          cancel: () => this.abortMotionDelivery(domainCommand),
        };
      },
      abortMotion: (command) => {
        const active = this.motionDeliveryLease;
        if (active
          && active.command.transactionId === command.transactionId
          && active.command.operationId === command.operationId) {
          this.abortMotionDelivery(active.command);
        }
      },
      forceSettleCharacter: (command) => this.forceSettleCharacter(command),
    });
    this.sceneRuntimeCommandSink = options.sceneRuntimeCommandSink
      ?? ((command) => {
        throw new Error(
          `Scene runtime command route is not bound for ${command.type}.`,
        );
      });

    const services: OrchestrationServices = {
      planNavigation: (sourceNodeId, targetNodeId) => (
        this.planNavigationWithRecovery(sourceNodeId, targetNodeId)
      ),
      planZoneReveal: (characterNodeId) => (
        this.planZoneRevealWithRecovery(characterNodeId)
      ),
      planZoneDismiss: (characterNodeId) => (
        this.planZoneDismissWithRecovery(characterNodeId)
      ),
      commitNavigationBeforeAction: (planId, stageIndex, actionIndex) => {
        this.coordinator.commitNavigationBeforeAction(planId, stageIndex, actionIndex);
      },
      commitNavigationStageStarted: (planId, stageIndex) => {
        this.coordinator.commitNavigationStageStarted(planId, stageIndex);
      },
      commitNavigationAfterAction: (planId, stageIndex, actionIndex, arrivedNodeId) => {
        this.coordinator.commitNavigationAfterAction(
          planId,
          stageIndex,
          actionIndex,
          arrivedNodeId,
        );
      },
      commitNavigationStageArrived: (planId, stageIndex, arrivedNodeId) => {
        this.coordinator.commitNavigationStageArrived(planId, stageIndex, arrivedNodeId);
        const transactionId = this.recoveryBoundaryStore.getSnapshot()?.transactionId;
        if (transactionId) {
          this.recoveryBoundaryStore.advance(arrivedNodeId, transactionId);
        }
      },
      cancelNavigationPlan: (planId) => this.coordinator.cancelNavigationPlan(planId),
      commitZoneRevealBeforeAction: (planId, actionIndex) => {
        this.coordinator.commitZoneRevealBeforeAction(planId, actionIndex);
      },
      commitZoneRevealStep: (planId, stepIndex) => {
        this.coordinator.commitZoneRevealStep(planId, stepIndex);
      },
      commitZoneDismissStep: (planId, stepIndex) => {
        this.coordinator.commitZoneDismissStep(planId, stepIndex);
      },
      executePresentation: (command) => this.issuePresentationCommand(command),
      executeMotion: (command) => this.issueMotionCommand(command),
      executeCharacterForceSettle: (command) => {
        this.issueCharacterForceSettleCommand(command);
      },
      characterNaturalSettleTimeoutMs: this.characterNaturalSettleTimeoutMs,
      characterForceSettleAckTimeoutMs: this.characterForceSettleAckTimeoutMs,
      prepareRecoveryInput: (request) => this.prepareRecoveryInput(request),
      executeRecoveryCommand: (command) => this.executeRecoveryCommand(command),
      finalizeRecovery: (request, outcome) => {
        this.finalizeRecovery(request, outcome);
      },
      cancelRecovery: (request) => this.cancelRecoveryAdapter(request),
      recoveryCommandTimeoutMs: this.presentationAckTimeoutSeconds * 1_000,
      recoveryCharacterIdleTimeoutMs: this.characterNaturalSettleTimeoutMs
        + this.characterForceSettleAckTimeoutMs,
      onOperationRetry: (notice) => {
        this.emitTransition(
          "operation-retrying",
          notice.operationId,
          `attempt=${notice.nextAttempt}; ${notice.reason}`,
        );
      },
      onNavigationTransactionSettled: (notice) => {
        if (this.motionDeliveryLease?.command.navigationPlanId === notice.planId) {
          this.motionDeliveryLease = null;
        }
        // A promoted queued navigation can be planned in this same XState
        // macrostep, before the next render frame gets a chance to finalize the
        // previous journal. Close the successful transaction synchronously.
        const boundary = this.recoveryBoundaryStore.getSnapshot();
        if (!this.activeRecoveryInput && boundary?.transactionId === notice.transactionId) {
          this.recoveryBoundaryStore.complete(notice.transactionId);
        } else if (!this.activeRecoveryInput && boundary?.transactionId === null) {
          this.recoveryBoundaryStore.reset();
        }
      },
      onNavigationSettled: (notice) => {
        this.emitTransition("navigation-settled", notice.planId, notice.nodeId);
        this.onNavigationSettled?.(notice);
      },
      onStandaloneZoneTransactionSettled: ({ transactionId, kind }) => {
        if (!this.activeRecoveryInput
          && this.recoveryBoundaryStore.getSnapshot()?.transactionId === transactionId) {
          this.recoveryBoundaryStore.complete(transactionId);
        }
        this.emitTransition("zone-transaction-settled", transactionId, kind);
      },
      onNavigationRejected: (notice) => {
        this.emitTransition("navigation-rejected", notice.targetNodeId, notice.detail);
        this.onNavigationRejected?.(notice);
      },
    };
    this.orchestrationBinding = Object.freeze({
      input: Object.freeze({
        initialNodeId: options.initialNodeId,
        initialCharacterVisualIdle: this.character.isVisuallyIdle(),
        initialZoneStatus: "inactive",
      }),
      services,
      bindActor: (actor: PathOrchestrationActor) => {
        if (this.disposed) throw new Error("Cannot bind a disposed learning-path runtime.");
        if (this.actor && this.actor !== actor) {
          throw new Error("Learning-path runtime is already bound to another orchestration actor.");
        }
        this.actor = actor;
      },
      unbindActor: (actor?: PathOrchestrationActor) => {
        if (actor && this.actor !== actor) return;
        this.actor = null;
      },
    });
    this.stopArrivalSubscription = this.simulation.onArrival((event) => {
      this.handlePhysicalArrival(event);
    });
  }

  public requestNavigation(targetNodeId: NodeId): void {
    this.assertLive();
    this.completeRecoveryBoundaryIfStable();
    if (targetNodeId !== this.zoneRevealFailureLatchNodeId) {
      this.zoneRevealFailureLatchNodeId = null;
    }
    this.requireOrchestrationActor().send({ type: "NAVIGATION.REQUESTED", targetNodeId });
  }

  /** Call after CharacterRig.update() and before rendering the frame. */
  public frame(deltaSeconds: number): void {
    if (this.disposed) return;
    const safeDelta = Number.isFinite(deltaSeconds) ? Math.max(0, deltaSeconds) : 0;
    this.syncOccupiedOverpass();
    this.flushDeferredPresentations();
    this.presentation.frame(safeDelta);
    this.characterAdapter.frame();
    this.publishVisualIdleIfReady();
    this.acknowledgeRecoveryCharacterIdle();
    this.observeMotionFaultPoint();
    this.observeCharacterWatchdogRecovery();
    this.completeRecoveryBoundaryIfStable();
    this.driveIdleZoneRules();
  }

  public setReducedMotion(reducedMotion: boolean): void {
    this.assertLive();
    this.reducedMotion = reducedMotion;
    this.presentation.setReducedMotion(reducedMotion);
    const motion = this.motionDeliveryLease;
    if (!reducedMotion || !motion || !this.simulation.getSnapshot().isRunning) return;
    motion.expectedRouteRevision = this.simulation.getSnapshot().routeRevision + 1;
    if (!this.simulation.moveImmediatelyTo(motion.command.toNodeId)) {
      throw new Error(`Cannot complete reduced-motion route to "${motion.command.toNodeId}".`);
    }
  }

  public reportCharacterFailure(error: unknown): void {
    this.assertLive();
    this.characterAdapter.reportFailure(error);
  }

  public getSnapshot(): LearningPathMachineSnapshot {
    return this.requireOrchestrationActor().getSnapshot();
  }

  /**
   * Generation can load the character before the application root has entered
   * its active experience state. Read-only Session/DEV projections use this
   * readiness check instead of treating that expected staging window as a
   * model-load failure.
   */
  public isPathOrchestrationBound(): boolean {
    return !this.disposed && this.actor !== null;
  }

  public getDebugSnapshot(): LearningPathRuntimeDebugSnapshot {
    const presentationObjects = this.diagnosticLedger.snapshot();
    const recoveryBoundary = this.recoveryBoundaryStore.getSnapshot();
    return Object.freeze({
      orchestration: getLearningPathDebugSnapshot(this.requireOrchestrationActor().getSnapshot()),
      motionDeliveryLease: this.motionDeliveryLease
        ? Object.freeze({
          token: this.motionDeliveryLease.command.token,
          fromNodeId: this.motionDeliveryLease.command.fromNodeId,
          toNodeId: this.motionDeliveryLease.command.toNodeId,
          expectedRouteRevision: this.motionDeliveryLease.expectedRouteRevision,
          progress35Observed: this.motionDeliveryLease.progress35Observed,
        })
        : null,
      deferredPresentations: Object.freeze(
        [...this.deferredPresentations.values()].map(({ command, reason }) => Object.freeze({
          commandId: command.commandId,
          objectId: command.objectId,
          objectKind: command.objectKind,
          reason,
        })),
      ),
      presentationObjects: Object.freeze({
        platforms: presentationObjects.platforms,
        longRoads: presentationObjects.longRoads,
        overpasses: presentationObjects.overpasses,
        character: presentationObjects.character,
      }),
      recoveryRuntime: Object.freeze({
        transactionId: recoveryBoundary?.transactionId ?? null,
        safeNodeId: recoveryBoundary?.safeNodeId ?? null,
        journalObjectIds: recoveryBoundary?.journalObjectIds ?? Object.freeze([]),
        activeRecoveryId: this.activeRecoveryInput?.recoveryId ?? null,
        activeStepIndex: this.activeRecoveryCommand?.type === "RECOVERY.COMPENSATE_PRESENTATION"
          ? this.activeRecoveryInput?.journal.length
            ? this.activeRecoveryInput.journal.length - this.activeRecoveryCommand.journalIndex
            : 0
          : 0,
        activeStepCount: this.activeRecoveryInput?.journal.length ?? 0,
      }),
      faultTimeline: this.faultInjection.getTimeline(),
    });
  }

  public isNavigationIdle(): boolean {
    return isLearningPathNavigationIdle(this.requireOrchestrationActor().getSnapshot());
  }

  /** Port injected into the application root's sceneSession gateway. */
  public getSceneRuntimePort(): SceneRuntimePort {
    return this.sceneRuntimePort;
  }

  /**
   * Binds the runtime to the application-owned scene-session revision. The
   * application root remains the only command route and ACK authority; the
   * runtime contributes only the imperative port implementation.
   */
  public bindSceneRuntimeGateway(
    sessionRevision: number,
    commandSink: (command: SceneRuntimeGatewayCommand) => void,
  ): void {
    this.assertLive();
    if (!Number.isSafeInteger(sessionRevision) || sessionRevision < 0) {
      throw new Error("sessionRevision must be a non-negative safe integer.");
    }
    this.recoverySessionRevision = sessionRevision;
    this.sceneRuntimeCommandSink = commandSink;
  }

  /**
   * Restores the rule ledger and its terminal Three.js projection as one
   * pre-interactive operation. No animation command or gateway ACK is emitted:
   * persisted progress represents an already settled scene boundary.
   */
  public reconcileRestoredRuleProjection(
    nodeId: NodeId,
    preferredActivationNodeId?: NodeId,
  ): RestoredRuleProjection {
    this.assertLive();
    const restoredZone = this.coordinator.restoreStableZoneSessionForNode(
      nodeId,
      preferredActivationNodeId,
    );
    const snapshot = this.coordinator.getDebugSnapshot();
    const visibleNodeIds = new Set(snapshot.unlockedNodeIds);
    const visibleStraightEdgeIds = new Set(snapshot.unlockedStraightEdgeIds);

    for (const state of this.pathView.getNodePresenceStates()) {
      const visible = visibleNodeIds.has(state.id);
      this.pathView.setNodeVisible(state.id, visible);
      this.diagnosticLedger.reconcileStableVisibility("platform", state.id, visible);
    }
    for (const state of this.pathView.getStraightEdgePresenceStates()) {
      const visible = visibleStraightEdgeIds.has(state.id);
      this.pathView.setStraightEdgeVisible(state.id, visible);
      this.diagnosticLedger.reconcileStableVisibility("long-road", state.id, visible);
    }

    const activeBridges = snapshot.bridges.filter((bridge) => bridge.active);
    for (const bridge of activeBridges) {
      this.registerOverpass(bridge.edge);
      this.pathView.updateOverpassVisibility(bridge.bridgeId, 0, {
        desiredVisible: true,
        characterSideNodeId: bridge.ownerSourceNodeId,
        reducedMotion: true,
      });
      this.diagnosticLedger.reconcileStableVisibility(
        "overpass",
        bridge.bridgeId,
        true,
      );
    }

    return Object.freeze({
      restoredZoneId: restoredZone?.zoneId ?? null,
      visibleNodeIds: Object.freeze([...visibleNodeIds].sort()),
      visibleStraightEdgeIds: Object.freeze([...visibleStraightEdgeIds].sort()),
      visibleOverpassIds: Object.freeze(
        activeBridges.map((bridge) => bridge.bridgeId).sort(),
      ),
    });
  }

  /** Ports/input consumed by the application root's invoked orchestration child. */
  public getPathOrchestrationBinding(): PathOrchestrationRuntimeBinding {
    this.assertLive();
    return Object.freeze({
      ...this.orchestrationBinding,
      input: Object.freeze({
        ...this.orchestrationBinding.input,
        initialNodeId: this.simulation.getSnapshot().currentNodeId,
        initialCharacterVisualIdle: this.character.isVisuallyIdle(),
        initialZoneStatus: this.coordinator.hasVisibleZoneSession()
          ? "active" as const
          : "inactive" as const,
      }),
    });
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.stopArrivalSubscription();
    this.stopPresentationSubscription();
    this.stopCharacterSubscription();
    this.characterAdapter.dispose();
    this.presentation.dispose();
    this.pendingCharacterSettles.clear();
    this.sceneRuntimePort.dispose();
    this.actor = null;
    this.clearRecoveryAdapterState();
    this.deferredPresentations.clear();
    this.recoveryBoundaryStore.reset();
  }

  private planNavigationWithRecovery(
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
  ): NavigationPlanResult {
    const staged = this.recoveryBoundaryStore.begin(sourceNodeId);
    const result = this.coordinator.planNavigation(sourceNodeId, targetNodeId);
    // The coordinator's plan id is not the XState navigation transaction id.
    // Keep the checkpoint unbound until the first correlated presentation or
    // motion command arrives; those commands carry the authoritative workflow
    // transaction used by failure, retry, recovery, and settlement events.
    if (!result.accepted && staged) {
      this.recoveryBoundaryStore.reset();
    }
    return result;
  }

  private planZoneRevealWithRecovery(characterNodeId: NodeId): ZoneRevealPlan | null {
    const staged = this.recoveryBoundaryStore.begin(characterNodeId);
    const plan = this.coordinator.planIdleZoneReveal(characterNodeId);
    if (plan) {
      this.recoveryBoundaryStore.bind(plan.id, characterNodeId);
    } else if (staged) {
      this.recoveryBoundaryStore.reset();
    }
    return plan;
  }

  private planZoneDismissWithRecovery(characterNodeId: NodeId): ZoneDismissPlan | null {
    const staged = this.recoveryBoundaryStore.begin(characterNodeId);
    const plan = this.coordinator.planIdleZoneDismissal(characterNodeId);
    if (plan) {
      this.recoveryBoundaryStore.bind(
        plan.linkedNavigationPlanId ?? plan.id,
        characterNodeId,
      );
    } else if (staged) {
      this.recoveryBoundaryStore.reset();
    }
    return plan;
  }

  private recordPresentationJournal(command: PresentationCommand): void {
    const visibleBefore = this.diagnosticLedger.getDesiredVisibility(
      command.objectKind,
      command.objectId,
    );
    if (visibleBefore === undefined) {
      throw new Error(`Cannot journal unknown ${command.objectKind} "${command.objectId}".`);
    }
    this.recoveryBoundaryStore.record(Object.freeze({
      transactionId: command.transactionId,
      operationId: command.operationId,
      objectId: command.objectId,
      objectKind: command.objectKind,
      visibleBefore,
      order: command.order,
      metadata: command.metadata,
    }));
  }

  private completeRecoveryBoundaryIfStable(): void {
    const boundary = this.recoveryBoundaryStore.getSnapshot();
    if (!boundary || this.activeRecoveryInput) return;
    const snapshot = this.requireOrchestrationActor().getSnapshot();
    if (!isLearningPathNavigationIdle(snapshot)
      || snapshot.context.navigationPlan !== null
      || snapshot.context.zoneRevealPlan !== null
      || snapshot.context.zoneDismissPlan !== null
      || snapshot.context.zoneTransitionActive
      || !snapshot.context.characterVisualIdle) return;
    if (boundary.transactionId) this.recoveryBoundaryStore.complete(boundary.transactionId);
    else this.recoveryBoundaryStore.reset();
  }

  private issuePresentationCommand(command: DomainPresentationCommand): void {
    try {
      this.sceneRuntimeCommandSink({
        type: "PRESENTATION.EXECUTE",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        payload: command,
        timeoutMs: this.presentationAckTimeoutSeconds * 1_000,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.sceneRuntimePort.publish({
        type: "PRESENTATION.FAILED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        error: message,
      });
    }
  }

  private issueMotionCommand(command: MotionCommand): void {
    try {
      this.sceneRuntimeCommandSink({
        type: "MOTION.EXECUTE",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        payload: command,
        timeoutMs: this.motionRouteTimeoutMs,
      });
    } catch (error) {
      this.failMotionCommand(
        command,
        error instanceof Error ? error.message : String(error),
      );
    }
  }

  private issueCharacterForceSettleCommand(
    command: Parameters<NonNullable<OrchestrationServices["executeCharacterForceSettle"]>>[0],
  ): void {
    try {
      this.sceneRuntimeCommandSink({
        type: "CHARACTER.FORCE_SETTLE",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        reason: command.reason,
        timeoutMs: this.characterForceSettleAckTimeoutMs,
      });
    } catch (error) {
      this.sceneRuntimePort.publish({
        type: "CHARACTER.FAILED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  private requireDomainPresentationPayload(
    command: PresentationExecuteCommand,
  ): DomainPresentationCommand {
    const payload = command.payload as DomainPresentationCommand | null;
    if (!payload
      || (payload.type !== "PRESENTATION.BRIDGE"
        && payload.type !== "PRESENTATION.CONSTRUCT")
      || payload.transactionId !== command.transactionId
      || payload.operationId !== command.operationId
      || payload.attemptId !== command.attemptId
      || payload.attempt !== command.attempt) {
      throw new Error(`Invalid presentation payload for "${command.attemptId}".`);
    }
    return payload;
  }

  private requireMotionPayload(command: MotionExecuteCommand): MotionCommand {
    const payload = command.payload as MotionCommand | null;
    if (!payload
      || payload.type !== "MOTION.NAVIGATE"
      || payload.transactionId !== command.transactionId
      || payload.operationId !== command.operationId
      || payload.attemptId !== command.attemptId
      || payload.attempt !== command.attempt) {
      throw new Error(`Invalid motion payload for "${command.attemptId}".`);
    }
    return payload;
  }

  private cancelPresentationDelivery(transactionId: string): void {
    this.presentation.cancelTransaction(transactionId);
    [...this.deferredPresentations.entries()].forEach(([commandId, deferred]) => {
      if (deferred.command.transactionId === transactionId) {
        this.deferredPresentations.delete(commandId);
      }
    });
  }

  private abortMotionDelivery(command: MotionCommand): void {
    if (this.motionDeliveryLease?.command.token !== command.token) return;
    this.simulation.abortToNode(
      this.recoveryBoundaryStore.getSnapshot()?.safeNodeId ?? command.fromNodeId,
    );
    this.motionDeliveryLease = null;
    this.lastVisualIdleToken = null;
  }

  private forceSettleCharacter(command: CharacterForceSettleCommand) {
    this.pendingCharacterSettles.set(command.attemptId, command);
    this.character.debugRecoverStalledAnimation(
      command.reason ?? "scene-runtime-force-settle",
    );
    if (this.character.isVisuallyIdle()) {
      queueMicrotask(() => this.settlePendingCharacterCommands());
    }
    return {
      disposition: "accepted" as const,
      cancel: () => {
        this.pendingCharacterSettles.delete(command.attemptId);
      },
    };
  }

  private settlePendingCharacterCommands(): void {
    if (this.disposed || !this.character.isVisuallyIdle()) return;
    [...this.pendingCharacterSettles.values()].forEach((command) => {
      this.sceneRuntimePort.publish({
        type: "CHARACTER.SETTLED",
        sessionRevision: command.sessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
      });
      this.pendingCharacterSettles.delete(command.attemptId);
    });
  }

  private failPendingCharacterCommands(error: string): void {
    if (this.disposed) return;
    [...this.pendingCharacterSettles.values()].forEach((command) => {
      this.sceneRuntimePort.publish({
        type: "CHARACTER.FAILED",
        sessionRevision: command.sessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        error,
      });
      this.pendingCharacterSettles.delete(command.attemptId);
    });
  }

  private executePresentation(command: DomainPresentationCommand): void {
    try {
      const resolved = command.type === "PRESENTATION.CONSTRUCT"
        ? this.resolveConstructCommand(command)
        : this.resolveBridgeCommand(command.action, command);
      this.recoveryBoundaryStore.bind(
        command.transactionId,
        this.actor?.getSnapshot().context.currentNodeId
          ?? this.simulation.getSnapshot().currentNodeId,
      );
      this.recordPresentationJournal(resolved);
      this.emitTransition(
        "presentation-command",
        resolved.objectId,
        `${resolved.commandId}; visible=${resolved.visible}`,
      );
      this.dispatchOrDeferPresentation(resolved);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.sceneRuntimePort.publish({
        type: "PRESENTATION.FAILED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        error: message,
      });
    }
  }

  private resolveConstructCommand(
    command: Extract<DomainPresentationCommand, { readonly type: "PRESENTATION.CONSTRUCT" }>,
  ): PresentationCommand {
    if (command.construct.kind === "bridge") {
      throw new Error(`Construct command "${command.token}" cannot contain a bridge.`);
    }
    const isNode = command.construct.kind === "node";
    return Object.freeze({
      commandId: command.token,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attempt: command.attempt,
      objectId: isNode ? command.construct.nodeId : command.construct.edgeId,
      objectKind: isNode ? "platform" as const : "long-road" as const,
      visible: command.direction === "fall-in",
      order: null,
      metadata: Object.freeze({
        token: command.token,
        lane: command.lane,
        planId: command.planId,
        stepIndex: command.stepIndex,
        reason: command.direction,
      }),
    });
  }

  private resolveBridgeCommand(
    action: BridgeTransitionAction,
    command: Extract<DomainPresentationCommand, { readonly type: "PRESENTATION.BRIDGE" }>,
  ): PresentationCommand {
    if (action.kind === "ensure-bridge") {
      this.registerOverpass(action.bridge.edge);
    }
    const bridgeId = action.kind === "ensure-bridge"
      ? action.bridge.bridgeId
      : action.bridgeId;
    const edge = this.requireOverpass(bridgeId);
    const registered = this.findRegisteredBridge(bridgeId);
    const role = action.kind === "ensure-bridge"
      ? action.bridge.role
      : registered?.role ?? "ordinary";
    const sourceNodeId = action.characterSideNodeId;
    const targetNodeId = edge.fromNodeId === sourceNodeId
      ? edge.toNodeId
      : edge.fromNodeId;
    const worldOrdered = role === "zone-entry"
      || role === "zone-transient"
      || command.lane === "zone-reveal"
      || command.lane === "zone-reveal-before"
      || command.lane === "zone-dismiss";
    return Object.freeze({
      commandId: command.token,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attempt: command.attempt,
      objectId: bridgeId,
      objectKind: "overpass" as const,
      visible: action.kind === "ensure-bridge",
      order: worldOrdered ? "world-left-to-right" as const : "source-to-target" as const,
      metadata: Object.freeze({
        token: command.token,
        lane: command.lane,
        planId: command.planId,
        stepIndex: command.stepIndex,
        sourceNodeId,
        targetNodeId,
        role,
        reason: action.kind,
      }),
    });
  }

  private dispatchOrDeferPresentation(command: PresentationCommand): void {
    const reason = this.getPresentationDeferralReason(command);
    if (reason) {
      this.deferredPresentations.set(command.commandId, { command, reason });
      this.emitTransition("presentation-deferred", command.objectId, reason);
      return;
    }
    this.dispatchPresentation(command);
  }

  private dispatchPresentation(command: PresentationCommand): void {
    this.diagnosticLedger.acceptPresentationCommand(command);
    this.presentation.command(command);
  }

  private getPresentationDeferralReason(
    command: PresentationCommand,
  ): DeferredPresentation["reason"] | null {
    if (command.visible) return null;
    const snapshot = this.simulation.getSnapshot();
    if (command.objectKind === "platform"
      && snapshot.remainingRouteNodeIds.includes(command.objectId)) {
      const isDepartedSource = snapshot.isRunning
        && this.motionDeliveryLease?.command.fromNodeId === command.objectId;
      // The source platform must start rising with the character's first
      // movement frame. The simulator already owns the support curve after
      // requestRoute(), so only the destination and future route nodes remain
      // leased; retaining the source until arrival serialized the whole zone
      // cleanup behind a long bridge crossing.
      if (!isDepartedSource) return "route-lease";
    }
    if (command.objectKind === "long-road"
      && snapshot.remainingRouteEdgeIds.includes(command.objectId)) {
      return "route-lease";
    }
    if (command.objectKind === "overpass"
      && snapshot.remainingRouteEdgeIds.includes(command.objectId)) {
      return "route-lease";
    }
    if (command.objectKind === "overpass"
      && snapshot.activeLeg?.edgeId === command.objectId) {
      return "occupied-overpass";
    }
    return null;
  }

  private flushDeferredPresentations(): void {
    [...this.deferredPresentations.entries()].forEach(([commandId, pending]) => {
      if (this.getPresentationDeferralReason(pending.command)) return;
      this.deferredPresentations.delete(commandId);
      this.emitTransition(
        "presentation-lease-released",
        pending.command.objectId,
        pending.reason,
      );
      try {
        this.dispatchPresentation(pending.command);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        this.sceneRuntimePort.publish({
          type: "PRESENTATION.FAILED",
          sessionRevision: this.recoverySessionRevision,
          transactionId: pending.command.transactionId,
          operationId: pending.command.operationId,
          attemptId: pending.command.commandId,
          attempt: pending.command.attempt,
          error: message,
        });
      }
    });
  }

  private executeMotion(command: MotionCommand): void {
    this.recoveryBoundaryStore.bind(command.transactionId, command.fromNodeId);
    if (this.motionDeliveryLease && this.simulation.getSnapshot().isRunning) {
      this.failMotionCommand(
        command,
        `Motion "${command.token}" cannot replace active motion "${this.motionDeliveryLease.command.token}".`,
      );
      return;
    }
    this.motionDeliveryLease = {
      command,
      expectedRouteRevision: this.simulation.getSnapshot().routeRevision + 1,
      arrived: false,
      progress35Observed: false,
    };
    const injected = this.faultInjection.decide({
      point: FAULT_TRIGGER_POINT.MOTION_COMMAND,
      operation: command.operationId,
      attempt: command.attempt,
      transactionId: command.transactionId,
      metadata: { token: command.token, from: command.fromNodeId, to: command.toNodeId },
    });
    if (injected.kind === "throw") {
      this.failMotionCommand(command, injected.message);
      return;
    }
    if (injected.kind === "drop" || injected.kind === "stall") {
      this.emitTransition("motion-issued", command.token, `injected-${injected.kind}`);
      return;
    }
    try {
      const request = this.simulation.requestRoute({
        targetNodeId: command.toNodeId,
        nodeIds: command.routeNodeIds,
        edgeIds: command.routeEdgeIds,
      });
      if (!request.accepted || request.status !== "started") {
        const detail = request.accepted ? request.status : request.message;
        this.failMotionCommand(command, `Explicit motion failed: ${detail}.`);
        return;
      }
      this.lastVisualIdleToken = null;
      this.emitTransition("motion-issued", command.token, command.stageId);
      this.sceneRuntimePort.publish({
        type: "MOTION.DEPARTED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
        nodeId: command.fromNodeId,
      });
      this.emitTransition("motion-departed", command.token, command.fromNodeId);
      if (this.reducedMotion) {
        const active = this.motionDeliveryLease;
        if (active?.command.token === command.token) {
          active.expectedRouteRevision = this.simulation.getSnapshot().routeRevision + 1;
          if (!this.simulation.moveImmediatelyTo(command.toNodeId)) {
            this.failMotionCommand(command, "Reduced-motion teleport failed.");
          }
        }
      }
    } catch (error) {
      this.failMotionCommand(command, error instanceof Error ? error.message : String(error));
    }
  }

  private handlePhysicalArrival(event: ArrivalEvent): void {
    const active = this.motionDeliveryLease;
    if (!active
      || active.command.toNodeId !== event.nodeId
      || active.expectedRouteRevision !== event.routeRevision) {
      return;
    }
    const before = this.requireOrchestrationActor().getSnapshot().context.navigationPlan;
    const finalStage = active.command.stageIndex
      === Math.max(0, (before?.stages.length ?? 1) - 1);
    const arrivingCommand = active.command;
    active.arrived = true;
    this.emitTransition("motion-arrived", arrivingCommand.token, event.nodeId);
    this.sceneRuntimePort.publish({
      type: "MOTION.ARRIVED",
      sessionRevision: this.recoverySessionRevision,
      transactionId: arrivingCommand.transactionId,
      operationId: arrivingCommand.operationId,
      attemptId: arrivingCommand.attemptId,
      attempt: arrivingCommand.attempt,
      nodeId: event.nodeId,
    });
    this.onPhysicalArrival?.({
      command: arrivingCommand,
      nodeId: event.nodeId,
      routeRevision: event.routeRevision,
      finalStage,
    });
    if (this.motionDeliveryLease?.command.token === arrivingCommand.token) {
      this.publishVisualIdleIfReady();
    }
  }

  private publishVisualIdleIfReady(): void {
    const motion = this.motionDeliveryLease;
    if (!motion || this.lastVisualIdleToken === motion.command.token) return;
    const snapshot = this.requireOrchestrationActor().getSnapshot();
    if (snapshot.context.arrivedNodeId !== motion.command.toNodeId
      || !this.character.isVisuallyIdle()) return;
    this.lastVisualIdleToken = motion.command.token;
    this.emitTransition("motion-visual-idle", motion.command.token, motion.command.toNodeId);
    this.sceneRuntimePort.publish({
      type: "MOTION.VISUAL_IDLE",
      sessionRevision: this.recoverySessionRevision,
      transactionId: motion.command.transactionId,
      operationId: motion.command.operationId,
      attemptId: motion.command.attemptId,
      attempt: motion.command.attempt,
      nodeId: motion.command.toNodeId,
    });
  }

  private isCurrentPresentationCommand(commandId: string): boolean {
    const recoveryCommand = this.currentRecoveryCommand();
    if (recoveryCommand?.type === "RECOVERY.COMPENSATE_PRESENTATION"
      && recoveryCommand.attemptId === commandId) return true;
    const context = this.requireOrchestrationActor().getSnapshot().context;
    return commandId === context.navigationCommandToken
      || commandId === context.zoneRevealCommandToken
      || commandId === context.zoneDismissCommandToken;
  }

  private handlePresentationEvent(event: PresentationCoordinatorEvent): void {
    const recoveryCommand = this.currentRecoveryCommand();
    const isRecoveryPresentation = recoveryCommand?.type
      === "RECOVERY.COMPENSATE_PRESENTATION"
      && recoveryCommand.attemptId === event.commandId;
    const isCurrentCommand = this.isCurrentPresentationCommand(event.commandId);
    const isCurrentIntent = this.presentation.isCurrentCommand(
      event.commandId,
      event.objectKind,
      event.objectId,
    );
    if (event.type === "PRESENTATION.STARTED") {
      if (!isCurrentIntent) {
        this.emitTransition("stale-event-ignored", event.commandId, "presentation STARTED");
        return;
      }
      this.sceneRuntimePort.publish({
        type: "PRESENTATION.STARTED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: event.transactionId,
        operationId: event.operationId,
        attemptId: event.commandId,
        attempt: event.attempt,
      });
      this.emitTransition("presentation-started", event.objectId, event.commandId);
      return;
    }
    if (event.type === "PRESENTATION.PHASE") {
      if (!isCurrentIntent) {
        this.emitTransition("stale-event-ignored", event.commandId, "presentation PHASE");
        return;
      }
      this.diagnosticLedger.acceptPresentationEvent(event);
      return;
    }

    if (event.type === "PRESENTATION.FAILED") {
      if (!isCurrentIntent || !isCurrentCommand) {
        this.emitTransition("stale-event-ignored", event.commandId, "presentation failure");
        return;
      }
      this.emitTransition(
        "presentation-failed",
        event.objectId,
        `${event.commandId}; ${event.error}`,
      );
      this.sceneRuntimePort.publish({
        type: "PRESENTATION.FAILED",
        sessionRevision: this.recoverySessionRevision,
        transactionId: event.transactionId,
        operationId: event.operationId,
        attemptId: event.commandId,
        attempt: event.attempt,
        error: event.error,
      });
      if (isRecoveryPresentation && recoveryCommand) {
        this.sendRecoveryPresentationAck(recoveryCommand, event, event.error);
        return;
      }
      return;
    }

    if (!isCurrentCommand) {
      this.emitTransition("stale-event-ignored", event.commandId, "presentation ACK");
      return;
    }

    this.diagnosticLedger.acceptPresentationEvent(event);
    this.sceneRuntimePort.publish({
      type: "PRESENTATION.SETTLED",
      sessionRevision: this.recoverySessionRevision,
      transactionId: event.transactionId,
      operationId: event.operationId,
      attemptId: event.commandId,
      attempt: event.attempt,
      result: {
        objectKind: event.objectKind,
        objectId: event.objectId,
        terminal: event.terminal,
      },
    });
    this.emitTransition(
      "presentation-settled",
      event.objectId,
      `${event.commandId}; ${event.terminal}`,
    );
    if (!isRecoveryPresentation) {
      this.recoveryBoundaryStore.terminal(event.transactionId, event.operationId);
    }
    this.onPresentationSettled?.(event);
    if (isRecoveryPresentation && recoveryCommand) {
      this.sendRecoveryPresentationAck(recoveryCommand, event);
      return;
    }
  }

  private prepareRecoveryInput(request: RecoveryRequest): RecoveryMachineInput {
    if (this.activeRecoveryInput?.recoveryId === request.recoveryId) {
      return this.activeRecoveryInput;
    }
    if (this.activeRecoveryInput) {
      throw new Error(
        `Recovery "${this.activeRecoveryInput.recoveryId}" is already active.`,
      );
    }
    const input = this.recoveryBoundaryStore.prepare({
      recoveryId: request.recoveryId,
      sessionRevision: this.recoverySessionRevision,
      transactionId: request.transactionId,
      safeNodeId: request.safeNodeId,
    });
    if (request.kind === "presentation-failed"
      || request.kind === "presentation-timeout") {
      const context = this.requireOrchestrationActor().getSnapshot().context;
      if (context.zoneRevealPlan !== null) {
        this.zoneRevealFailureLatchNodeId = request.safeNodeId;
      }
    }
    this.emitTransition(
      "recovery-started",
      request.recoveryId,
      `${request.kind}; steps=${input.journal.length}`,
    );
    this.activeRecoveryInput = input;
    this.activeRecoveryCommand = null;
    this.lastExecutedRecoveryAttemptId = null;
    return input;
  }

  private currentRecoveryCommand(): RecoveryCommand | null {
    return this.activeRecoveryCommand;
  }

  private executeRecoveryCommand(command: RecoveryCommand): void {
    const input = this.activeRecoveryInput;
    if (!input
      || input.recoveryId !== command.recoveryId
      || input.sessionRevision !== command.sessionRevision
      || input.transactionId !== command.transactionId) {
      this.emitTransition(
        "stale-event-ignored",
        command.attemptId,
        "recovery command",
      );
      return;
    }
    if (command.attemptId === this.lastExecutedRecoveryAttemptId) return;
    this.lastExecutedRecoveryAttemptId = command.attemptId;
    this.activeRecoveryCommand = command;
    this.dispatchRecoveryCommand(command);
  }

  private dispatchRecoveryCommand(command: RecoveryCommand): void {
    try {
      if (command.type === "RECOVERY.CANCEL_PRESENTATION") {
        this.presentation.cancelTransaction(command.transactionId);
        this.deferredPresentations.clear();
        this.sendRecoveryCommandResult(command);
        return;
      }
      if (command.type === "RECOVERY.ABORT_MOTION") {
        this.motionDeliveryLease = null;
        this.lastVisualIdleToken = null;
        if (!this.simulation.abortToNode(command.safeNodeId)) {
          this.sendRecoveryCommandResult(
            command,
            `Cannot restore safe node "${command.safeNodeId}".`,
          );
          return;
        }
        this.character.debugRecoverStalledAnimation("transaction-recovery");
        this.sendRecoveryCommandResult(command);
        return;
      }
      if (command.type === "RECOVERY.COMPENSATE_PRESENTATION") {
        const { entry } = command;
        const presentationCommand = Object.freeze({
          commandId: command.attemptId,
          transactionId: command.transactionId,
          operationId: command.operationId,
          attempt: command.attempt,
          objectId: entry.objectId,
          objectKind: entry.objectKind,
          visible: entry.visibleBefore,
          order: entry.objectKind === "overpass" ? entry.order : null,
          metadata: Object.freeze({
            ...entry.metadata,
            reason: "transaction-compensation",
            recoveryId: command.recoveryId,
          }),
        }) as PresentationCommand;
        this.emitTransition(
          "recovery-step",
          entry.objectId,
          `${command.operationId}; ${entry.visibleBefore ? "show" : "hide"}`,
        );
        this.dispatchPresentation(presentationCommand);
        return;
      }
      if (command.type === "RECOVERY.RESTORE_RULE_LEDGER") {
        try {
          this.recoveryBoundaryStore.restore(command.checkpointId);
        } catch (error) {
          this.sendRecoveryCommandResult(
            command,
            error instanceof Error ? error.message : String(error),
          );
          return;
        }
        this.sendRecoveryCommandResult(command);
        return;
      }
      if (this.character.isVisuallyIdle()) {
        this.sendRecoveryCommandResult(command);
      }
    } catch (error) {
      this.sendRecoveryCommandResult(
        command,
        error instanceof Error ? error.message : String(error),
      );
    }
  }

  private sendRecoveryCommandResult(
    command: RecoveryCommand,
    error?: string,
  ): void {
    const correlation = {
      recoveryId: command.recoveryId,
      sessionRevision: command.sessionRevision,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attemptId: command.attemptId,
      attempt: command.attempt,
    };
    if (error) {
      this.requireOrchestrationActor().send({
        type: "RECOVERY.COMMAND.FAILED",
        ...correlation,
        error,
      });
    } else {
      this.requireOrchestrationActor().send({
        type: "RECOVERY.COMMAND.SUCCEEDED",
        ...correlation,
      });
    }
  }

  private sendRecoveryPresentationAck(
    command: Extract<RecoveryCommand, { readonly type: "RECOVERY.COMPENSATE_PRESENTATION" }>,
    event: Exclude<PresentationCoordinatorEvent, { readonly type: "PRESENTATION.PHASE" }>,
    error?: string,
  ): void {
    const correlation = {
      recoveryId: command.recoveryId,
      sessionRevision: command.sessionRevision,
      transactionId: event.transactionId,
      operationId: event.operationId,
      attemptId: event.commandId,
      attempt: event.attempt,
    };
    if (error) {
      this.requireOrchestrationActor().send({
        type: "RECOVERY.COMMAND.FAILED",
        ...correlation,
        error,
      });
    } else {
      this.requireOrchestrationActor().send({
        type: "RECOVERY.COMMAND.SUCCEEDED",
        ...correlation,
      });
    }
  }

  private acknowledgeRecoveryCharacterIdle(): void {
    if (!this.character.isVisuallyIdle()) return;
    const command = this.currentRecoveryCommand();
    if (command?.type === "RECOVERY.AWAIT_CHARACTER_IDLE") {
      this.sendRecoveryCommandResult(command);
    }
  }

  private finalizeRecovery(
    request: RecoveryRequest,
    outcome: RecoveryMachineOutput,
  ): void {
    const input = this.activeRecoveryInput;
    if (!input || input.recoveryId !== request.recoveryId) return;
    if (outcome.status === "succeeded") {
      this.completeRecovery(request, outcome);
      return;
    }
    if (outcome.status === "degraded") {
      this.failRecovery(request, outcome);
      return;
    }
    this.clearRecoveryAdapterState();
  }

  private completeRecovery(
    request: RecoveryRequest,
    outcome: Extract<RecoveryMachineOutput, { readonly status: "succeeded" }>,
  ): void {
    const zoneStatus = this.coordinator.getDebugSnapshot().zones.some(
      (zone) => zone.sessionState === "active",
    ) ? "active" as const : "inactive" as const;
    const notice = {
      type: "ORCHESTRATION.RECOVERY.COMPLETE" as const,
      recoveryId: request.recoveryId,
      transactionId: request.transactionId,
      nodeId: outcome.safeNodeId,
      zoneStatus,
      compensatedOperationCount: outcome.compensatedOperationCount,
    };
    this.emitTransition(
      "recovery-complete",
      request.recoveryId,
      `compensated=${outcome.compensatedOperationCount}`,
    );
    this.clearRecoveryAdapterState();
    this.recoveryBoundaryStore.complete(request.transactionId);
    this.requireOrchestrationActor().send(notice);
  }

  private failRecovery(
    request: RecoveryRequest,
    outcome: Extract<RecoveryMachineOutput, { readonly status: "degraded" }>,
  ): void {
    this.presentation.cancelTransaction(request.transactionId);
    this.deferredPresentations.clear();
    this.motionDeliveryLease = null;
    this.lastVisualIdleToken = null;
    this.simulation.abortToNode(outcome.safeNodeId);
    this.character.debugRecoverStalledAnimation("recovery-failed");
    this.emitTransition("recovery-failed", request.recoveryId, outcome.failure.error);
    this.clearRecoveryAdapterState();
    this.recoveryBoundaryStore.complete(request.transactionId);
    this.requireOrchestrationActor().send({
      type: "ORCHESTRATION.RECOVERY.FAILED",
      recoveryId: request.recoveryId,
      transactionId: request.transactionId,
      error: outcome.failure.error,
    });
  }

  private cancelRecoveryAdapter(request: RecoveryRequest): void {
    if (this.activeRecoveryInput
      && this.activeRecoveryInput.recoveryId !== request.recoveryId) return;
    if (!this.activeRecoveryInput
      && this.recoveryBoundaryStore.getSnapshot()?.transactionId
        !== request.transactionId) return;
    this.presentation.cancelTransaction(request.transactionId);
    this.deferredPresentations.clear();
    this.motionDeliveryLease = null;
    this.lastVisualIdleToken = null;
    this.simulation.abortToNode(request.safeNodeId);
    this.character.debugRecoverStalledAnimation("recovery-cancelled");
    this.clearRecoveryAdapterState();
    this.recoveryBoundaryStore.complete(request.transactionId);
  }

  private clearRecoveryAdapterState(): void {
    this.activeRecoveryInput = null;
    this.activeRecoveryCommand = null;
    this.lastExecutedRecoveryAttemptId = null;
  }

  private observeMotionFaultPoint(): void {
    const lease = this.motionDeliveryLease;
    if (!lease
      || lease.arrived
      || lease.progress35Observed
      || this.activeRecoveryInput) return;
    const leg = this.simulation.getSnapshot().activeLeg;
    if (!leg || leg.progress < 0.35) return;
    lease.progress35Observed = true;
    const decision = this.faultInjection.decide({
      point: "motion.progress-35",
      operation: lease.command.operationId,
      attempt: lease.command.attempt,
      transactionId: lease.command.transactionId,
      metadata: { progress: leg.progress, edgeId: leg.edgeId },
    });
    if (decision.kind === "pass") return;
    const detail = decision.kind === "throw"
      ? decision.message
      : `Injected motion ${decision.kind} at 35%.`;
    this.failMotionCommand(lease.command, detail);
  }

  private failMotionCommand(
    command: MotionCommand,
    error: string,
  ): void {
    const active = this.motionDeliveryLease;
    if (active?.command.token === command.token) {
      this.simulation.abortToNode(
        this.recoveryBoundaryStore.getSnapshot()?.safeNodeId ?? command.fromNodeId,
      );
      this.motionDeliveryLease = null;
    }
    this.emitTransition(
      "motion-failed",
      command.operationId,
      error,
    );
    this.sceneRuntimePort.publish({
      type: "MOTION.FAILED",
      sessionRevision: this.recoverySessionRevision,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attemptId: command.attemptId,
      attempt: command.attempt,
      error,
    });
  }

  private observeCharacterWatchdogRecovery(): void {
    const watchdog = this.character.getDebugState().watchdog;
    if (watchdog.timeoutCount <= this.lastCharacterWatchdogTimeoutCount) return;
    this.lastCharacterWatchdogTimeoutCount = watchdog.timeoutCount;
    this.emitTransition(
      "character-watchdog-recovered",
      watchdog.lastRecoveryReason ?? "animation-watchdog",
      `count=${watchdog.timeoutCount}`,
    );
  }

  private syncOccupiedOverpass(): void {
    const leg = this.simulation.getSnapshot().activeLeg;
    const next = leg?.pathKind === "overpass" ? leg.edgeId : null;
    if (next === this.occupiedOverpassId) return;
    this.occupiedOverpassId = next;
    this.diagnosticLedger.setOccupiedOverpass(next);
  }

  private driveIdleZoneRules(): void {
    const snapshot = this.requireOrchestrationActor().getSnapshot();
    if (!isLearningPathNavigationIdle(snapshot)
      || !snapshot.context.characterVisualIdle) return;
    if (isLearningPathZoneInactive(snapshot)) {
      // A failed automatic reveal is latched at the safe node so recovery does
      // not immediately re-enter the same failing transition every frame. Any
      // subsequent navigation request clears the latch after leaving the node.
      if (snapshot.context.currentNodeId === this.zoneRevealFailureLatchNodeId) return;
      this.requireOrchestrationActor().send({
        type: "ZONE.REVEAL.REQUESTED",
        nodeId: snapshot.context.currentNodeId,
      });
      return;
    }
    if (isLearningPathZoneActive(snapshot)) {
      this.requireOrchestrationActor().send({
        type: "ZONE.DISMISS.REQUESTED",
        nodeId: snapshot.context.currentNodeId,
      });
    }
  }

  private findRegisteredBridge(bridgeId: EdgeId): RuntimeBridgeInstance | null {
    return this.coordinator.getDebugSnapshot().bridges.find(
      (bridge) => bridge.bridgeId === bridgeId,
    ) ?? null;
  }

  private requireOverpass(edgeId: EdgeId): OverpassLearningPathEdge {
    const edge = this.edgeById.get(edgeId);
    if (!edge || edge.pathKind !== "overpass") {
      throw new Error(`Unknown overpass "${edgeId}".`);
    }
    return edge;
  }

  /**
   * Atomically registers an actually selected bridge across simulation,
   * presentation and mirror state. Repeated registration is idempotent.
   */
  private registerOverpass(edge: OverpassLearningPathEdge): void {
    const existing = this.edgeById.get(edge.id);
    if (existing) {
      if (existing.pathKind !== "overpass" || JSON.stringify(existing) !== JSON.stringify(edge)) {
        throw new Error(`Runtime edge id "${edge.id}" is already registered.`);
      }
      this.diagnosticLedger.registerOverpass(edge);
      return;
    }

    // Every registrar validates before mutating its own index; the catalog's
    // immutable edge makes retries safe after an interrupted command.
    this.simulation.registerEdge(edge);
    this.presentation.registerEdge(edge);
    this.edgeById.set(edge.id, edge);
    this.diagnosticLedger.registerOverpass(edge);
  }

  private createUniqueCatalog<T extends { readonly id: string }>(
    entries: readonly T[],
    label: string,
  ): Map<string, T> {
    const result = new Map<string, T>();
    entries.forEach((entry) => {
      if (result.has(entry.id)) throw new Error(`Duplicate ${label} id "${entry.id}".`);
      result.set(entry.id, entry);
    });
    return result;
  }

  private emitTransition(
    type: LearningPathRuntimeTransitionNotice["type"],
    objectId: string,
    detail?: string,
  ): void {
    this.onTransition?.(Object.freeze({ type, objectId, ...(detail ? { detail } : {}) }));
  }

  private requireOrchestrationActor(): PathOrchestrationActor {
    this.assertLive();
    if (!this.actor) {
      throw new Error(
        "LearningPathXStateRuntime is not bound to the application-owned orchestration actor.",
      );
    }
    return this.actor;
  }

  private assertLive(): void {
    if (this.disposed) throw new Error("LearningPathXStateRuntime is disposed.");
  }
}
