import * as THREE from "three";

export const MIN_TOUCH_HIT_RADIUS_CSS_PX = 22;
const PAN_GESTURE_THRESHOLD_CSS_PX = 6;
const HOVER_STABILITY_RADIUS_CSS_PX = 64;

export type PathKeyboardCommand =
  | "left"
  | "right"
  | "up"
  | "down"
  | "home"
  | "end";

export interface PathInputOptions {
  readonly canvas: HTMLCanvasElement;
  readonly camera: THREE.Camera;
  readonly pickTargets: readonly THREE.Object3D[];
  readonly nodeCount: number;
  readonly initialNodeIndex: number;
  readonly resolveNodeIndex: (object: THREE.Object3D | null) => number | null;
  readonly resolveKeyboardIndex: (
    fromNodeIndex: number,
    command: PathKeyboardCommand,
  ) => number | null;
  readonly isNodeVisible?: (nodeIndex: number) => boolean;
  readonly onActivate: (nodeIndex: number) => void;
  readonly onBackgroundActivate?: () => void;
  readonly onPanByPixels?: (deltaX: number, deltaY: number) => void;
  readonly onHover: (nodeIndex: number | null) => void;
  readonly onPress: (nodeIndex: number | null) => void;
  readonly onKeyboardSelection: (nodeIndex: number) => void;
}

export class PathInputController {
  private readonly canvas: HTMLCanvasElement;
  private readonly camera: THREE.Camera;
  private readonly pickTargets: readonly THREE.Object3D[];
  private readonly nodeCount: number;
  private readonly resolveNodeIndex: PathInputOptions["resolveNodeIndex"];
  private readonly resolveKeyboardIndex: PathInputOptions["resolveKeyboardIndex"];
  private readonly isNodeVisibleOverride: PathInputOptions["isNodeVisible"];
  private readonly onActivate: PathInputOptions["onActivate"];
  private readonly onBackgroundActivate: PathInputOptions["onBackgroundActivate"];
  private readonly onPanByPixels: PathInputOptions["onPanByPixels"];
  private readonly onHover: PathInputOptions["onHover"];
  private readonly onPress: PathInputOptions["onPress"];
  private readonly onKeyboardSelection: PathInputOptions["onKeyboardSelection"];
  private readonly raycaster = new THREE.Raycaster();
  private readonly pointer = new THREE.Vector2();
  private readonly projectedTargetPosition = new THREE.Vector3();
  private keyboardIndex: number;
  private hoveredIndex: number | null = null;
  private hoverLatchClientX = 0;
  private hoverLatchClientY = 0;
  private pressedIndex: number | null = null;
  private capturedPointerId: number | null = null;
  private pointerStartX = 0;
  private pointerStartY = 0;
  private pointerLastX = 0;
  private pointerLastY = 0;
  private isPanning = false;
  private enabled = false;

  public constructor(options: PathInputOptions) {
    this.canvas = options.canvas;
    this.camera = options.camera;
    this.pickTargets = options.pickTargets;
    this.nodeCount = options.nodeCount;
    this.keyboardIndex = options.initialNodeIndex;
    this.resolveNodeIndex = options.resolveNodeIndex;
    this.resolveKeyboardIndex = options.resolveKeyboardIndex;
    this.isNodeVisibleOverride = options.isNodeVisible;
    this.onActivate = options.onActivate;
    this.onBackgroundActivate = options.onBackgroundActivate;
    this.onPanByPixels = options.onPanByPixels;
    this.onHover = options.onHover;
    this.onPress = options.onPress;
    this.onKeyboardSelection = options.onKeyboardSelection;
    this.raycaster.layers.set(1);

    this.canvas.addEventListener("pointermove", this.handlePointerMove);
    this.canvas.addEventListener("pointerdown", this.handlePointerDown);
    this.canvas.addEventListener("pointerup", this.handlePointerUp);
    this.canvas.addEventListener("pointercancel", this.handlePointerCancel);
    this.canvas.addEventListener("pointerleave", this.handlePointerLeave);
    this.canvas.addEventListener("lostpointercapture", this.handleLostPointerCapture);
    this.canvas.addEventListener("wheel", this.handleWheel, { passive: false });
    this.canvas.addEventListener("keydown", this.handleKeyDown);
    this.canvas.addEventListener("focus", this.handleFocus);
    this.canvas.addEventListener("blur", this.handleBlur);
    this.canvas.setAttribute("aria-disabled", "true");
    this.canvas.dataset.viewportPan = String(this.onPanByPixels !== undefined);
  }

  public setEnabled(value: boolean): void {
    if (this.enabled === value) {
      return;
    }
    this.enabled = value;
    this.canvas.setAttribute("aria-disabled", String(!value));
    if (!value) {
      this.releaseActivePointerCapture();
      this.resetPointerState();
      this.canvas.blur();
    }
  }

  public setKeyboardIndex(nodeIndex: number): void {
    if (
      nodeIndex >= 0
      && nodeIndex < this.nodeCount
      && this.isNodeVisible(nodeIndex)
    ) {
      this.keyboardIndex = nodeIndex;
    }
  }

  public dispose(): void {
    this.releaseActivePointerCapture();
    this.resetPointerState();
    this.enabled = false;
    this.canvas.setAttribute("aria-disabled", "true");
    this.canvas.removeEventListener("pointermove", this.handlePointerMove);
    this.canvas.removeEventListener("pointerdown", this.handlePointerDown);
    this.canvas.removeEventListener("pointerup", this.handlePointerUp);
    this.canvas.removeEventListener("pointercancel", this.handlePointerCancel);
    this.canvas.removeEventListener("pointerleave", this.handlePointerLeave);
    this.canvas.removeEventListener("lostpointercapture", this.handleLostPointerCapture);
    this.canvas.removeEventListener("wheel", this.handleWheel);
    this.canvas.removeEventListener("keydown", this.handleKeyDown);
    this.canvas.removeEventListener("focus", this.handleFocus);
    this.canvas.removeEventListener("blur", this.handleBlur);
  }

  private readonly handlePointerMove = (event: PointerEvent): void => {
    if (!this.enabled) {
      return;
    }
    if (this.capturedPointerId === event.pointerId && event.buttons !== 0) {
      const totalDistance = Math.hypot(
        event.clientX - this.pointerStartX,
        event.clientY - this.pointerStartY,
      );
      if (!this.isPanning
        && this.onPanByPixels !== undefined
        && totalDistance >= PAN_GESTURE_THRESHOLD_CSS_PX) {
        this.isPanning = true;
        this.pressedIndex = null;
        this.onPress(null);
        this.publishHover(null);
        this.canvas.style.cursor = "grabbing";
      }
      const deltaX = event.clientX - this.pointerLastX;
      const deltaY = event.clientY - this.pointerLastY;
      this.pointerLastX = event.clientX;
      this.pointerLastY = event.clientY;
      if (this.isPanning) {
        event.preventDefault();
        this.onPanByPixels?.(-deltaX, -deltaY);
      }
      return;
    }
    if (event.pointerType !== "mouse" && event.buttons === 0) {
      return;
    }
    const nodeIndex = this.pickNode(event);
    if (nodeIndex === null
      && event.pointerType === "mouse"
      && this.hoveredIndex !== null
      && Math.hypot(
        event.clientX - this.hoverLatchClientX,
        event.clientY - this.hoverLatchClientY,
      ) < HOVER_STABILITY_RADIUS_CSS_PX) {
      this.canvas.style.cursor = "pointer";
      return;
    }
    if (nodeIndex !== null) {
      this.hoverLatchClientX = event.clientX;
      this.hoverLatchClientY = event.clientY;
    }
    this.canvas.style.cursor = nodeIndex === null && this.onPanByPixels ? "grab" : nodeIndex === null ? "default" : "pointer";
    this.publishHover(nodeIndex);
  };

  private readonly handlePointerDown = (event: PointerEvent): void => {
    if (!this.enabled || event.button !== 0) {
      return;
    }
    this.pressedIndex = this.pickNode(event);
    this.pointerStartX = event.clientX;
    this.pointerStartY = event.clientY;
    this.pointerLastX = event.clientX;
    this.pointerLastY = event.clientY;
    this.isPanning = false;
    this.onPress(this.pressedIndex);
    this.canvas.setPointerCapture(event.pointerId);
    this.capturedPointerId = event.pointerId;
    this.canvas.focus({ preventScroll: true });
  };

  private readonly handlePointerUp = (event: PointerEvent): void => {
    if (!this.enabled) {
      this.resetPointerState();
      return;
    }
    const wasPanning = this.isPanning;
    const releasedIndex = wasPanning ? null : this.pickNode(event);
    const shouldActivate = !wasPanning && releasedIndex !== null && releasedIndex === this.pressedIndex;
    this.pressedIndex = null;
    this.isPanning = false;
    this.onPress(null);

    if (this.canvas.hasPointerCapture(event.pointerId)) {
      this.canvas.releasePointerCapture(event.pointerId);
    }
    if (this.capturedPointerId === event.pointerId) {
      this.capturedPointerId = null;
    }
    if (shouldActivate) {
      this.keyboardIndex = releasedIndex;
      this.onActivate(releasedIndex);
    } else if (!wasPanning && releasedIndex === null) {
      this.onBackgroundActivate?.();
    }
    this.canvas.style.cursor = releasedIndex === null && this.onPanByPixels ? "grab" : releasedIndex === null ? "default" : "pointer";
  };

  private readonly handlePointerCancel = (event: PointerEvent): void => {
    if (this.canvas.hasPointerCapture(event.pointerId)) {
      this.canvas.releasePointerCapture(event.pointerId);
    }
    if (this.capturedPointerId === event.pointerId) {
      this.capturedPointerId = null;
    }
    this.resetPointerState();
  };

  private readonly handlePointerLeave = (): void => {
    if (this.capturedPointerId === null) {
      this.resetPointerState();
    }
  };

  private readonly handleLostPointerCapture = (): void => {
    this.capturedPointerId = null;
    this.resetPointerState();
  };

  private readonly handleWheel = (event: WheelEvent): void => {
    if (!this.enabled || !this.onPanByPixels) return;
    event.preventDefault();
    const linePixels = 18;
    const pagePixels = Math.max(1, this.canvas.clientHeight * 0.84);
    const multiplier = event.deltaMode === event.DOM_DELTA_LINE
      ? linePixels
      : event.deltaMode === event.DOM_DELTA_PAGE
        ? pagePixels
        : 1;
    let deltaX = event.deltaX * multiplier;
    let deltaY = event.deltaY * multiplier;
    if (event.shiftKey && Math.abs(deltaX) < 0.01) {
      deltaX = deltaY;
      deltaY = 0;
    }
    const maximumDelta = Math.max(this.canvas.clientWidth, this.canvas.clientHeight, 1);
    this.publishHover(null);
    this.onPanByPixels(
      Math.max(-maximumDelta, Math.min(maximumDelta, deltaX)),
      Math.max(-maximumDelta, Math.min(maximumDelta, deltaY)),
    );
    this.canvas.style.cursor = "grab";
  };

  private readonly handleKeyDown = (event: KeyboardEvent): void => {
    if (!this.enabled) {
      return;
    }
    switch (event.key) {
      case "Enter":
      case " ":
        event.preventDefault();
        if (this.isNodeVisible(this.keyboardIndex)) {
          this.onActivate(this.keyboardIndex);
        }
        return;
    }

    const command = this.getKeyboardCommand(event.key);
    if (command === null) {
      return;
    }

    event.preventDefault();
    const previous = this.keyboardIndex;
    const resolvedIndex = this.resolveKeyboardIndex(previous, command);
    if (
      resolvedIndex !== null
      && Number.isInteger(resolvedIndex)
      && resolvedIndex >= 0
      && resolvedIndex < this.nodeCount
      && this.isNodeVisible(resolvedIndex)
    ) {
      this.keyboardIndex = resolvedIndex;
    }
    if (previous !== this.keyboardIndex) {
      this.publishHover(this.keyboardIndex);
      this.onKeyboardSelection(this.keyboardIndex);
    }
  };

  private readonly handleFocus = (): void => {
    if (!this.enabled) {
      return;
    }
    if (!this.isNodeVisible(this.keyboardIndex)) {
      this.publishHover(null);
      return;
    }
    this.publishHover(this.keyboardIndex);
    this.onKeyboardSelection(this.keyboardIndex);
  };

  private readonly handleBlur = (): void => {
    this.resetPointerState();
  };

  private resetPointerState(): void {
    this.pressedIndex = null;
    this.isPanning = false;
    this.publishHover(null);
    this.onPress(null);
    this.canvas.style.cursor = this.onPanByPixels ? "grab" : "default";
  }

  private publishHover(nodeIndex: number | null): void {
    if (this.hoveredIndex === nodeIndex) return;
    this.hoveredIndex = nodeIndex;
    this.onHover(nodeIndex);
  }

  private releaseActivePointerCapture(): void {
    const pointerId = this.capturedPointerId;
    this.capturedPointerId = null;
    if (pointerId !== null && this.canvas.hasPointerCapture(pointerId)) {
      this.canvas.releasePointerCapture(pointerId);
    }
  }

  private getKeyboardCommand(key: string): PathKeyboardCommand | null {
    switch (key) {
      case "ArrowLeft":
        return "left";
      case "ArrowRight":
        return "right";
      case "ArrowUp":
        return "up";
      case "ArrowDown":
        return "down";
      case "Home":
        return "home";
      case "End":
        return "end";
      default:
        return null;
    }
  }

  private pickNode(event: PointerEvent): number | null {
    const bounds = this.canvas.getBoundingClientRect();
    this.pointer.set(
      ((event.clientX - bounds.left) / bounds.width) * 2 - 1,
      -((event.clientY - bounds.top) / bounds.height) * 2 + 1,
    );
    this.raycaster.setFromCamera(this.pointer, this.camera);
    const visiblePickTargets = this.pickTargets.filter((target) => (
      this.isPickTargetVisible(target)
    ));
    const intersection = this.raycaster.intersectObjects(visiblePickTargets, false)[0];

    if (event.pointerType === "touch" || event.pointerType === "pen") {
      const nearestTouchTarget = this.pickNearestTouchTarget(event, bounds);
      if (nearestTouchTarget !== null) {
        return nearestTouchTarget;
      }
    }

    return this.resolveNodeIndex(intersection?.object ?? null);
  }

  private pickNearestTouchTarget(
    event: PointerEvent,
    bounds: DOMRect,
  ): number | null {
    const pointerX = event.clientX - bounds.left;
    const pointerY = event.clientY - bounds.top;
    const radiusSquared = MIN_TOUCH_HIT_RADIUS_CSS_PX ** 2;
    let nearestTarget: THREE.Object3D | null = null;
    let nearestDistanceSquared = Number.POSITIVE_INFINITY;

    for (const target of this.pickTargets) {
      if (!this.isPickTargetVisible(target)) {
        continue;
      }
      target.getWorldPosition(this.projectedTargetPosition).project(this.camera);
      if (
        this.projectedTargetPosition.z < -1
        || this.projectedTargetPosition.z > 1
      ) {
        continue;
      }

      const targetX = (this.projectedTargetPosition.x + 1) * 0.5 * bounds.width;
      const targetY = (1 - this.projectedTargetPosition.y) * 0.5 * bounds.height;
      const dx = pointerX - targetX;
      const dy = pointerY - targetY;
      const distanceSquared = dx * dx + dy * dy;
      if (
        distanceSquared <= radiusSquared
        && distanceSquared < nearestDistanceSquared
      ) {
        nearestTarget = target;
        nearestDistanceSquared = distanceSquared;
      }
    }

    return this.resolveNodeIndex(nearestTarget);
  }

  private isPickTargetVisible(target: THREE.Object3D): boolean {
    if (!target.visible || target.userData.pathNodeVisible === false) {
      return false;
    }
    const nodeIndex = this.resolveNodeIndex(target);
    return nodeIndex !== null && (
      this.isNodeVisibleOverride?.(nodeIndex) ?? true
    );
  }

  private isNodeVisible(nodeIndex: number): boolean {
    if (this.isNodeVisibleOverride) {
      return this.isNodeVisibleOverride(nodeIndex);
    }
    return this.pickTargets.some((target) => (
      this.resolveNodeIndex(target) === nodeIndex
      && target.visible
      && target.userData.pathNodeVisible !== false
    ));
  }
}
