import type {
  EdgeId,
  LearningPathEdge,
  LearningPathGraph,
  NodeId,
  OverpassLearningPathEdge,
  PathKind,
  PathPosition,
} from "../config/pathData";
import { OVERPASS_ARCH_SHOULDER_RUN } from "../config/overpassSpec";

export const NODE_PATH_SURFACE_Y = 0.523;
export const STRAIGHT_PATH_SURFACE_Y = 0.026;
export const STRAIGHT_PATH_WIDTH = 0.64;
export const STRAIGHT_STEP_TOP_DISTANCE = 0.52;
export const STRAIGHT_STEP_BASE_DISTANCE = 0.82;
export const MINIMUM_PATH_LUT_SEGMENTS = 160;
export const DEFAULT_PATH_LUT_SEGMENTS = 256;

const GEOMETRY_EPSILON = 0.000_001;
const CLEARANCE_AUDIT_SEGMENTS = 4096;

export interface PathPoint3D {
  readonly x: number;
  readonly y: number;
  readonly z: number;
}

export interface PathGeometrySample {
  /** Canonical source-curve parameter, not an arc-length percentage. */
  readonly sourceT: number;
  /** Canonical fromNodeId -> toNodeId 3D arc-length percentage. */
  readonly normalizedDistance: number;
  readonly distance: number;
  readonly position: PathPoint3D;
  readonly tangent: PathPoint3D;
  readonly surfaceY: number;
}

export interface RoutePathSample extends PathGeometrySample {
  readonly edgeId: EdgeId;
  readonly pathKind: PathKind;
  /** Traversal endpoints; these reverse when the edge is sampled backwards. */
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly canonicalNormalizedDistance: number;
}

export interface ClearanceAudit {
  readonly overpassEdgeId: EdgeId;
  readonly underpassEdgeId: EdgeId;
  readonly requiredClearance: number;
  readonly minimumClearance: number;
  readonly bridgeBottomY: number;
  readonly underpassSurfaceY: number;
  readonly crossingSourceT: number;
  readonly underpassCrossingSourceT: number;
  readonly overlapStartT: number;
  readonly overlapEndT: number;
  readonly bridgeSurfaceY: number;
  readonly isSymmetric: boolean;
  readonly passed: boolean;
}

export interface OverpassProfileAudit {
  readonly edgeId: EdgeId;
  readonly maximumSurfacePitchDegrees: number;
  readonly allowedSurfacePitchDegrees: number;
  readonly maximumSymmetryError: number;
  readonly isSymmetric: boolean;
  readonly passed: boolean;
}

export interface CompiledEdgePath {
  readonly edge: LearningPathEdge;
  readonly id: EdgeId;
  readonly pathKind: PathKind;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  /** True three-dimensional arc length, including elevation changes. */
  readonly length: number;
  readonly lutSegments: number;
  /** Uniform source-t samples carrying cumulative true-arc-length metadata. */
  readonly samples: readonly PathGeometrySample[];
  /** All configured underpass audits for this edge. Empty for ordinary paths. */
  readonly clearanceAudits: readonly ClearanceAudit[];
  /** @deprecated Compatibility alias for the first clearance audit, if any. */
  readonly clearanceAudit: ClearanceAudit | null;
  /** Samples canonical fromNodeId -> toNodeId by normalized 3D arc distance. */
  sample(normalizedDistance: number): PathGeometrySample;
}

export interface PathGeometryRegistryOptions {
  readonly lutSegments?: number;
}

interface EvaluatedCurvePoint {
  readonly position: PathPoint3D;
  readonly derivative: PathPoint3D;
}

type CurveEvaluator = (sourceT: number) => EvaluatedCurvePoint;

class CompiledEdgePathRuntime implements CompiledEdgePath {
  public readonly id: EdgeId;
  public readonly pathKind: PathKind;
  public readonly fromNodeId: NodeId;
  public readonly toNodeId: NodeId;
  public readonly length: number;
  public readonly samples: readonly PathGeometrySample[];
  public readonly clearanceAudits: ClearanceAudit[] = [];
  public clearanceAudit: ClearanceAudit | null = null;

  public constructor(
    public readonly edge: LearningPathEdge,
    public readonly lutSegments: number,
    private readonly evaluateCurve: CurveEvaluator,
  ) {
    this.id = edge.id;
    this.pathKind = edge.pathKind;
    this.fromNodeId = edge.fromNodeId;
    this.toNodeId = edge.toNodeId;

    const samples: PathGeometrySample[] = [];
    let cumulativeDistance = 0;
    let previousPosition: PathPoint3D | null = null;

    for (let index = 0; index <= lutSegments; index += 1) {
      const sourceT = index / lutSegments;
      const evaluated = evaluateCurve(sourceT);
      if (previousPosition !== null) {
        cumulativeDistance += distance3D(previousPosition, evaluated.position);
      }
      samples.push({
        sourceT,
        normalizedDistance: 0,
        distance: cumulativeDistance,
        position: evaluated.position,
        tangent: normalize3D(evaluated.derivative),
        surfaceY: evaluated.position.y,
      });
      previousPosition = evaluated.position;
    }

    if (!Number.isFinite(cumulativeDistance) || cumulativeDistance <= GEOMETRY_EPSILON) {
      throw new Error(`Path edge "${edge.id}" has zero or non-finite 3D length.`);
    }

    this.length = cumulativeDistance;
    this.samples = Object.freeze(samples.map((sample) => Object.freeze({
      ...sample,
      normalizedDistance: sample.distance / cumulativeDistance,
    })));
  }

  public sample(normalizedDistance: number): PathGeometrySample {
    assertFinite(normalizedDistance, `Normalized distance for edge "${this.id}"`);
    const clampedDistance = clamp01(normalizedDistance);
    const rightIndex = this.findRightSampleIndex(clampedDistance);
    const right = this.samples[rightIndex]!;
    const left = this.samples[Math.max(0, rightIndex - 1)]!;
    const span = right.normalizedDistance - left.normalizedDistance;
    const fraction = span > GEOMETRY_EPSILON
      ? (clampedDistance - left.normalizedDistance) / span
      : 0;
    const sourceT = lerp(left.sourceT, right.sourceT, fraction);
    const evaluated = this.evaluateCurve(sourceT);

    return {
      sourceT,
      normalizedDistance: clampedDistance,
      distance: clampedDistance * this.length,
      position: evaluated.position,
      tangent: normalize3D(evaluated.derivative),
      surfaceY: evaluated.position.y,
    };
  }

  public sampleSourceT(sourceT: number): EvaluatedCurvePoint {
    return this.evaluateCurve(clamp01(sourceT));
  }

  private findRightSampleIndex(normalizedDistance: number): number {
    let low = 0;
    let high = this.samples.length - 1;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (this.samples[middle]!.normalizedDistance < normalizedDistance) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    return low;
  }
}

/**
 * Registers the complete graph and compiles arc-length paths on first use.
 * Straight roads are naturally warmed by the view, while the O(V²) candidate
 * bridge catalogue stays definition-only until a rule actually selects a
 * bridge. Rendering and movement still consume the exact same cached curve.
 */
export class PathGeometryRegistry {
  public readonly lutSegments: number;

  private readonly edgeById = new Map<EdgeId, LearningPathEdge>();
  private readonly nodeById: ReadonlyMap<NodeId, { readonly position: PathPosition }>;
  private readonly compiledById = new Map<EdgeId, CompiledEdgePathRuntime>();
  private readonly clearanceAudits: ClearanceAudit[] = [];
  private readonly overpassProfileAudits: OverpassProfileAudit[] = [];

  public constructor(
    graph: LearningPathGraph,
    options: PathGeometryRegistryOptions = {},
  ) {
    const requestedSegments = options.lutSegments ?? DEFAULT_PATH_LUT_SEGMENTS;
    if (
      !Number.isInteger(requestedSegments)
      || requestedSegments < MINIMUM_PATH_LUT_SEGMENTS
    ) {
      throw new Error(
        `Path LUT segments must be an integer >= ${MINIMUM_PATH_LUT_SEGMENTS}.`,
      );
    }
    this.lutSegments = requestedSegments;

    this.nodeById = this.validateNodes(graph);
    this.validateEdgeIdentities(graph, this.nodeById);
    graph.edges.forEach((edge) => this.edgeById.set(edge.id, edge));
  }

  public get(edgeId: EdgeId): CompiledEdgePath {
    const compiled = this.compiledById.get(edgeId) ?? this.compile(edgeId);
    if (compiled === null) {
      throw new Error(`Unknown path edge "${edgeId}".`);
    }
    return compiled;
  }

  public tryGet(edgeId: EdgeId): CompiledEdgePath | null {
    return this.compiledById.get(edgeId) ?? this.compile(edgeId);
  }

  /**
   * Adds a lazily materialised runtime edge without compiling its LUT. The
   * operation is idempotent for the same immutable definition and rejects an
   * ID collision before any cache is mutated.
   */
  public registerEdge(edge: LearningPathEdge): boolean {
    const existing = this.edgeById.get(edge.id);
    if (existing) {
      if (existing === edge || areEquivalentEdgeDefinitions(existing, edge)) {
        return false;
      }
      throw new Error(`Path geometry edge id "${edge.id}" is already registered.`);
    }
    if (edge.id.trim().length === 0) {
      throw new Error("Path geometry cannot register an edge with an empty id.");
    }
    if (!this.nodeById.has(edge.fromNodeId) || !this.nodeById.has(edge.toNodeId)) {
      throw new Error(`Path edge "${edge.id}" references a missing endpoint.`);
    }
    if (edge.fromNodeId === edge.toNodeId) {
      throw new Error(`Path edge "${edge.id}" is a self-loop.`);
    }
    if (edge.pathKind === "overpass") {
      this.validateOverpassConfiguration(edge);
      const uniqueUnderpasses = new Set(edge.underpassEdgeIds);
      if (uniqueUnderpasses.size !== edge.underpassEdgeIds.length) {
        throw new Error(`Overpass "${edge.id}" repeats an underpass edge.`);
      }
      edge.underpassEdgeIds.forEach((underpassEdgeId) => {
        if (!this.edgeById.has(underpassEdgeId)) {
          throw new Error(
            `Overpass "${edge.id}" references missing underpass "${underpassEdgeId}".`,
          );
        }
        if (underpassEdgeId === edge.id) {
          throw new Error(`Overpass "${edge.id}" cannot pass under itself.`);
        }
      });
    }
    this.edgeById.set(edge.id, edge);
    return true;
  }

  public sampleRoute(
    edgeId: EdgeId,
    fromNodeId: NodeId,
    normalizedDistance: number,
  ): RoutePathSample {
    const compiled = this.get(edgeId);
    assertFinite(normalizedDistance, `Normalized route distance for edge "${edgeId}"`);
    const routeDistance = clamp01(normalizedDistance);
    const isForward = fromNodeId === compiled.fromNodeId;
    if (!isForward && fromNodeId !== compiled.toNodeId) {
      throw new Error(
        `Node "${fromNodeId}" is not an endpoint of path edge "${edgeId}".`,
      );
    }

    const canonicalNormalizedDistance = isForward
      ? routeDistance
      : 1 - routeDistance;
    const canonical = compiled.sample(canonicalNormalizedDistance);
    const tangentScale = isForward ? 1 : -1;

    return {
      ...canonical,
      edgeId,
      pathKind: compiled.pathKind,
      fromNodeId,
      toNodeId: isForward ? compiled.toNodeId : compiled.fromNodeId,
      normalizedDistance: routeDistance,
      canonicalNormalizedDistance,
      tangent: {
        x: canonical.tangent.x * tangentScale,
        y: canonical.tangent.y * tangentScale,
        z: canonical.tangent.z * tangentScale,
      },
    };
  }

  public getClearanceAudits(): readonly ClearanceAudit[] {
    this.compileAllOverpasses();
    return this.clearanceAudits;
  }

  public getOverpassProfileAudits(): readonly OverpassProfileAudit[] {
    this.compileAllOverpasses();
    return this.overpassProfileAudits;
  }

  /** Number of paths whose LUTs currently occupy memory. */
  public get compiledPathCount(): number {
    return this.compiledById.size;
  }

  private compile(edgeId: EdgeId): CompiledEdgePathRuntime | null {
    const edge = this.edgeById.get(edgeId);
    if (!edge) return null;
    const from = this.nodeById.get(edge.fromNodeId)!;
    const to = this.nodeById.get(edge.toNodeId)!;
    const evaluator = edge.pathKind === "overpass"
      ? this.createOverpassEvaluator(edge, from.position, to.position)
      : this.createStraightEvaluator(from.position, to.position);
    const compiled = new CompiledEdgePathRuntime(edge, this.lutSegments, evaluator);
    // Install before clearance recursion so an underpass may safely resolve
    // this edge without compiling the same object twice.
    this.compiledById.set(edge.id, compiled);
    if (edge.pathKind !== "overpass") return compiled;

    const profileAudit = this.auditOverpassProfile(edge, compiled, this.nodeById);
    this.overpassProfileAudits.push(profileAudit);
    if (!profileAudit.passed) {
      this.compiledById.delete(edge.id);
      throw new Error(
        `Overpass "${edge.id}" profile failed: pitch `
        + `${profileAudit.maximumSurfacePitchDegrees.toFixed(3)}° / `
        + `${profileAudit.allowedSurfacePitchDegrees.toFixed(3)}°, `
        + `symmetry error ${profileAudit.maximumSymmetryError.toExponential(3)}.`,
      );
    }
    edge.underpassEdgeIds.forEach((underpassEdgeId, index) => {
      this.get(underpassEdgeId);
      const audit = this.auditOverpassClearance(edge, underpassEdgeId);
      compiled.clearanceAudits.push(audit);
      if (index === 0) compiled.clearanceAudit = audit;
      this.clearanceAudits.push(audit);
      if (!audit.passed) {
        throw new Error(
          `Overpass "${edge.id}" clearance above "${underpassEdgeId}" `
          + `${audit.minimumClearance.toFixed(3)} is below required `
          + `${audit.requiredClearance.toFixed(3)} `
          + `(bridge t=${audit.crossingSourceT.toFixed(3)}, `
          + `ground t=${audit.underpassCrossingSourceT.toFixed(3)}, `
          + `bottom=${audit.bridgeBottomY.toFixed(3)}, `
          + `ground=${audit.underpassSurfaceY.toFixed(3)}, `
          + `symmetric=${String(audit.isSymmetric)}).`,
        );
      }
    });
    return compiled;
  }

  private compileAllOverpasses(): void {
    for (const edge of this.edgeById.values()) {
      if (edge.pathKind === "overpass") this.get(edge.id);
    }
  }

  private validateNodes(graph: LearningPathGraph): Map<NodeId, { readonly position: PathPosition }> {
    const nodeById = new Map<NodeId, { readonly position: PathPosition }>();
    graph.nodes.forEach((node, index) => {
      if (node.id.trim().length === 0 || nodeById.has(node.id)) {
        throw new Error(`Path geometry has an invalid or duplicate node at index ${index}.`);
      }
      assertFinitePosition(node.position, `Node "${node.id}"`);
      assertFinite(node.surfaceY, `Node "${node.id}" surfaceY`);
      nodeById.set(node.id, node);
    });
    return nodeById;
  }

  private validateEdgeIdentities(
    graph: LearningPathGraph,
    nodeById: ReadonlyMap<NodeId, { readonly position: PathPosition }>,
  ): void {
    const edgeIds = new Set<EdgeId>();
    graph.edges.forEach((edge, index) => {
      if (edge.id.trim().length === 0 || edgeIds.has(edge.id)) {
        throw new Error(`Path geometry has an invalid or duplicate edge at index ${index}.`);
      }
      if (!nodeById.has(edge.fromNodeId) || !nodeById.has(edge.toNodeId)) {
        throw new Error(`Path edge "${edge.id}" references a missing endpoint.`);
      }
      if (edge.fromNodeId === edge.toNodeId) {
        throw new Error(`Path edge "${edge.id}" is a self-loop.`);
      }
      if (edge.pathKind === "overpass") {
        this.validateOverpassConfiguration(edge);
      }
      edgeIds.add(edge.id);
    });

    for (const edge of graph.edges) {
      if (edge.pathKind !== "overpass") {
        continue;
      }
      const uniqueUnderpasses = new Set(edge.underpassEdgeIds);
      if (uniqueUnderpasses.size !== edge.underpassEdgeIds.length) {
        throw new Error(`Overpass "${edge.id}" repeats an underpass edge.`);
      }
      for (const underpassEdgeId of edge.underpassEdgeIds) {
        if (!edgeIds.has(underpassEdgeId)) {
          throw new Error(
            `Overpass "${edge.id}" references missing underpass "${underpassEdgeId}".`,
          );
        }
        if (underpassEdgeId === edge.id) {
          throw new Error(`Overpass "${edge.id}" cannot pass under itself.`);
        }
      }
    }
  }

  private validateOverpassConfiguration(edge: OverpassLearningPathEdge): void {
    for (const [name, value] of [
      ["width", edge.width],
      ["deckThickness", edge.deckThickness],
      ["platformEdgeOffset", edge.platformEdgeOffset],
      ["straightApproachLength", edge.straightApproachLength],
      ["bridgeSurfaceY", edge.bridgeSurfaceY],
      ["maximumSurfacePitchDegrees", edge.maximumSurfacePitchDegrees],
      ["routingCost", edge.routingCost],
      ["requiredClearance", edge.requiredClearance],
    ] as const) {
      assertFinite(value, `Overpass "${edge.id}" ${name}`);
    }
    if (
      edge.width <= 0
      || edge.deckThickness <= 0
      || edge.platformEdgeOffset <= 0
      || edge.straightApproachLength <= 0
      || edge.maximumSurfacePitchDegrees <= 0
      || edge.maximumSurfacePitchDegrees >= 90
      || edge.routingCost <= 0
      || edge.requiredClearance <= 0
    ) {
      throw new Error(`Overpass "${edge.id}" dimensions and clearance must be positive.`);
    }
    if (edge.curveStyle !== "symmetric-eased-arch") {
      throw new Error(`Overpass "${edge.id}" has an unsupported curve style.`);
    }
    if (Math.abs(edge.width - STRAIGHT_PATH_WIDTH) > GEOMETRY_EPSILON) {
      throw new Error(
        `Overpass "${edge.id}" must match the ordinary road width.`,
      );
    }
    if (edge.bridgeSurfaceY <= NODE_PATH_SURFACE_Y) {
      throw new Error(`Overpass "${edge.id}" arch must rise above its endpoints.`);
    }
  }

  private auditOverpassProfile(
    edge: OverpassLearningPathEdge,
    overpass: CompiledEdgePathRuntime,
    nodeById: ReadonlyMap<NodeId, { readonly position: PathPosition }>,
  ): OverpassProfileAudit {
    const from = nodeById.get(edge.fromNodeId)!;
    const to = nodeById.get(edge.toNodeId)!;
    const chordX = to.position.x - from.position.x;
    const chordZ = to.position.z - from.position.z;
    const chordLength = Math.hypot(chordX, chordZ);
    const axisX = chordX / chordLength;
    const axisZ = chordZ / chordLength;
    const sideX = -axisZ;
    const sideZ = axisX;
    const midpointX = (from.position.x + to.position.x) / 2;
    const midpointZ = (from.position.z + to.position.z) / 2;
    const centralArchInset = edge.platformEdgeOffset + edge.straightApproachLength;
    let maximumSymmetryError = 0;
    let maximumSurfacePitchRadians = 0;

    overpass.samples.forEach((sample, index) => {
      const mirror = overpass.samples[overpass.samples.length - 1 - index]!;
      const sampleOffsetX = sample.position.x - midpointX;
      const sampleOffsetZ = sample.position.z - midpointZ;
      const mirrorOffsetX = mirror.position.x - midpointX;
      const mirrorOffsetZ = mirror.position.z - midpointZ;
      const sampleAlong = sampleOffsetX * axisX + sampleOffsetZ * axisZ;
      const mirrorAlong = mirrorOffsetX * axisX + mirrorOffsetZ * axisZ;
      const sampleSide = sampleOffsetX * sideX + sampleOffsetZ * sideZ;
      const mirrorSide = mirrorOffsetX * sideX + mirrorOffsetZ * sideZ;
      const sampleTangentAlong = sample.tangent.x * axisX + sample.tangent.z * axisZ;
      const mirrorTangentAlong = mirror.tangent.x * axisX + mirror.tangent.z * axisZ;
      const sampleTangentSide = sample.tangent.x * sideX + sample.tangent.z * sideZ;
      const mirrorTangentSide = mirror.tangent.x * sideX + mirror.tangent.z * sideZ;
      maximumSymmetryError = Math.max(
        maximumSymmetryError,
        Math.abs(sample.surfaceY - mirror.surfaceY),
        Math.abs(sampleAlong + mirrorAlong),
        Math.abs(sampleSide - mirrorSide),
        Math.abs(sampleTangentAlong - mirrorTangentAlong),
        Math.abs(sampleTangentSide + mirrorTangentSide),
        Math.abs(sample.tangent.y + mirror.tangent.y),
      );
      const distanceFromStart = sampleAlong + chordLength / 2;
      if (
        distanceFromStart + GEOMETRY_EPSILON >= centralArchInset
        && distanceFromStart - GEOMETRY_EPSILON <= chordLength - centralArchInset
      ) {
        maximumSurfacePitchRadians = Math.max(
          maximumSurfacePitchRadians,
          Math.atan2(
            Math.abs(sample.tangent.y),
            Math.hypot(sample.tangent.x, sample.tangent.z),
          ),
        );
      }
    });

    const maximumSurfacePitchDegrees = maximumSurfacePitchRadians * 180 / Math.PI;
    const isSymmetric = maximumSymmetryError <= 0.000_01;
    const passed = isSymmetric
      && maximumSurfacePitchDegrees <= edge.maximumSurfacePitchDegrees + 0.000_01;
    return Object.freeze({
      edgeId: edge.id,
      maximumSurfacePitchDegrees,
      allowedSurfacePitchDegrees: edge.maximumSurfacePitchDegrees,
      maximumSymmetryError,
      isSymmetric,
      passed,
    });
  }

  private createStraightEvaluator(
    from: PathPosition,
    to: PathPosition,
  ): CurveEvaluator {
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const horizontalLength = Math.hypot(dx, dz);
    if (!Number.isFinite(horizontalLength) || horizontalLength <= GEOMETRY_EPSILON) {
      throw new Error("Straight path endpoints must not coincide.");
    }

    return (sourceT) => {
      const t = clamp01(sourceT);
      const distanceFromNode = Math.min(t, 1 - t) * horizontalLength;
      const stepT = (
        distanceFromNode - STRAIGHT_STEP_TOP_DISTANCE
      ) / (
        STRAIGHT_STEP_BASE_DISTANCE - STRAIGHT_STEP_TOP_DISTANCE
      );
      const clampedStepT = clamp01(stepT);
      const nodeSupport = 1 - smootherStep(clampedStepT);
      const surfaceY = lerp(
        STRAIGHT_PATH_SURFACE_Y,
        NODE_PATH_SURFACE_Y,
        nodeSupport,
      );

      let derivativeY = 0;
      if (stepT > 0 && stepT < 1) {
        const distanceDerivative = t < 0.5 ? horizontalLength : -horizontalLength;
        const stepDerivative = distanceDerivative
          / (STRAIGHT_STEP_BASE_DISTANCE - STRAIGHT_STEP_TOP_DISTANCE);
        derivativeY = -(
          NODE_PATH_SURFACE_Y - STRAIGHT_PATH_SURFACE_Y
        ) * smootherStepDerivative(clampedStepT) * stepDerivative;
      }

      return {
        position: {
          x: lerp(from.x, to.x, t),
          y: surfaceY,
          z: lerp(from.z, to.z, t),
        },
        derivative: { x: dx, y: derivativeY, z: dz },
      };
    };
  }

  private createOverpassEvaluator(
    edge: OverpassLearningPathEdge,
    from: PathPosition,
    to: PathPosition,
  ): CurveEvaluator {
    const chordX = to.x - from.x;
    const chordZ = to.z - from.z;
    const chordLength = Math.hypot(chordX, chordZ);
    if (chordLength <= GEOMETRY_EPSILON) {
      throw new Error(`Overpass "${edge.id}" endpoints must not coincide.`);
    }
    const endInset = edge.platformEdgeOffset + edge.straightApproachLength;
    if (endInset * 2 >= chordLength) {
      throw new Error(
        `Overpass "${edge.id}" approaches consume its entire span.`,
      );
    }

    const unitX = chordX / chordLength;
    const unitZ = chordZ / chordLength;
    const centerX = (from.x + to.x) / 2;
    const centerZ = (from.z + to.z) / 2;
    const curveHalfRun = chordLength / 2 - endInset;
    const archRise = edge.bridgeSurfaceY - STRAIGHT_PATH_SURFACE_Y;
    const archLength = approximateEasedArchLength(curveHalfRun, archRise);
    const approachRise = NODE_PATH_SURFACE_Y - STRAIGHT_PATH_SURFACE_Y;
    const approachReferenceLength = Math.hypot(endInset, approachRise);
    const totalReferenceLength = archLength + approachReferenceLength * 2;
    const approachFraction = approachReferenceLength / totalReferenceLength;
    const archStartT = approachFraction;
    const archEndT = 1 - approachFraction;
    const archFraction = archEndT - archStartT;

    return (sourceT) => {
      const t = clamp01(sourceT);
      if (t < archStartT) {
        const localT = t / approachFraction;
        const distanceFromNode = endInset * localT;
        const transition = evaluateNodeRoadTransition(distanceFromNode);
        const distanceDerivative = endInset / approachFraction;
        return {
          position: {
            x: from.x + unitX * distanceFromNode,
            y: transition.surfaceY,
            z: from.z + unitZ * distanceFromNode,
          },
          derivative: {
            x: unitX * distanceDerivative,
            y: transition.derivativePerDistance * distanceDerivative,
            z: unitZ * distanceDerivative,
          },
        };
      }
      if (t > archEndT) {
        const localT = (t - archEndT) / approachFraction;
        const distanceFromNode = endInset * (1 - localT);
        const transition = evaluateNodeRoadTransition(distanceFromNode);
        const distanceDerivative = endInset / approachFraction;
        return {
          position: {
            x: to.x - unitX * distanceFromNode,
            y: transition.surfaceY,
            z: to.z - unitZ * distanceFromNode,
          },
          derivative: {
            x: unitX * distanceDerivative,
            y: -transition.derivativePerDistance * distanceDerivative,
            z: unitZ * distanceDerivative,
          },
        };
      }

      const archT = (t - archStartT) / archFraction;
      const arch = evaluateSymmetricArch(archT, curveHalfRun);
      const alongChord = curveHalfRun * arch.normalizedX;
      const x = centerX + unitX * alongChord;
      const z = centerZ + unitZ * alongChord;
      const surfaceY = STRAIGHT_PATH_SURFACE_Y
        + archRise * arch.normalizedHeight;
      const alongDerivative = curveHalfRun
        * arch.normalizedXDerivative / archFraction;
      return {
        position: { x, y: surfaceY, z },
        derivative: {
          x: unitX * alongDerivative,
          y: archRise * arch.normalizedHeightDerivative / archFraction,
          z: unitZ * alongDerivative,
        },
      };
    };
  }

  private auditOverpassClearance(
    edge: OverpassLearningPathEdge,
    underpassEdgeId: EdgeId,
  ): ClearanceAudit {
    const overpass = this.compiledById.get(edge.id)!;
    const underpass = this.compiledById.get(underpassEdgeId);
    if (!underpass) {
      throw new Error(`Missing compiled underpass "${underpassEdgeId}".`);
    }

    const combinedHalfWidth = (
      getPathWidth(overpass.edge) + getPathWidth(underpass.edge)
    ) / 2;
    let overlapStartT = Number.POSITIVE_INFINITY;
    let overlapEndT = Number.NEGATIVE_INFINITY;
    let minimumClearance = Number.POSITIVE_INFINITY;
    let minimumBridgeBottomY = Number.POSITIVE_INFINITY;
    let correspondingUnderpassY = Number.NEGATIVE_INFINITY;
    let closestDistanceXZ = Number.POSITIVE_INFINITY;
    let crossingSourceT = 0;
    let underpassCrossingSourceT = 0;

    for (let index = 0; index <= CLEARANCE_AUDIT_SEGMENTS; index += 1) {
      const sourceT = index / CLEARANCE_AUDIT_SEGMENTS;
      const bridgePoint = overpass.sampleSourceT(sourceT).position;
      const closest = closestPointOnPolylineXZ(bridgePoint, underpass.samples);
      if (closest.distanceXZ < closestDistanceXZ) {
        closestDistanceXZ = closest.distanceXZ;
        crossingSourceT = sourceT;
        underpassCrossingSourceT = closest.sourceT;
      }
      if (closest.distanceXZ > combinedHalfWidth + GEOMETRY_EPSILON) {
        continue;
      }

      overlapStartT = Math.min(overlapStartT, sourceT);
      overlapEndT = Math.max(overlapEndT, sourceT);
      const bridgeBottomY = bridgePoint.y - edge.deckThickness;
      const clearance = bridgeBottomY - closest.surfaceY;
      if (clearance < minimumClearance) {
        minimumClearance = clearance;
        minimumBridgeBottomY = bridgeBottomY;
        correspondingUnderpassY = closest.surfaceY;
      }
    }

    if (!Number.isFinite(overlapStartT) || !Number.isFinite(minimumClearance)) {
      throw new Error(
        `Overpass "${edge.id}" has no measurable overlap with "${underpassEdgeId}".`,
      );
    }

    const isSymmetric = this.overpassProfileAudits.find(
      (audit) => audit.edgeId === edge.id,
    )?.isSymmetric ?? false;
    const passed = isSymmetric
      && minimumClearance + GEOMETRY_EPSILON >= edge.requiredClearance;

    return Object.freeze({
      overpassEdgeId: edge.id,
      underpassEdgeId,
      requiredClearance: edge.requiredClearance,
      minimumClearance,
      bridgeBottomY: minimumBridgeBottomY,
      underpassSurfaceY: correspondingUnderpassY,
      crossingSourceT,
      underpassCrossingSourceT,
      overlapStartT,
      overlapEndT,
      bridgeSurfaceY: edge.bridgeSurfaceY,
      isSymmetric,
      passed,
    });
  }
}

interface SymmetricArchSample {
  readonly normalizedX: number;
  readonly normalizedHeight: number;
  readonly normalizedXDerivative: number;
  readonly normalizedHeightDerivative: number;
}

const ARCH_START_EASE_FRACTION = 0.08;
const ARCH_TAPER_START = 0.65;

function evaluateSymmetricArch(
  progress: number,
  curveHalfRun: number,
): SymmetricArchSample {
  const t = clamp01(progress);
  const onLeft = t <= 0.5;
  const halfProgress = onLeft ? t * 2 : (t - 0.5) * 2;
  const distanceFromLanding = (
    onLeft ? halfProgress : 1 - halfProgress
  ) * curveHalfRun;
  const shoulderScale = curveHalfRun > OVERPASS_ARCH_SHOULDER_RUN
    ? curveHalfRun / OVERPASS_ARCH_SHOULDER_RUN
    : 1;
  const shoulderProgress = curveHalfRun > OVERPASS_ARCH_SHOULDER_RUN
    ? clamp01(distanceFromLanding / OVERPASS_ARCH_SHOULDER_RUN)
    : clamp01(distanceFromLanding / curveHalfRun);
  const half = evaluateArchHalf(shoulderProgress);
  return {
    normalizedX: onLeft ? -1 + halfProgress : halfProgress,
    normalizedHeight: half.height,
    normalizedXDerivative: 2,
    normalizedHeightDerivative: (
      (onLeft ? 1 : -1) * half.derivative * shoulderScale * 2
    ),
  };
}

function evaluateArchHalf(progress: number): {
  readonly height: number;
  readonly derivative: number;
} {
  const u = clamp01(progress);
  const startEase = ARCH_START_EASE_FRACTION;
  const taperStart = ARCH_TAPER_START;
  const integral = startEase / 2
    + (taperStart - startEase)
    + (1 - taperStart) / 2;
  const scale = 1 / integral;
  if (u < startEase) {
    const local = u / startEase;
    return {
      height: scale * startEase * smootherStepIntegral(local),
      derivative: scale * smootherStep(local),
    };
  }
  if (u <= taperStart) {
    return {
      height: scale * (u - startEase / 2),
      derivative: scale,
    };
  }
  const taperLength = 1 - taperStart;
  const local = (u - taperStart) / taperLength;
  return {
    height: scale * (taperStart - startEase / 2)
      + scale * taperLength * (local - smootherStepIntegral(local)),
    derivative: scale * (1 - smootherStep(local)),
  };
}

function smootherStepIntegral(value: number): number {
  const t = clamp01(value);
  return t ** 6 - 3 * t ** 5 + 2.5 * t ** 4;
}

function evaluateNodeRoadTransition(distanceFromNode: number): {
  readonly surfaceY: number;
  readonly derivativePerDistance: number;
} {
  const stepT = (
    distanceFromNode - STRAIGHT_STEP_TOP_DISTANCE
  ) / (
    STRAIGHT_STEP_BASE_DISTANCE - STRAIGHT_STEP_TOP_DISTANCE
  );
  const clampedStepT = clamp01(stepT);
  const nodeSupport = 1 - smootherStep(clampedStepT);
  const heightDifference = NODE_PATH_SURFACE_Y - STRAIGHT_PATH_SURFACE_Y;
  const derivativePerDistance = stepT > 0 && stepT < 1
    ? -heightDifference * smootherStepDerivative(clampedStepT)
      / (STRAIGHT_STEP_BASE_DISTANCE - STRAIGHT_STEP_TOP_DISTANCE)
    : 0;
  return {
    surfaceY: lerp(STRAIGHT_PATH_SURFACE_Y, NODE_PATH_SURFACE_Y, nodeSupport),
    derivativePerDistance,
  };
}

function approximateEasedArchLength(
  halfRun: number,
  rise: number,
): number {
  const segments = 256;
  let length = 0;
  let previous = evaluateSymmetricArch(0, halfRun);
  for (let index = 1; index <= segments; index += 1) {
    const sample = evaluateSymmetricArch(index / segments, halfRun);
    length += Math.hypot(
      (sample.normalizedX - previous.normalizedX) * halfRun,
      (sample.normalizedHeight - previous.normalizedHeight) * rise,
    );
    previous = sample;
  }
  return length;
}

function getPathWidth(edge: LearningPathEdge): number {
  return edge.pathKind === "overpass" ? edge.width : STRAIGHT_PATH_WIDTH;
}

function closestPointOnPolylineXZ(
  point: PathPoint3D,
  samples: readonly PathGeometrySample[],
): { readonly distanceXZ: number; readonly surfaceY: number; readonly sourceT: number } {
  let minimumDistanceSquared = Number.POSITIVE_INFINITY;
  let surfaceY = samples[0]!.surfaceY;
  let sourceT = samples[0]!.sourceT;
  for (let index = 1; index < samples.length; index += 1) {
    const start = samples[index - 1]!;
    const end = samples[index]!;
    const dx = end.position.x - start.position.x;
    const dz = end.position.z - start.position.z;
    const lengthSquared = dx * dx + dz * dz;
    const fraction = lengthSquared > GEOMETRY_EPSILON
      ? clamp01(
        ((point.x - start.position.x) * dx + (point.z - start.position.z) * dz)
          / lengthSquared,
      )
      : 0;
    const closestX = start.position.x + dx * fraction;
    const closestZ = start.position.z + dz * fraction;
    const deltaX = point.x - closestX;
    const deltaZ = point.z - closestZ;
    const distanceSquared = deltaX * deltaX + deltaZ * deltaZ;
    if (distanceSquared < minimumDistanceSquared) {
      minimumDistanceSquared = distanceSquared;
      surfaceY = lerp(start.surfaceY, end.surfaceY, fraction);
      sourceT = lerp(start.sourceT, end.sourceT, fraction);
    }
  }
  return { distanceXZ: Math.sqrt(minimumDistanceSquared), surfaceY, sourceT };
}

function smootherStep(value: number): number {
  const clamped = clamp01(value);
  return clamped * clamped * clamped
    * (clamped * (clamped * 6 - 15) + 10);
}

function smootherStepDerivative(value: number): number {
  const clamped = clamp01(value);
  return 30 * clamped * clamped * (clamped - 1) * (clamped - 1);
}

function normalize3D(vector: PathPoint3D): PathPoint3D {
  const length = Math.hypot(vector.x, vector.y, vector.z);
  if (!Number.isFinite(length) || length <= GEOMETRY_EPSILON) {
    throw new Error("Path curve produced a zero or non-finite tangent.");
  }
  return { x: vector.x / length, y: vector.y / length, z: vector.z / length };
}

function distance3D(first: PathPoint3D, second: PathPoint3D): number {
  return Math.hypot(
    second.x - first.x,
    second.y - first.y,
    second.z - first.z,
  );
}

function assertFinite(value: number, label: string): void {
  if (!Number.isFinite(value)) {
    throw new Error(`${label} must be finite.`);
  }
}

function areEquivalentEdgeDefinitions(
  first: LearningPathEdge,
  second: LearningPathEdge,
): boolean {
  return first.pathKind === second.pathKind
    && first.fromNodeId === second.fromNodeId
    && first.toNodeId === second.toNodeId
    && JSON.stringify(first) === JSON.stringify(second);
}

function assertFinitePosition(position: PathPosition, label: string): void {
  assertFinite(position.x, `${label} x`);
  assertFinite(position.z, `${label} z`);
}

function clamp01(value: number): number {
  return Math.max(0, Math.min(1, value));
}

function lerp(from: number, to: number, progress: number): number {
  return from + (to - from) * progress;
}
