import type { SceneRuntimeGatewayScheduler } from "../../runtime/gateway";

type TimerHandle = ReturnType<typeof globalThis.setTimeout>;

export interface VisibilityAwareSchedulerDocument {
  readonly hidden: boolean;
  addEventListener(type: "visibilitychange", listener: EventListener): void;
  removeEventListener(type: "visibilitychange", listener: EventListener): void;
}

export interface VisibilityAwareSceneRuntimeGatewaySchedulerOptions {
  readonly document: VisibilityAwareSchedulerDocument;
  readonly now?: () => number;
  readonly setTimeout?: (callback: () => void, delayMs: number) => TimerHandle;
  readonly clearTimeout?: (handle: TimerHandle) => void;
}

interface SuspensibleTimer {
  readonly callback: () => void;
  remainingMs: number;
  startedAtMs: number | null;
  nativeHandle: TimerHandle | null;
}

/**
 * Counts only foreground time for scene command watchdogs.
 *
 * BrowserSessionLifecycle pauses requestAnimationFrame while the document is
 * hidden. Pausing these matching gateway deadlines prevents a healthy bridge,
 * route or character animation from being declared timed out while no frame
 * is allowed to advance it.
 */
export class VisibilityAwareSceneRuntimeGatewayScheduler
implements SceneRuntimeGatewayScheduler {
  readonly #document: VisibilityAwareSchedulerDocument;
  readonly #now: () => number;
  readonly #setNativeTimeout: (callback: () => void, delayMs: number) => TimerHandle;
  readonly #clearNativeTimeout: (handle: TimerHandle) => void;
  readonly #timers = new Map<number, SuspensibleTimer>();
  #nextHandle = 1;
  #visible: boolean;
  #disposed = false;

  public constructor(options: VisibilityAwareSceneRuntimeGatewaySchedulerOptions) {
    this.#document = options.document;
    this.#now = options.now ?? (() => globalThis.performance?.now() ?? Date.now());
    this.#setNativeTimeout = options.setTimeout
      ?? ((callback, delayMs) => globalThis.setTimeout(callback, delayMs));
    this.#clearNativeTimeout = options.clearTimeout
      ?? ((handle) => globalThis.clearTimeout(handle));
    this.#visible = !options.document.hidden;
    this.#document.addEventListener("visibilitychange", this.#handleVisibilityChange);
  }

  public setTimeout(callback: () => void, delayMs: number): TimerHandle {
    const virtualHandle = this.#nextHandle++;
    const timer: SuspensibleTimer = {
      callback,
      remainingMs: Math.max(0, delayMs),
      startedAtMs: null,
      nativeHandle: null,
    };
    this.#timers.set(virtualHandle, timer);
    if (this.#visible && !this.#disposed) this.#arm(virtualHandle, timer);
    return virtualHandle;
  }

  public clearTimeout(handle: TimerHandle): void {
    const virtualHandle = Number(handle);
    const timer = this.#timers.get(virtualHandle);
    if (!timer) return;
    if (timer.nativeHandle !== null) {
      this.#clearNativeTimeout(timer.nativeHandle);
    }
    this.#timers.delete(virtualHandle);
  }

  public dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    this.#document.removeEventListener("visibilitychange", this.#handleVisibilityChange);
    for (const timer of this.#timers.values()) {
      if (timer.nativeHandle !== null) this.#clearNativeTimeout(timer.nativeHandle);
    }
    this.#timers.clear();
  }

  readonly #handleVisibilityChange = (): void => {
    if (this.#disposed) return;
    const visible = !this.#document.hidden;
    if (visible === this.#visible) return;
    this.#visible = visible;
    if (visible) this.#resumeAll();
    else this.#pauseAll();
  };

  #arm(virtualHandle: number, timer: SuspensibleTimer): void {
    timer.startedAtMs = this.#now();
    timer.nativeHandle = this.#setNativeTimeout(() => {
      if (this.#disposed || this.#timers.get(virtualHandle) !== timer) return;
      this.#timers.delete(virtualHandle);
      timer.nativeHandle = null;
      timer.startedAtMs = null;
      timer.callback();
    }, timer.remainingMs);
  }

  #pauseAll(): void {
    const pausedAtMs = this.#now();
    for (const timer of this.#timers.values()) {
      if (timer.nativeHandle === null || timer.startedAtMs === null) continue;
      this.#clearNativeTimeout(timer.nativeHandle);
      timer.remainingMs = Math.max(
        0,
        timer.remainingMs - Math.max(0, pausedAtMs - timer.startedAtMs),
      );
      timer.nativeHandle = null;
      timer.startedAtMs = null;
    }
  }

  #resumeAll(): void {
    for (const [virtualHandle, timer] of this.#timers) {
      if (timer.nativeHandle === null) this.#arm(virtualHandle, timer);
    }
  }
}
