export class PerformanceMeter {
  public fps = 0;

  private accumulatedSeconds = 0;
  private accumulatedFrames = 0;

  public update(deltaSeconds: number): void {
    this.accumulatedSeconds += deltaSeconds;
    this.accumulatedFrames += 1;

    if (this.accumulatedSeconds >= 0.5) {
      const sample = this.accumulatedFrames / this.accumulatedSeconds;
      this.fps = this.fps === 0 ? sample : this.fps * 0.72 + sample * 0.28;
      this.accumulatedSeconds = 0;
      this.accumulatedFrames = 0;
    }
  }
}
