import type {
  LearningPathEdge,
  LearningPathNode,
  OverpassLearningPathEdge,
} from "../../config/pathData";
import type {
  PresentationCommand,
  PresentationCoordinatorEvent,
} from "../XStatePresentationCoordinator";
import type { CharacterAdapterEvent } from "../XStateCharacterAdapter";
import type { OverpassInternalPhase } from "../../statecharts/objects/overpassMachine";

type PresenceState = "hidden" | "dropping" | "visible" | "rising";
type OverpassState = "absent" | "assembling" | "ready" | "occupied" | "retiring";

interface PresenceDiagnostic {
  state: PresenceState;
  desiredVisible: boolean;
  activeCommandId: string | null;
}

interface OverpassDiagnostic {
  state: OverpassState;
  desiredVisible: boolean;
  occupied: boolean;
  activeCommandId: string | null;
  internalPhase: OverpassInternalPhase;
}

interface CharacterDiagnostic {
  state: string;
  context: {
    observedPhase: string;
    visuallyIdle: boolean;
    sequence: number;
    error: string | null;
  };
}

export interface SceneRuntimeDiagnosticSnapshot {
  readonly platforms: Readonly<Record<string, PresenceState>>;
  readonly longRoads: Readonly<Record<string, PresenceState>>;
  readonly overpasses: Readonly<Record<string, Readonly<{
    readonly state: OverpassState;
    readonly internalPhase: OverpassInternalPhase;
  }>>>;
  readonly character: Readonly<CharacterDiagnostic>;
}

const PHASE_INDEX: Readonly<Record<OverpassInternalPhase, number>> = {
  none: 0,
  "first-short-road": 1,
  arch: 2,
  "second-short-road": 3,
};

/**
 * Pure diagnostic mirror replacing one XState actor per render object. Business
 * state stays in orchestration/gateway actors; this ledger only retains the
 * same debug projection that LearningPathXStateRuntime exposed previously.
 */
export class SceneRuntimeDiagnosticLedger {
  private readonly platforms = new Map<string, PresenceDiagnostic>();
  private readonly longRoads = new Map<string, PresenceDiagnostic>();
  private readonly overpasses = new Map<string, OverpassDiagnostic>();
  private character: CharacterDiagnostic;

  public constructor(options: Readonly<{
    nodes: readonly LearningPathNode[];
    edges: readonly LearningPathEdge[];
    initialCharacterPhase: string;
    initiallyCharacterVisuallyIdle: boolean;
  }>) {
    options.nodes.forEach((node) => {
      this.platforms.set(node.id, this.createPresence(node.initiallyVisible));
    });
    options.edges.forEach((edge) => {
      if (edge.pathKind === "straight") {
        this.longRoads.set(edge.id, this.createPresence(edge.initiallyVisible));
      } else {
        this.registerOverpass(edge);
      }
    });
    this.character = {
      state: options.initialCharacterPhase,
      context: {
        observedPhase: options.initialCharacterPhase,
        visuallyIdle: options.initiallyCharacterVisuallyIdle,
        sequence: 0,
        error: null,
      },
    };
  }

  public registerOverpass(edge: OverpassLearningPathEdge): void {
    if (this.overpasses.has(edge.id)) return;
    this.overpasses.set(edge.id, {
      state: edge.initiallyVisible ? "ready" : "absent",
      desiredVisible: edge.initiallyVisible,
      occupied: false,
      activeCommandId: null,
      internalPhase: "none",
    });
  }

  public acceptPresentationCommand(command: PresentationCommand): void {
    if (command.objectKind === "overpass") {
      const entry = this.requireOverpass(command.objectId);
      entry.desiredVisible = command.visible;
      entry.activeCommandId = command.commandId;
      entry.internalPhase = "none";
      if (command.visible) {
        if (entry.state === "absent" || entry.state === "retiring") {
          entry.state = "assembling";
        }
      } else if (entry.state === "assembling" || entry.state === "ready") {
        entry.state = "retiring";
      }
      return;
    }

    const entry = this.requirePresence(command.objectKind, command.objectId);
    entry.desiredVisible = command.visible;
    entry.activeCommandId = command.commandId;
    if (command.visible) {
      if (entry.state === "hidden" || entry.state === "rising") {
        entry.state = "dropping";
      }
    } else if (entry.state === "visible" || entry.state === "dropping") {
      entry.state = "rising";
    }
  }

  public getDesiredVisibility(
    objectKind: "platform" | "long-road" | "overpass",
    objectId: string,
  ): boolean | undefined {
    if (objectKind === "overpass") {
      return this.overpasses.get(objectId)?.desiredVisible;
    }
    const entry = objectKind === "platform"
      ? this.platforms.get(objectId)
      : this.longRoads.get(objectId);
    return entry?.desiredVisible;
  }

  /**
   * Reconciles a terminal renderer state before the application enables
   * interaction. Hydration has no presentation command/ACK pair, so leaving
   * the diagnostic mirror at its constructor defaults would manufacture false
   * scene drift even though the renderer was restored correctly.
   */
  public reconcileStableVisibility(
    objectKind: "platform" | "long-road" | "overpass",
    objectId: string,
    visible: boolean,
  ): void {
    if (objectKind === "overpass") {
      const entry = this.requireOverpass(objectId);
      entry.desiredVisible = visible;
      entry.occupied = false;
      entry.activeCommandId = null;
      entry.internalPhase = "none";
      entry.state = visible ? "ready" : "absent";
      return;
    }
    const entry = this.requirePresence(objectKind, objectId);
    entry.desiredVisible = visible;
    entry.activeCommandId = null;
    entry.state = visible ? "visible" : "hidden";
  }

  public acceptPresentationEvent(event: PresentationCoordinatorEvent): void {
    if (event.type === "PRESENTATION.STARTED" || event.type === "PRESENTATION.FAILED") {
      return;
    }
    if (event.type === "PRESENTATION.PHASE") {
      const entry = this.overpasses.get(event.objectId);
      if (!entry || entry.activeCommandId !== event.commandId) return;
      if (entry.state !== "assembling" && entry.state !== "retiring") return;
      const current = PHASE_INDEX[entry.internalPhase];
      const candidate = PHASE_INDEX[event.phase];
      if (event.phase !== "none" && (candidate === current || candidate === current + 1)) {
        entry.internalPhase = event.phase;
      }
      return;
    }

    if (event.objectKind === "overpass") {
      const entry = this.overpasses.get(event.objectId);
      if (!entry || entry.activeCommandId !== event.commandId) return;
      if (event.terminal === "visible" && entry.desiredVisible) {
        entry.state = entry.occupied ? "occupied" : "ready";
      } else if (event.terminal === "hidden" && !entry.desiredVisible) {
        entry.state = "absent";
      } else {
        return;
      }
      entry.activeCommandId = null;
      entry.internalPhase = "none";
      return;
    }

    const entry = this.requirePresence(event.objectKind, event.objectId);
    if (entry.activeCommandId !== event.commandId) return;
    if (event.terminal === "visible" && entry.desiredVisible) {
      entry.state = "visible";
    } else if (event.terminal === "hidden" && !entry.desiredVisible) {
      entry.state = "hidden";
    } else {
      return;
    }
    entry.activeCommandId = null;
  }

  public setOccupiedOverpass(edgeId: string | null): void {
    this.overpasses.forEach((entry, id) => {
      const occupied = id === edgeId;
      if (entry.occupied === occupied) return;
      entry.occupied = occupied;
      if (occupied && entry.state === "ready") {
        entry.state = "occupied";
      } else if (!occupied && entry.state === "occupied") {
        entry.state = entry.desiredVisible ? "ready" : "retiring";
      }
    });
  }

  public acceptCharacterEvent(event: CharacterAdapterEvent): void {
    if (event.sequence <= this.character.context.sequence) return;
    if (event.type === "CHARACTER.PHASE") {
      this.character = {
        state: event.phase,
        context: {
          observedPhase: event.phase,
          visuallyIdle: (event.phase === "idle" || event.phase === "reduced")
            && event.visuallyIdle,
          sequence: event.sequence,
          error: null,
        },
      };
      return;
    }
    if (event.type === "CHARACTER.FAILED") {
      this.character = {
        state: "failed",
        context: {
          observedPhase: "failed",
          visuallyIdle: false,
          sequence: event.sequence,
          error: event.error,
        },
      };
      return;
    }
    this.character = {
      state: "disposed",
      context: {
        observedPhase: "disposed",
        visuallyIdle: false,
        sequence: event.sequence,
        error: null,
      },
    };
  }

  public snapshot(): SceneRuntimeDiagnosticSnapshot {
    return Object.freeze({
      platforms: Object.freeze(Object.fromEntries(
        [...this.platforms.entries()].map(([id, entry]) => [id, entry.state]),
      )),
      longRoads: Object.freeze(Object.fromEntries(
        [...this.longRoads.entries()].map(([id, entry]) => [id, entry.state]),
      )),
      overpasses: Object.freeze(Object.fromEntries(
        [...this.overpasses.entries()].map(([id, entry]) => [id, Object.freeze({
          state: entry.state,
          internalPhase: entry.internalPhase,
        })]),
      )),
      character: Object.freeze({
        state: this.character.state,
        context: Object.freeze({ ...this.character.context }),
      }),
    });
  }

  private createPresence(initiallyVisible: boolean): PresenceDiagnostic {
    return {
      state: initiallyVisible ? "visible" : "hidden",
      desiredVisible: initiallyVisible,
      activeCommandId: null,
    };
  }

  private requirePresence(
    objectKind: "platform" | "long-road",
    objectId: string,
  ): PresenceDiagnostic {
    const entry = objectKind === "platform"
      ? this.platforms.get(objectId)
      : this.longRoads.get(objectId);
    if (!entry) throw new Error(`Missing ${objectKind} diagnostic "${objectId}".`);
    return entry;
  }

  private requireOverpass(objectId: string): OverpassDiagnostic {
    const entry = this.overpasses.get(objectId);
    if (!entry) throw new Error(`Missing overpass diagnostic "${objectId}".`);
    return entry;
  }
}
