import type {
  CharacterForceSettleCommand,
  MotionAbortCommand,
  MotionExecuteCommand,
  PresentationCancelTransactionCommand,
  PresentationExecuteCommand,
  SceneRuntimeDispatchReceipt,
  SceneRuntimeGatewayCommand,
  SceneRuntimePort,
  SceneRuntimePortAck,
} from "./types";

export type SceneRuntimeAckPublisher = (ack: SceneRuntimePortAck) => void;

/**
 * Imperative handlers implemented by the existing Three.js runtime. The port
 * owns neither orchestration policy nor animation frames: it only translates
 * low-frequency gateway commands into calls on the runtime boundary.
 */
export interface LearningPathSceneRuntimeHandlers {
  readonly executePresentation: (
    command: PresentationExecuteCommand,
    publish: SceneRuntimeAckPublisher,
  ) => SceneRuntimeDispatchReceipt | void;
  readonly cancelPresentationTransaction: (
    command: PresentationCancelTransactionCommand,
    publish: SceneRuntimeAckPublisher,
  ) => SceneRuntimeDispatchReceipt | void;
  readonly executeMotion: (
    command: MotionExecuteCommand,
    publish: SceneRuntimeAckPublisher,
  ) => SceneRuntimeDispatchReceipt | void;
  readonly abortMotion: (
    command: MotionAbortCommand,
    publish: SceneRuntimeAckPublisher,
  ) => SceneRuntimeDispatchReceipt | void;
  readonly forceSettleCharacter: (
    command: CharacterForceSettleCommand,
    publish: SceneRuntimeAckPublisher,
  ) => SceneRuntimeDispatchReceipt | void;
  readonly dispose?: () => void;
}

/**
 * Injectable SceneRuntimePort backed by existing imperative runtime methods.
 * It intentionally creates no actors; sceneSession owns the one gateway actor
 * and this class remains a disposable adapter below that boundary.
 */
export class LearningPathSceneRuntimePort implements SceneRuntimePort {
  private readonly listeners = new Set<(ack: SceneRuntimePortAck) => void>();
  private disposed = false;

  public constructor(
    private readonly handlers: LearningPathSceneRuntimeHandlers,
  ) {}

  public subscribe(listener: (ack: SceneRuntimePortAck) => void): () => void {
    this.assertLive();
    this.listeners.add(listener);
    let subscribed = true;
    return () => {
      if (!subscribed) return;
      subscribed = false;
      this.listeners.delete(listener);
    };
  }

  public dispatch(
    command: SceneRuntimeGatewayCommand,
  ): SceneRuntimeDispatchReceipt | void {
    this.assertLive();
    switch (command.type) {
      case "PRESENTATION.EXECUTE":
        return this.handlers.executePresentation(command, this.publish);
      case "PRESENTATION.CANCEL_TRANSACTION":
        return this.handlers.cancelPresentationTransaction(command, this.publish);
      case "MOTION.EXECUTE":
        return this.handlers.executeMotion(command, this.publish);
      case "MOTION.ABORT":
        return this.handlers.abortMotion(command, this.publish);
      case "CHARACTER.FORCE_SETTLE":
        return this.handlers.forceSettleCharacter(command, this.publish);
    }
  }

  /** Publishes only coarse lifecycle ACKs. It is safe to call asynchronously. */
  public readonly publish: SceneRuntimeAckPublisher = (ack) => {
    if (this.disposed) return;
    this.listeners.forEach((listener) => listener(ack));
  };

  /**
   * The owning scene lifecycle calls dispose. Gateway stop only unsubscribes,
   * because the same runtime port may survive a sceneSession state transition.
   */
  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.listeners.clear();
    this.handlers.dispose?.();
  }

  public get isDisposed(): boolean {
    return this.disposed;
  }

  private assertLive(): void {
    if (this.disposed) {
      throw new Error("LearningPathSceneRuntimePort is disposed.");
    }
  }
}
