export interface SessionFrameLoopPort {
  start(): void;
  stop(): void;
}

export type LearningPathSessionLifecycleEvent =
  | Readonly<{ type: "MODEL.LOAD_STARTED" }>
  | Readonly<{ type: "MODEL.READY" }>
  | Readonly<{ type: "MODEL.FAILED"; error: string }>
  | Readonly<{ type: "PRESENTATION.STARTED" }>
  | Readonly<{ type: "PRESENTATION.READY" }>
  | Readonly<{ type: "PRESENTATION.FAILED"; error: string }>
  | Readonly<{ type: "CONTEXT.LOST" }>
  | Readonly<{ type: "CONTEXT.RESTORED" }>;

export type LearningPathSessionModelPhase =
  | "not-started"
  | "loading"
  | "ready"
  | "failed";

export type LearningPathSessionPresentationPhase =
  | "not-started"
  | "presenting"
  | "ready"
  | "failed";

export interface LearningPathSessionLifecycleSnapshot {
  readonly sequence: number;
  readonly modelPhase: LearningPathSessionModelPhase;
  readonly modelError: string | null;
  readonly presentationPhase: LearningPathSessionPresentationPhase;
  readonly presentationError: string | null;
  readonly contextAvailable: boolean;
}

export interface LearningPathSessionLifecycleSubscription {
  unsubscribe(): void;
}

export type LearningPathSessionLifecycleListener = (
  event: LearningPathSessionLifecycleEvent,
  snapshot: LearningPathSessionLifecycleSnapshot,
) => void;

const initialLifecycleSnapshot = (): LearningPathSessionLifecycleSnapshot => Object.freeze({
  sequence: 0,
  modelPhase: "not-started",
  modelError: null,
  presentationPhase: "not-started",
  presentationError: null,
  contextAvailable: true,
});

/**
 * Low-frequency fact journal shared by the browser session and the
 * renderer-independent application actor. It contains no DOM, Three.js, or
 * ActorRef values, and lets a late application binding replay already-settled
 * model/presentation facts exactly once before subscribing to future edges.
 */
export class LearningPathSessionLifecycleJournal {
  readonly #listeners = new Set<LearningPathSessionLifecycleListener>();
  #snapshot = initialLifecycleSnapshot();
  #disposed = false;

  getSnapshot(): LearningPathSessionLifecycleSnapshot {
    return this.#snapshot;
  }

  subscribe(
    listener: LearningPathSessionLifecycleListener,
  ): LearningPathSessionLifecycleSubscription {
    if (this.#disposed) return Object.freeze({ unsubscribe: () => {} });
    this.#listeners.add(listener);
    let subscribed = true;
    return Object.freeze({
      unsubscribe: () => {
        if (!subscribed) return;
        subscribed = false;
        this.#listeners.delete(listener);
      },
    });
  }

  record(event: LearningPathSessionLifecycleEvent): void {
    if (this.#disposed || !this.#changesFacts(event)) return;
    const previous = this.#snapshot;
    const common = { sequence: previous.sequence + 1 };
    switch (event.type) {
      case "MODEL.LOAD_STARTED":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          modelPhase: "loading",
          modelError: null,
        });
        break;
      case "MODEL.READY":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          modelPhase: "ready",
          modelError: null,
        });
        break;
      case "MODEL.FAILED":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          modelPhase: "failed",
          modelError: event.error,
        });
        break;
      case "PRESENTATION.STARTED":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          presentationPhase: "presenting",
          presentationError: null,
        });
        break;
      case "PRESENTATION.READY":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          presentationPhase: "ready",
          presentationError: null,
        });
        break;
      case "PRESENTATION.FAILED":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          presentationPhase: "failed",
          presentationError: event.error,
        });
        break;
      case "CONTEXT.LOST":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          contextAvailable: false,
        });
        break;
      case "CONTEXT.RESTORED":
        this.#snapshot = Object.freeze({
          ...previous,
          ...common,
          contextAvailable: true,
        });
        break;
    }
    const next = this.#snapshot;
    [...this.#listeners].forEach((listener) => listener(event, next));
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    this.#listeners.clear();
  }

  #changesFacts(event: LearningPathSessionLifecycleEvent): boolean {
    const snapshot = this.#snapshot;
    switch (event.type) {
      case "MODEL.LOAD_STARTED": return snapshot.modelPhase !== "loading";
      case "MODEL.READY": return snapshot.modelPhase !== "ready";
      case "MODEL.FAILED":
        return snapshot.modelPhase !== "failed" || snapshot.modelError !== event.error;
      case "PRESENTATION.STARTED": return snapshot.presentationPhase !== "presenting";
      case "PRESENTATION.READY": return snapshot.presentationPhase !== "ready";
      case "PRESENTATION.FAILED":
        return snapshot.presentationPhase !== "failed"
          || snapshot.presentationError !== event.error;
      case "CONTEXT.LOST": return snapshot.contextAvailable;
      case "CONTEXT.RESTORED": return !snapshot.contextAvailable;
    }
  }
}

export interface BrowserSessionLifecycleCallbacks {
  readonly onResize: (width?: number, height?: number) => void;
  readonly onReducedMotionChanged: (reducedMotion: boolean) => void;
  readonly onContextLost: (event: Event) => void;
  readonly onContextRestored: () => void;
  readonly onVisibilityChanged?: (visible: boolean) => void;
}

export interface ResizeObserverEntryPort {
  readonly contentRect: Readonly<{ width: number; height: number }>;
}

export interface ResizeObserverPort {
  observe(target: Element): void;
  disconnect(): void;
}

export type ResizeObserverFactory = (
  callback: (entries: readonly ResizeObserverEntryPort[]) => void,
) => ResizeObserverPort;

export interface BrowserSessionLifecycleOptions {
  readonly browserWindow: Pick<Window, "addEventListener" | "removeEventListener" | "matchMedia">;
  readonly document: Pick<Document, "hidden" | "addEventListener" | "removeEventListener">;
  readonly canvas: Pick<HTMLCanvasElement, "addEventListener" | "removeEventListener">;
  readonly viewport: Element;
  readonly frameLoop: SessionFrameLoopPort;
  readonly callbacks: BrowserSessionLifecycleCallbacks;
  readonly resizeObserverFactory?: ResizeObserverFactory | null;
}

const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

export const getPreferredReducedMotion = (
  browserWindow: Pick<Window, "matchMedia">,
): boolean => browserWindow.matchMedia(REDUCED_MOTION_QUERY).matches;

const getDefaultResizeObserverFactory = (): ResizeObserverFactory | null => (
  typeof ResizeObserver === "undefined"
    ? null
    : (callback) => new ResizeObserver((entries) => callback(entries))
);

/**
 * Owns browser listeners around a Three session and the frame-loop run policy.
 * It intentionally emits only lifecycle edges; per-frame work remains outside
 * XState and outside this adapter.
 */
export class BrowserSessionLifecycle {
  readonly #browserWindow: BrowserSessionLifecycleOptions["browserWindow"];
  readonly #document: BrowserSessionLifecycleOptions["document"];
  readonly #canvas: BrowserSessionLifecycleOptions["canvas"];
  readonly #viewport: Element;
  readonly #frameLoop: SessionFrameLoopPort;
  readonly #callbacks: BrowserSessionLifecycleCallbacks;
  readonly #reducedMotionQuery: MediaQueryList;
  readonly #resizeObserver: ResizeObserverPort | null;
  #visible: boolean;
  #contextLost = false;
  #started = false;
  #disposed = false;

  constructor(options: BrowserSessionLifecycleOptions) {
    this.#browserWindow = options.browserWindow;
    this.#document = options.document;
    this.#canvas = options.canvas;
    this.#viewport = options.viewport;
    this.#frameLoop = options.frameLoop;
    this.#callbacks = options.callbacks;
    this.#visible = !options.document.hidden;
    this.#reducedMotionQuery = options.browserWindow.matchMedia(REDUCED_MOTION_QUERY);
    const resizeObserverFactory = options.resizeObserverFactory === undefined
      ? getDefaultResizeObserverFactory()
      : options.resizeObserverFactory;
    this.#resizeObserver = resizeObserverFactory?.(this.#handleObservedResize) ?? null;
  }

  get reducedMotion(): boolean {
    return this.#reducedMotionQuery.matches;
  }

  get visible(): boolean {
    return this.#visible;
  }

  get contextLost(): boolean {
    return this.#contextLost;
  }

  get started(): boolean {
    return this.#started;
  }

  get disposed(): boolean {
    return this.#disposed;
  }

  start(): void {
    if (this.#disposed || this.#started) return;
    this.#started = true;
    this.#canvas.addEventListener("webglcontextlost", this.#handleContextLost);
    this.#canvas.addEventListener("webglcontextrestored", this.#handleContextRestored);
    this.#document.addEventListener("visibilitychange", this.#handleVisibilityChange);
    this.#reducedMotionQuery.addEventListener("change", this.#handleReducedMotionChange);
    if (this.#resizeObserver) this.#resizeObserver.observe(this.#viewport);
    else this.#browserWindow.addEventListener("resize", this.#handleWindowResize, { passive: true });
    this.#syncFrameLoop();
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    if (this.#started) {
      this.#started = false;
      this.#canvas.removeEventListener("webglcontextlost", this.#handleContextLost);
      this.#canvas.removeEventListener("webglcontextrestored", this.#handleContextRestored);
      this.#document.removeEventListener("visibilitychange", this.#handleVisibilityChange);
      this.#reducedMotionQuery.removeEventListener("change", this.#handleReducedMotionChange);
      if (this.#resizeObserver) this.#resizeObserver.disconnect();
      else this.#browserWindow.removeEventListener("resize", this.#handleWindowResize);
    }
    this.#frameLoop.stop();
  }

  readonly #handleWindowResize = (): void => {
    if (!this.#started || this.#disposed) return;
    this.#callbacks.onResize();
  };

  readonly #handleObservedResize = (
    entries: readonly ResizeObserverEntryPort[],
  ): void => {
    if (!this.#started || this.#disposed) return;
    const entry = entries[entries.length - 1];
    if (!entry) return;
    this.#callbacks.onResize(entry.contentRect.width, entry.contentRect.height);
  };

  readonly #handleVisibilityChange = (): void => {
    if (!this.#started || this.#disposed) return;
    const visible = !this.#document.hidden;
    if (visible === this.#visible) return;
    this.#visible = visible;
    this.#callbacks.onVisibilityChanged?.(visible);
    this.#syncFrameLoop();
  };

  readonly #handleReducedMotionChange = (event: MediaQueryListEvent): void => {
    if (!this.#started || this.#disposed) return;
    this.#callbacks.onReducedMotionChanged(event.matches);
  };

  readonly #handleContextLost = (event: Event): void => {
    event.preventDefault();
    if (!this.#started || this.#disposed || this.#contextLost) return;
    this.#contextLost = true;
    this.#frameLoop.stop();
    this.#callbacks.onContextLost(event);
  };

  readonly #handleContextRestored = (): void => {
    if (!this.#started || this.#disposed || !this.#contextLost) return;
    this.#contextLost = false;
    this.#callbacks.onContextRestored();
    this.#syncFrameLoop();
  };

  #syncFrameLoop(): void {
    if (!this.#started || this.#disposed || this.#contextLost || !this.#visible) {
      this.#frameLoop.stop();
      return;
    }
    this.#frameLoop.start();
  }
}
