import type { LearningPathEdge } from "../../../config/pathData";

export interface GenerationPresentationAdapterPort {
  readonly revealNode: (
    nodeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ) => Promise<void>;
  readonly revealEdge: (
    edgeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ) => Promise<void>;
  readonly revealCharacter: (
    nodeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ) => Promise<void>;
}

export interface GenerationPresenceState {
  readonly status: string;
}

export interface GenerationPathViewPort {
  updateNodePresence(
    nodeId: string,
    deltaSeconds: number,
    state: Readonly<{
      desiredVisible: true;
      reducedMotion: boolean;
      speedMultiplier: number;
    }>,
  ): GenerationPresenceState;
  updateStraightEdgePresence(
    edgeId: string,
    deltaSeconds: number,
    state: Readonly<{
      desiredVisible: true;
      reducedMotion: boolean;
      speedMultiplier: number;
    }>,
  ): GenerationPresenceState;
}

export interface GenerationCharacterStagePort {
  visible: boolean;
  readonly position: { y: number };
}

export interface PresentationFrameScheduler {
  now(): number;
  request(callback: (timestamp: number) => void): number;
  cancel(frameId: number): void;
}

export interface GenerationPresentationAdapterOptions {
  readonly initialNodeId: string;
  readonly nodeExists: (nodeId: string) => boolean;
  readonly edges: readonly Pick<LearningPathEdge, "id" | "pathKind">[];
  readonly pathView: GenerationPathViewPort;
  readonly characterStage: GenerationCharacterStagePort;
  readonly setSemanticNodeVisible: (nodeId: string, visible: boolean) => void;
  readonly publishState: () => void;
  readonly frameScheduler?: PresentationFrameScheduler;
  readonly presenceSpeedMultiplier?: number;
  readonly characterDropHeight?: number;
  readonly characterDropDurationSeconds?: number;
}

interface ActiveAnimation {
  frameId: number;
  active: boolean;
  readonly signal?: AbortSignal;
  readonly abort: () => void;
  readonly reject: (error: unknown) => void;
}

const createAbortError = (): DOMException => (
  new DOMException("Presentation cancelled.", "AbortError")
);

export const createBrowserPresentationFrameScheduler = (
  browserWindow: Window,
): PresentationFrameScheduler => ({
  now: () => browserWindow.performance.now(),
  request: (callback) => browserWindow.requestAnimationFrame(callback),
  cancel: (frameId) => browserWindow.cancelAnimationFrame(frameId),
});

/**
 * Three presentation boundary for the page-generation statechart.
 *
 * The adapter owns the character readiness barrier and every one-shot RAF used
 * during initial reveal. Abort/dispose synchronously invalidate each task, so a
 * delayed platform callback can never mutate an already-replaced scene.
 */
export class GenerationPresentationAdapter {
  readonly presentation: GenerationPresentationAdapterPort;

  readonly #initialNodeId: string;
  readonly #nodeExists: (nodeId: string) => boolean;
  readonly #edgeById: ReadonlyMap<string, Pick<LearningPathEdge, "id" | "pathKind">>;
  readonly #pathView: GenerationPathViewPort;
  readonly #characterStage: GenerationCharacterStagePort;
  readonly #setSemanticNodeVisible: (nodeId: string, visible: boolean) => void;
  readonly #publishState: () => void;
  readonly #scheduler: PresentationFrameScheduler;
  readonly #presenceSpeedMultiplier: number;
  readonly #characterDropHeight: number;
  readonly #characterDropDurationSeconds: number;
  readonly #activeAnimations = new Set<ActiveAnimation>();
  readonly #characterReady: Promise<void>;
  #resolveCharacterReady: (() => void) | null = null;
  #rejectCharacterReady: ((error: unknown) => void) | null = null;
  #characterReadySettled = false;
  #disposed = false;

  constructor(options: GenerationPresentationAdapterOptions) {
    this.#initialNodeId = options.initialNodeId;
    this.#nodeExists = options.nodeExists;
    this.#edgeById = new Map(options.edges.map((edge) => [edge.id, edge] as const));
    this.#pathView = options.pathView;
    this.#characterStage = options.characterStage;
    this.#setSemanticNodeVisible = options.setSemanticNodeVisible;
    this.#publishState = options.publishState;
    this.#scheduler = options.frameScheduler
      ?? createBrowserPresentationFrameScheduler(window);
    this.#presenceSpeedMultiplier = options.presenceSpeedMultiplier ?? 1;
    this.#characterDropHeight = options.characterDropHeight ?? 5.4;
    this.#characterDropDurationSeconds = Math.max(
      0,
      options.characterDropDurationSeconds ?? 0.48,
    );

    this.#characterReady = new Promise<void>((resolve, reject) => {
      this.#resolveCharacterReady = resolve;
      this.#rejectCharacterReady = reject;
    });
    // A session may be replaced before revealCharacter begins awaiting this
    // barrier. Keep the rejection handled without changing future awaiters.
    void this.#characterReady.catch(() => {});

    this.presentation = Object.freeze({
      revealNode: this.#revealNode,
      revealEdge: this.#revealEdge,
      revealCharacter: this.#revealCharacter,
    });
  }

  markCharacterReady(): void {
    if (this.#disposed || this.#characterReadySettled) return;
    this.#characterReadySettled = true;
    this.#resolveCharacterReady?.();
    this.#releaseCharacterReadyCallbacks();
  }

  markCharacterFailed(error: unknown): void {
    if (this.#disposed || this.#characterReadySettled) return;
    this.#characterReadySettled = true;
    this.#rejectCharacterReady?.(error);
    this.#releaseCharacterReadyCallbacks();
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    const abortError = createAbortError();
    if (!this.#characterReadySettled) {
      this.#characterReadySettled = true;
      this.#rejectCharacterReady?.(abortError);
      this.#releaseCharacterReadyCallbacks();
    }
    [...this.#activeAnimations].forEach((animation) => {
      this.#settleAnimation(animation, abortError);
    });
  }

  get disposed(): boolean {
    return this.#disposed;
  }

  get activeAnimationCount(): number {
    return this.#activeAnimations.size;
  }

  readonly #revealNode = async (
    nodeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ): Promise<void> => {
    this.#throwIfUnavailable(signal);
    if (!this.#nodeExists(nodeId)) {
      throw new Error(`Cannot reveal unknown node "${nodeId}".`);
    }
    await this.#animateUntil((deltaSeconds) => {
      const state = this.#pathView.updateNodePresence(nodeId, deltaSeconds, {
        desiredVisible: true,
        reducedMotion,
        speedMultiplier: this.#presenceSpeedMultiplier,
      });
      return state.status === "visible";
    }, signal);
    this.#throwIfUnavailable(signal);
    this.#setSemanticNodeVisible(nodeId, true);
    this.#publishState();
  };

  readonly #revealEdge = async (
    edgeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ): Promise<void> => {
    this.#throwIfUnavailable(signal);
    const edge = this.#edgeById.get(edgeId);
    if (!edge) throw new Error(`Cannot reveal unknown edge "${edgeId}".`);
    if (edge.pathKind !== "straight") {
      throw new Error(`Initial generation cannot reveal overpass edge "${edgeId}".`);
    }
    await this.#animateUntil((deltaSeconds) => {
      const state = this.#pathView.updateStraightEdgePresence(edgeId, deltaSeconds, {
        desiredVisible: true,
        reducedMotion,
        speedMultiplier: this.#presenceSpeedMultiplier,
      });
      return state.status === "visible";
    }, signal);
    this.#throwIfUnavailable(signal);
    this.#publishState();
  };

  readonly #revealCharacter = async (
    nodeId: string,
    reducedMotion: boolean,
    signal?: AbortSignal,
  ): Promise<void> => {
    this.#throwIfUnavailable(signal);
    if (nodeId !== this.#initialNodeId) {
      throw new Error(
        `Character reveal must target initial node "${this.#initialNodeId}".`,
      );
    }
    await this.#waitForCharacterReady(signal);
    this.#throwIfUnavailable(signal);
    this.#characterStage.visible = true;
    if (reducedMotion) {
      this.#characterStage.position.y = 0;
      this.#publishState();
      return;
    }

    let elapsedSeconds = 0;
    this.#characterStage.position.y = this.#characterDropHeight;
    await this.#animateUntil((deltaSeconds) => {
      elapsedSeconds = Math.min(
        this.#characterDropDurationSeconds,
        elapsedSeconds + deltaSeconds,
      );
      const progress = this.#characterDropDurationSeconds <= 0
        ? 1
        : elapsedSeconds / this.#characterDropDurationSeconds;
      const eased = 1 - (1 - progress) ** 4;
      this.#characterStage.position.y = this.#characterDropHeight * (1 - eased);
      return progress >= 1;
    }, signal);
    this.#throwIfUnavailable(signal);
    this.#characterStage.position.y = 0;
    this.#publishState();
  };

  #animateUntil(
    update: (deltaSeconds: number) => boolean,
    signal?: AbortSignal,
  ): Promise<void> {
    this.#throwIfUnavailable(signal);
    return new Promise<void>((resolve, reject) => {
      let previous = this.#scheduler.now();
      const animation: ActiveAnimation = {
        frameId: 0,
        active: true,
        ...(signal ? { signal } : {}),
        abort: () => {
          this.#settleAnimation(animation, createAbortError());
        },
        reject,
      };
      const frame = (now: number): void => {
        if (!animation.active || this.#disposed) return;
        if (signal?.aborted) {
          animation.abort();
          return;
        }
        const deltaSeconds = Math.min(Math.max(0, (now - previous) / 1_000), 0.1);
        previous = now;
        try {
          if (update(deltaSeconds)) {
            this.#settleAnimation(animation);
            resolve();
            return;
          }
        } catch (error) {
          this.#settleAnimation(animation, error);
          return;
        }
        this.#requestFrame(animation, frame);
      };

      this.#activeAnimations.add(animation);
      signal?.addEventListener("abort", animation.abort, { once: true });
      this.#requestFrame(animation, frame);
    });
  }

  #requestFrame(
    animation: ActiveAnimation,
    frame: (timestamp: number) => void,
  ): void {
    if (!animation.active) return;
    try {
      animation.frameId = this.#scheduler.request(frame);
    } catch (error) {
      this.#settleAnimation(animation, error);
    }
  }

  #waitForCharacterReady(signal?: AbortSignal): Promise<void> {
    this.#throwIfUnavailable(signal);
    if (!signal) return this.#characterReady;
    return new Promise<void>((resolve, reject) => {
      let settled = false;
      const finish = (error?: unknown): void => {
        if (settled) return;
        settled = true;
        signal.removeEventListener("abort", abort);
        if (error === undefined) resolve();
        else reject(error);
      };
      const abort = (): void => finish(createAbortError());
      signal.addEventListener("abort", abort, { once: true });
      void this.#characterReady.then(
        () => finish(),
        (error) => finish(error),
      );
    });
  }

  #settleAnimation(animation: ActiveAnimation, error?: unknown): void {
    if (!animation.active) return;
    animation.active = false;
    this.#scheduler.cancel(animation.frameId);
    animation.signal?.removeEventListener("abort", animation.abort);
    this.#activeAnimations.delete(animation);
    if (error !== undefined) animation.reject(error);
  }

  #throwIfUnavailable(signal?: AbortSignal): void {
    if (this.#disposed || signal?.aborted) throw createAbortError();
  }

  #releaseCharacterReadyCallbacks(): void {
    this.#resolveCharacterReady = null;
    this.#rejectCharacterReady = null;
  }
}
