import type { LearningPathNode } from "../config/pathData";
import type { LearningPathDomElements } from "./LearningPathDom";

export class AppUI {
  private readonly app: HTMLElement;
  private readonly canvas: HTMLCanvasElement;
  private readonly nodeOptions: HTMLOListElement;
  private readonly statusLabel: HTMLElement;
  private readonly loadingPanel: HTMLElement;
  private readonly loadingLabel: HTMLElement;
  private readonly toast: HTMLElement;
  private readonly screenReaderStatus: HTMLElement;
  private readonly document: Document;
  private readonly browserWindow: Window;
  private readonly optionIdPrefix: string;
  private readonly nodesById = new Map<string, LearningPathNode>();
  private readonly nodeOptionById = new Map<string, HTMLLIElement>();
  private readonly learningStatusByNodeId = new Map<
    string,
    "locked" | "available" | "in-progress" | "completed"
  >();
  private readonly hiddenNodeIds = new Set<string>();
  private activeNodeId: string | null = null;
  private currentNodeId: string | null = null;
  private toastTimer = 0;
  private hudTimer = 0;
  private announcementFrame = 0;

  public constructor(elements: LearningPathDomElements, instanceId: string) {
    this.app = elements.root;
    this.canvas = elements.canvas;
    this.nodeOptions = elements.nodeOptions;
    this.statusLabel = elements.statusLabel;
    this.loadingPanel = elements.loadingPanel;
    this.loadingLabel = elements.loadingLabel;
    this.toast = elements.toast;
    this.screenReaderStatus = elements.screenReaderStatus;
    this.document = elements.root.ownerDocument;
    const browserWindow = this.document.defaultView;
    if (!browserWindow) throw new Error("Learning-path UI requires a browser window.");
    this.browserWindow = browserWindow;
    this.optionIdPrefix = `learning-path-${instanceId}-node-option`;
  }

  public setLoading(progress: number | null): void {
    this.showHud(false);
    this.app.setAttribute("aria-busy", "true");
    this.loadingPanel.dataset.state = "visible";
    this.loadingLabel.textContent = progress === null
      ? "正在召唤刘看山…"
      : `正在召唤刘看山… ${Math.round(progress * 100)}%`;
  }

  public dispose(): void {
    this.browserWindow.clearTimeout(this.toastTimer);
    this.browserWindow.clearTimeout(this.hudTimer);
    this.browserWindow.cancelAnimationFrame(this.announcementFrame);
  }

  public configureNodes(
    nodes: readonly LearningPathNode[],
    currentNode: LearningPathNode | string | null = null,
  ): void {
    this.nodesById.clear();
    this.nodeOptionById.clear();
    this.learningStatusByNodeId.clear();
    this.hiddenNodeIds.clear();
    this.activeNodeId = null;
    this.currentNodeId = this.resolveNodeId(currentNode);
    this.canvas.removeAttribute("aria-activedescendant");

    const options = this.document.createDocumentFragment();
    for (const node of nodes) {
      if (this.nodesById.has(node.id)) {
        throw new Error(`Duplicate learning-path node id: ${node.id}`);
      }

      this.nodesById.set(node.id, node);
      this.learningStatusByNodeId.set(
        node.id,
        node.initiallyGreen ? "completed" : "locked",
      );

      const option = this.document.createElement("li");
      option.id = this.getOptionId(node.id);
      option.dataset.nodeId = node.id;
      option.setAttribute("role", "option");
      option.setAttribute("aria-selected", "false");
      if (!node.initiallyVisible) {
        this.hiddenNodeIds.add(node.id);
        this.applyNodeOptionVisibility(option, false);
      } else {
        this.applyNodeOptionVisibility(option, true);
      }
      this.nodeOptionById.set(node.id, option);
      options.append(option);
    }

    this.nodeOptions.replaceChildren(options);
    this.nodeOptions.setAttribute(
      "aria-label",
      `${nodes.length - this.hiddenNodeIds.size} 个可见学习路径节点`,
    );
    this.updateAllNodeOptions();
    if (this.currentNodeId !== null) {
      this.setActiveNode(this.currentNodeId);
    }
  }

  public setReady(currentNode: LearningPathNode): void {
    this.app.setAttribute("aria-busy", "false");
    this.loadingPanel.dataset.state = "hidden";
    this.statusLabel.textContent = `${currentNode.label} · 点击任意圆台查看`;
    this.setCurrentNode(currentNode.id);
    this.setActiveNode(currentNode);
    this.showHud(true);
    this.announce(`学习路径已就绪，刘看山位于${currentNode.label}。`);
  }

  public setTravelling(targetNode: LearningPathNode): void {
    this.statusLabel.textContent = `正在前往 ${targetNode.label}`;
    this.setCurrentNode(null);
    this.setActiveNode(targetNode);
    this.app.dataset.hint = "hidden";
    this.showHud(true);
    this.announce(`刘看山正在前往${targetNode.label}。`);
  }

  public setArrived(node: LearningPathNode): void {
    this.statusLabel.textContent = `${node.label} · 已到达`;
    this.setCurrentNode(node.id);
    this.setActiveNode(node);
    this.showToast(`已到达 ${node.label}`);
    this.showHud(true);
    this.announce(`刘看山已到达${node.label}。`);
  }

  public announceKeyboardSelection(node: LearningPathNode): void {
    this.setActiveNode(node);
    this.announce(`已选择${node.label}，按回车键查看详情。`);
  }

  /** Instance-scoped semantic option lookup for the accessibility bridge. */
  public getNodeOptionElement(nodeId: string): HTMLLIElement | null {
    return this.nodeOptionById.get(nodeId) ?? null;
  }

  public setNodeLearningStatus(
    nodeId: string,
    status: "locked" | "available" | "in-progress" | "completed",
  ): void {
    if (!this.nodesById.has(nodeId)) return;
    if (this.learningStatusByNodeId.get(nodeId) === status) return;
    this.learningStatusByNodeId.set(nodeId, status);
    this.updateNodeOption(nodeId);
  }

  public setNodeVisible(
    node: LearningPathNode | string,
    visible: boolean,
  ): void {
    const nodeId = this.resolveNodeId(node);
    if (nodeId === null || !this.nodesById.has(nodeId)) {
      return;
    }
    const option = this.nodeOptionById.get(nodeId);
    if (!option) {
      return;
    }

    const currentlyVisible = !this.hiddenNodeIds.has(nodeId);
    if (currentlyVisible === visible) return;

    if (visible) {
      this.hiddenNodeIds.delete(nodeId);
    } else {
      this.hiddenNodeIds.add(nodeId);
      if (this.activeNodeId === nodeId) {
        this.activeNodeId = null;
        this.canvas.removeAttribute("aria-activedescendant");
      }
    }
    this.applyNodeOptionVisibility(option, visible);
    this.nodeOptions.setAttribute(
      "aria-label",
      `${this.nodesById.size - this.hiddenNodeIds.size} 个可见学习路径节点`,
    );
    this.updateNodeOption(nodeId);
    this.updateSelectedOptions();
  }

  public setContextPaused(): void {
    this.statusLabel.textContent = "图形显示已暂停，正在恢复…";
    this.showToast("3D 显示暂时中断，正在安全恢复");
    this.showHud(false);
  }

  public setError(message: string): void {
    this.app.setAttribute("aria-busy", "false");
    this.loadingPanel.dataset.state = "error";
    this.loadingLabel.textContent = message;
    this.statusLabel.textContent = "3D 场景暂不可用";
    this.showHud(false);
    this.announce(message);
  }

  private showToast(message: string): void {
    this.browserWindow.clearTimeout(this.toastTimer);
    this.toast.textContent = message;
    this.toast.dataset.state = "visible";
    this.toastTimer = this.browserWindow.setTimeout(() => {
      this.toast.dataset.state = "hidden";
    }, 1800);
  }

  public setActiveNode(node: LearningPathNode | string | null): void {
    const nodeId = this.resolveNodeId(node);
    const option = nodeId === null ? null : this.nodeOptionById.get(nodeId) ?? null;
    if (
      !option
      || !this.nodeOptions.contains(option)
      || this.hiddenNodeIds.has(nodeId!)
    ) {
      if (this.activeNodeId === null) return;
      this.activeNodeId = null;
      this.canvas.removeAttribute("aria-activedescendant");
      this.updateSelectedOptions();
      return;
    }

    if (this.activeNodeId === nodeId) return;
    this.activeNodeId = nodeId;
    this.updateSelectedOptions();
    this.canvas.setAttribute("aria-activedescendant", option.id);
  }

  private setCurrentNode(node: LearningPathNode | string | null): void {
    const nodeId = this.resolveNodeId(node);
    if (this.currentNodeId === nodeId) return;
    this.currentNodeId = nodeId;
    this.updateAllNodeOptions();
  }

  private updateAllNodeOptions(): void {
    for (const nodeId of this.nodesById.keys()) {
      this.updateNodeOption(nodeId);
    }
    this.updateSelectedOptions();
  }

  private updateNodeOption(nodeId: string): void {
    const node = this.nodesById.get(nodeId);
    const option = this.nodeOptionById.get(nodeId);
    if (!node || !option) {
      return;
    }

    const status = this.learningStatusByNodeId.get(nodeId) ?? "locked";
    const color = node.variant === "brown"
      && (status === "in-progress" || status === "completed")
      ? "棕色"
      : node.variant !== "brown" && status === "completed"
        ? "绿色"
        : "灰色";
    const statusLabel = status === "locked"
      ? "未解锁"
      : status === "available"
        ? "可学习"
        : status === "in-progress"
          ? "学习中"
          : "已完成";
    const isCurrent = nodeId === this.currentNodeId;
    option.dataset.learningState = status;
    option.textContent = `${node.label}，${color}，${statusLabel}${isCurrent ? "，当前位置" : ""}`;
    option.setAttribute(
      "aria-disabled",
      String(this.hiddenNodeIds.has(nodeId)),
    );
    if (isCurrent) {
      option.setAttribute("aria-current", "step");
    } else {
      option.removeAttribute("aria-current");
    }
  }

  private updateSelectedOptions(): void {
    for (const [nodeId, option] of this.nodeOptionById) {
      option.setAttribute(
        "aria-selected",
        String(!this.hiddenNodeIds.has(nodeId) && nodeId === this.activeNodeId),
      );
    }
  }

  private applyNodeOptionVisibility(
    option: HTMLLIElement,
    visible: boolean,
  ): void {
    option.hidden = !visible;
    option.setAttribute("aria-hidden", String(!visible));
    option.setAttribute("aria-disabled", String(!visible));
    option.tabIndex = -1;
  }

  private resolveNodeId(node: LearningPathNode | string | null): string | null {
    return typeof node === "string" ? node : node?.id ?? null;
  }

  private getOptionId(nodeId: string): string {
    return `${this.optionIdPrefix}-${nodeId}`;
  }

  private announce(message: string): void {
    this.browserWindow.cancelAnimationFrame(this.announcementFrame);
    this.screenReaderStatus.textContent = "";
    this.announcementFrame = this.browserWindow.requestAnimationFrame(() => {
      this.announcementFrame = 0;
      this.screenReaderStatus.textContent = message;
    });
  }

  private showHud(autoHide: boolean): void {
    this.browserWindow.clearTimeout(this.hudTimer);
    this.app.dataset.hud = "visible";
    if (autoHide) {
      this.hudTimer = this.browserWindow.setTimeout(() => {
        this.app.dataset.hud = "hidden";
      }, 3200);
    }
  }

}
