import type { NodeId } from "../../config/pathData";
import type {
  RecoveryJournalEntry,
  RecoveryMachineInput,
  RecoverySerializableValue,
} from "./types";

/** The real checkpoint stays behind this port and never enters machine context. */
export interface PathRuleRecoveryPort<TCheckpoint = unknown> {
  captureCheckpoint(): TCheckpoint;
  restoreCheckpoint(checkpoint: TCheckpoint): void;
  discardPendingAfterRecovery(): void;
}

export interface RecoveryBoundaryRecord {
  readonly transactionId: string;
  readonly operationId: string;
  readonly objectId: string;
  readonly objectKind: RecoveryJournalEntry["objectKind"];
  readonly visibleBefore: boolean;
  readonly order: RecoveryJournalEntry["order"];
  readonly metadata: Readonly<Record<string, unknown>>;
}

export interface RecoveryBoundarySnapshot {
  readonly transactionId: string | null;
  readonly safeNodeId: NodeId;
  readonly checkpointId: string;
  readonly journalObjectIds: readonly string[];
}

interface StoredJournalEntry extends RecoveryBoundaryRecord {
  readonly journalId: string;
}

interface ActiveRecoveryBoundary<TCheckpoint> {
  transactionId: string | null;
  safeNodeId: NodeId;
  checkpointId: string;
  checkpoint: TCheckpoint;
  readonly journalById: Map<string, StoredJournalEntry>;
  readonly journalOrder: string[];
  readonly terminalOperationIds: Set<string>;
  restored: boolean;
}

function requireNonEmpty(value: string, label: string): string {
  if (value.trim().length === 0) throw new Error(`${label} must not be empty.`);
  return value;
}

function serializeMetadata(
  metadata: Readonly<Record<string, unknown>>,
): Readonly<Record<string, RecoverySerializableValue>> {
  const serialized = JSON.parse(JSON.stringify(metadata)) as unknown;
  if (typeof serialized !== "object" || serialized === null || Array.isArray(serialized)) {
    throw new Error("Recovery journal metadata must serialize to an object.");
  }
  return Object.freeze(serialized as Record<string, RecoverySerializableValue>);
}

/**
 * Pure recovery-boundary owner. It contains no actor, timer, renderer object,
 * or coordinator implementation detail.
 */
export class RecoveryBoundaryStore<TCheckpoint = unknown> {
  private readonly port: PathRuleRecoveryPort<TCheckpoint>;
  private boundary: ActiveRecoveryBoundary<TCheckpoint> | null = null;
  private nextCheckpointRevision = 1;

  public constructor(port: PathRuleRecoveryPort<TCheckpoint>) {
    this.port = port;
  }

  public begin(safeNodeId: NodeId): boolean {
    requireNonEmpty(safeNodeId, "safeNodeId");
    if (this.boundary) return false;
    this.boundary = {
      transactionId: null,
      safeNodeId,
      checkpointId: this.allocateCheckpointId(),
      checkpoint: this.port.captureCheckpoint(),
      journalById: new Map(),
      journalOrder: [],
      terminalOperationIds: new Set(),
      restored: false,
    };
    return true;
  }

  public bind(transactionId: string, fallbackSafeNodeId: NodeId): void {
    requireNonEmpty(transactionId, "transactionId");
    if (!this.boundary) this.begin(fallbackSafeNodeId);
    const boundary = this.requireBoundary();
    if (boundary.transactionId !== null && boundary.transactionId !== transactionId) {
      throw new Error(
        `Recovery transaction "${boundary.transactionId}" cannot accept "${transactionId}".`,
      );
    }
    boundary.transactionId = transactionId;
  }

  public record(record: RecoveryBoundaryRecord): boolean {
    const boundary = this.boundary;
    if (!boundary || boundary.transactionId !== record.transactionId) return false;
    const journalId = `${record.objectKind}:${record.objectId}`;
    if (boundary.journalById.has(journalId)) return false;
    boundary.journalById.set(journalId, Object.freeze({ ...record, journalId }));
    boundary.journalOrder.push(journalId);
    return true;
  }

  public terminal(transactionId: string, operationId: string): boolean {
    const boundary = this.boundary;
    if (!boundary || boundary.transactionId !== transactionId) return false;
    boundary.terminalOperationIds.add(operationId);
    return true;
  }

  /**
   * Advances the safe boundary. Entries already terminal are behind it and are
   * dropped; in-flight entries retain their original observed visibility.
   */
  public advance(safeNodeId: NodeId, transactionId: string): boolean {
    const boundary = this.boundary;
    if (!boundary || boundary.transactionId !== transactionId) return false;
    const pendingEntries = boundary.journalOrder.flatMap((journalId) => {
      const entry = boundary.journalById.get(journalId);
      return entry && !boundary.terminalOperationIds.has(entry.operationId)
        ? [entry]
        : [];
    });
    boundary.safeNodeId = safeNodeId;
    boundary.checkpointId = this.allocateCheckpointId();
    boundary.checkpoint = this.port.captureCheckpoint();
    boundary.restored = false;
    boundary.journalById.clear();
    boundary.journalOrder.length = 0;
    boundary.terminalOperationIds.clear();
    pendingEntries.forEach((entry) => {
      boundary.journalById.set(entry.journalId, entry);
      boundary.journalOrder.push(entry.journalId);
    });
    return true;
  }

  public prepare(input: Readonly<{
    recoveryId: string;
    sessionRevision: number;
    transactionId: string;
    safeNodeId: NodeId;
  }>): RecoveryMachineInput {
    const boundary = this.requireBoundary();
    if (boundary.transactionId !== input.transactionId
      || boundary.safeNodeId !== input.safeNodeId) {
      throw new Error(`Missing recovery checkpoint for ${input.transactionId}.`);
    }
    const journal = Object.freeze(boundary.journalOrder.flatMap((journalId) => {
      const entry = boundary.journalById.get(journalId);
      if (!entry) return [];
      return [Object.freeze({
        journalId: entry.journalId,
        objectId: entry.objectId,
        objectKind: entry.objectKind,
        visibleBefore: entry.visibleBefore,
        order: entry.objectKind === "overpass" ? entry.order : null,
        metadata: serializeMetadata(entry.metadata),
      })];
    }));
    return Object.freeze({
      recoveryId: input.recoveryId,
      sessionRevision: input.sessionRevision,
      transactionId: input.transactionId,
      checkpointId: boundary.checkpointId,
      safeNodeId: input.safeNodeId,
      journal,
    });
  }

  public restore(checkpointId: string): void {
    const boundary = this.requireBoundary();
    if (boundary.checkpointId !== checkpointId) {
      throw new Error(`Missing recovery checkpoint "${checkpointId}".`);
    }
    if (boundary.restored) {
      throw new Error(`Recovery checkpoint "${checkpointId}" was already restored.`);
    }
    this.port.restoreCheckpoint(boundary.checkpoint);
    this.port.discardPendingAfterRecovery();
    boundary.restored = true;
  }

  public complete(transactionId: string): boolean {
    if (!this.boundary || this.boundary.transactionId !== transactionId) return false;
    this.boundary = null;
    return true;
  }

  public reset(): void {
    this.boundary = null;
  }

  public getSnapshot(): RecoveryBoundarySnapshot | null {
    if (!this.boundary) return null;
    const boundary = this.boundary;
    return Object.freeze({
      transactionId: boundary.transactionId,
      safeNodeId: boundary.safeNodeId,
      checkpointId: boundary.checkpointId,
      journalObjectIds: Object.freeze(boundary.journalOrder.map((journalId) => (
        boundary.journalById.get(journalId)?.objectId ?? journalId
      ))),
    });
  }

  private requireBoundary(): ActiveRecoveryBoundary<TCheckpoint> {
    if (!this.boundary) throw new Error("No recovery boundary is active.");
    return this.boundary;
  }

  private allocateCheckpointId(): string {
    const id = `recovery-checkpoint:${this.nextCheckpointRevision}`;
    this.nextCheckpointRevision += 1;
    return id;
  }
}
