/**
 * Deterministic, opt-in fault injection for runtime and animation diagnostics.
 *
 * Production callers should depend on {@link FaultInjectionPort} and default to
 * {@link NO_FAULT_INJECTION}. Merely constructing a real controller never
 * enables a scenario: tests or a diagnostics UI must activate one explicitly.
 */

export type FaultBehaviorKind = "throw" | "drop" | "delay" | "stall";

export interface ThrowFaultBehavior {
  readonly kind: "throw";
  readonly message?: string;
}

export interface DropFaultBehavior {
  readonly kind: "drop";
}

export interface DelayFaultBehavior {
  readonly kind: "delay";
  readonly delayMs: number;
}

export interface StallFaultBehavior {
  readonly kind: "stall";
}

export type FaultBehavior =
  | ThrowFaultBehavior
  | DropFaultBehavior
  | DelayFaultBehavior
  | StallFaultBehavior;

export interface FaultTrigger {
  /** Stable integration point, for example `presentation.ack`. */
  readonly point: string;
  /** Stable operation identity, normally a command token or animation name. */
  readonly operation: string;
  /** One-based attempt number for retries. */
  readonly attempt: number;
  readonly transactionId?: string;
  readonly metadata?: Readonly<Record<string, unknown>>;
}

export interface FaultRule {
  readonly id: string;
  readonly point: string;
  /** Omit to match every operation at this point. */
  readonly operation?: string | readonly string[];
  /** Omit to match every attempt. */
  readonly attempt?: number | readonly number[];
  /** Defaults to one. A rule is skipped after this many matches. */
  readonly times?: number;
  readonly behavior: FaultBehavior;
}

export interface FaultScenario {
  readonly id: string;
  readonly label?: string;
  readonly rules: readonly FaultRule[];
}

export interface FaultPassDecision {
  readonly kind: "pass";
}

interface FaultDecisionBase {
  readonly scenarioId: string;
  readonly ruleId: string;
  readonly point: string;
  readonly operation: string;
  readonly attempt: number;
  readonly transactionId?: string;
  readonly remaining: number;
}

export interface FaultThrowDecision extends FaultDecisionBase {
  readonly kind: "throw";
  readonly message: string;
}

export interface FaultDropDecision extends FaultDecisionBase {
  readonly kind: "drop";
}

export interface FaultDelayDecision extends FaultDecisionBase {
  readonly kind: "delay";
  readonly delayMs: number;
}

export interface FaultStallDecision extends FaultDecisionBase {
  readonly kind: "stall";
}

export type InjectedFaultDecision =
  | FaultThrowDecision
  | FaultDropDecision
  | FaultDelayDecision
  | FaultStallDecision;

export type FaultDecision = FaultPassDecision | InjectedFaultDecision;

export interface FaultTimelineEntry {
  readonly sequence: number;
  readonly atMs: number;
  readonly scenarioId: string;
  readonly ruleId: string;
  readonly point: string;
  readonly operation: string;
  readonly attempt: number;
  readonly transactionId?: string;
  readonly behavior: FaultBehaviorKind;
  readonly remaining: number;
  readonly metadata?: Readonly<Record<string, unknown>>;
}

export interface ContinuedFaultInterception<T> {
  readonly status: "continued";
  readonly value: T;
}

export interface SuppressedFaultInterception {
  readonly status: "dropped" | "stalled";
  readonly decision: FaultDropDecision | FaultStallDecision;
}

export interface DelayedFaultInterception {
  readonly status: "delayed";
  readonly decision: FaultDelayDecision;
  /** Idempotently prevents the delayed continuation from running. */
  readonly cancel: () => void;
}

export type FaultInterception<T> =
  | ContinuedFaultInterception<T>
  | SuppressedFaultInterception
  | DelayedFaultInterception;

export interface FaultScheduler {
  schedule(callback: () => void, delayMs: number): () => void;
}

export interface FaultInjectionPort {
  readonly activeScenarioId: string | null;
  decide(trigger: FaultTrigger): FaultDecision;
  intercept<T>(trigger: FaultTrigger, continuation: () => T): FaultInterception<T>;
  getTimeline(): readonly FaultTimelineEntry[];
}

export interface FaultInjectionControllerOptions {
  readonly scenarios: readonly FaultScenario[];
  readonly scheduler?: FaultScheduler;
  readonly now?: () => number;
}

interface CompiledFaultRule {
  readonly scenarioId: string;
  readonly rule: FaultRule;
  readonly initialTimes: number;
  remaining: number;
}

const PASS: FaultPassDecision = Object.freeze({ kind: "pass" });
const EMPTY_TIMELINE: readonly FaultTimelineEntry[] = Object.freeze([]);

/** Stable trigger names shared by runtime, render adapters, and diagnostics. */
export const FAULT_TRIGGER_POINT = Object.freeze({
  PRESENTATION_COMMAND: "presentation.command",
  PRESENTATION_ACK: "presentation.ack",
  MOTION_COMMAND: "motion.command",
  MOTION_DEPARTED: "motion.departed",
  MOTION_ARRIVED: "motion.arrived",
  CHARACTER_STOP_FINISHED: "character.stop.finished",
  CHARACTER_TURN_FINISHED: "character.turn.finished",
} as const);

/** Pure matcher used by both the controller and its deterministic tests. */
export function faultRuleMatches(rule: FaultRule, trigger: FaultTrigger): boolean {
  if (rule.point !== trigger.point) return false;
  if (!matchesScalar(rule.operation, trigger.operation)) return false;
  return matchesScalar(rule.attempt, trigger.attempt);
}

/**
 * Pure first-match selection. Declaration order is the only tie-breaker, so
 * the same scenario, budget snapshot, and trigger always produce the same hit.
 */
export function findMatchingFaultRuleIndex(
  rules: readonly FaultRule[],
  remaining: readonly number[],
  trigger: FaultTrigger,
): number {
  for (let index = 0; index < rules.length; index += 1) {
    const rule = rules[index];
    if (rule && (remaining[index] ?? 0) > 0 && faultRuleMatches(rule, trigger)) {
      return index;
    }
  }
  return -1;
}

/** Error type intentionally distinguishable from an application exception. */
export class InjectedFaultError extends Error {
  public readonly decision: FaultThrowDecision;

  public constructor(decision: FaultThrowDecision) {
    super(decision.message);
    this.name = "InjectedFaultError";
    this.decision = decision;
  }
}

/**
 * Stateful diagnostics controller. It is disabled until activateScenario() is
 * called and consumes each matching rule at most `times` times.
 */
export class FaultInjectionController implements FaultInjectionPort {
  private readonly scenarios = new Map<string, CompiledFaultRule[]>();
  private readonly scheduler: FaultScheduler;
  private readonly now: () => number;
  private readonly timeline: FaultTimelineEntry[] = [];
  private readonly pendingCancels = new Set<() => void>();
  private sequence = 0;
  private activeId: string | null = null;

  public constructor(options: FaultInjectionControllerOptions) {
    validateScenarios(options.scenarios);
    options.scenarios.forEach((scenario) => {
      this.scenarios.set(
        scenario.id,
        scenario.rules.map((rule) => {
          const initialTimes = rule.times ?? 1;
          return {
            scenarioId: scenario.id,
            rule,
            initialTimes,
            remaining: initialTimes,
          };
        }),
      );
    });
    this.scheduler = options.scheduler ?? browserFaultScheduler;
    this.now = options.now ?? (() => Date.now());
  }

  public get activeScenarioId(): string | null {
    return this.activeId;
  }

  public activateScenario(scenarioId: string): void {
    if (!this.scenarios.has(scenarioId)) {
      throw new Error(`Unknown fault-injection scenario "${scenarioId}".`);
    }
    this.cancelPending();
    this.activeId = scenarioId;
  }

  /** Disable injection while preserving budgets and the diagnostic timeline. */
  public deactivate(): void {
    this.cancelPending();
    this.activeId = null;
  }

  public decide(trigger: FaultTrigger): FaultDecision {
    validateTrigger(trigger);
    const scenarioId = this.activeId;
    if (scenarioId === null) return PASS;
    const compiled = this.scenarios.get(scenarioId);
    if (!compiled) return PASS;
    const index = findMatchingFaultRuleIndex(
      compiled.map((entry) => entry.rule),
      compiled.map((entry) => entry.remaining),
      trigger,
    );
    const hit = compiled[index];
    if (!hit) return PASS;

    hit.remaining -= 1;
    const decision = createDecision(hit, trigger);
    this.sequence += 1;
    this.timeline.push(Object.freeze({
      sequence: this.sequence,
      atMs: this.now(),
      scenarioId,
      ruleId: hit.rule.id,
      point: trigger.point,
      operation: trigger.operation,
      attempt: trigger.attempt,
      ...(trigger.transactionId === undefined
        ? {}
        : { transactionId: trigger.transactionId }),
      behavior: decision.kind,
      remaining: hit.remaining,
      ...(trigger.metadata === undefined
        ? {}
        : { metadata: Object.freeze({ ...trigger.metadata }) }),
    }));
    return decision;
  }

  /**
   * Convenience wrapper for imperative adapters.
   *
   * - pass: continues synchronously;
   * - throw: raises InjectedFaultError;
   * - drop/stall: suppresses the continuation;
   * - delay: schedules it and returns an idempotent cancellation handle.
   */
  public intercept<T>(
    trigger: FaultTrigger,
    continuation: () => T,
  ): FaultInterception<T> {
    const decision = this.decide(trigger);
    if (decision.kind === "pass") {
      return { status: "continued", value: continuation() };
    }
    if (decision.kind === "throw") {
      throw new InjectedFaultError(decision);
    }
    if (decision.kind === "drop" || decision.kind === "stall") {
      return { status: decision.kind === "drop" ? "dropped" : "stalled", decision };
    }

    let active = true;
    let cancelScheduled = (): void => undefined;
    const cancel = (): void => {
      if (!active) return;
      active = false;
      this.pendingCancels.delete(cancel);
      cancelScheduled();
    };
    cancelScheduled = this.scheduler.schedule(() => {
      if (!active) return;
      active = false;
      this.pendingCancels.delete(cancel);
      continuation();
    }, decision.delayMs);
    this.pendingCancels.add(cancel);
    return { status: "delayed", decision, cancel };
  }

  public getTimeline(): readonly FaultTimelineEntry[] {
    return Object.freeze(this.timeline.map((entry) => Object.freeze({ ...entry })));
  }

  /**
   * Re-arm consumed rules and clear the timeline while keeping the active
   * scenario. This makes repeated captures of a scenario byte-for-byte stable.
   */
  public reset(): void {
    this.cancelPending();
    this.scenarios.forEach((rules) => {
      rules.forEach((entry) => {
        entry.remaining = entry.initialTimes;
      });
    });
    this.timeline.length = 0;
    this.sequence = 0;
  }

  /** Hard clear: reset all state and return to the production-safe off mode. */
  public clear(): void {
    this.reset();
    this.activeId = null;
  }

  private cancelPending(): void {
    [...this.pendingCancels].forEach((cancel) => cancel());
    this.pendingCancels.clear();
  }
}

/** Production default: allocation-free pass-through and no injectable state. */
export class NullFaultInjectionController implements FaultInjectionPort {
  public readonly activeScenarioId = null;

  public decide(_trigger: FaultTrigger): FaultDecision {
    return PASS;
  }

  public intercept<T>(
    _trigger: FaultTrigger,
    continuation: () => T,
  ): FaultInterception<T> {
    return { status: "continued", value: continuation() };
  }

  public getTimeline(): readonly FaultTimelineEntry[] {
    return EMPTY_TIMELINE;
  }
}

export const NO_FAULT_INJECTION: FaultInjectionPort = Object.freeze(
  new NullFaultInjectionController(),
);

const browserFaultScheduler: FaultScheduler = Object.freeze({
  schedule(callback: () => void, delayMs: number) {
    const timeout = globalThis.setTimeout(callback, delayMs);
    return () => globalThis.clearTimeout(timeout);
  },
});

function matchesScalar<T>(
  expected: T | readonly T[] | undefined,
  actual: T,
): boolean {
  if (expected === undefined) return true;
  return Array.isArray(expected) ? expected.includes(actual) : expected === actual;
}

function createDecision(
  hit: CompiledFaultRule,
  trigger: FaultTrigger,
): InjectedFaultDecision {
  const base = {
    scenarioId: hit.scenarioId,
    ruleId: hit.rule.id,
    point: trigger.point,
    operation: trigger.operation,
    attempt: trigger.attempt,
    ...(trigger.transactionId === undefined
      ? {}
      : { transactionId: trigger.transactionId }),
    remaining: hit.remaining,
  };
  switch (hit.rule.behavior.kind) {
    case "throw":
      return Object.freeze({
        ...base,
        kind: "throw",
        message: hit.rule.behavior.message
          ?? `Injected fault "${hit.rule.id}" at ${trigger.point} (${trigger.operation}).`,
      });
    case "drop":
      return Object.freeze({ ...base, kind: "drop" });
    case "delay":
      return Object.freeze({
        ...base,
        kind: "delay",
        delayMs: hit.rule.behavior.delayMs,
      });
    case "stall":
      return Object.freeze({ ...base, kind: "stall" });
  }
}

function validateScenarios(scenarios: readonly FaultScenario[]): void {
  const scenarioIds = new Set<string>();
  scenarios.forEach((scenario) => {
    requireNonEmpty(scenario.id, "Fault scenario id");
    if (scenarioIds.has(scenario.id)) {
      throw new Error(`Duplicate fault scenario id "${scenario.id}".`);
    }
    scenarioIds.add(scenario.id);
    const ruleIds = new Set<string>();
    scenario.rules.forEach((rule) => {
      requireNonEmpty(rule.id, `Fault rule id in scenario "${scenario.id}"`);
      requireNonEmpty(rule.point, `Fault point for rule "${rule.id}"`);
      if (ruleIds.has(rule.id)) {
        throw new Error(`Duplicate fault rule id "${rule.id}" in scenario "${scenario.id}".`);
      }
      ruleIds.add(rule.id);
      const times = rule.times ?? 1;
      if (!Number.isSafeInteger(times) || times < 1) {
        throw new Error(`Fault rule "${rule.id}" times must be a positive integer.`);
      }
      validateExpected(rule.operation, "operation", rule.id, (value) => (
        typeof value === "string" && value.trim().length > 0
      ));
      validateExpected(rule.attempt, "attempt", rule.id, (value) => (
        Number.isSafeInteger(value) && value >= 1
      ));
      if (
        rule.behavior.kind === "delay"
        && (!Number.isFinite(rule.behavior.delayMs) || rule.behavior.delayMs < 0)
      ) {
        throw new Error(`Fault rule "${rule.id}" delayMs must be finite and non-negative.`);
      }
    });
  });
}

function validateTrigger(trigger: FaultTrigger): void {
  requireNonEmpty(trigger.point, "Fault trigger point");
  requireNonEmpty(trigger.operation, "Fault trigger operation");
  if (!Number.isSafeInteger(trigger.attempt) || trigger.attempt < 1) {
    throw new Error("Fault trigger attempt must be a positive integer.");
  }
}

function validateExpected<T>(
  expected: T | readonly T[] | undefined,
  field: string,
  ruleId: string,
  isValid: (value: T) => boolean,
): void {
  if (expected === undefined) return;
  const values = Array.isArray(expected) ? expected : [expected];
  if (values.length === 0 || !values.every(isValid)) {
    throw new Error(`Fault rule "${ruleId}" ${field} matcher is invalid.`);
  }
}

function requireNonEmpty(value: string, label: string): void {
  if (value.trim().length === 0) {
    throw new Error(`${label} must not be empty.`);
  }
}
