import type {
  LearningPathEdge,
  LearningPathNode,
  OverpassLearningPathEdge,
} from "../config/pathData";
import type {
  OverpassAnimatedPieceRole,
  OverpassAnimationState,
  PresenceAnimationState,
  LearningPathView,
} from "../render/objects/LearningPathView";
import type {
  OverpassInternalPhase,
  OverpassOrder,
} from "../statecharts/objects/overpassMachine";
import {
  FAULT_TRIGGER_POINT,
  NO_FAULT_INJECTION,
  type FaultInjectionPort,
} from "../diagnostics/FaultInjectionController";

export type PresentationObjectKind = "platform" | "long-road" | "overpass";
export type PresentationOrder = OverpassOrder;

export interface PresentationCommandMetadata {
  /** Physical route origin, required for source-to-target ordering. */
  readonly sourceNodeId?: string;
  /** Physical route destination, required for target-to-source ordering. */
  readonly targetNodeId?: string;
  readonly reason?: string;
  readonly [key: string]: unknown;
}

interface PresentationCommandBase {
  readonly commandId: string;
  readonly transactionId: string;
  readonly operationId: string;
  readonly attempt: number;
  readonly objectId: string;
  readonly visible: boolean;
  readonly metadata: PresentationCommandMetadata;
}

export interface PresencePresentationCommand extends PresentationCommandBase {
  readonly objectKind: "platform" | "long-road";
  readonly order: null;
}

export interface OverpassPresentationCommand extends PresentationCommandBase {
  readonly objectKind: "overpass";
  readonly order: PresentationOrder;
}

export type PresentationCommand =
  | PresencePresentationCommand
  | OverpassPresentationCommand;

export interface PresentationSettledEvent {
  readonly type: "PRESENTATION.SETTLED";
  readonly commandId: string;
  readonly transactionId: string;
  readonly operationId: string;
  readonly attempt: number;
  readonly objectKind: PresentationObjectKind;
  readonly objectId: string;
  readonly terminal: "visible" | "hidden";
  readonly metadata: PresentationCommandMetadata;
}

export interface PresentationStartedEvent {
  readonly type: "PRESENTATION.STARTED";
  readonly commandId: string;
  readonly transactionId: string;
  readonly operationId: string;
  readonly attempt: number;
  readonly objectKind: PresentationObjectKind;
  readonly objectId: string;
  readonly metadata: PresentationCommandMetadata;
}

export interface PresentationFailedEvent {
  readonly type: "PRESENTATION.FAILED";
  readonly commandId: string;
  readonly transactionId: string;
  readonly operationId: string;
  readonly attempt: number;
  readonly objectKind: PresentationObjectKind;
  readonly objectId: string;
  readonly error: string;
  readonly metadata: PresentationCommandMetadata;
}

export interface PresentationPhaseEvent {
  readonly type: "PRESENTATION.PHASE";
  readonly commandId: string;
  readonly transactionId: string;
  readonly operationId: string;
  readonly attempt: number;
  readonly objectKind: "overpass";
  readonly objectId: string;
  readonly phase: OverpassInternalPhase;
  readonly metadata: PresentationCommandMetadata;
}

export type PresentationCoordinatorEvent =
  | PresentationStartedEvent
  | PresentationSettledEvent
  | PresentationPhaseEvent
  | PresentationFailedEvent;

export interface XStatePresentationCoordinatorOptions {
  readonly view: LearningPathView;
  readonly nodes: readonly LearningPathNode[];
  readonly edges: readonly LearningPathEdge[];
  readonly reducedMotion?: boolean;
  readonly onEvent?: (event: PresentationCoordinatorEvent) => void;
  readonly faultInjection?: FaultInjectionPort;
}

interface ActiveIntent {
  readonly command: PresentationCommand;
  readonly characterSideNodeId: string | null;
  acknowledged: boolean;
  blocked: boolean;
  lastPhase: OverpassInternalPhase | null;
}

interface PendingFaultDelay {
  readonly commandId: string;
  readonly transactionId: string;
  readonly intent: ActiveIntent;
  readonly handle: ReturnType<typeof globalThis.setTimeout>;
}

/**
 * The only imperative writer from XState presentation intent into
 * LearningPathView. It may advance unrelated objects concurrently, while a
 * newer command on the same object immediately supersedes the older command.
 */
export class XStatePresentationCoordinator {
  private readonly view: LearningPathView;
  private readonly nodeById: ReadonlyMap<string, LearningPathNode>;
  private readonly edgeById: Map<string, LearningPathEdge>;
  private readonly intents = new Map<string, ActiveIntent>();
  private readonly commandOwnerById = new Map<string, string>();
  private readonly commandIntentById = new Map<string, ActiveIntent>();
  private readonly pendingFaultDelays = new Set<PendingFaultDelay>();
  private readonly listeners = new Set<(
    event: PresentationCoordinatorEvent,
  ) => void>();
  private reducedMotion: boolean;
  private readonly faultInjection: FaultInjectionPort;
  private disposed = false;

  public constructor(options: XStatePresentationCoordinatorOptions) {
    this.view = options.view;
    this.nodeById = this.createUniqueCatalog(options.nodes, "node");
    this.edgeById = this.createUniqueCatalog(options.edges, "edge");
    this.reducedMotion = options.reducedMotion ?? false;
    this.faultInjection = options.faultInjection ?? NO_FAULT_INJECTION;
    if (options.onEvent) {
      this.listeners.add(options.onEvent);
    }
  }

  public subscribe(
    listener: (event: PresentationCoordinatorEvent) => void,
  ): () => void {
    if (this.disposed) return () => undefined;
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public setReducedMotion(reducedMotion: boolean): void {
    this.reducedMotion = reducedMotion;
  }

  /** Registers a lazily selected bridge before its first presentation intent. */
  public registerEdge(edge: OverpassLearningPathEdge): boolean {
    this.assertNotDisposed();
    const existing = this.edgeById.get(edge.id);
    if (existing) {
      if (existing === edge || JSON.stringify(existing) === JSON.stringify(edge)) {
        return false;
      }
      throw new Error(`Presentation edge id "${edge.id}" is already registered.`);
    }
    if (!this.nodeById.has(edge.fromNodeId) || !this.nodeById.has(edge.toNodeId)) {
      throw new Error(`Presentation overpass "${edge.id}" has a missing endpoint.`);
    }
    this.view.registerOverpass(edge);
    this.edgeById.set(edge.id, edge);
    return true;
  }

  /** Stops every still-live render intent owned by a failed transaction. */
  public cancelTransaction(transactionId: string): void {
    this.intents.forEach((intent, objectKey) => {
      if (intent.command.transactionId === transactionId) {
        this.retireIntent(intent, objectKey);
      }
    });
    this.cancelPendingFaultDelays(
      (pending) => pending.transactionId === transactionId,
    );
  }

  public isCurrentCommand(
    commandId: string,
    objectKind: PresentationObjectKind,
    objectId: string,
  ): boolean {
    const objectKey = this.getObjectKey(objectKind, objectId);
    return this.intents.get(objectKey)?.command.commandId === commandId;
  }

  /** Accepts one latest-wins command for a render construct. */
  public command(command: PresentationCommand): void {
    this.assertNotDisposed();
    this.validateCommand(command);
    const objectKey = this.getObjectKey(command.objectKind, command.objectId);
    const existingOwner = this.commandOwnerById.get(command.commandId);
    if (existingOwner && existingOwner !== objectKey) {
      throw new Error(
        `Presentation commandId "${command.commandId}" already belongs to ${existingOwner}; `
        + `it cannot be reused for ${objectKey}.`,
      );
    }
    const supersededIntent = this.intents.get(objectKey);
    if (supersededIntent) {
      this.retireIntent(supersededIntent, objectKey);
    }
    this.commandOwnerById.set(command.commandId, objectKey);
    const characterSideNodeId = command.objectKind === "overpass"
      ? this.resolveCharacterSideNodeId(command)
      : null;
    const intent: ActiveIntent = {
      command,
      characterSideNodeId,
      acknowledged: false,
      blocked: false,
      lastPhase: null,
    };
    this.intents.set(objectKey, intent);
    this.commandIntentById.set(command.commandId, intent);
    this.publishEvent(this.createStartedEvent(intent));
    if (this.disposed || this.intents.get(objectKey) !== intent) return;
    const decision = this.faultInjection.decide({
      point: FAULT_TRIGGER_POINT.PRESENTATION_COMMAND,
      operation: command.operationId,
      attempt: command.attempt,
      transactionId: command.transactionId,
      metadata: { commandId: command.commandId, objectId: command.objectId },
    });
    if (decision.kind === "throw") {
      intent.acknowledged = true;
      this.publishEvent(
        this.createFailedEvent(intent, new Error(decision.message)),
        intent,
      );
    } else if (decision.kind === "drop" || decision.kind === "stall") {
      intent.blocked = true;
    } else if (decision.kind === "delay") {
      intent.blocked = true;
      this.scheduleFaultDelay(intent, decision.delayMs, () => {
        const current = this.intents.get(objectKey);
        if (current === intent) current.blocked = false;
      });
    }
  }

  /**
   * Advances every active construct once and returns events produced by this
   * frame. Terminal ACKs reflect real view state, never a missing-ID fallback.
   */
  public frame(deltaSeconds: number): readonly PresentationCoordinatorEvent[] {
    const emitted: PresentationCoordinatorEvent[] = [];
    const safeDelta = Number.isFinite(deltaSeconds)
      ? Math.max(0, deltaSeconds)
      : 0;

    this.intents.forEach((intent) => {
      if (intent.blocked || intent.acknowledged) return;
      const { command } = intent;
      try {
        if (command.objectKind === "platform") {
        const state = this.view.updateNodeVisibility(
          command.objectId,
          safeDelta,
          {
            desiredVisible: command.visible,
            reducedMotion: this.reducedMotion,
          },
        );
        this.collectPresenceTerminal(intent, state, emitted);
        return;
        }
        if (command.objectKind === "long-road") {
        const state = this.view.updateStraightEdgeVisibility(
          command.objectId,
          safeDelta,
          {
            desiredVisible: command.visible,
            reducedMotion: this.reducedMotion,
          },
        );
        this.collectPresenceTerminal(intent, state, emitted);
        return;
        }

        const state = this.view.updateOverpassVisibility(
        command.objectId,
        safeDelta,
        {
          desiredVisible: command.visible,
          characterSideNodeId: intent.characterSideNodeId,
          reducedMotion: this.reducedMotion,
        },
      );
        this.collectOverpassPhase(intent, state, emitted);
        this.collectOverpassTerminal(intent, state, emitted);
      } catch (error) {
        intent.acknowledged = true;
        emitted.push(this.createFailedEvent(intent, error));
      }
    });

    emitted.forEach((event) => {
      const completedIntent = event.type === "PRESENTATION.SETTLED"
        || event.type === "PRESENTATION.FAILED"
        ? this.findIntentForEvent(event)
        : undefined;
      this.publishEvent(event, completedIntent);
    });
    return Object.freeze(emitted);
  }

  public getActiveCommands(): readonly PresentationCommand[] {
    return Object.freeze(
      [...this.intents.values()].map((intent) => intent.command),
    );
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.cancelPendingFaultDelays(() => true);
    this.intents.clear();
    this.commandOwnerById.clear();
    this.commandIntentById.clear();
    this.listeners.clear();
  }

  private collectPresenceTerminal(
    intent: ActiveIntent,
    state: PresenceAnimationState,
    emitted: PresentationCoordinatorEvent[],
  ): void {
    if (state.id !== intent.command.objectId) {
      throw new Error(
        `LearningPathView returned presence "${state.id}" for requested `
        + `"${intent.command.objectId}".`,
      );
    }
    const expected = intent.command.visible ? "visible" : "hidden";
    if (!intent.acknowledged && state.status === expected) {
      intent.acknowledged = true;
      this.collectAckWithFault(intent, this.createSettledEvent(intent, expected), emitted);
    }
  }

  private collectOverpassTerminal(
    intent: ActiveIntent,
    state: OverpassAnimationState,
    emitted: PresentationCoordinatorEvent[],
  ): void {
    if (state.edgeId !== intent.command.objectId) {
      throw new Error(
        `LearningPathView returned overpass "${state.edgeId ?? "null"}" for requested `
        + `"${intent.command.objectId}".`,
      );
    }
    const expected = intent.command.visible ? "visible" : "hidden";
    if (!intent.acknowledged && state.status === expected) {
      intent.acknowledged = true;
      this.collectAckWithFault(intent, this.createSettledEvent(intent, expected), emitted);
    }
  }

  private collectOverpassPhase(
    intent: ActiveIntent,
    state: OverpassAnimationState,
    emitted: PresentationCoordinatorEvent[],
  ): void {
    const phase = this.resolveOverpassPhase(intent, state);
    if (phase === intent.lastPhase) return;
    intent.lastPhase = phase;
    emitted.push({
      type: "PRESENTATION.PHASE",
      commandId: intent.command.commandId,
      transactionId: intent.command.transactionId,
      operationId: intent.command.operationId,
      attempt: intent.command.attempt,
      objectKind: "overpass",
      objectId: intent.command.objectId,
      phase,
      metadata: intent.command.metadata,
    });
  }

  private createSettledEvent(
    intent: ActiveIntent,
    terminal: "visible" | "hidden",
  ): PresentationSettledEvent {
    return {
      type: "PRESENTATION.SETTLED",
      commandId: intent.command.commandId,
      transactionId: intent.command.transactionId,
      operationId: intent.command.operationId,
      attempt: intent.command.attempt,
      objectKind: intent.command.objectKind,
      objectId: intent.command.objectId,
      terminal,
      metadata: intent.command.metadata,
    };
  }

  private collectAckWithFault(
    intent: ActiveIntent,
    settled: PresentationSettledEvent,
    emitted: PresentationCoordinatorEvent[],
  ): void {
    const decision = this.faultInjection.decide({
      point: FAULT_TRIGGER_POINT.PRESENTATION_ACK,
      operation: intent.command.operationId,
      attempt: intent.command.attempt,
      transactionId: intent.command.transactionId,
      metadata: {
        commandId: intent.command.commandId,
        objectId: intent.command.objectId,
      },
    });
    if (decision.kind === "pass") {
      emitted.push(settled);
      return;
    }
    if (decision.kind === "throw") {
      emitted.push(this.createFailedEvent(intent, new Error(decision.message)));
      return;
    }
    if (decision.kind === "delay") {
      this.scheduleFaultDelay(intent, decision.delayMs, () => {
        const objectKey = this.getObjectKey(
          intent.command.objectKind,
          intent.command.objectId,
        );
        if (this.intents.get(objectKey) !== intent) return;
        this.publishEvent(settled, intent);
      });
    }
    // drop/stall deliberately produce no ACK; the frame-driven watchdog owns recovery.
  }

  private createStartedEvent(intent: ActiveIntent): PresentationStartedEvent {
    const { command } = intent;
    return {
      type: "PRESENTATION.STARTED",
      commandId: command.commandId,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attempt: command.attempt,
      objectKind: command.objectKind,
      objectId: command.objectId,
      metadata: command.metadata,
    };
  }

  private createFailedEvent(intent: ActiveIntent, error: unknown): PresentationFailedEvent {
    const { command } = intent;
    return {
      type: "PRESENTATION.FAILED",
      commandId: command.commandId,
      transactionId: command.transactionId,
      operationId: command.operationId,
      attempt: command.attempt,
      objectKind: command.objectKind,
      objectId: command.objectId,
      error: error instanceof Error ? error.message : String(error),
      metadata: command.metadata,
    };
  }

  private publishEvent(
    event: PresentationCoordinatorEvent,
    completedIntent?: ActiveIntent,
  ): void {
    try {
      if (this.disposed) return;
      for (const listener of [...this.listeners]) {
        if (this.disposed) break;
        listener(event);
      }
    } finally {
      if (completedIntent) this.retireIntent(completedIntent);
    }
  }

  private findIntentForEvent(
    event: PresentationSettledEvent | PresentationFailedEvent,
  ): ActiveIntent | undefined {
    const objectKey = this.getObjectKey(event.objectKind, event.objectId);
    const intent = this.intents.get(objectKey);
    return intent?.command.commandId === event.commandId ? intent : undefined;
  }

  private scheduleFaultDelay(
    intent: ActiveIntent,
    delayMs: number,
    continuation: () => void,
  ): void {
    if (this.disposed) return;
    let pending: PendingFaultDelay;
    const handle = globalThis.setTimeout(() => {
      this.pendingFaultDelays.delete(pending);
      if (this.disposed) return;
      continuation();
    }, delayMs);
    pending = {
      commandId: intent.command.commandId,
      transactionId: intent.command.transactionId,
      intent,
      handle,
    };
    this.pendingFaultDelays.add(pending);
  }

  private cancelPendingFaultDelays(
    predicate: (pending: PendingFaultDelay) => boolean,
  ): void {
    [...this.pendingFaultDelays].forEach((pending) => {
      if (!predicate(pending)) return;
      globalThis.clearTimeout(pending.handle);
      this.pendingFaultDelays.delete(pending);
    });
  }

  private retireIntent(
    intent: ActiveIntent,
    objectKey = this.getObjectKey(
      intent.command.objectKind,
      intent.command.objectId,
    ),
  ): void {
    if (this.intents.get(objectKey) === intent) {
      this.intents.delete(objectKey);
    }
    this.cancelPendingFaultDelays(
      (pending) => pending.intent === intent,
    );
    if (this.commandIntentById.get(intent.command.commandId) === intent) {
      this.commandOwnerById.delete(intent.command.commandId);
      this.commandIntentById.delete(intent.command.commandId);
    }
  }

  private assertNotDisposed(): void {
    if (this.disposed) {
      throw new Error("XStatePresentationCoordinator is disposed.");
    }
  }

  private resolveOverpassPhase(
    intent: ActiveIntent,
    state: OverpassAnimationState,
  ): OverpassInternalPhase {
    if (state.status === "visible" || state.status === "hidden") {
      return "none";
    }
    const orderedRoles = this.getOrderedPieceRoles(intent.characterSideNodeId, intent.command.objectId);
    const pieces = new Map(state.pieces.map((piece) => [piece.role, piece]));
    const hasStarted = (role: OverpassAnimatedPieceRole): boolean => {
      const progress = pieces.get(role)?.progress;
      if (progress === undefined) return false;
      return intent.command.visible ? progress > 1e-6 : progress < 1 - 1e-6;
    };
    if (hasStarted(orderedRoles[2])) return "second-short-road";
    if (hasStarted(orderedRoles[1])) return "arch";
    return "first-short-road";
  }

  private getOrderedPieceRoles(
    characterSideNodeId: string | null,
    edgeId: string,
  ): readonly [
    OverpassAnimatedPieceRole,
    OverpassAnimatedPieceRole,
    OverpassAnimatedPieceRole,
  ] {
    const edge = this.getOverpassEdge(edgeId);
    return characterSideNodeId === edge.toNodeId
      ? ["to-approach", "arch", "from-approach"]
      : ["from-approach", "arch", "to-approach"];
  }

  private resolveCharacterSideNodeId(
    command: OverpassPresentationCommand,
  ): string {
    const edge = this.getOverpassEdge(command.objectId);
    const endpoints = [edge.fromNodeId, edge.toNodeId] as const;
    if (command.order === "world-left-to-right") {
      return this.getWorldOrderedEndpoint(endpoints, true);
    }
    if (command.order === "world-right-to-left") {
      return this.getWorldOrderedEndpoint(endpoints, false);
    }
    const metadataKey = command.order === "source-to-target"
      ? "sourceNodeId"
      : "targetNodeId";
    const candidate = command.metadata[metadataKey];
    if (typeof candidate !== "string" || !endpoints.includes(candidate)) {
      throw new Error(
        `Overpass ${command.order} command "${command.commandId}" requires metadata.${metadataKey} `
        + `to be one of ${endpoints.join(", ")}.`,
      );
    }
    return candidate;
  }

  private getWorldOrderedEndpoint(
    endpoints: readonly [string, string],
    leftFirst: boolean,
  ): string {
    const [fromId, toId] = endpoints;
    const from = this.nodeById.get(fromId);
    const to = this.nodeById.get(toId);
    if (!from || !to) {
      throw new Error(`Overpass endpoint catalog is incomplete: ${fromId}, ${toId}.`);
    }
    if (from.position.x === to.position.x) {
      // Stable tie-break keeps vertical bridges deterministic.
      return leftFirst ? fromId : toId;
    }
    const fromIsLeft = from.position.x < to.position.x;
    return leftFirst === fromIsLeft ? fromId : toId;
  }

  private validateCommand(command: PresentationCommand): void {
    if (command.commandId.trim().length === 0) {
      throw new Error("Presentation commandId must not be empty.");
    }
    if (command.objectKind === "platform") {
      if (!this.nodeById.has(command.objectId)) {
        throw new Error(`Unknown platform id "${command.objectId}".`);
      }
      return;
    }
    const edge = this.edgeById.get(command.objectId);
    if (!edge) {
      throw new Error(`Unknown ${command.objectKind} id "${command.objectId}".`);
    }
    const expectedKind = command.objectKind === "long-road" ? "straight" : "overpass";
    if (edge.pathKind !== expectedKind) {
      throw new Error(
        `Presentation object "${command.objectId}" is ${edge.pathKind}, not ${command.objectKind}.`,
      );
    }
  }

  private getOverpassEdge(edgeId: string): OverpassLearningPathEdge {
    const edge = this.edgeById.get(edgeId);
    if (!edge || edge.pathKind !== "overpass") {
      throw new Error(`Unknown overpass id "${edgeId}".`);
    }
    return edge;
  }

  private getObjectKey(kind: PresentationObjectKind, id: string): string {
    return `${kind}:${id}`;
  }

  private createUniqueCatalog<T extends { readonly id: string }>(
    entries: readonly T[],
    label: string,
  ): Map<string, T> {
    const catalog = new Map<string, T>();
    entries.forEach((entry) => {
      if (catalog.has(entry.id)) {
        throw new Error(`Duplicate ${label} id "${entry.id}".`);
      }
      catalog.set(entry.id, entry);
    });
    return catalog;
  }
}
