import * as THREE from "three";

const PLATFORM_RADIUS = 0.79;
const PLATFORM_VISIBLE_HEIGHT = 0.593;
const SAMPLE_COUNT = 12;
const TAU = Math.PI * 2;

export interface NodeOverlayAnchorNode {
  readonly position: { readonly x: number; readonly z: number };
  readonly surfaceY: number;
  /** Optional visual override for non-standard platforms. */
  readonly overlayRadius?: number;
  /** Optional explicit world-space lower rim used by the screen anchor. */
  readonly overlayBottomY?: number;
}

export type NodeOverlayAnchorLookup =
  | ReadonlyMap<string, NodeOverlayAnchorNode>
  | ((nodeId: string) => NodeOverlayAnchorNode | null | undefined);

export interface NodeOverlayViewportRect {
  readonly left: number;
  readonly top: number;
  readonly width: number;
  readonly height: number;
}

/**
 * The object is owned and reused by the projector. Consumers should read it
 * immediately rather than retaining it as a historical snapshot.
 */
export interface NodeOverlayAnchorProjection {
  readonly nodeId: string;
  readonly visible: boolean;
  readonly left: number;
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly width: number;
  readonly height: number;
  readonly centerX: number;
  readonly anchorClientX: number;
  readonly anchorClientY: number;
  readonly normalizedDepth: number;
}

interface MutableProjection {
  nodeId: string;
  visible: boolean;
  left: number;
  top: number;
  right: number;
  bottom: number;
  width: number;
  height: number;
  centerX: number;
  anchorClientX: number;
  anchorClientY: number;
  normalizedDepth: number;
}

/** Allocation-free projector for the render loop (one vector and one result object). */
export class NodeOverlayAnchorProjector {
  private readonly worldPoint = new THREE.Vector3();
  private readonly result: MutableProjection = {
    nodeId: "",
    visible: false,
    left: 0,
    top: 0,
    right: 0,
    bottom: 0,
    width: 0,
    height: 0,
    centerX: 0,
    anchorClientX: 0,
    anchorClientY: 0,
    normalizedDepth: 1,
  };

  public project(
    nodeId: string,
    camera: THREE.Camera,
    viewportRect: NodeOverlayViewportRect,
    nodeLookup: NodeOverlayAnchorLookup,
  ): NodeOverlayAnchorProjection | null {
    const node = typeof nodeLookup === "function"
      ? nodeLookup(nodeId)
      : nodeLookup.get(nodeId);
    if (!node || !isValidViewport(viewportRect) || !isFiniteNode(node)) return null;

    const radius = isPositiveFinite(node.overlayRadius) ? node.overlayRadius : PLATFORM_RADIUS;
    const lowerRimY = Number.isFinite(node.overlayBottomY)
      ? node.overlayBottomY as number
      : node.surfaceY - PLATFORM_VISIBLE_HEIGHT;
    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let minY = Number.POSITIVE_INFINITY;
    let maxY = Number.NEGATIVE_INFINITY;
    let minimumDepth = Number.POSITIVE_INFINITY;
    let inClipSpace = false;

    camera.updateMatrixWorld();
    for (let index = 0; index < SAMPLE_COUNT; index += 1) {
      const angle = (index / SAMPLE_COUNT) * TAU;
      this.worldPoint
        .set(
          node.position.x + Math.cos(angle) * radius,
          lowerRimY,
          node.position.z + Math.sin(angle) * radius,
        )
        .project(camera);
      const clientX = viewportRect.left + (this.worldPoint.x + 1) * 0.5 * viewportRect.width;
      const clientY = viewportRect.top + (1 - this.worldPoint.y) * 0.5 * viewportRect.height;
      minX = Math.min(minX, clientX);
      maxX = Math.max(maxX, clientX);
      minY = Math.min(minY, clientY);
      maxY = Math.max(maxY, clientY);
      minimumDepth = Math.min(minimumDepth, this.worldPoint.z);
      if (this.worldPoint.z >= -1 && this.worldPoint.z <= 1) inClipSpace = true;
    }

    const intersectsViewport = maxX >= viewportRect.left
      && minX <= viewportRect.left + viewportRect.width
      && maxY >= viewportRect.top
      && minY <= viewportRect.top + viewportRect.height;
    this.result.nodeId = nodeId;
    this.result.visible = inClipSpace && intersectsViewport;
    this.result.left = minX;
    this.result.top = minY;
    this.result.right = maxX;
    this.result.bottom = maxY;
    this.result.width = maxX - minX;
    this.result.height = maxY - minY;
    this.result.centerX = (minX + maxX) * 0.5;
    this.result.anchorClientX = this.result.centerX;
    this.result.anchorClientY = maxY;
    this.result.normalizedDepth = minimumDepth;
    return this.result;
  }
}

function isPositiveFinite(value: number | undefined): value is number {
  return value !== undefined && Number.isFinite(value) && value > 0;
}

function isValidViewport(viewport: NodeOverlayViewportRect): boolean {
  return Number.isFinite(viewport.left)
    && Number.isFinite(viewport.top)
    && Number.isFinite(viewport.width)
    && Number.isFinite(viewport.height)
    && viewport.width > 0
    && viewport.height > 0;
}

function isFiniteNode(node: NodeOverlayAnchorNode): boolean {
  return Number.isFinite(node.position.x)
    && Number.isFinite(node.position.z)
    && Number.isFinite(node.surfaceY);
}
