import type {
  EdgeId,
  LearningPathNode,
  NodeId,
  OverpassLearningPathEdge,
  StraightLearningPathEdge,
} from "../config/pathData";
import type {
  DynamicBridgeRuleSpec,
  ResolvedSpecialRevealStep,
  SpecialPathZoneSpec,
  SpecialRevealStep,
  ZoneEntryConnectionSpec,
} from "../config/pathRules";
import type {
  BasePathAuthoredEdge,
  BasePathRoute,
} from "./BasePathIndex";
import { BasePathIndex } from "./BasePathIndex";

export type OverpassPairLookup = (
  firstNodeId: NodeId,
  secondNodeId: NodeId,
) => OverpassLearningPathEdge | null;

export type RuntimeBridgeRole =
  | "ordinary"
  | "zone-entry"
  | "zone-transient";

export interface RuntimeBridgeInstance {
  readonly bridgeId: EdgeId;
  readonly edge: OverpassLearningPathEdge;
  /** The node which originally caused this physical bridge to be built. */
  readonly ownerSourceNodeId: NodeId;
  readonly role: RuntimeBridgeRole;
  readonly zoneId: string | null;
  /** Identifies one concrete activation of a repeatable row zone. */
  readonly zoneSessionId: string | null;
  readonly active: boolean;
  readonly createdRevision: number;
  readonly changedRevision: number;
}

export type BridgeTransitionAction =
  | {
    readonly kind: "retire-bridge";
    readonly bridgeId: EdgeId;
    /** Always one physical endpoint, chosen nearest to the safe character node. */
    readonly characterSideNodeId: NodeId;
  }
  | {
    readonly kind: "ensure-bridge";
    readonly bridge: RuntimeBridgeInstance;
    readonly characterSideNodeId: NodeId;
  };

export type NavigationDecisionKind =
  | "already-there"
  | "base-route"
  | "ordinary-overpass"
  | "zone-entry"
  | "zone-base-route"
  | "zone-transient-overpass"
  | "reuse-overpass"
  | "relay-existing-zone-overpass"
  | "leave-zone-base-route"
  | "leave-zone-overpass";

export interface NavigationStage {
  readonly id: string;
  readonly index: number;
  readonly decisionKind: NavigationDecisionKind;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly routeNodeIds: readonly NodeId[];
  readonly routeEdgeIds: readonly EdgeId[];
  readonly baseHopCount: number | null;
  /** Execute and finish these visual transitions before requestRoute(). */
  readonly beforeTravelBridgeActions: readonly BridgeTransitionAction[];
  /** Commit these immediately on the simulation's physical arrival event. */
  readonly afterArrivalBridgeActions: readonly BridgeTransitionAction[];
}

export interface NavigationPlan {
  readonly id: string;
  readonly revision: number;
  readonly sourceNodeId: NodeId;
  readonly targetNodeId: NodeId;
  readonly authoredHopCount: number | null;
  /** Present only while leaving the active special-session envelope. */
  readonly linkedZoneDismissalPlanId: string | null;
  readonly stages: readonly NavigationStage[];
  readonly flattenedRouteNodeIds: readonly NodeId[];
  readonly flattenedRouteEdgeIds: readonly EdgeId[];
}

export type NavigationPlanResult =
  | {
    readonly accepted: true;
    readonly plan: NavigationPlan;
    /** Teardown which runs concurrently with this navigation, when applicable. */
    readonly concurrentZoneDismissalPlan: ZoneDismissPlan | null;
  }
  | {
    readonly accepted: false;
    readonly reason:
      | "unknown-node"
      | "locked-node"
      | "missing-overpass"
      | "unreachable"
      | "rule-conflict";
    readonly detail: string;
  };

export interface ZoneRevealPlanStep {
  readonly index: number;
  readonly source: ResolvedSpecialRevealStep;
  readonly bridgeAction: BridgeTransitionAction | null;
}

export interface ZoneRevealPlan {
  readonly id: string;
  readonly revision: number;
  readonly zoneId: string;
  readonly sessionId: string;
  readonly activationNodeId: NodeId;
  readonly entryConnectorKind: "straight" | "overpass";
  readonly entryConnectorId: EdgeId;
  readonly entryConnectorEndpoints: Readonly<{
    readonly fromNodeId: NodeId;
    readonly toNodeId: NodeId;
  }>;
  /** @deprecated Use entryConnectorEndpoints; retained for debug consumers. */
  readonly entryBridgeEndpoints: Readonly<{
    readonly fromNodeId: NodeId;
    readonly toNodeId: NodeId;
  }>;
  readonly characterNodeId: NodeId;
  readonly kind: "initial-reveal" | "restore-entry-connector";
  /** Retire stale ordinary sessions while safely idle, before the reveal. */
  readonly beforeRevealBridgeActions: readonly BridgeTransitionAction[];
  readonly steps: readonly ZoneRevealPlanStep[];
}

export interface ZoneDismissPlanStep {
  readonly index: number;
  readonly source: ResolvedSpecialRevealStep;
  /** Present only for the leading bridge-retirement portion of the plan. */
  readonly bridgeAction: BridgeTransitionAction | null;
}

/**
 * A complete, independently committed teardown transaction. Bridge sessions
 * are precleared by navigation; hidden nodes and straight roads follow the
 * authored left-to-right reveal sequence in reverse (right-to-left). The plan
 * starts together with physical departure from the session envelope.
 */
export interface ZoneDismissPlan {
  readonly id: string;
  readonly revision: number;
  readonly zoneId: string;
  readonly sessionId: string;
  readonly activationNodeId: NodeId;
  readonly entryConnectorKind: "straight" | "overpass";
  readonly entryConnectorId: EdgeId;
  readonly entryConnectorEndpoints: Readonly<{
    readonly fromNodeId: NodeId;
    readonly toNodeId: NodeId;
  }>;
  /** @deprecated Use entryConnectorEndpoints; retained for debug consumers. */
  readonly entryBridgeEndpoints: Readonly<{
    readonly fromNodeId: NodeId;
    readonly toNodeId: NodeId;
  }>;
  readonly characterNodeId: NodeId;
  readonly kind: "zone-dismissal";
  readonly trigger:
    | "idle-outside-zone"
    | "concurrent-departure-from-session-envelope";
  /** Navigation half of the atomic concurrent departure, otherwise null. */
  readonly linkedNavigationPlanId: string | null;
  readonly steps: readonly ZoneDismissPlanStep[];
}

export interface BridgeRuleInvariantDebug {
  readonly ordinaryBridgeCount: number;
  readonly activeBridgeCount: number;
  readonly maximumActiveBridgesFromOneSource: number;
  readonly duplicateEndpointPairCount: number;
  readonly violations: readonly string[];
}

export interface PathRuleCoordinatorDebugSnapshot {
  readonly revision: number;
  readonly unlockedNodeIds: readonly NodeId[];
  readonly unlockedStraightEdgeIds: readonly EdgeId[];
  readonly zones: readonly {
    readonly id: string;
    readonly activated: boolean;
    readonly revealProgress: number;
    readonly revealStepCount: number;
    readonly entryConnectorKind: "straight" | "overpass" | null;
    readonly entryConnectorId: EdgeId | null;
    readonly entryConnectorActive: boolean;
    readonly entryConnectorEndpoints: Readonly<{
      readonly fromNodeId: NodeId;
      readonly toNodeId: NodeId;
    }> | null;
    /** Legacy bridge-only fields. Straight entries report a null bridge id. */
    readonly entryBridgeId: EdgeId | null;
    readonly entryBridgeActive: boolean;
    readonly dismissalPending: boolean;
    readonly sessionState: "inactive" | "revealing" | "active" | "dismissing";
    readonly sessionId: string | null;
    readonly activationNodeId: NodeId | null;
    readonly entryNodeId: NodeId;
    readonly entryBridgeEndpoints: Readonly<{
      readonly fromNodeId: NodeId;
      readonly toNodeId: NodeId;
    }> | null;
  }[];
  readonly bridges: readonly RuntimeBridgeInstance[];
  readonly invariants: BridgeRuleInvariantDebug;
}

export interface PathRuleCoordinatorOptions {
  readonly nodes: readonly LearningPathNode[];
  /** Physical runtime straight roads, including hidden session entry roads. */
  readonly authoredStraightEdges: readonly StraightLearningPathEdge[];
  /** Immutable hop truth: excludes session entry roads and all runtime bridges. */
  readonly authoredLogicalEdges: readonly BasePathAuthoredEdge[];
  readonly dynamicBridgeRule: DynamicBridgeRuleSpec;
  readonly specialZones: readonly SpecialPathZoneSpec[];
  readonly overpassPairLookup: OverpassPairLookup;
  readonly basePathIndex: BasePathIndex;
}

export interface RestoredZoneSession {
  readonly zoneId: string;
  readonly sessionId: string;
  readonly activationNodeId: NodeId;
  readonly entryNodeId: NodeId;
}

/**
 * Opaque, coordinator-bound snapshot of the rule ledger and all in-flight
 * transaction cursors. A checkpoint is intentionally one-shot: restoring the
 * same checkpoint twice would overwrite work committed after the first
 * recovery, so a repeated restore is rejected explicitly.
 */
declare const pathRuleRecoveryCheckpointBrand: unique symbol;
export interface PathRuleRecoveryCheckpoint {
  readonly [pathRuleRecoveryCheckpointBrand]: true;
}

interface MutableBridgeInstance {
  bridgeId: EdgeId;
  edge: OverpassLearningPathEdge;
  ownerSourceNodeId: NodeId;
  role: RuntimeBridgeRole;
  zoneId: string | null;
  zoneSessionId: string | null;
  active: boolean;
  createdRevision: number;
  changedRevision: number;
}

interface MutableNavigationStage {
  decisionKind: NavigationDecisionKind;
  fromNodeId: NodeId;
  toNodeId: NodeId;
  routeNodeIds: NodeId[];
  routeEdgeIds: EdgeId[];
  baseHopCount: number | null;
  beforeTravelBridgeActions: BridgeTransitionAction[];
  afterArrivalBridgeActions: BridgeTransitionAction[];
}

interface PendingNavigationPlan {
  readonly plan: NavigationPlan;
  nextStageIndex: number;
  nextBeforeActionIndex: number;
  nextAfterActionIndex: number;
  awaitingArrival: boolean;
  /** Latched once MOTION.DEPARTED starts the first stage. */
  departureCommitted: boolean;
}

interface PendingZoneRevealPlan {
  readonly plan: ZoneRevealPlan;
  nextBeforeActionIndex: number;
  nextStepIndex: number;
}

interface PendingZoneDismissPlan {
  readonly plan: ZoneDismissPlan;
  nextStepIndex: number;
}

interface PlanningContext {
  readonly activeBridges: Map<EdgeId, RuntimeBridgeInstance>;
  readonly stages: MutableNavigationStage[];
  pendingBeforeActions: BridgeTransitionAction[];
  readonly traversedTransientBridgeIds: Set<EdgeId>;
}

type ResolvedSessionEntryConnector =
  | Readonly<{
    readonly kind: "straight";
    readonly edgeId: EdgeId;
    readonly endpoints: Readonly<{
      readonly fromNodeId: NodeId;
      readonly toNodeId: NodeId;
    }>;
  }>
  | Readonly<{
    readonly kind: "overpass";
    readonly edgeId: EdgeId;
    readonly endpoints: Readonly<{
      readonly fromNodeId: NodeId;
      readonly toNodeId: NodeId;
    }>;
  }>;

interface ActiveZoneSession {
  readonly id: string;
  readonly zoneId: string;
  readonly activationNodeId: NodeId;
  readonly entryNodeId: NodeId;
  readonly entryConnector: ResolvedSessionEntryConnector;
  state: "revealing" | "active" | "dismissing";
  revealProgress: number;
}

interface ConcurrentZoneDeparture {
  readonly session: ActiveZoneSession;
  readonly zone: SpecialPathZoneSpec;
}

interface RecoveryCheckpointPayload {
  readonly revision: number;
  readonly unlockedNodeIds: readonly NodeId[];
  readonly unlockedStraightEdgeIds: readonly EdgeId[];
  readonly bridgeRegistry: readonly MutableBridgeInstance[];
  readonly activeZoneSession: ActiveZoneSession | null;
  readonly entryConnectorIdByZoneId: readonly (readonly [string, EdgeId])[];
  readonly pendingNavigation: PendingNavigationPlan | null;
  readonly pendingZoneReveals: readonly (readonly [string, PendingZoneRevealPlan])[];
  readonly pendingZoneDismissals: readonly (readonly [string, PendingZoneDismissPlan])[];
}

class NavigationPlanningError extends Error {
  public constructor(
    public readonly reason: Exclude<
      NavigationPlanResult,
      { readonly accepted: true }
    >["reason"],
    message: string,
  ) {
    super(message);
  }
}

/**
 * Pure business-rule coordinator for authored roads, reveal groups and runtime
 * bridge sessions. It never advances time, samples Three.js geometry, or moves
 * the character. Callers may only request navigation while the character is
 * idle at a safe node, then explicitly commit visual transition steps.
 */
export class PathRuleCoordinator {
  private readonly nodes: readonly LearningPathNode[];
  private readonly authoredStraightEdges: readonly StraightLearningPathEdge[];
  private readonly authoredLogicalEdges: readonly BasePathAuthoredEdge[];
  private readonly dynamicBridgeRule: DynamicBridgeRuleSpec;
  private readonly specialZones: readonly SpecialPathZoneSpec[];
  private readonly overpassPairLookup: OverpassPairLookup;
  private readonly basePathIndex: BasePathIndex;

  private readonly nodeById = new Map<NodeId, LearningPathNode>();
  private readonly straightEdgeById = new Map<EdgeId, StraightLearningPathEdge>();
  private readonly zoneById = new Map<string, SpecialPathZoneSpec>();
  private readonly activationZoneByNodeId = new Map<NodeId, SpecialPathZoneSpec>();
  private readonly memberZoneByNodeId = new Map<NodeId, SpecialPathZoneSpec>();
  private readonly entryConnectorIdByZoneId = new Map<string, EdgeId>();

  private readonly unlockedNodeIds = new Set<NodeId>();
  private readonly unlockedStraightEdgeIds = new Set<EdgeId>();
  private readonly bridgeRegistry = new Map<EdgeId, MutableBridgeInstance>();
  private activeZoneSession: ActiveZoneSession | null = null;

  /** Traversable straight roads; session entry connectors are staged explicitly. */
  private activeStraightPathIndex: BasePathIndex;
  private revision = 0;
  private pendingNavigation: PendingNavigationPlan | null = null;
  private readonly pendingZoneRevealById = new Map<string, PendingZoneRevealPlan>();
  private readonly pendingZoneDismissById = new Map<string, PendingZoneDismissPlan>();
  private readonly recoveryPayloadByCheckpoint = new WeakMap<
    object,
    RecoveryCheckpointPayload
  >();
  private readonly restoredRecoveryCheckpoints = new WeakSet<object>();

  public constructor(options: PathRuleCoordinatorOptions) {
    this.nodes = options.nodes;
    this.authoredStraightEdges = options.authoredStraightEdges;
    this.authoredLogicalEdges = options.authoredLogicalEdges;
    this.dynamicBridgeRule = options.dynamicBridgeRule;
    this.specialZones = options.specialZones;
    this.overpassPairLookup = options.overpassPairLookup;
    this.basePathIndex = options.basePathIndex;

    this.validateAndIndexConfiguration();
    this.nodes.forEach((node) => {
      if (node.initiallyVisible) {
        this.unlockedNodeIds.add(node.id);
      }
    });
    this.authoredStraightEdges.forEach((edge) => {
      if (edge.initiallyVisible) {
        this.unlockedStraightEdgeIds.add(edge.id);
      }
    });
    this.activeStraightPathIndex = this.buildActiveStraightPathIndex();
    this.assertInvariants();
  }

  public isNodeUnlocked(nodeId: NodeId): boolean {
    return this.unlockedNodeIds.has(nodeId);
  }

  public isStraightEdgeUnlocked(edgeId: EdgeId): boolean {
    return this.unlockedStraightEdgeIds.has(edgeId);
  }

  public isZoneActivated(zoneId: string): boolean {
    return this.activeZoneSession?.zoneId === zoneId
      && this.activeZoneSession.state !== "revealing";
  }

  public getActiveBridgeInstances(): readonly RuntimeBridgeInstance[] {
    return Object.freeze(
      [...this.bridgeRegistry.values()]
        .filter((bridge) => bridge.active)
        .sort(compareBridgeInstances)
        .map(freezeBridgeInstance),
    );
  }

  /**
   * Captures an exact recovery boundary, including partially consumed plan
   * sequences. The returned value exposes no mutable state to callers and can
   * only be restored by this coordinator instance.
   */
  public createRecoveryCheckpoint(): PathRuleRecoveryCheckpoint {
    this.assertInvariants();
    const checkpoint = Object.freeze(Object.create(null)) as (
      PathRuleRecoveryCheckpoint & object
    );
    this.recoveryPayloadByCheckpoint.set(checkpoint, {
      revision: this.revision,
      unlockedNodeIds: [...this.unlockedNodeIds],
      unlockedStraightEdgeIds: [...this.unlockedStraightEdgeIds],
      bridgeRegistry: [...this.bridgeRegistry.values()].map(cloneMutableBridge),
      activeZoneSession: cloneActiveZoneSession(this.activeZoneSession),
      entryConnectorIdByZoneId: [...this.entryConnectorIdByZoneId.entries()],
      pendingNavigation: clonePendingNavigation(this.pendingNavigation),
      pendingZoneReveals: [...this.pendingZoneRevealById.entries()].map(
        ([zoneId, pending]) => [zoneId, clonePendingZoneReveal(pending)] as const,
      ),
      pendingZoneDismissals: [...this.pendingZoneDismissById.entries()].map(
        ([zoneId, pending]) => [zoneId, clonePendingZoneDismiss(pending)] as const,
      ),
    });
    return checkpoint;
  }

  /**
   * Restores a previously captured recovery boundary. Revision never moves
   * backwards, even when rolling state back, so every subsequently planned
   * transaction receives a fresh plan/session identity.
   */
  public restoreRecoveryCheckpoint(
    checkpoint: PathRuleRecoveryCheckpoint,
  ): void {
    if (typeof checkpoint !== "object" || checkpoint === null) {
      throw new Error("Path-rule recovery checkpoint is invalid.");
    }
    if (this.restoredRecoveryCheckpoints.has(checkpoint)) {
      throw new Error("Path-rule recovery checkpoint was already restored.");
    }
    const payload = this.recoveryPayloadByCheckpoint.get(checkpoint);
    if (!payload) {
      throw new Error(
        "Path-rule recovery checkpoint belongs to another coordinator or is invalid.",
      );
    }

    const recoveryRevision = Math.max(this.revision, payload.revision) + 1;
    replaceSetContents(this.unlockedNodeIds, payload.unlockedNodeIds);
    replaceSetContents(
      this.unlockedStraightEdgeIds,
      payload.unlockedStraightEdgeIds,
    );
    replaceMapContents(
      this.bridgeRegistry,
      payload.bridgeRegistry.map((bridge) => [
        bridge.bridgeId,
        cloneMutableBridge(bridge),
      ] as const),
    );
    this.activeZoneSession = cloneActiveZoneSession(payload.activeZoneSession);
    replaceMapContents(
      this.entryConnectorIdByZoneId,
      payload.entryConnectorIdByZoneId,
    );
    this.pendingNavigation = clonePendingNavigation(payload.pendingNavigation);
    replaceMapContents(
      this.pendingZoneRevealById,
      payload.pendingZoneReveals.map(([zoneId, pending]) => [
        zoneId,
        clonePendingZoneReveal(pending),
      ] as const),
    );
    replaceMapContents(
      this.pendingZoneDismissById,
      payload.pendingZoneDismissals.map(([zoneId, pending]) => [
        zoneId,
        clonePendingZoneDismiss(pending),
      ] as const),
    );
    this.revision = recoveryRevision;
    this.rebuildActiveStraightPathIndex();
    this.assertInvariants();
    this.restoredRecoveryCheckpoints.add(checkpoint);
  }

  /**
   * Recovery-only abort hook for callers that restored the last safe-node
   * checkpoint and intentionally do not want to resume its in-flight command
   * sequence. Sequencing contracts are discarded and a restored session is
   * compensated back to its complete, stable active phase.
   */
  public discardPendingTransactionsAfterRecovery(): void {
    this.pendingNavigation = null;
    this.pendingZoneRevealById.clear();
    this.pendingZoneDismissById.clear();
    if (this.activeZoneSession) {
      this.stabilizeActiveZoneSessionAfterRecovery(this.activeZoneSession);
    }
    this.nextRevision();
    this.rebuildActiveStraightPathIndex();
    this.assertInvariants();
  }

  /**
   * Returns the next declarative reveal sequence. A dismissed repeatable
   * session replays the entire authored sequence on the next idle visit to its
   * activation node.
   */
  public planIdleZoneReveal(characterNodeId: NodeId): ZoneRevealPlan | null {
    if (this.pendingNavigation || this.pendingZoneDismissById.size > 0) {
      return null;
    }
    const existingSession = this.activeZoneSession;
    const zone = existingSession
      ? this.zoneById.get(existingSession.zoneId) ?? null
      : this.activationZoneByNodeId.get(characterNodeId) ?? null;
    if (!zone || (existingSession && (
      existingSession.state === "dismissing"
      || !this.isNodeInSession(characterNodeId, existingSession, zone)
    ))) {
      return null;
    }

    const existingPending = this.pendingZoneRevealById.get(zone.id);
    if (existingPending) {
      return existingPending.plan;
    }
    if (this.pendingZoneRevealById.size > 0) {
      return null;
    }

    const hasStaleTransientBridge = [...this.bridgeRegistry.values()].some(
      (bridge) => bridge.active && bridge.role !== "zone-entry",
    );
    if (existingSession) {
      if (this.isSessionEntryConnectorActive(existingSession)
        && !hasStaleTransientBridge) {
        return null;
      }
    }

    const planRevision = this.nextRevision();
    const session = existingSession ?? this.createZoneSession(
      zone,
      characterNodeId,
      planRevision,
    );
    const projectedBridges = this.snapshotActiveBridges();
    const beforeRevealBridgeActions = [...projectedBridges.values()]
      .filter((bridge) => (
        bridge.role !== "zone-entry"
        || bridge.zoneSessionId !== session.id
      ))
      .sort((left, right) => this.compareBridgesByCharacterProximity(
        left,
        right,
        characterNodeId,
      ))
      .map((bridge) => this.makeRetireBridgeAction(
        bridge,
        characterNodeId,
      ));
    beforeRevealBridgeActions.forEach((action) => {
      applyActionToProjection(action, projectedBridges);
    });
    const sources: readonly SpecialRevealStep[] = existingSession
      ? [Object.freeze({ kind: "session-entry-connector" as const })]
      : zone.revealSequence.slice(session.revealProgress);
    const steps = sources.map((template, index): ZoneRevealPlanStep => {
      const source = this.resolveRevealStep(template, session);
      const bridgeAction = source.kind === "bridge"
        ? this.makeEnsureBridgeAction(
          source.endpoints.fromNodeId,
          source.endpoints.toNodeId,
          session.activationNodeId,
          "zone-entry",
          zone.id,
          session.id,
          characterNodeId,
          projectedBridges,
        )
        : null;
      return Object.freeze({ index, source, bridgeAction });
    });
    const plan: ZoneRevealPlan = Object.freeze({
      id: `zone-reveal:${zone.id}:${planRevision}`,
      revision: planRevision,
      zoneId: zone.id,
      sessionId: session.id,
      activationNodeId: session.activationNodeId,
      entryConnectorKind: session.entryConnector.kind,
      entryConnectorId: session.entryConnector.edgeId,
      entryConnectorEndpoints: session.entryConnector.endpoints,
      entryBridgeEndpoints: session.entryConnector.endpoints,
      characterNodeId,
      kind: existingSession ? "restore-entry-connector" : "initial-reveal",
      beforeRevealBridgeActions: Object.freeze(beforeRevealBridgeActions),
      steps: Object.freeze(steps),
    });
    this.pendingZoneRevealById.set(zone.id, {
      plan,
      nextBeforeActionIndex: 0,
      nextStepIndex: 0,
    });
    return plan;
  }

  /** Commit one stale-bridge retirement before starting a zone reveal. */
  public commitZoneRevealBeforeAction(planId: string, actionIndex: number): void {
    const pending = this.findPendingZoneReveal(planId);
    if (actionIndex !== pending.nextBeforeActionIndex) {
      throw new Error(
        `Zone reveal "${planId}" expected before-action `
        + `${pending.nextBeforeActionIndex}, received ${actionIndex}.`,
      );
    }
    const action = pending.plan.beforeRevealBridgeActions[actionIndex];
    if (!action) {
      throw new Error(`Zone reveal "${planId}" has no before-action ${actionIndex}.`);
    }
    this.applyBridgeAction(action);
    pending.nextBeforeActionIndex += 1;
    this.assertInvariants();
  }

  /** Commit one reveal item after its fall animation has completed. */
  public commitZoneRevealStep(planId: string, stepIndex: number): void {
    const pending = this.findPendingZoneReveal(planId);
    if (pending.nextBeforeActionIndex
      !== pending.plan.beforeRevealBridgeActions.length) {
      throw new Error(`Zone reveal "${planId}" still has before-actions.`);
    }
    if (stepIndex !== pending.nextStepIndex) {
      throw new Error(
        `Zone reveal "${planId}" expected step ${pending.nextStepIndex}, received ${stepIndex}.`,
      );
    }
    const step = pending.plan.steps[stepIndex];
    if (!step) {
      throw new Error(`Zone reveal "${planId}" has no step ${stepIndex}.`);
    }

    if (step.source.kind === "node") {
      this.unlockNode(step.source.nodeId);
    } else if (step.source.kind === "straight-edge") {
      this.unlockStraightEdge(step.source.edgeId);
    } else if (step.bridgeAction) {
      this.applyBridgeAction(step.bridgeAction);
    }

    pending.nextStepIndex += 1;
    const session = this.requireSession(pending.plan.sessionId);
    if (pending.plan.kind === "initial-reveal") {
      session.revealProgress += 1;
    }
    if (pending.nextStepIndex === pending.plan.steps.length) {
      session.state = "active";
      this.pendingZoneRevealById.delete(pending.plan.zoneId);
    }
    this.assertInvariants();
  }

  /** Reduced-motion convenience: commits the remaining sequence in order. */
  public commitEntireZoneReveal(planId: string): void {
    const pending = this.findPendingZoneReveal(planId);
    while (pending.nextBeforeActionIndex
      < pending.plan.beforeRevealBridgeActions.length) {
      this.commitZoneRevealBeforeAction(planId, pending.nextBeforeActionIndex);
    }
    while (pending.nextStepIndex < pending.plan.steps.length) {
      this.commitZoneRevealStep(planId, pending.nextStepIndex);
    }
  }

  /**
   * @deprecated Activation-to-green departure is now one atomic transaction
   * returned by planNavigation(). Retained temporarily for source compatibility.
   */
  public planZoneDepartureDismissal(
    characterNodeId: NodeId,
    targetNodeId: NodeId,
  ): ZoneDismissPlan | null {
    void characterNodeId;
    void targetNodeId;
    return null;
  }

  /**
   * Plans the repeatable-session teardown after the character has completed an
   * Legacy recovery hook for a session already found outside its envelope.
   * Normal navigation creates the linked departure dismissal immediately.
   */
  public planIdleZoneDismissal(characterNodeId: NodeId): ZoneDismissPlan | null {
    if (!this.nodeById.has(characterNodeId)) {
      return null;
    }
    if (this.pendingNavigation || this.pendingZoneRevealById.size > 0) {
      return null;
    }

    const existing = [...this.pendingZoneDismissById.values()]
      .sort((left, right) => left.plan.zoneId.localeCompare(right.plan.zoneId))[0];
    if (existing) {
      return existing.plan;
    }

    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    if (!session || !zone || session.state !== "active"
      || this.isNodeInSession(characterNodeId, session, zone)) {
      return null;
    }

    return this.buildZoneDismissPlan(
      session,
      zone,
      characterNodeId,
      "idle-outside-zone",
    );
  }

  private buildZoneDismissPlan(
    session: ActiveZoneSession,
    zone: SpecialPathZoneSpec,
    characterNodeId: NodeId,
    trigger: ZoneDismissPlan["trigger"],
  ): ZoneDismissPlan {
    const plan = this.createZoneDismissPlan(
      session,
      zone,
      characterNodeId,
      trigger,
      null,
    );
    this.registerZoneDismissPlan(session, zone, plan);
    return plan;
  }

  private createZoneDismissPlan(
    session: ActiveZoneSession,
    zone: SpecialPathZoneSpec,
    characterNodeId: NodeId,
    trigger: ZoneDismissPlan["trigger"],
    linkedNavigationPlanId: string | null,
  ): ZoneDismissPlan {
    const planRevision = this.nextRevision();
    // Bridge teardown belongs to the navigation transaction. Keeping this
    // plan construct-only makes the right-to-left disappearance independent
    // from the entry-overpass preclear and safe to run beside movement.
    const constructSteps = [...zone.revealSequence]
      .reverse()
      .map((source) => this.resolveRevealStep(source, session))
      .filter((source) => source.kind !== "bridge")
      .map((source): Omit<ZoneDismissPlanStep, "index"> => Object.freeze({
        source,
        bridgeAction: null,
      }));
    const steps = constructSteps
      .map((step, index): ZoneDismissPlanStep => Object.freeze({
        index,
        source: step.source,
        bridgeAction: step.bridgeAction,
      }));
    const plan: ZoneDismissPlan = Object.freeze({
      id: `zone-dismiss:${zone.id}:${planRevision}`,
      revision: planRevision,
      zoneId: zone.id,
      sessionId: session.id,
      activationNodeId: session.activationNodeId,
      entryConnectorKind: session.entryConnector.kind,
      entryConnectorId: session.entryConnector.edgeId,
      entryConnectorEndpoints: session.entryConnector.endpoints,
      entryBridgeEndpoints: session.entryConnector.endpoints,
      characterNodeId,
      kind: "zone-dismissal",
      trigger,
      linkedNavigationPlanId,
      steps: Object.freeze(steps),
    });
    return plan;
  }

  private registerZoneDismissPlan(
    session: ActiveZoneSession,
    zone: SpecialPathZoneSpec,
    plan: ZoneDismissPlan,
  ): void {
    session.state = "dismissing";
    this.pendingZoneDismissById.set(zone.id, {
      plan,
      nextStepIndex: 0,
    });
  }

  /** Commit one completed rise/disappear animation in strict plan order. */
  public commitZoneDismissStep(planId: string, stepIndex: number): void {
    const pending = this.findPendingZoneDismiss(planId);
    if (stepIndex !== pending.nextStepIndex) {
      throw new Error(
        `Zone dismissal "${planId}" expected step ${pending.nextStepIndex}, `
        + `received ${stepIndex}.`,
      );
    }
    const step = pending.plan.steps[stepIndex];
    if (!step) {
      throw new Error(`Zone dismissal "${planId}" has no step ${stepIndex}.`);
    }
    if (pending.plan.trigger
      === "concurrent-departure-from-session-envelope") {
      const linkedNavigation = this.pendingNavigation;
      if (!linkedNavigation
        || linkedNavigation.plan.id !== pending.plan.linkedNavigationPlanId
        || !linkedNavigation.departureCommitted) {
        throw new Error(
          `Concurrent dismissal "${planId}" cannot commit before its linked `
          + "navigation emits MOTION.DEPARTED and starts stage 0.",
        );
      }
      const activeSessionBridge = [...this.bridgeRegistry.values()].find(
        (bridge) => (
          bridge.active && bridge.zoneSessionId === pending.plan.sessionId
        ),
      );
      if (activeSessionBridge) {
        throw new Error(
          `Concurrent dismissal "${planId}" must wait for navigation to retire `
          + `session bridge "${activeSessionBridge.bridgeId}".`,
        );
      }
    }

    if (step.source.kind === "bridge") {
      if (!step.bridgeAction || step.bridgeAction.kind !== "retire-bridge") {
        throw new Error(`Zone dismissal "${planId}" has an invalid bridge step.`);
      }
      this.applyBridgeAction(step.bridgeAction);
    } else if (step.source.kind === "node") {
      this.lockNode(step.source.nodeId);
    } else {
      this.lockStraightEdge(step.source.edgeId);
    }

    pending.nextStepIndex += 1;
    if (pending.nextStepIndex === pending.plan.steps.length) {
      this.finishZoneDismissal(pending.plan.zoneId);
    }
    this.assertInvariants();
  }

  /** Reduced-motion/test convenience: commits the remaining teardown in order. */
  public commitEntireZoneDismissal(planId: string): void {
    const pending = this.findPendingZoneDismiss(planId);
    while (pending.nextStepIndex < pending.plan.steps.length) {
      this.commitZoneDismissStep(planId, pending.nextStepIndex);
    }
  }

  /**
   * Plan an idle click. The authored BasePathIndex is the only hop oracle;
   * projected or active runtime bridges never feed back into the threshold.
   */
  public planNavigation(
    currentNodeId: NodeId,
    targetNodeId: NodeId,
  ): NavigationPlanResult {
    if (
      this.pendingNavigation
      || this.pendingZoneRevealById.size > 0
      || this.pendingZoneDismissById.size > 0
    ) {
      return rejectPlan(
        "rule-conflict",
        "A rule transaction is already awaiting visual or movement commits.",
      );
    }
    if (!this.nodeById.has(currentNodeId) || !this.nodeById.has(targetNodeId)) {
      return rejectPlan("unknown-node", "Navigation references an unknown node.");
    }
    if (!this.unlockedNodeIds.has(currentNodeId)) {
      return rejectPlan("locked-node", `Current node "${currentNodeId}" is locked.`);
    }
    if (!this.unlockedNodeIds.has(targetNodeId)) {
      return rejectPlan("locked-node", `Target node "${targetNodeId}" is locked.`);
    }
    if (this.hasActivatedZoneOutsideCharacter(currentNodeId)) {
      return rejectPlan(
        "rule-conflict",
        "A completed zone exit must finish its idle dismissal before navigation.",
      );
    }

    const concurrentDeparture = this.resolveConcurrentZoneDeparture(
      currentNodeId,
      targetNodeId,
    );

    const planRevision = this.nextRevision();
    const context: PlanningContext = {
      activeBridges: this.snapshotActiveBridges(),
      stages: [],
      pendingBeforeActions: [],
      traversedTransientBridgeIds: new Set<EdgeId>(),
    };

    try {
      if (currentNodeId !== targetNodeId) {
        this.buildNavigationStages(
          currentNodeId,
          targetNodeId,
          context,
        );
        this.attachTransientRetirements(
          context,
          targetNodeId,
        );
      }
      if (concurrentDeparture) {
        this.normalizeConcurrentDepartureBridgeActions(
          concurrentDeparture.session,
          context,
        );
      }
      const navigationPlanId = `navigation-plan:${planRevision}`;
      const concurrentZoneDismissalPlan = concurrentDeparture
        ? this.createZoneDismissPlan(
          concurrentDeparture.session,
          concurrentDeparture.zone,
          currentNodeId,
          "concurrent-departure-from-session-envelope",
          navigationPlanId,
        )
        : null;
      const plan = this.freezeNavigationPlan(
        planRevision,
        currentNodeId,
        targetNodeId,
        context.stages,
        concurrentZoneDismissalPlan?.id ?? null,
      );
      if (concurrentZoneDismissalPlan) {
        this.validateConcurrentDepartureTransaction(
          concurrentDeparture!.session,
          plan,
          concurrentZoneDismissalPlan,
        );
      }
      this.pendingNavigation = plan.stages.length === 0
        ? null
        : {
          plan,
          nextStageIndex: 0,
          nextBeforeActionIndex: 0,
          nextAfterActionIndex: 0,
          awaitingArrival: false,
          departureCommitted: false,
        };
      if (concurrentZoneDismissalPlan) {
        this.registerZoneDismissPlan(
          concurrentDeparture!.session,
          concurrentDeparture!.zone,
          concurrentZoneDismissalPlan,
        );
      }
      this.assertInvariants();
      return {
        accepted: true,
        plan,
        concurrentZoneDismissalPlan,
      };
    } catch (error) {
      if (error instanceof NavigationPlanningError) {
        return rejectPlan(error.reason, error.message);
      }
      throw error;
    }
  }

  /** Commit one pre-travel bridge transition after its animation completes. */
  public commitNavigationBeforeAction(
    planId: string,
    stageIndex: number,
    actionIndex: number,
  ): void {
    const pending = this.requirePendingNavigation(planId, stageIndex);
    if (pending.awaitingArrival) {
      throw new Error(`Navigation stage ${stageIndex} has already started.`);
    }
    if (actionIndex !== pending.nextBeforeActionIndex) {
      throw new Error(
        `Navigation stage ${stageIndex} expected before-action `
        + `${pending.nextBeforeActionIndex}, received ${actionIndex}.`,
      );
    }
    const stage = pending.plan.stages[stageIndex]!;
    const action = stage.beforeTravelBridgeActions[actionIndex];
    if (!action) {
      throw new Error(`Navigation stage ${stageIndex} has no before-action ${actionIndex}.`);
    }
    this.applyBridgeAction(action);
    pending.nextBeforeActionIndex += 1;
    this.assertInvariants();
  }

  /** Marks requestRoute() as started after all pre-travel actions are settled. */
  public commitNavigationStageStarted(planId: string, stageIndex: number): void {
    const pending = this.requirePendingNavigation(planId, stageIndex);
    const stage = pending.plan.stages[stageIndex]!;
    if (pending.nextBeforeActionIndex !== stage.beforeTravelBridgeActions.length) {
      throw new Error(
        `Navigation stage ${stageIndex} still has uncommitted before-actions.`,
      );
    }
    if (pending.awaitingArrival) {
      throw new Error(`Navigation stage ${stageIndex} was already started.`);
    }
    pending.awaitingArrival = true;
    if (stageIndex === 0) pending.departureCommitted = true;
    this.assertInvariants();
  }

  /** Commit one bridge transition immediately on physical arrival at the node. */
  public commitNavigationAfterAction(
    planId: string,
    stageIndex: number,
    actionIndex: number,
    arrivedNodeId: NodeId,
  ): void {
    const pending = this.requirePendingNavigation(planId, stageIndex);
    const stage = pending.plan.stages[stageIndex]!;
    this.assertExpectedArrival(pending, stage, arrivedNodeId);
    if (actionIndex !== pending.nextAfterActionIndex) {
      throw new Error(
        `Navigation stage ${stageIndex} expected after-action `
        + `${pending.nextAfterActionIndex}, received ${actionIndex}.`,
      );
    }
    const action = stage.afterArrivalBridgeActions[actionIndex];
    if (!action) {
      throw new Error(`Navigation stage ${stageIndex} has no after-action ${actionIndex}.`);
    }
    this.applyBridgeAction(action);
    pending.nextAfterActionIndex += 1;
    this.assertInvariants();
  }

  /** Advances to the next stage after movement and all arrival actions finish. */
  public commitNavigationStageArrived(
    planId: string,
    stageIndex: number,
    arrivedNodeId: NodeId,
  ): void {
    const pending = this.requirePendingNavigation(planId, stageIndex);
    const stage = pending.plan.stages[stageIndex]!;
    this.assertExpectedArrival(pending, stage, arrivedNodeId);
    if (pending.nextAfterActionIndex !== stage.afterArrivalBridgeActions.length) {
      throw new Error(
        `Navigation stage ${stageIndex} still has uncommitted after-actions.`,
      );
    }

    pending.nextStageIndex += 1;
    pending.nextBeforeActionIndex = 0;
    pending.nextAfterActionIndex = 0;
    pending.awaitingArrival = false;
    if (pending.nextStageIndex === pending.plan.stages.length) {
      const linkedDismissalStillPending = pending.plan.linkedZoneDismissalPlanId !== null
        && [...this.pendingZoneDismissById.values()].some(
          (candidate) => candidate.plan.id === pending.plan.linkedZoneDismissalPlanId,
        );
      // A concurrent zone cleanup may legitimately outlive the character's
      // physical trip. Keep the linked navigation transaction as the departure
      // proof until the last right-to-left construct has acknowledged hidden;
      // otherwise later dismissal ACKs lose their MOTION.DEPARTED latch.
      if (!linkedDismissalStillPending) {
        this.pendingNavigation = null;
      }
    }
    this.assertInvariants();
  }

  /**
   * Abandons only the remaining sequencing contract. Bridge actions already
   * committed after completed animations are durable and are not rolled back.
   */
  public cancelNavigationPlan(planId: string): void {
    const pending = this.pendingNavigation;
    if (!pending || pending.plan.id !== planId) {
      return;
    }
    const linkedDismissalPlanId = pending.plan.linkedZoneDismissalPlanId;
    if (linkedDismissalPlanId) {
      const linkedPending = [...this.pendingZoneDismissById.values()].find(
        (candidate) => candidate.plan.id === linkedDismissalPlanId,
      );
      if (!linkedPending) {
        throw new Error(
          `Navigation plan "${planId}" cannot be cancelled after its linked `
          + "dismissal has completed.",
        );
      }
      const untouched = pending.nextStageIndex === 0
        && pending.nextBeforeActionIndex === 0
        && pending.nextAfterActionIndex === 0
        && !pending.awaitingArrival
        && !pending.departureCommitted
        && linkedPending.nextStepIndex === 0;
      if (!untouched) {
        throw new Error(
          `Atomic navigation plan "${planId}" cannot be cancelled after commits begin.`,
        );
      }
      this.pendingZoneDismissById.delete(linkedPending.plan.zoneId);
      const session = this.activeZoneSession;
      if (!session || session.id !== linkedPending.plan.sessionId) {
        throw new Error(
          `Atomic navigation plan "${planId}" lost its zone session.`,
        );
      }
      session.state = "active";
      this.nextRevision();
    }
    this.pendingNavigation = null;
    this.assertInvariants();
  }

  /** Explicit persistence hook for reveal systems outside the built-in plans. */
  public unlockNode(nodeId: NodeId): void {
    if (!this.nodeById.has(nodeId)) {
      throw new Error(`Cannot unlock unknown node "${nodeId}".`);
    }
    if (!this.unlockedNodeIds.has(nodeId)) {
      this.unlockedNodeIds.add(nodeId);
      this.nextRevision();
      this.rebuildActiveStraightPathIndex();
    }
  }

  /** Explicit persistence hook for reveal systems outside the built-in plans. */
  public unlockStraightEdge(edgeId: EdgeId): void {
    const edge = this.straightEdgeById.get(edgeId);
    if (!edge) {
      throw new Error(`Cannot unlock unknown straight edge "${edgeId}".`);
    }
    if (!this.unlockedStraightEdgeIds.has(edgeId)) {
      this.unlockedStraightEdgeIds.add(edgeId);
      this.nextRevision();
      this.rebuildActiveStraightPathIndex();
    }
  }

  private lockNode(nodeId: NodeId): void {
    const node = this.nodeById.get(nodeId);
    if (!node) {
      throw new Error(`Cannot lock unknown node "${nodeId}".`);
    }
    if (node.initiallyVisible) {
      throw new Error(`Repeatable dismissal cannot lock initial node "${nodeId}".`);
    }
    if (this.unlockedNodeIds.delete(nodeId)) {
      this.nextRevision();
      this.rebuildActiveStraightPathIndex();
    }
  }

  private lockStraightEdge(edgeId: EdgeId): void {
    const edge = this.straightEdgeById.get(edgeId);
    if (!edge) {
      throw new Error(`Cannot lock unknown straight edge "${edgeId}".`);
    }
    if (edge.initiallyVisible) {
      throw new Error(`Repeatable dismissal cannot lock initial edge "${edgeId}".`);
    }
    if (this.unlockedStraightEdgeIds.delete(edgeId)) {
      this.nextRevision();
      this.rebuildActiveStraightPathIndex();
    }
  }

  /** Retires a bridge only while the caller has the character on a safe node. */
  public retireBridge(bridgeId: EdgeId, safeNodeId: NodeId): void {
    if (!this.nodeById.has(safeNodeId)) {
      throw new Error(`Cannot retire a bridge from unknown safe node "${safeNodeId}".`);
    }
    this.commitBridgeRetirement(bridgeId);
    this.assertInvariants();
  }

  public getDebugSnapshot(): PathRuleCoordinatorDebugSnapshot {
    const zones = this.specialZones.map((zone) => {
      const session = this.activeZoneSession?.zoneId === zone.id
        ? this.activeZoneSession
        : null;
      const entryConnectorId = session
        ? this.entryConnectorIdByZoneId.get(zone.id) ?? null
        : null;
      const entryBridgeId = session?.entryConnector.kind === "overpass"
        ? entryConnectorId
        : null;
      const activated = session !== null && session.state !== "revealing";
      const revealing = this.pendingZoneRevealById.has(zone.id);
      const dismissing = this.pendingZoneDismissById.has(zone.id);
      const entryBridge = entryBridgeId === null
        ? null
        : this.bridgeRegistry.get(entryBridgeId) ?? null;
      return Object.freeze({
        id: zone.id,
        activated,
        revealProgress: session?.revealProgress ?? 0,
        revealStepCount: zone.revealSequence.length,
        entryConnectorKind: session?.entryConnector.kind ?? null,
        entryConnectorId,
        entryConnectorActive: session
          ? this.isSessionEntryConnectorActive(session)
          : false,
        entryConnectorEndpoints: session?.entryConnector.endpoints ?? null,
        entryBridgeId,
        entryBridgeActive: entryBridge?.active === true
          && entryBridge.role === "zone-entry"
          && entryBridge.zoneSessionId === session?.id,
        dismissalPending: dismissing,
        sessionState: dismissing
          ? "dismissing" as const
          : revealing
            ? "revealing" as const
            : activated
              ? "active" as const
              : "inactive" as const,
        sessionId: session?.id ?? null,
        activationNodeId: session?.activationNodeId ?? null,
        entryNodeId: zone.entryNodeId,
        entryBridgeEndpoints: session?.entryConnector.endpoints ?? null,
      });
    });
    return Object.freeze({
      revision: this.revision,
      unlockedNodeIds: Object.freeze([...this.unlockedNodeIds].sort()),
      unlockedStraightEdgeIds: Object.freeze(
        [...this.unlockedStraightEdgeIds].sort(),
      ),
      zones: Object.freeze(zones),
      bridges: Object.freeze(
        [...this.bridgeRegistry.values()]
          .sort(compareBridgeInstances)
          .map(freezeBridgeInstance),
      ),
      invariants: this.getInvariantDebug(),
    });
  }

  /** Allocation-free render-loop query; inactive zones have no live session. */
  public hasVisibleZoneSession(): boolean {
    return this.activeZoneSession !== null;
  }

  /**
   * Reconstructs the stable repeatable-session envelope required by a
   * persisted concept/member node. Persistence deliberately stores learning
   * progress rather than transient presentation plans, so a fresh coordinator
   * must rebuild the zone topology before the restored node can participate in
   * navigation again.
   *
   * This method commits the complete reveal synchronously and emits no timed
   * presentation work. The caller is responsible for projecting the resulting
   * rule snapshot into its renderer before interaction is enabled.
   */
  public restoreStableZoneSessionForNode(
    nodeId: NodeId,
    preferredActivationNodeId?: NodeId,
  ): RestoredZoneSession | null {
    if (!this.nodeById.has(nodeId)) {
      throw new Error(`Cannot restore an unknown node "${nodeId}".`);
    }
    const zone = this.memberZoneByNodeId.get(nodeId) ?? null;
    if (!zone) return null;

    const existing = this.activeZoneSession;
    if (existing) {
      if (existing.zoneId !== zone.id
        || existing.state !== "active"
        || !this.isNodeInSession(nodeId, existing, zone)) {
        throw new Error(
          `Cannot restore zone "${zone.id}" while session "${existing.id}" is active.`,
        );
      }
      return Object.freeze({
        zoneId: zone.id,
        sessionId: existing.id,
        activationNodeId: existing.activationNodeId,
        entryNodeId: existing.entryNodeId,
      });
    }
    if (this.pendingNavigation
      || this.pendingZoneRevealById.size > 0
      || this.pendingZoneDismissById.size > 0) {
      throw new Error(
        `Cannot restore zone "${zone.id}" while another path transaction is pending.`,
      );
    }

    const activationNodeId = preferredActivationNodeId
      ?? zone.activationNodeIds.find((candidate) => (
        this.unlockedNodeIds.has(candidate)
      ))
      ?? zone.activationNodeIds[0];
    if (!activationNodeId
      || !zone.activationNodeIds.includes(activationNodeId)) {
      throw new Error(
        `Node "${String(preferredActivationNodeId)}" is not an activation for zone "${zone.id}".`,
      );
    }

    // A member could only have become a persisted safe node through this
    // activation. Reinstating its physical visibility is therefore a
    // reconciliation of established progress, not a new learning unlock.
    this.unlockNode(activationNodeId);
    const plan = this.planIdleZoneReveal(activationNodeId);
    if (!plan) {
      throw new Error(`Cannot reconstruct the reveal plan for zone "${zone.id}".`);
    }
    this.commitEntireZoneReveal(plan.id);
    const session = this.activeZoneSession;
    if (!session
      || session.zoneId !== zone.id
      || session.state !== "active"
      || !this.unlockedNodeIds.has(nodeId)
      || !this.isSessionEntryConnectorActive(session)) {
      throw new Error(`Zone "${zone.id}" did not reach a stable restored state.`);
    }
    this.assertInvariants();
    return Object.freeze({
      zoneId: zone.id,
      sessionId: session.id,
      activationNodeId: session.activationNodeId,
      entryNodeId: session.entryNodeId,
    });
  }

  public assertInvariants(): void {
    const debug = this.getInvariantDebug();
    if (debug.violations.length > 0) {
      throw new Error(`Path-rule invariant failed: ${debug.violations.join("; ")}`);
    }
  }

  private resolveConcurrentZoneDeparture(
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
  ): ConcurrentZoneDeparture | null {
    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    if (!session || !zone || session.state !== "active"
      || targetNodeId === sourceNodeId
      || !this.isNodeInSession(sourceNodeId, session, zone)
      || !this.unlockedNodeIds.has(targetNodeId)
      || this.isNodeInSession(targetNodeId, session, zone)) {
      return null;
    }
    return { session, zone };
  }

  /**
   * Makes bridge teardown the navigation half of the atomic departure. The
   * linked construct dismissal therefore contains no bridge steps and can run
   * beside movement without racing a second retirement of the same bridge.
   */
  private normalizeConcurrentDepartureBridgeActions(
    session: ActiveZoneSession,
    context: PlanningContext,
  ): void {
    const firstStage = context.stages[0];
    if (!firstStage) {
      throw new NavigationPlanningError(
        "unreachable",
        "Concurrent zone departure did not produce a navigation stage.",
      );
    }
    const entryBridge = session.entryConnector.kind === "overpass"
      ? this.bridgeRegistry.get(session.entryConnector.edgeId) ?? null
      : null;
    const entryBridgeId = entryBridge?.active === true
      && entryBridge.role === "zone-entry"
      && entryBridge.zoneSessionId === session.id
      ? entryBridge.bridgeId
      : null;
    const withoutSessionRetirements = (
      actions: BridgeTransitionAction[],
    ): BridgeTransitionAction[] => actions.filter((action) => !(
      action.kind === "retire-bridge"
      && action.bridgeId === entryBridgeId
    ));

    context.stages.forEach((stage) => {
      stage.beforeTravelBridgeActions = withoutSessionRetirements(
        stage.beforeTravelBridgeActions,
      );
      stage.afterArrivalBridgeActions = withoutSessionRetirements(
        stage.afterArrivalBridgeActions,
      );
    });
    context.pendingBeforeActions = withoutSessionRetirements(
      context.pendingBeforeActions,
    );

    const retirements = entryBridgeId && entryBridge
      ? [this.makeRetireBridgeAction(
        freezeBridgeInstance(entryBridge),
        // Entry overpasses always rise from the special-green (left) end,
        // independent of which brown platform the character is leaving.
        session.activationNodeId,
      )]
      : [];
    firstStage.beforeTravelBridgeActions = [
      ...retirements,
      ...firstStage.beforeTravelBridgeActions,
    ];
    if (entryBridgeId) context.activeBridges.delete(entryBridgeId);
  }

  private validateConcurrentDepartureTransaction(
    session: ActiveZoneSession,
    navigationPlan: NavigationPlan,
    dismissalPlan: ZoneDismissPlan,
  ): void {
    if (dismissalPlan.trigger
      !== "concurrent-departure-from-session-envelope"
      || dismissalPlan.linkedNavigationPlanId !== navigationPlan.id
      || navigationPlan.linkedZoneDismissalPlanId !== dismissalPlan.id) {
      throw new NavigationPlanningError(
        "rule-conflict",
        "Concurrent zone departure plans are not linked symmetrically.",
      );
    }
    if (dismissalPlan.steps.some((step) => (
      step.source.kind === "bridge" || step.bridgeAction !== null
    ))) {
      throw new NavigationPlanningError(
        "rule-conflict",
        "Concurrent construct dismissal cannot contain bridge steps.",
      );
    }

    const entryBridgeId = session.entryConnector.kind === "overpass"
      && this.bridgeRegistry.get(session.entryConnector.edgeId)?.active === true
      ? session.entryConnector.edgeId
      : null;
    const firstStage = navigationPlan.stages[0];
    if (!firstStage) {
      throw new NavigationPlanningError(
        "unreachable",
        "Concurrent zone departure has no first navigation stage.",
      );
    }
    const allActions = navigationPlan.stages.flatMap((stage) => [
      ...stage.beforeTravelBridgeActions,
      ...stage.afterArrivalBridgeActions,
    ]);
    if (entryBridgeId) {
      const retireCount = allActions.filter((action) => (
        action.kind === "retire-bridge" && action.bridgeId === entryBridgeId
      )).length;
      if (retireCount !== 1) {
        throw new NavigationPlanningError(
          "rule-conflict",
          `Session entry bridge "${entryBridgeId}" has ${retireCount} departure retirements.`,
        );
      }
    }
    const firstAction = firstStage.beforeTravelBridgeActions[0];
    if (entryBridgeId && (
      firstAction?.kind !== "retire-bridge"
      || firstAction.bridgeId !== entryBridgeId
      || firstAction.characterSideNodeId !== session.activationNodeId
    )) {
      throw new NavigationPlanningError(
        "rule-conflict",
        "The session entry overpass must preclear left-to-right before travel.",
      );
    }

    const projection = this.snapshotActiveBridges();
    navigationPlan.stages.forEach((stage) => {
      stage.beforeTravelBridgeActions.forEach((action) => {
        if (action.kind === "ensure-bridge" && action.bridge.role === "ordinary") {
          const staleSessionBridge = [...projection.values()].find((bridge) => (
            bridge.active && bridge.zoneSessionId === session.id
          ));
          if (staleSessionBridge) {
            throw new NavigationPlanningError(
              "rule-conflict",
              `Ordinary bridge was ensured before session bridge `
              + `"${staleSessionBridge.bridgeId}" retired.`,
            );
          }
        }
        applyActionToProjection(action, projection);
      });
      stage.afterArrivalBridgeActions.forEach((action) => {
        applyActionToProjection(action, projection);
      });
    });
  }

  private buildNavigationStages(
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
  ): void {
    if (sourceNodeId === targetNodeId) {
      return;
    }

    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    const sourceInSession = session !== null && zone !== null
      && this.isNodeInSession(sourceNodeId, session, zone);
    const targetInSession = session !== null && zone !== null
      && this.isNodeInSession(targetNodeId, session, zone);

    if (sourceInSession && session && zone) {
      if (session.state !== "active") {
        throw new NavigationPlanningError(
          "rule-conflict",
          `Zone session "${session.id}" is not ready for traversal.`,
        );
      }
      if (targetInSession) {
        this.planInsideZone(
          zone,
          session,
          sourceNodeId,
          targetNodeId,
          context,
        );
      } else {
        this.planLeaveZone(
          zone,
          session,
          sourceNodeId,
          targetNodeId,
          context,
        );
      }
      return;
    }

    if (targetInSession) {
      throw new NavigationPlanningError(
        "rule-conflict",
        "An active zone cannot be entered from outside before its prior exit is dismissed.",
      );
    }

    this.planOrdinaryRoute(
      sourceNodeId,
      targetNodeId,
      context,
      "base-route",
      "ordinary-overpass",
    );

  }

  private planInsideZone(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
  ): void {
    this.planEnsureZoneEntry(session, sourceNodeId, context);
    const activationToMemberHopCount = zone.activationMemberRoutingPolicy
      === "direct-only-from-activation-to-far-member-otherwise-existing-chain"
      && sourceNodeId === session.activationNodeId
      && zone.memberNodeIds.includes(targetNodeId)
      ? this.sessionAwareHopDistance(sourceNodeId, targetNodeId)
      : null;
    if (activationToMemberHopCount !== null
      && this.requiresDynamicBridge(activationToMemberHopCount)) {
      // This is the sole two-bridge exception: an overpass entry remains while
      // the activation green gets one direct transient to a far brown member.
      // With a straight entry the same route owns only that single transient.
      this.planZoneTransientOverpass(
        zone,
        sourceNodeId,
        targetNodeId,
        context,
        activationToMemberHopCount,
        true,
      );
      return;
    }
    if (sourceNodeId === session.activationNodeId) {
      this.addSessionEntryStage(
        session,
        sourceNodeId,
        zone.entryNodeId,
        context,
      );
      if (targetNodeId !== zone.entryNodeId) {
        this.planZoneMemberRoute(
          zone.entryNodeId,
          targetNodeId,
          context,
        );
      }
      return;
    }

    if (targetNodeId === session.activationNodeId) {
      if (sourceNodeId !== zone.entryNodeId) {
        this.planZoneMemberRoute(
          sourceNodeId,
          zone.entryNodeId,
          context,
        );
      }
      this.addSessionEntryStage(
        session,
        zone.entryNodeId,
        session.activationNodeId,
        context,
      );
      return;
    }

    this.planZoneMemberRoute(
      sourceNodeId,
      targetNodeId,
      context,
    );
  }

  private planZoneMemberRoute(
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
  ): void {
    const route = this.activeStraightPathIndex.shortestRoute(
      sourceNodeId,
      targetNodeId,
    );
    const authoredHopCount = this.basePathIndex.hopDistance(sourceNodeId, targetNodeId);
    if (!route || authoredHopCount === null) {
      throw new NavigationPlanningError(
        "unreachable",
        `No existing brown-chain route exists from "${sourceNodeId}" to "${targetNodeId}".`,
      );
    }
    this.addBaseStage(route, "zone-base-route", authoredHopCount, context);
  }

  private planZoneTransientOverpass(
    zone: SpecialPathZoneSpec,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
    resolvedHopCount?: number,
    allowActivationFarMemberDouble = false,
  ): void {
    const exactBridge = findActiveBridgeByPair(
      context.activeBridges,
      sourceNodeId,
      targetNodeId,
    );
    if (exactBridge) {
      this.addOverpassStage(
        sourceNodeId,
        targetNodeId,
        exactBridge.edge,
        "reuse-overpass",
        context,
        resolvedHopCount,
      );
      return;
    }

    const requestedEdge = this.requireOverpass(sourceNodeId, targetNodeId);
    this.planRetireUnservedTransientBridges(
      requestedEdge.id,
      sourceNodeId,
      context,
    );
    const conflictingOwned = findActiveBridgeOwnedBy(
      context.activeBridges,
      sourceNodeId,
    );
    const retainsEntryForAllowedDouble = allowActivationFarMemberDouble
      && conflictingOwned?.role === "zone-entry";
    if (conflictingOwned && conflictingOwned.bridgeId !== requestedEdge.id
      && !retainsEntryForAllowedDouble) {
      this.queueBridgeAction(
        this.makeRetireBridgeAction(conflictingOwned, sourceNodeId),
        context,
      );
    }
    const session = this.requireActiveSessionForZone(zone.id);
    const action = this.planEnsureBridge(
      sourceNodeId,
      targetNodeId,
      sourceNodeId,
      "zone-transient",
      zone.id,
      session.id,
      sourceNodeId,
      context,
      allowActivationFarMemberDouble,
    );
    if (!action && !findActiveBridgeByPair(
      context.activeBridges,
      sourceNodeId,
      targetNodeId,
    )) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Node "${sourceNodeId}" already owns a different transient bridge.`,
      );
    }
    const bridge = this.requireOverpass(sourceNodeId, targetNodeId);
    this.addOverpassStage(
      sourceNodeId,
      targetNodeId,
      bridge,
      action ? "zone-transient-overpass" : "reuse-overpass",
      context,
      resolvedHopCount,
    );
  }

  private planLeaveZone(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
  ): void {
    const memberToEntryRoute = sourceNodeId === session.activationNodeId
      ? null
      : this.activeStraightPathIndex.shortestRoute(sourceNodeId, zone.entryNodeId);
    const activationToTargetRoute = this.activeStraightPathIndex.shortestRoute(
      session.activationNodeId,
      targetNodeId,
    );
    const authoredHopCount = this.sessionAwareHopDistance(sourceNodeId, targetNodeId);
    if (authoredHopCount === null || !activationToTargetRoute
      || (sourceNodeId !== session.activationNodeId && !memberToEntryRoute)) {
      throw new NavigationPlanningError(
        "unreachable",
        `No resolved zone-exit route exists from "${sourceNodeId}" to "${targetNodeId}".`,
      );
    }

    // An overpass entry is always precleared before departure. A character on
    // a brown member therefore cannot route back across that retired edge,
    // even when immutable distance is only one or two hops. Use a direct
    // temporary overpass, or a member-chain relay whose final bridge avoids
    // the retired entry edge entirely.
    if (session.entryConnector.kind === "overpass"
      && sourceNodeId !== session.activationNodeId) {
      this.planSafeMemberDepartureAfterEntryPreclear(
        zone,
        session,
        sourceNodeId,
        targetNodeId,
        authoredHopCount,
        context,
      );
      return;
    }

    if (!this.requiresDynamicBridge(authoredHopCount)) {
      this.planRetireUnservedTransientBridges(null, sourceNodeId, context);
      if (memberToEntryRoute && memberToEntryRoute.hopCount > 0) {
        this.addBaseStage(
          memberToEntryRoute,
          "leave-zone-base-route",
          memberToEntryRoute.hopCount,
          context,
        );
      }
      if (sourceNodeId !== session.activationNodeId) {
        this.planEnsureZoneEntry(session, zone.entryNodeId, context);
        this.addSessionEntryStage(
          session,
          zone.entryNodeId,
          session.activationNodeId,
          context,
        );
      }
      if (activationToTargetRoute.hopCount > 0) {
        this.addBaseStage(
          activationToTargetRoute,
          "leave-zone-base-route",
          activationToTargetRoute.hopCount,
          context,
        );
      }
      const finalStage = context.stages.at(-1);
      const activeEntryBridge = session.entryConnector.kind === "overpass"
        ? context.activeBridges.get(session.entryConnector.edgeId)
        : null;
      if (finalStage && activeEntryBridge?.role === "zone-entry") {
        finalStage.afterArrivalBridgeActions.push(
          this.makeRetireBridgeAction(activeEntryBridge, targetNodeId),
        );
      }
      return;
    }

    // A runtime session-entry straight deliberately has no matching overpass
    // geometry. While another activation owns this zone, that straight must
    // stay locked until the old session is fully dismissed. Return through
    // the current session connector, then continue over authored ground roads
    // to the adjacent activation instead of trying to manufacture a bridge.
    if (!this.overpassPairLookup(sourceNodeId, targetNodeId)
      && this.canLeaveZoneViaAdjacentActivation(
        zone,
        session,
        sourceNodeId,
        targetNodeId,
      )) {
      this.planLeaveZoneViaCurrentActivation(
        zone,
        session,
        sourceNodeId,
        targetNodeId,
        memberToEntryRoute,
        activationToTargetRoute,
        context,
      );
      return;
    }

    const requestedEdge = this.requireOverpass(sourceNodeId, targetNodeId);
    this.planRetireUnservedTransientBridges(requestedEdge.id, sourceNodeId, context);
    this.planRetireZoneLineageBeforeExternalBridge(
      zone,
      session,
      context,
    );
    const conflictingOwned = findActiveBridgeOwnedBy(
      context.activeBridges,
      sourceNodeId,
    );
    if (conflictingOwned && conflictingOwned.bridgeId !== requestedEdge.id) {
      this.queueBridgeAction(
        this.makeRetireBridgeAction(conflictingOwned, sourceNodeId),
        context,
      );
    }
    const existing = findActiveBridgeByPair(
      context.activeBridges,
      sourceNodeId,
      targetNodeId,
    );
    const ensureAction = this.planEnsureBridge(
      sourceNodeId,
      targetNodeId,
      sourceNodeId,
      "ordinary",
      null,
      null,
      sourceNodeId,
      context,
    );
    this.addOverpassStage(
      sourceNodeId,
      targetNodeId,
      requestedEdge,
      existing && !ensureAction ? "reuse-overpass" : "leave-zone-overpass",
      context,
    );
  }

  private planSafeMemberDepartureAfterEntryPreclear(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    authoredHopCount: number,
    context: PlanningContext,
  ): void {
    const directEdge = this.overpassPairLookup(sourceNodeId, targetNodeId);
    const relay = directEdge
      ? null
      : zone.memberNodeIds
        .filter((candidateNodeId) => candidateNodeId !== sourceNodeId)
        .map((candidateNodeId) => {
          const groundRoute = this.activeStraightPathIndex.shortestRoute(
            sourceNodeId,
            candidateNodeId,
          );
          const edge = this.overpassPairLookup(candidateNodeId, targetNodeId);
          return groundRoute && edge
            ? { bridgeFromNodeId: candidateNodeId, groundRoute, edge }
            : null;
        })
        .filter((candidate): candidate is {
          bridgeFromNodeId: NodeId;
          groundRoute: BasePathRoute;
          edge: OverpassLearningPathEdge;
        } => candidate !== null)
        .sort((left, right) => (
          left.groundRoute.hopCount - right.groundRoute.hopCount
          || left.bridgeFromNodeId.localeCompare(right.bridgeFromNodeId)
        ))[0] ?? null;
    const bridgeFromNodeId = directEdge ? sourceNodeId : relay?.bridgeFromNodeId;
    const requestedEdge = directEdge ?? relay?.edge ?? null;
    if (!bridgeFromNodeId || !requestedEdge) {
      throw new NavigationPlanningError(
        "missing-overpass",
        `No safe post-preclear departure exists from "${sourceNodeId}" to "${targetNodeId}".`,
      );
    }

    this.planRetireUnservedTransientBridges(
      requestedEdge.id,
      sourceNodeId,
      context,
    );
    this.planRetireZoneLineageBeforeExternalBridge(zone, session, context);
    if (relay && relay.groundRoute.hopCount > 0) {
      this.addBaseStage(
        relay.groundRoute,
        "leave-zone-base-route",
        relay.groundRoute.hopCount,
        context,
      );
    }
    const conflictingOwned = findActiveBridgeOwnedBy(
      context.activeBridges,
      bridgeFromNodeId,
    );
    if (conflictingOwned && conflictingOwned.bridgeId !== requestedEdge.id) {
      this.queueBridgeAction(
        this.makeRetireBridgeAction(conflictingOwned, sourceNodeId),
        context,
      );
    }
    const existing = findActiveBridgeByPair(
      context.activeBridges,
      bridgeFromNodeId,
      targetNodeId,
    );
    const ensureAction = this.planEnsureBridge(
      bridgeFromNodeId,
      targetNodeId,
      bridgeFromNodeId,
      "ordinary",
      null,
      null,
      sourceNodeId,
      context,
    );
    this.addOverpassStage(
      bridgeFromNodeId,
      targetNodeId,
      requestedEdge,
      existing && !ensureAction ? "reuse-overpass" : "leave-zone-overpass",
      context,
      directEdge ? authoredHopCount : undefined,
    );
  }

  private canLeaveZoneViaAdjacentActivation(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
  ): boolean {
    if (sourceNodeId === session.activationNodeId
      || targetNodeId === session.activationNodeId
      || this.activationZoneByNodeId.get(targetNodeId)?.id !== zone.id) {
      return false;
    }
    const targetConnection = this.requireZoneEntryConnection(zone, targetNodeId);
    if (targetConnection.kind !== "straight-edge") {
      return false;
    }
    const targetEntryRoad = this.straightEdgeById.get(targetConnection.edgeId);
    return targetEntryRoad !== undefined
      && makePairKey(targetEntryRoad.fromNodeId, targetEntryRoad.toNodeId)
        === makePairKey(zone.entryNodeId, targetNodeId);
  }

  private planLeaveZoneViaCurrentActivation(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    memberToEntryRoute: BasePathRoute | null,
    activationToTargetRoute: BasePathRoute,
    context: PlanningContext,
  ): void {
    this.planRetireUnservedTransientBridges(null, sourceNodeId, context);
    if (memberToEntryRoute && memberToEntryRoute.hopCount > 0) {
      this.addBaseStage(
        memberToEntryRoute,
        "leave-zone-base-route",
        memberToEntryRoute.hopCount,
        context,
      );
    }
    this.planEnsureZoneEntry(session, zone.entryNodeId, context);
    this.addSessionEntryStage(
      session,
      zone.entryNodeId,
      session.activationNodeId,
      context,
    );
    if (activationToTargetRoute.hopCount > 0) {
      this.addBaseStage(
        activationToTargetRoute,
        "leave-zone-base-route",
        activationToTargetRoute.hopCount,
        context,
      );
    }

    const finalStage = context.stages.at(-1);
    const activeEntryBridge = session.entryConnector.kind === "overpass"
      ? context.activeBridges.get(session.entryConnector.edgeId)
      : null;
    if (finalStage && activeEntryBridge?.role === "zone-entry") {
      finalStage.afterArrivalBridgeActions.push(
        this.makeRetireBridgeAction(activeEntryBridge, targetNodeId),
      );
    }
  }

  private planOrdinaryRoute(
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    context: PlanningContext,
    baseDecision: NavigationDecisionKind,
    overpassDecision: NavigationDecisionKind,
  ): void {
    const authoredHopCount = this.basePathIndex.hopDistance(
      sourceNodeId,
      targetNodeId,
    );
    if (authoredHopCount === null) {
      throw new NavigationPlanningError(
        "unreachable",
        `No authored route exists from "${sourceNodeId}" to "${targetNodeId}".`,
      );
    }
    const activeRoute = this.activeStraightPathIndex.shortestRoute(
      sourceNodeId,
      targetNodeId,
    );
    if (activeRoute && authoredHopCount !== null
      && !this.requiresDynamicBridge(authoredHopCount)) {
      this.planRetireUnservedTransientBridges(null, sourceNodeId, context);
      this.addBaseStage(activeRoute, baseDecision, authoredHopCount, context);
      return;
    }

    const requestedEdge = this.requireOverpass(sourceNodeId, targetNodeId);
    this.planRetireUnservedTransientBridges(
      requestedEdge.id,
      sourceNodeId,
      context,
    );
    const existing = findActiveBridgeByPair(
      context.activeBridges,
      sourceNodeId,
      targetNodeId,
    );
    // Non-zone routes still replace a conflicting source-owned bridge. Zone
    // exits have already retired their complete retained bridge lineage above,
    // so the replacement bridge can never overlap an earlier session bridge.
    const conflictingOwned = findActiveBridgeOwnedBy(
      context.activeBridges,
      sourceNodeId,
    );
    if (conflictingOwned && conflictingOwned.bridgeId !== requestedEdge.id) {
      this.queueBridgeAction(
        this.makeRetireBridgeAction(conflictingOwned, sourceNodeId),
        context,
      );
    }
    const ensureAction = this.planEnsureBridge(
      sourceNodeId,
      targetNodeId,
      sourceNodeId,
      "ordinary",
      null,
      null,
      sourceNodeId,
      context,
    );
    this.addOverpassStage(
      sourceNodeId,
      targetNodeId,
      requestedEdge,
      existing && !ensureAction ? "reuse-overpass" : overpassDecision,
      context,
    );
  }

  private planEnsureZoneEntry(
    session: ActiveZoneSession,
    characterSideNodeId: NodeId,
    context: PlanningContext,
  ): void {
    if (session.entryConnector.kind === "straight") {
      if (!this.unlockedStraightEdgeIds.has(session.entryConnector.edgeId)) {
        throw new NavigationPlanningError(
          "rule-conflict",
          `Session entry road "${session.entryConnector.edgeId}" is not visible.`,
        );
      }
      return;
    }
    this.planEnsureBridge(
      session.entryConnector.endpoints.fromNodeId,
      session.entryConnector.endpoints.toNodeId,
      session.activationNodeId,
      "zone-entry",
      session.zoneId,
      session.id,
      characterSideNodeId,
      context,
    );
  }

  private addSessionEntryStage(
    session: ActiveZoneSession,
    fromNodeId: NodeId,
    toNodeId: NodeId,
    context: PlanningContext,
  ): void {
    if (makePairKey(fromNodeId, toNodeId) !== makePairKey(
      session.entryConnector.endpoints.fromNodeId,
      session.entryConnector.endpoints.toNodeId,
    )) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Session entry connector "${session.entryConnector.edgeId}" has mismatched endpoints.`,
      );
    }
    if (session.entryConnector.kind === "overpass") {
      this.addOverpassStage(
        fromNodeId,
        toNodeId,
        this.requireOverpass(fromNodeId, toNodeId),
        "zone-entry",
        context,
      );
      return;
    }

    const edge = this.straightEdgeById.get(session.entryConnector.edgeId);
    if (!edge || !this.unlockedStraightEdgeIds.has(edge.id)) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Session entry road "${session.entryConnector.edgeId}" is not traversable.`,
      );
    }
    this.addBaseStage(
      Object.freeze({
        nodeIds: Object.freeze([fromNodeId, toNodeId]),
        edgeIds: Object.freeze([edge.id]),
        legs: Object.freeze([Object.freeze({
          edgeId: edge.id,
          fromNodeId,
          toNodeId,
        })]),
        hopCount: 1,
      }),
      "zone-entry",
      1,
      context,
    );
  }

  private planRetireUnservedTransientBridges(
    servedBridgeId: EdgeId | null,
    characterSideNodeId: NodeId,
    context: PlanningContext,
  ): void {
    [...context.activeBridges.values()]
      .filter((bridge) => (
        bridge.role !== "zone-entry" && bridge.bridgeId !== servedBridgeId
      ))
      .sort(compareBridgeInstances)
      .forEach((bridge) => {
        this.queueBridgeAction(
          this.makeRetireBridgeAction(bridge, characterSideNodeId),
          context,
        );
      });
  }

  private planRetireZoneLineageBeforeExternalBridge(
    zone: SpecialPathZoneSpec,
    session: ActiveZoneSession,
    context: PlanningContext,
  ): void {
    if (
      zone.externalBridgeReplacement
      !== "retire-entry-overpass-before-ensure"
      || session.entryConnector.kind !== "overpass"
    ) {
      return;
    }
    const entryBridge = context.activeBridges.get(session.entryConnector.edgeId);
    if (entryBridge?.active && entryBridge.role === "zone-entry"
      && entryBridge.zoneSessionId === session.id) {
      this.queueBridgeAction(
        this.makeRetireBridgeAction(entryBridge, session.activationNodeId),
        context,
      );
    }
  }

  private planEnsureBridge(
    firstNodeId: NodeId,
    secondNodeId: NodeId,
    requestedOwnerSourceNodeId: NodeId,
    role: RuntimeBridgeRole,
    zoneId: string | null,
    zoneSessionId: string | null,
    characterSideNodeId: NodeId,
    context: PlanningContext,
    allowActivationFarMemberDouble = false,
  ): BridgeTransitionAction | null {
    const action = this.makeEnsureBridgeAction(
      firstNodeId,
      secondNodeId,
      requestedOwnerSourceNodeId,
      role,
      zoneId,
      zoneSessionId,
      characterSideNodeId,
      context.activeBridges,
      allowActivationFarMemberDouble,
    );
    if (action) {
      this.queueBridgeAction(action, context);
    }
    return action;
  }

  private makeEnsureBridgeAction(
    firstNodeId: NodeId,
    secondNodeId: NodeId,
    requestedOwnerSourceNodeId: NodeId,
    role: RuntimeBridgeRole,
    zoneId: string | null,
    zoneSessionId: string | null,
    characterSideNodeId: NodeId,
    activeBridges: ReadonlyMap<EdgeId, RuntimeBridgeInstance>,
    allowActivationFarMemberDouble = false,
  ): BridgeTransitionAction | null {
    const edge = this.requireOverpass(firstNodeId, secondNodeId);
    const existingPair = findActiveBridgeByPair(
      activeBridges,
      firstNodeId,
      secondNodeId,
    );
    const desiredOwner = requestedOwnerSourceNodeId;
    const desiredRole = role;
    const desiredZoneId = zoneId;
    const desiredZoneSessionId = zoneSessionId;
    if (existingPair
      && existingPair.role === desiredRole
      && existingPair.zoneId === desiredZoneId
      && existingPair.zoneSessionId === desiredZoneSessionId) {
      return null;
    }

    const owned = findActiveBridgeOwnedBy(activeBridges, desiredOwner);
    const allowedDouble = allowActivationFarMemberDouble
      && owned?.role === "zone-entry"
      && desiredRole === "zone-transient"
      && owned.zoneId === desiredZoneId
      && owned.zoneSessionId === desiredZoneSessionId;
    if (owned && owned.bridgeId !== edge.id && !allowedDouble) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Node "${desiredOwner}" already owns bridge "${owned.bridgeId}".`,
      );
    }
    return Object.freeze({
      kind: "ensure-bridge",
      characterSideNodeId: this.resolveBridgeAnimationSideNodeId(
        edge,
        characterSideNodeId,
      ),
      bridge: Object.freeze({
        bridgeId: edge.id,
        edge,
        ownerSourceNodeId: desiredOwner,
        role: desiredRole,
        zoneId: desiredZoneId,
        zoneSessionId: desiredZoneSessionId,
        active: true,
        createdRevision: existingPair?.createdRevision ?? this.revision + 1,
        changedRevision: this.revision + 1,
      }),
    });
  }

  private makeRetireBridgeAction(
    bridge: RuntimeBridgeInstance,
    safeCharacterNodeId: NodeId,
  ): BridgeTransitionAction {
    return Object.freeze({
      kind: "retire-bridge",
      bridgeId: bridge.bridgeId,
      characterSideNodeId: this.resolveBridgeAnimationSideNodeId(
        bridge.edge,
        safeCharacterNodeId,
      ),
    });
  }

  private compareBridgesByCharacterProximity(
    left: RuntimeBridgeInstance | MutableBridgeInstance,
    right: RuntimeBridgeInstance | MutableBridgeInstance,
    characterNodeId: NodeId,
  ): number {
    const leftDistance = this.bridgeEndpointDistanceSquared(
      left.edge,
      characterNodeId,
    );
    const rightDistance = this.bridgeEndpointDistanceSquared(
      right.edge,
      characterNodeId,
    );
    return leftDistance - rightDistance || compareBridgeInstances(left, right);
  }

  private bridgeEndpointDistanceSquared(
    edge: OverpassLearningPathEdge,
    characterNodeId: NodeId,
  ): number {
    const character = this.nodeById.get(characterNodeId);
    const from = this.nodeById.get(edge.fromNodeId);
    const to = this.nodeById.get(edge.toNodeId);
    if (!character || !from || !to) {
      return Number.POSITIVE_INFINITY;
    }
    return Math.min(
      squaredDistance(character, from),
      squaredDistance(character, to),
    );
  }

  private resolveBridgeAnimationSideNodeId(
    edge: OverpassLearningPathEdge,
    characterNodeId: NodeId,
  ): NodeId {
    if (characterNodeId === edge.fromNodeId || characterNodeId === edge.toNodeId) {
      return characterNodeId;
    }
    const fromHops = this.basePathIndex.hopDistance(
      characterNodeId,
      edge.fromNodeId,
    );
    const toHops = this.basePathIndex.hopDistance(
      characterNodeId,
      edge.toNodeId,
    );
    if (fromHops !== null && (toHops === null || fromHops < toHops)) {
      return edge.fromNodeId;
    }
    if (toHops !== null && (fromHops === null || toHops < fromHops)) {
      return edge.toNodeId;
    }

    const character = this.nodeById.get(characterNodeId);
    const from = this.nodeById.get(edge.fromNodeId);
    const to = this.nodeById.get(edge.toNodeId);
    if (character && from && to) {
      const fromDistance = squaredDistance(character, from);
      const toDistance = squaredDistance(character, to);
      if (fromDistance !== toDistance) {
        return fromDistance < toDistance ? edge.fromNodeId : edge.toNodeId;
      }
    }
    return edge.fromNodeId < edge.toNodeId ? edge.fromNodeId : edge.toNodeId;
  }

  private queueBridgeAction(
    action: BridgeTransitionAction,
    context: PlanningContext,
  ): void {
    context.pendingBeforeActions.push(action);
    applyActionToProjection(action, context.activeBridges);
  }

  private addBaseStage(
    route: BasePathRoute,
    decisionKind: NavigationDecisionKind,
    baseHopCount: number,
    context: PlanningContext,
  ): void {
    if (route.hopCount === 0) {
      return;
    }
    context.stages.push({
      decisionKind,
      fromNodeId: route.nodeIds[0]!,
      toNodeId: route.nodeIds.at(-1)!,
      routeNodeIds: [...route.nodeIds],
      routeEdgeIds: [...route.edgeIds],
      baseHopCount,
      beforeTravelBridgeActions: this.takePendingBeforeActions(context),
      afterArrivalBridgeActions: [],
    });
  }

  private addOverpassStage(
    fromNodeId: NodeId,
    toNodeId: NodeId,
    edge: OverpassLearningPathEdge,
    decisionKind: NavigationDecisionKind,
    context: PlanningContext,
    resolvedHopCount?: number,
  ): void {
    const activeBridge = context.activeBridges.get(edge.id);
    if (activeBridge?.role !== "zone-entry") {
      context.traversedTransientBridgeIds.add(edge.id);
    }
    context.stages.push({
      decisionKind,
      fromNodeId,
      toNodeId,
      routeNodeIds: [fromNodeId, toNodeId],
      routeEdgeIds: [edge.id],
      baseHopCount: resolvedHopCount
        ?? this.basePathIndex.hopDistance(fromNodeId, toNodeId),
      beforeTravelBridgeActions: this.takePendingBeforeActions(context),
      afterArrivalBridgeActions: [],
    });
  }

  /**
   * A planning split must not turn into a visible stop. Every bridge traversed
   * during this click stays assembled through running and is retired together
   * on the simulation's final physical Arrival event, before idle/turn settles.
   */
  private attachTransientRetirements(
    context: PlanningContext,
    finalTargetNodeId: NodeId,
  ): void {
    const finalStage = context.stages.at(-1);
    if (!finalStage || context.traversedTransientBridgeIds.size === 0) {
      return;
    }
    const retirements = [...context.traversedTransientBridgeIds]
      .map((bridgeId) => context.activeBridges.get(bridgeId) ?? null)
      .filter((bridge): bridge is RuntimeBridgeInstance => (
        bridge !== null && bridge.active && bridge.role !== "zone-entry"
      ))
      .sort((left, right) => this.compareBridgesByCharacterProximity(
        left,
        right,
        finalTargetNodeId,
      ))
      .map((bridge) => this.makeRetireBridgeAction(
        bridge,
        finalTargetNodeId,
      ));
    finalStage.afterArrivalBridgeActions.push(...retirements);
  }

  private takePendingBeforeActions(
    context: PlanningContext,
  ): BridgeTransitionAction[] {
    const actions = context.pendingBeforeActions;
    context.pendingBeforeActions = [];
    return actions;
  }

  private freezeNavigationPlan(
    planRevision: number,
    sourceNodeId: NodeId,
    targetNodeId: NodeId,
    stages: readonly MutableNavigationStage[],
    linkedZoneDismissalPlanId: string | null,
  ): NavigationPlan {
    if (stages.length === 0 && sourceNodeId !== targetNodeId) {
      throw new NavigationPlanningError(
        "unreachable",
        `No route was produced from "${sourceNodeId}" to "${targetNodeId}".`,
      );
    }
    const retiredBeforeTravelEdgeIds = new Set(
      stages.flatMap((stage) => stage.beforeTravelBridgeActions
        .filter((action) => action.kind === "retire-bridge")
        .map((action) => action.bridgeId)),
    );
    const retiredRouteEdgeId = stages
      .flatMap((stage) => stage.routeEdgeIds)
      .find((edgeId) => retiredBeforeTravelEdgeIds.has(edgeId));
    if (retiredRouteEdgeId) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Navigation cannot retire route edge "${retiredRouteEdgeId}" before travel.`,
      );
    }
    const continuousStages = mergeContinuousNavigationStages(stages);
    const frozenStages = continuousStages.map((stage, index): NavigationStage => Object.freeze({
      id: `navigation-stage:${planRevision}:${index}`,
      index,
      decisionKind: stage.decisionKind,
      fromNodeId: stage.fromNodeId,
      toNodeId: stage.toNodeId,
      routeNodeIds: Object.freeze([...stage.routeNodeIds]),
      routeEdgeIds: Object.freeze([...stage.routeEdgeIds]),
      baseHopCount: stage.baseHopCount,
      beforeTravelBridgeActions: Object.freeze([
        ...stage.beforeTravelBridgeActions,
      ]),
      afterArrivalBridgeActions: Object.freeze([
        ...stage.afterArrivalBridgeActions,
      ]),
    }));
    const flattened = flattenStageRoutes(frozenStages, sourceNodeId);
    return Object.freeze({
      id: `navigation-plan:${planRevision}`,
      revision: planRevision,
      sourceNodeId,
      targetNodeId,
      authoredHopCount: this.sessionAwareHopDistance(
        sourceNodeId,
        targetNodeId,
      ),
      linkedZoneDismissalPlanId,
      stages: Object.freeze(frozenStages),
      flattenedRouteNodeIds: Object.freeze(flattened.nodeIds),
      flattenedRouteEdgeIds: Object.freeze(flattened.edgeIds),
    });
  }

  private applyBridgeAction(action: BridgeTransitionAction): void {
    if (action.kind === "retire-bridge") {
      this.commitBridgeRetirement(action.bridgeId);
      return;
    }

    const desired = action.bridge;
    const current = this.bridgeRegistry.get(desired.bridgeId);
    const changedRevision = this.nextRevision();
    this.bridgeRegistry.set(desired.bridgeId, {
      bridgeId: desired.bridgeId,
      edge: desired.edge,
      ownerSourceNodeId: desired.ownerSourceNodeId,
      role: desired.role,
      zoneId: desired.zoneId,
      zoneSessionId: desired.zoneSessionId,
      active: true,
      createdRevision: current?.createdRevision ?? changedRevision,
      changedRevision,
    });
  }

  private commitBridgeRetirement(bridgeId: EdgeId): void {
    const bridge = this.bridgeRegistry.get(bridgeId);
    if (!bridge?.active) {
      return;
    }
    bridge.active = false;
    bridge.changedRevision = this.nextRevision();
  }

  private requiresDynamicBridge(hopCount: number): boolean {
    return hopCount > this.dynamicBridgeRule.hopThresholdExclusive;
  }

  private requireOverpass(
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ): OverpassLearningPathEdge {
    const edge = this.overpassPairLookup(firstNodeId, secondNodeId);
    if (!edge) {
      throw new NavigationPlanningError(
        "missing-overpass",
        `No bridge geometry exists between "${firstNodeId}" and "${secondNodeId}".`,
      );
    }
    if (makePairKey(edge.fromNodeId, edge.toNodeId)
      !== makePairKey(firstNodeId, secondNodeId)) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Bridge lookup returned mismatched edge "${edge.id}".`,
      );
    }
    return edge;
  }

  private snapshotActiveBridges(): Map<EdgeId, RuntimeBridgeInstance> {
    return new Map(
      [...this.bridgeRegistry.values()]
        .filter((bridge) => bridge.active)
        .map((bridge) => [bridge.bridgeId, freezeBridgeInstance(bridge)]),
    );
  }

  private buildActiveStraightPathIndex(): BasePathIndex {
    const edges = this.authoredStraightEdges.filter((edge) => (
      this.unlockedStraightEdgeIds.has(edge.id)
      && this.unlockedNodeIds.has(edge.fromNodeId)
      && this.unlockedNodeIds.has(edge.toNodeId)
    ));
    return new BasePathIndex(this.nodes, edges);
  }

  private rebuildActiveStraightPathIndex(): void {
    this.activeStraightPathIndex = this.buildActiveStraightPathIndex();
  }

  private validateAndIndexConfiguration(): void {
    this.validateDynamicRule();
    this.nodes.forEach((node, index) => {
      if (node.id.trim().length === 0 || this.nodeById.has(node.id)) {
        throw new Error(`Path rules received an invalid node at index ${index}.`);
      }
      this.nodeById.set(node.id, node);
    });
    this.authoredStraightEdges.forEach((edge, index) => {
      if (edge.pathKind !== "straight") {
        throw new Error(`Authored edge at index ${index} is not straight.`);
      }
      if (edge.id.trim().length === 0 || this.straightEdgeById.has(edge.id)) {
        throw new Error(`Path rules received an invalid straight edge at index ${index}.`);
      }
      if (!this.nodeById.has(edge.fromNodeId) || !this.nodeById.has(edge.toNodeId)) {
        throw new Error(`Straight edge "${edge.id}" references a missing node.`);
      }
      this.straightEdgeById.set(edge.id, edge);
    });

    this.specialZones.forEach((zone) => this.validateAndIndexZone(zone));
    this.validateAuthoredLogicalIndex();
  }

  private validateAuthoredLogicalIndex(): void {
    const authoritativeIndex = new BasePathIndex(
      this.nodes,
      this.authoredLogicalEdges,
    );
    const logicalById = new Map(
      this.authoredLogicalEdges.map((edge) => [edge.id, edge] as const),
    );
    if (logicalById.size !== this.authoredLogicalEdges.length) {
      throw new Error("Authored logical path repeats an edge id.");
    }
    const sessionEntryStraightIds = new Set(
      this.specialZones.flatMap((zone) => zone.entryConnections
        .filter((connection) => connection.kind === "straight-edge")
        .map((connection) => connection.edgeId)),
    );
    this.authoredLogicalEdges.forEach((logical) => {
      const runtimeStraight = this.straightEdgeById.get(logical.id);
      if (!runtimeStraight
        || makePairKey(logical.fromNodeId, logical.toNodeId)
          !== makePairKey(runtimeStraight.fromNodeId, runtimeStraight.toNodeId)) {
        throw new Error(
          `Authored logical edge "${logical.id}" is not a matching runtime straight road.`,
        );
      }
      if (sessionEntryStraightIds.has(logical.id)) {
        throw new Error(
          `Session entry road "${logical.id}" cannot enter authored logical hop truth.`,
        );
      }
    });
    this.nodes.forEach((fromNode) => {
      this.nodes.forEach((toNode) => {
        const expectedRoute = authoritativeIndex.shortestRoute(
          fromNode.id,
          toNode.id,
        );
        const receivedRoute = this.basePathIndex.shortestRoute(
          fromNode.id,
          toNode.id,
        );
        const expectedSignature = routeIdentitySignature(expectedRoute);
        const receivedSignature = routeIdentitySignature(receivedRoute);
        if (receivedSignature !== expectedSignature) {
          throw new Error(
            `Supplied BasePathIndex differs from authored logical truth for `
            + `"${fromNode.id}" -> "${toNode.id}".`,
          );
        }
      });
    });
  }

  private validateDynamicRule(): void {
    if (!Number.isInteger(this.dynamicBridgeRule.hopThresholdExclusive)
      || this.dynamicBridgeRule.hopThresholdExclusive < 0) {
      throw new Error("Dynamic bridge hop threshold must be a non-negative integer.");
    }
    if (!Number.isInteger(this.dynamicBridgeRule.ordinaryBridgeLimit)
      || this.dynamicBridgeRule.ordinaryBridgeLimit < 1) {
      throw new Error("Ordinary bridge limit must be a positive integer.");
    }
    if (!Number.isInteger(this.dynamicBridgeRule.outgoingBridgeLimitPerAnchor)
      || this.dynamicBridgeRule.outgoingBridgeLimitPerAnchor < 1) {
      throw new Error("Outgoing bridge limit must be a positive integer.");
    }
  }

  private validateAndIndexZone(zone: SpecialPathZoneSpec): void {
    if (zone.id.trim().length === 0 || this.zoneById.has(zone.id)) {
      throw new Error(`Special path zone has invalid or duplicate id "${zone.id}".`);
    }
    if (
      zone.unlockPolicy !== "repeatable-session"
      || zone.retention !== "retain-inside-session-envelope"
      || zone.externalBridgeReplacement
        !== "retire-entry-overpass-before-ensure"
      || zone.dismissalTrigger !== "departure-from-session-envelope"
      || zone.dismissalBridgeOrder !== "entry-left-to-right-preclear"
      || zone.dismissalConstructOrder !== "reverse-reveal-right-to-left"
      || zone.lockHiddenMembersAfterDismissal !== true
      || zone.activationTrigger !== "idle-at-any-activation-node"
      || !isSupportedActivationMemberRoutingPolicy(
        zone.activationMemberRoutingPolicy,
      )
      || zone.memberDynamicBridgeLifetime !== "retire-at-physical-arrival"
      || zone.entryConnectorRevealPolicy !== "first"
      || zone.retainEntryConnectorDuringMemberRoutes !== true
      || zone.retainedEntryOverpassCountsTowardOrdinaryLimit !== false
      || zone.entryConnectorAffectsAuthoredHopDistance !== false
    ) {
      throw new Error(
        `Zone "${zone.id}" does not satisfy the repeatable-session lifecycle contract.`,
      );
    }
    const activations = new Set(zone.activationNodeIds);
    if (activations.size === 0 || activations.size !== zone.activationNodeIds.length) {
      throw new Error(
        `Zone "${zone.id}" must contain unique activation nodes.`,
      );
    }
    const entryConnectionsByActivation = new Map<NodeId, ZoneEntryConnectionSpec>();
    zone.entryConnections.forEach((connection) => {
      if (!activations.has(connection.activationNodeId)) {
        throw new Error(
          `Zone "${zone.id}" entry connection references non-activation `
          + `"${connection.activationNodeId}".`,
        );
      }
      if (entryConnectionsByActivation.has(connection.activationNodeId)) {
        throw new Error(
          `Zone "${zone.id}" repeats entry connection for `
          + `"${connection.activationNodeId}".`,
        );
      }
      entryConnectionsByActivation.set(connection.activationNodeId, connection);
    });
    if (entryConnectionsByActivation.size !== activations.size) {
      throw new Error(
        `Zone "${zone.id}" needs exactly one entry connection per activation.`,
      );
    }
    activations.forEach((nodeId) => {
      const node = this.nodeById.get(nodeId);
      if (!node || !node.initiallyVisible || node.variant !== "green") {
        throw new Error(
          `Zone "${zone.id}" activation "${nodeId}" must be a visible green node.`,
        );
      }
      const previousZone = this.activationZoneByNodeId.get(nodeId);
      if (previousZone) {
        throw new Error(
          `Activation "${nodeId}" belongs to both "${previousZone.id}" and "${zone.id}".`,
        );
      }
      if (this.memberZoneByNodeId.has(nodeId)) {
        throw new Error(`Activation "${nodeId}" is already a hidden zone member.`);
      }
      this.activationZoneByNodeId.set(nodeId, zone);
      const connection = entryConnectionsByActivation.get(nodeId)!;
      if (connection.kind === "overpass") {
        this.requireOverpass(nodeId, zone.entryNodeId);
      } else {
        const edge = this.straightEdgeById.get(connection.edgeId);
        if (!edge
          || makePairKey(edge.fromNodeId, edge.toNodeId)
            !== makePairKey(nodeId, zone.entryNodeId)) {
          throw new Error(
            `Zone "${zone.id}" has invalid entry road "${connection.edgeId}" `
            + `for activation "${nodeId}".`,
          );
        }
        if (edge.initiallyVisible) {
          throw new Error(
            `Zone "${zone.id}" entry road "${edge.id}" must start hidden.`,
          );
        }
      }
    });

    const members = new Set(zone.memberNodeIds);
    if (members.size !== zone.memberNodeIds.length
      || !members.has(zone.entryNodeId)) {
      throw new Error(
        `Zone "${zone.id}" must uniquely include its brown entry node.`,
      );
    }
    members.forEach((nodeId) => {
      const node = this.nodeById.get(nodeId);
      if (!node) {
        throw new Error(`Zone "${zone.id}" references unknown node "${nodeId}".`);
      }
      if (node.initiallyVisible || node.variant !== "brown") {
        throw new Error(`Zone "${zone.id}" member "${nodeId}" must be hidden brown.`);
      }
      if (this.activationZoneByNodeId.has(nodeId)) {
        throw new Error(`Zone member "${nodeId}" is already an activation node.`);
      }
      const previousZone = this.memberZoneByNodeId.get(nodeId);
      if (previousZone) {
        throw new Error(
          `Node "${nodeId}" belongs to both "${previousZone.id}" and "${zone.id}".`,
        );
      }
      this.memberZoneByNodeId.set(nodeId, zone);
    });

    const memberEdgeIds = new Set(zone.memberStraightEdgeIds);
    if (memberEdgeIds.size !== zone.memberStraightEdgeIds.length) {
      throw new Error(`Zone "${zone.id}" repeats a member straight edge.`);
    }
    memberEdgeIds.forEach((edgeId) => {
      const edge = this.straightEdgeById.get(edgeId);
      if (!edge || !members.has(edge.fromNodeId) || !members.has(edge.toNodeId)) {
        throw new Error(
          `Zone "${zone.id}" has invalid member straight edge "${edgeId}".`,
        );
      }
    });
    const revealEntryCount = zone.revealSequence.filter(
      (step) => step.kind === "session-entry-connector",
    ).length;
    if (revealEntryCount !== 1
      || zone.revealSequence[0]?.kind !== "session-entry-connector") {
      throw new Error(
        `Zone "${zone.id}" reveal sequence must start with one session entry connector.`,
      );
    }
    zone.revealSequence.forEach((step) => this.validateRevealStep(zone, step));
    this.zoneById.set(zone.id, zone);
  }

  private validateRevealStep(
    zone: SpecialPathZoneSpec,
    step: SpecialRevealStep,
  ): void {
    if (step.kind === "node") {
      if (!zone.memberNodeIds.includes(step.nodeId)) {
        throw new Error(
          `Zone "${zone.id}" reveal references non-member node "${step.nodeId}".`,
        );
      }
      return;
    }
    if (step.kind === "straight-edge") {
      if (!zone.memberStraightEdgeIds.includes(step.edgeId)) {
        throw new Error(
          `Zone "${zone.id}" reveal references non-member edge "${step.edgeId}".`,
        );
      }
      return;
    }
    if (step.kind !== "session-entry-connector") {
      throw new Error(`Zone "${zone.id}" has an unknown reveal template step.`);
    }
  }

  private createZoneSession(
    zone: SpecialPathZoneSpec,
    activationNodeId: NodeId,
    revision: number,
  ): ActiveZoneSession {
    if (this.activeZoneSession) {
      throw new Error(
        `Cannot create zone session while "${this.activeZoneSession.id}" is active.`,
      );
    }
    if (this.activationZoneByNodeId.get(activationNodeId)?.id !== zone.id) {
      throw new Error(
        `Node "${activationNodeId}" is not an activation for zone "${zone.id}".`,
      );
    }
    const endpoints = Object.freeze({
      fromNodeId: activationNodeId,
      toNodeId: zone.entryNodeId,
    });
    const connection = this.requireZoneEntryConnection(zone, activationNodeId);
    const entryConnector: ResolvedSessionEntryConnector = connection.kind === "straight-edge"
      ? Object.freeze({
        kind: "straight" as const,
        edgeId: connection.edgeId,
        endpoints,
      })
      : (() => {
        const edge = this.requireOverpass(
          endpoints.fromNodeId,
          endpoints.toNodeId,
        );
        return Object.freeze({
          kind: "overpass" as const,
          edgeId: edge.id,
          endpoints,
        });
      })();
    const session: ActiveZoneSession = {
      id: `zone-session:${zone.id}:${activationNodeId}:${revision}`,
      zoneId: zone.id,
      activationNodeId,
      entryNodeId: zone.entryNodeId,
      entryConnector,
      state: "revealing",
      revealProgress: 0,
    };
    this.activeZoneSession = session;
    this.entryConnectorIdByZoneId.set(zone.id, entryConnector.edgeId);
    return session;
  }

  private resolveRevealStep(
    step: SpecialRevealStep,
    session: ActiveZoneSession,
  ): ResolvedSpecialRevealStep {
    if (step.kind === "session-entry-connector") {
      return session.entryConnector.kind === "straight"
        ? Object.freeze({
          kind: "straight-edge" as const,
          edgeId: session.entryConnector.edgeId,
        })
        : Object.freeze({
          kind: "bridge" as const,
          endpoints: session.entryConnector.endpoints,
        });
    }
    return step;
  }

  private requireZoneEntryConnection(
    zone: SpecialPathZoneSpec,
    activationNodeId: NodeId,
  ): ZoneEntryConnectionSpec {
    const connection = zone.entryConnections.find(
      (candidate) => candidate.activationNodeId === activationNodeId,
    );
    if (!connection) {
      throw new Error(
        `Zone "${zone.id}" has no entry connection for "${activationNodeId}".`,
      );
    }
    return connection;
  }

  private isSessionEntryConnectorActive(session: ActiveZoneSession): boolean {
    if (session.entryConnector.kind === "straight") {
      return this.unlockedStraightEdgeIds.has(session.entryConnector.edgeId);
    }
    const bridge = this.bridgeRegistry.get(session.entryConnector.edgeId);
    return bridge?.active === true
      && bridge.role === "zone-entry"
      && bridge.zoneSessionId === session.id;
  }

  private requireSession(sessionId: string): ActiveZoneSession {
    const session = this.activeZoneSession;
    if (!session || session.id !== sessionId) {
      throw new Error(`Zone session "${sessionId}" is not active.`);
    }
    return session;
  }

  private requireActiveSessionForZone(zoneId: string): ActiveZoneSession {
    const session = this.activeZoneSession;
    if (!session || session.zoneId !== zoneId || session.state !== "active") {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Zone "${zoneId}" has no active traversal session.`,
      );
    }
    return session;
  }

  private isNodeInSession(
    nodeId: NodeId,
    session: ActiveZoneSession,
    zone: SpecialPathZoneSpec,
  ): boolean {
    return nodeId === session.activationNodeId
      || this.memberZoneByNodeId.get(nodeId)?.id === zone.id;
  }

  private sessionAwareHopDistance(
    fromNodeId: NodeId,
    toNodeId: NodeId,
  ): number | null {
    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    if (!session || !zone) {
      return this.basePathIndex.hopDistance(fromNodeId, toNodeId);
    }
    const fromInSession = this.isNodeInSession(fromNodeId, session, zone);
    const toInSession = this.isNodeInSession(toNodeId, session, zone);
    if (!fromInSession && !toInSession) {
      return this.basePathIndex.hopDistance(fromNodeId, toNodeId);
    }
    if (fromInSession && toInSession) {
      if (fromNodeId === session.activationNodeId) {
        const entryHops = this.basePathIndex.hopDistance(zone.entryNodeId, toNodeId);
        return entryHops === null ? null : entryHops + 1;
      }
      if (toNodeId === session.activationNodeId) {
        const entryHops = this.basePathIndex.hopDistance(fromNodeId, zone.entryNodeId);
        return entryHops === null ? null : entryHops + 1;
      }
      return this.basePathIndex.hopDistance(fromNodeId, toNodeId);
    }

    const memberNodeId = fromInSession ? fromNodeId : toNodeId;
    const outsideNodeId = fromInSession ? toNodeId : fromNodeId;
    const memberToActivationHops = memberNodeId === session.activationNodeId
      ? 0
      : this.basePathIndex.hopDistance(memberNodeId, zone.entryNodeId);
    const activationToOutsideHops = this.basePathIndex.hopDistance(
      session.activationNodeId,
      outsideNodeId,
    );
    if (memberToActivationHops === null || activationToOutsideHops === null) {
      return null;
    }
    return memberToActivationHops
      + (memberNodeId === session.activationNodeId ? 0 : 1)
      + activationToOutsideHops;
  }

  private requirePendingNavigation(
    planId: string,
    stageIndex: number,
  ): PendingNavigationPlan {
    const pending = this.pendingNavigation;
    if (!pending || pending.plan.id !== planId) {
      throw new Error(`Navigation plan "${planId}" is not pending.`);
    }
    if (stageIndex !== pending.nextStageIndex) {
      throw new Error(
        `Navigation plan "${planId}" expected stage `
        + `${pending.nextStageIndex}, received ${stageIndex}.`,
      );
    }
    return pending;
  }

  private findPendingZoneReveal(planId: string): PendingZoneRevealPlan {
    const pending = [...this.pendingZoneRevealById.values()].find(
      (candidate) => candidate.plan.id === planId,
    );
    if (!pending) {
      throw new Error(`Zone reveal plan "${planId}" is not pending.`);
    }
    return pending;
  }

  private findPendingZoneDismiss(planId: string): PendingZoneDismissPlan {
    const pending = [...this.pendingZoneDismissById.values()].find(
      (candidate) => candidate.plan.id === planId,
    );
    if (!pending) {
      throw new Error(`Zone dismissal plan "${planId}" is not pending.`);
    }
    return pending;
  }

  /**
   * Converts a partially revealed or dismissed session into the one stable
   * session shape understood by normal idle/navigation planning. Presentation
   * recovery can then reconcile the scene from the coordinator snapshot.
   */
  private stabilizeActiveZoneSessionAfterRecovery(
    session: ActiveZoneSession,
  ): void {
    const zone = this.zoneById.get(session.zoneId);
    if (!zone) {
      throw new Error(
        `Cannot stabilize recovery for unknown zone "${session.zoneId}".`,
      );
    }

    for (const bridge of this.bridgeRegistry.values()) {
      const isSessionEntry = session.entryConnector.kind === "overpass"
        && bridge.bridgeId === session.entryConnector.edgeId
        && bridge.role === "zone-entry"
        && bridge.zoneSessionId === session.id;
      if (bridge.active && !isSessionEntry) {
        this.commitBridgeRetirement(bridge.bridgeId);
      }
    }
    for (const nodeId of zone.memberNodeIds) this.unlockNode(nodeId);
    for (const edgeId of zone.memberStraightEdgeIds) {
      this.unlockStraightEdge(edgeId);
    }

    if (session.entryConnector.kind === "straight") {
      this.unlockStraightEdge(session.entryConnector.edgeId);
    } else {
      const current = this.bridgeRegistry.get(session.entryConnector.edgeId);
      const entryAlreadyActive = current?.active === true
        && current.role === "zone-entry"
        && current.zoneSessionId === session.id;
      if (!entryAlreadyActive) {
        const changedRevision = this.nextRevision();
        this.bridgeRegistry.set(session.entryConnector.edgeId, {
          bridgeId: session.entryConnector.edgeId,
          edge: this.requireOverpass(
            session.entryConnector.endpoints.fromNodeId,
            session.entryConnector.endpoints.toNodeId,
          ),
          ownerSourceNodeId: session.activationNodeId,
          role: "zone-entry",
          zoneId: session.zoneId,
          zoneSessionId: session.id,
          active: true,
          createdRevision: current?.createdRevision ?? changedRevision,
          changedRevision,
        });
      }
    }
    this.entryConnectorIdByZoneId.set(
      session.zoneId,
      session.entryConnector.edgeId,
    );
    session.revealProgress = zone.revealSequence.length;
    session.state = "active";
  }

  private finishZoneDismissal(zoneId: string): void {
    const zone = this.zoneById.get(zoneId);
    if (!zone) {
      throw new Error(`Cannot finish unknown zone dismissal "${zoneId}".`);
    }
    const session = this.activeZoneSession;
    if (!session || session.zoneId !== zoneId) {
      throw new Error(`Zone dismissal "${zoneId}" has no matching session.`);
    }
    const activeBridge = [...this.bridgeRegistry.values()].find(
      (bridge) => bridge.active && bridge.zoneSessionId === session.id,
    );
    if (activeBridge) {
      throw new Error(
        `Zone dismissal "${zoneId}" left bridge "${activeBridge.bridgeId}" active.`,
      );
    }
    const completedDismissal = this.pendingZoneDismissById.get(zoneId);
    if (!completedDismissal) {
      throw new Error(`Zone dismissal "${zoneId}" is not pending.`);
    }
    this.entryConnectorIdByZoneId.delete(zoneId);
    this.pendingZoneDismissById.delete(zoneId);
    this.activeZoneSession = null;
    const linkedNavigation = this.pendingNavigation;
    if (
      linkedNavigation
      && linkedNavigation.plan.linkedZoneDismissalPlanId === completedDismissal.plan.id
      && linkedNavigation.nextStageIndex === linkedNavigation.plan.stages.length
      && !linkedNavigation.awaitingArrival
    ) {
      this.pendingNavigation = null;
    }
    this.nextRevision();
    this.rebuildActiveStraightPathIndex();
  }

  private hasActivatedZoneOutsideCharacter(characterNodeId: NodeId): boolean {
    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    return session !== null && zone !== null
      && session.state !== "revealing"
      && !this.isNodeInSession(characterNodeId, session, zone);
  }

  private assertExpectedArrival(
    pending: PendingNavigationPlan,
    stage: NavigationStage,
    arrivedNodeId: NodeId,
  ): void {
    if (!pending.awaitingArrival) {
      throw new Error(`Navigation stage ${stage.index} has not started.`);
    }
    if (arrivedNodeId !== stage.toNodeId) {
      throw new Error(
        `Navigation stage ${stage.index} expected arrival at `
        + `"${stage.toNodeId}", received "${arrivedNodeId}".`,
      );
    }
  }

  private getInvariantDebug(): BridgeRuleInvariantDebug {
    const active = [...this.bridgeRegistry.values()].filter((bridge) => bridge.active);
    const ordinary = active.filter((bridge) => bridge.role === "ordinary");
    const session = this.activeZoneSession;
    const zone = session ? this.zoneById.get(session.zoneId) ?? null : null;
    const activeEntryBridges = active.filter((bridge) => bridge.role === "zone-entry");
    const activeZoneTransients = active.filter((bridge) => bridge.role === "zone-transient");
    const sourceCounts = countBy(active, (bridge) => bridge.ownerSourceNodeId);
    const pairCounts = countBy(
      active,
      (bridge) => makePairKey(bridge.edge.fromNodeId, bridge.edge.toNodeId),
    );
    const maximumActiveBridgesFromOneSource = Math.max(
      0,
      ...sourceCounts.values(),
    );
    const duplicateEndpointPairCount = [...pairCounts.values()].filter(
      (count) => count > 1,
    ).length;
    const violations: string[] = [];
    const allowedDoubleBridgeState = active.length === 2
      && session !== null
      && zone !== null
      && session.entryConnector.kind === "overpass"
      && activeEntryBridges.length === 1
      && activeZoneTransients.length === 1
      && activeEntryBridges[0]?.bridgeId === session.entryConnector.edgeId
      && activeZoneTransients[0]?.zoneSessionId === session.id
      && activeZoneTransients[0]?.zoneId === zone.id
      && activeZoneTransients[0]?.ownerSourceNodeId === session.activationNodeId
      && makePairKey(
        activeZoneTransients[0]!.edge.fromNodeId,
        activeZoneTransients[0]!.edge.toNodeId,
      ) === makePairKey(
        session.activationNodeId,
        activeZoneTransients[0]!.edge.fromNodeId === session.activationNodeId
          ? activeZoneTransients[0]!.edge.toNodeId
          : activeZoneTransients[0]!.edge.fromNodeId,
      )
      && zone.memberNodeIds.includes(
        activeZoneTransients[0]!.edge.fromNodeId === session.activationNodeId
          ? activeZoneTransients[0]!.edge.toNodeId
          : activeZoneTransients[0]!.edge.fromNodeId,
      )
      && (() => {
        const memberNodeId = activeZoneTransients[0]!.edge.fromNodeId
          === session.activationNodeId
          ? activeZoneTransients[0]!.edge.toNodeId
          : activeZoneTransients[0]!.edge.fromNodeId;
        const hops = this.sessionAwareHopDistance(
          session.activationNodeId,
          memberNodeId,
        );
        return hops !== null && this.requiresDynamicBridge(hops);
      })();
    const pendingDismissals = [...this.pendingZoneDismissById.values()];
    if (this.pendingNavigation && pendingDismissals.length > 0) {
      const linked = pendingDismissals.length === 1
        ? pendingDismissals[0]!
        : null;
      if (!linked
        || linked.plan.trigger
          !== "concurrent-departure-from-session-envelope"
        || linked.plan.linkedNavigationPlanId !== this.pendingNavigation.plan.id
        || this.pendingNavigation.plan.linkedZoneDismissalPlanId
          !== linked.plan.id) {
        violations.push("navigation overlaps an unlinked zone dismissal");
      }
    }
    const concurrentDismissals = pendingDismissals.filter((pending) => (
      pending.plan.trigger === "concurrent-departure-from-session-envelope"
    ));
    if (concurrentDismissals.length > 1) {
      violations.push(`concurrent zone dismissals ${concurrentDismissals.length}/1`);
    }
    if (ordinary.length > this.dynamicBridgeRule.ordinaryBridgeLimit) {
      violations.push(
        `ordinary bridges ${ordinary.length}/${this.dynamicBridgeRule.ordinaryBridgeLimit}`,
      );
    }
    if (active.length > 2 || (active.length === 2 && !allowedDoubleBridgeState)) {
      violations.push(
        `active bridge combination is not the activation-to-far-brown exception`,
      );
    }
    if (maximumActiveBridgesFromOneSource
      > this.dynamicBridgeRule.outgoingBridgeLimitPerAnchor
      && !allowedDoubleBridgeState) {
      violations.push(
        `per-source bridges ${maximumActiveBridgesFromOneSource}`,
      );
    }
    if (duplicateEndpointPairCount > 0) {
      violations.push(`duplicate endpoint pairs ${duplicateEndpointPairCount}`);
    }
    if (activeEntryBridges.length > 1) {
      violations.push(`active session entry bridges ${activeEntryBridges.length}/1`);
    }
    if (concurrentDismissals.length > 0 && session?.state !== "dismissing") {
      violations.push("concurrent zone dismissal lacks a dismissing session");
    }
    active.filter((bridge) => bridge.role !== "ordinary").forEach((bridge) => {
      if (!session || bridge.zoneId !== session.zoneId
        || bridge.zoneSessionId !== session.id) {
        violations.push(`bridge ${bridge.bridgeId} belongs to a stale zone session`);
      }
    });
    activeZoneTransients.forEach((bridge) => {
      if (!session || !zone
        || bridge.zoneSessionId !== session.id
        || bridge.zoneId !== zone.id
        || bridge.ownerSourceNodeId !== session.activationNodeId) {
        violations.push(`zone transient ${bridge.bridgeId} is not activation-owned`);
        return;
      }
      const otherNodeId = bridge.edge.fromNodeId === session.activationNodeId
        ? bridge.edge.toNodeId
        : bridge.edge.toNodeId === session.activationNodeId
          ? bridge.edge.fromNodeId
          : null;
      const hops = otherNodeId === null
        ? null
        : this.sessionAwareHopDistance(session.activationNodeId, otherNodeId);
      if (otherNodeId === null || !zone.memberNodeIds.includes(otherNodeId)
        || hops === null || !this.requiresDynamicBridge(hops)) {
        violations.push(`zone transient ${bridge.bridgeId} is not activation-to-far-member`);
      }
    });
    if (session) {
      if (session.entryConnector.kind === "straight"
        && activeEntryBridges.length > 0) {
        violations.push(
          `straight-entry session ${session.id} owns a zone-entry bridge`,
        );
      }
      if (session.entryConnector.kind === "overpass"
        && activeEntryBridges.some((bridge) => (
          bridge.bridgeId !== session.entryConnector.edgeId
          || makePairKey(bridge.edge.fromNodeId, bridge.edge.toNodeId)
            !== makePairKey(
              session.entryConnector.endpoints.fromNodeId,
              session.entryConnector.endpoints.toNodeId,
            )
        ))) {
        violations.push(`zone session ${session.id} has a mismatched entry bridge`);
      }
    }
    const straightEntryEdgeIds = new Set(
      this.specialZones.flatMap((zone) => zone.entryConnections
        .filter((connection) => connection.kind === "straight-edge")
        .map((connection) => connection.edgeId)),
    );
    [...this.unlockedStraightEdgeIds]
      .filter((edgeId) => straightEntryEdgeIds.has(edgeId))
      .forEach((edgeId) => {
        if (!session
          || session.entryConnector.kind !== "straight"
          || session.entryConnector.edgeId !== edgeId) {
          violations.push(`session entry road ${edgeId} is unlocked without its session`);
        }
      });
    if (session?.entryConnector.kind === "straight"
      && session.state === "active"
      && !this.unlockedStraightEdgeIds.has(session.entryConnector.edgeId)) {
      violations.push(
        `active session ${session.id} is missing entry road ${session.entryConnector.edgeId}`,
      );
    }
    return Object.freeze({
      ordinaryBridgeCount: ordinary.length,
      activeBridgeCount: active.length,
      maximumActiveBridgesFromOneSource,
      duplicateEndpointPairCount,
      violations: Object.freeze(violations),
    });
  }

  private nextRevision(): number {
    this.revision += 1;
    return this.revision;
  }
}

function isSupportedActivationMemberRoutingPolicy(
  policy: SpecialPathZoneSpec["activationMemberRoutingPolicy"],
): boolean {
  return policy === "entry-then-existing-chain"
    || policy
      === "direct-only-from-activation-to-far-member-otherwise-existing-chain";
}

function cloneMutableBridge(
  bridge: MutableBridgeInstance,
): MutableBridgeInstance {
  return {
    bridgeId: bridge.bridgeId,
    edge: bridge.edge,
    ownerSourceNodeId: bridge.ownerSourceNodeId,
    role: bridge.role,
    zoneId: bridge.zoneId,
    zoneSessionId: bridge.zoneSessionId,
    active: bridge.active,
    createdRevision: bridge.createdRevision,
    changedRevision: bridge.changedRevision,
  };
}

function cloneActiveZoneSession(
  session: ActiveZoneSession | null,
): ActiveZoneSession | null {
  return session === null
    ? null
    : {
      id: session.id,
      zoneId: session.zoneId,
      activationNodeId: session.activationNodeId,
      entryNodeId: session.entryNodeId,
      entryConnector: session.entryConnector,
      state: session.state,
      revealProgress: session.revealProgress,
    };
}

function clonePendingNavigation(
  pending: PendingNavigationPlan | null,
): PendingNavigationPlan | null {
  return pending === null
    ? null
    : {
      plan: pending.plan,
      nextStageIndex: pending.nextStageIndex,
      nextBeforeActionIndex: pending.nextBeforeActionIndex,
      nextAfterActionIndex: pending.nextAfterActionIndex,
      awaitingArrival: pending.awaitingArrival,
      departureCommitted: pending.departureCommitted,
    };
}

function clonePendingZoneReveal(
  pending: PendingZoneRevealPlan,
): PendingZoneRevealPlan {
  return {
    plan: pending.plan,
    nextBeforeActionIndex: pending.nextBeforeActionIndex,
    nextStepIndex: pending.nextStepIndex,
  };
}

function clonePendingZoneDismiss(
  pending: PendingZoneDismissPlan,
): PendingZoneDismissPlan {
  return {
    plan: pending.plan,
    nextStepIndex: pending.nextStepIndex,
  };
}

function replaceSetContents<T>(target: Set<T>, values: Iterable<T>): void {
  target.clear();
  for (const value of values) target.add(value);
}

function replaceMapContents<K, V>(
  target: Map<K, V>,
  entries: Iterable<readonly [K, V]>,
): void {
  target.clear();
  for (const [key, value] of entries) target.set(key, value);
}

function rejectPlan(
  reason: Exclude<NavigationPlanResult, { readonly accepted: true }>["reason"],
  detail: string,
): NavigationPlanResult {
  return { accepted: false, reason, detail };
}

function freezeBridgeInstance(
  bridge: MutableBridgeInstance | RuntimeBridgeInstance,
): RuntimeBridgeInstance {
  return Object.freeze({
    bridgeId: bridge.bridgeId,
    edge: bridge.edge,
    ownerSourceNodeId: bridge.ownerSourceNodeId,
    role: bridge.role,
    zoneId: bridge.zoneId,
    zoneSessionId: bridge.zoneSessionId,
    active: bridge.active,
    createdRevision: bridge.createdRevision,
    changedRevision: bridge.changedRevision,
  });
}

function applyActionToProjection(
  action: BridgeTransitionAction,
  projection: Map<EdgeId, RuntimeBridgeInstance>,
): void {
  if (action.kind === "retire-bridge") {
    projection.delete(action.bridgeId);
  } else {
    projection.set(action.bridge.bridgeId, action.bridge);
  }
}

function findActiveBridgeByPair(
  bridges: ReadonlyMap<EdgeId, RuntimeBridgeInstance>,
  firstNodeId: NodeId,
  secondNodeId: NodeId,
): RuntimeBridgeInstance | null {
  const pairKey = makePairKey(firstNodeId, secondNodeId);
  return [...bridges.values()].find((bridge) => (
    bridge.active
    && makePairKey(bridge.edge.fromNodeId, bridge.edge.toNodeId) === pairKey
  )) ?? null;
}

function findActiveBridgeOwnedBy(
  bridges: ReadonlyMap<EdgeId, RuntimeBridgeInstance>,
  ownerSourceNodeId: NodeId,
): RuntimeBridgeInstance | null {
  return [...bridges.values()].find((bridge) => (
    bridge.active && bridge.ownerSourceNodeId === ownerSourceNodeId
  )) ?? null;
}

/**
 * A planning split is not automatically a movement stop. Adjacent routes can
 * be submitted to PathSimulation as one continuous request whenever nothing
 * must run at the intermediate arrival and the later prerequisite list only
 * contains bridges that can be fully settled before the character starts.
 */
function mergeContinuousNavigationStages(
  stages: readonly MutableNavigationStage[],
): MutableNavigationStage[] {
  const merged: MutableNavigationStage[] = [];
  stages.forEach((source) => {
    const stage: MutableNavigationStage = {
      decisionKind: source.decisionKind,
      fromNodeId: source.fromNodeId,
      toNodeId: source.toNodeId,
      routeNodeIds: [...source.routeNodeIds],
      routeEdgeIds: [...source.routeEdgeIds],
      baseHopCount: source.baseHopCount,
      beforeTravelBridgeActions: [...source.beforeTravelBridgeActions],
      afterArrivalBridgeActions: [...source.afterArrivalBridgeActions],
    };
    const previous = merged.at(-1);
    const canMerge = previous
      && previous.toNodeId === stage.fromNodeId
      && previous.routeNodeIds.at(-1) === stage.routeNodeIds[0]
      && previous.afterArrivalBridgeActions.length === 0
      && stage.beforeTravelBridgeActions.every(
        (action) => action.kind === "ensure-bridge",
      );
    if (!canMerge) {
      merged.push(stage);
      return;
    }

    previous.toNodeId = stage.toNodeId;
    previous.routeNodeIds.push(...stage.routeNodeIds.slice(1));
    previous.routeEdgeIds.push(...stage.routeEdgeIds);
    previous.beforeTravelBridgeActions.push(...stage.beforeTravelBridgeActions);
    previous.afterArrivalBridgeActions = stage.afterArrivalBridgeActions;
    previous.baseHopCount = previous.baseHopCount === null || stage.baseHopCount === null
      ? null
      : previous.baseHopCount + stage.baseHopCount;
  });
  return merged;
}

function flattenStageRoutes(
  stages: readonly NavigationStage[],
  sourceNodeId: NodeId,
): { nodeIds: NodeId[]; edgeIds: EdgeId[] } {
  const nodeIds: NodeId[] = [sourceNodeId];
  const edgeIds: EdgeId[] = [];
  stages.forEach((stage) => {
    const current = nodeIds.at(-1);
    if (current !== stage.routeNodeIds[0]) {
      throw new NavigationPlanningError(
        "rule-conflict",
        `Navigation stages are discontinuous at "${stage.id}".`,
      );
    }
    nodeIds.push(...stage.routeNodeIds.slice(1));
    edgeIds.push(...stage.routeEdgeIds);
  });
  return { nodeIds, edgeIds };
}

function compareBridgeInstances(
  left: MutableBridgeInstance | RuntimeBridgeInstance,
  right: MutableBridgeInstance | RuntimeBridgeInstance,
): number {
  return left.bridgeId.localeCompare(right.bridgeId);
}

function countBy<T>(
  values: readonly T[],
  keyOf: (value: T) => string,
): Map<string, number> {
  const counts = new Map<string, number>();
  values.forEach((value) => {
    const key = keyOf(value);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  });
  return counts;
}

function makePairKey(firstNodeId: NodeId, secondNodeId: NodeId): string {
  return firstNodeId < secondNodeId
    ? `${firstNodeId}\u0000${secondNodeId}`
    : `${secondNodeId}\u0000${firstNodeId}`;
}

function routeIdentitySignature(route: BasePathRoute | null): string {
  return route === null
    ? "unreachable"
    : `${route.nodeIds.join("\u0001")}\u0002${route.edgeIds.join("\u0001")}`;
}

function squaredDistance(
  first: LearningPathNode,
  second: LearningPathNode,
): number {
  const deltaX = first.position.x - second.position.x;
  const deltaZ = first.position.z - second.position.z;
  return deltaX * deltaX + deltaZ * deltaZ;
}
