import * as THREE from "three";
import { OVERPASS_BRIDGE_SPEC } from "../../config/overpassSpec";
import {
  createSceneBounds,
  type SceneBounds,
  type ScenePathNode,
} from "./SceneBounds";
import { resolveBoundedCameraTargetAxis } from "./ViewportPanPolicy";

const BACKGROUND_COLOR = new THREE.Color("#fcfcfc");
// CharacterRig normalizes the visible model to 2.8 world units. Keep the
// bridge-top runner inside the frame without retaining the old tall-bridge
// camera bounds after the path is scaled down.
const CHARACTER_VISUAL_HEIGHT = 2.8;
const CHARACTER_TOP_SAFETY_MARGIN = 0.15;
const SCENE_TOP_Y = Math.max(
  4.6,
  OVERPASS_BRIDGE_SPEC.bridgeSurfaceY
    + CHARACTER_VISUAL_HEIGHT
    + CHARACTER_TOP_SAFETY_MARGIN,
);
const SCENE_FLOOR_Y = -0.05;
// The compact topology no longer needs the old generous dead-space. A modest
// overscan keeps the full bridge-top character safe while allowing the path
// and touch targets to read clearly on tall phones.
// Values below one reserve real projection headroom. This is especially
// important at the entry platform where the character stands above the
// topmost authored node; values above one zoom in and can clip the ears/feet.
const FRAME_FILL = 0.92;
const PATH_FRAMING_EXPANSION_SECONDS = 1.35;
const DESKTOP_MAX_READABLE_CAMERA_DISTANCE = 30;
const PORTRAIT_MAX_READABLE_CAMERA_DISTANCE = 24;
const PAN_EPSILON = 0.000_1;

interface CameraFrame {
  readonly target: THREE.Vector3;
  readonly direction: THREE.Vector3;
  readonly distance: number;
  readonly near: number;
  readonly far: number;
  readonly fogNear: number;
  readonly fogFar: number;
}

const EMPTY_SCENE_COMPATIBILITY_NODE: ScenePathNode = Object.freeze({
  position: Object.freeze({ x: 0, z: 0 }),
  initiallyVisible: true,
});

export interface LearningSceneOptions {
  readonly nodes?: readonly ScenePathNode[];
  readonly viewport?: Element | null;
}

export interface SetPathNodesOptions {
  /** Keep the current initial/full framing interpolation when swapping data. */
  readonly preserveFramingProgress?: boolean;
}

export interface ViewportPanSnapshot {
  readonly offsetX: number;
  readonly offsetZ: number;
  readonly minimumTargetX: number;
  readonly maximumTargetX: number;
  readonly minimumTargetZ: number;
  readonly maximumTargetZ: number;
  readonly canPanHorizontally: boolean;
  readonly canPanVertically: boolean;
}

export class LearningScene {
  public readonly renderer: THREE.WebGLRenderer;
  public readonly scene = new THREE.Scene();
  public readonly camera = new THREE.PerspectiveCamera(42, 1, 0.1, 500);

  private fullBounds: SceneBounds;
  private initialBounds: SceneBounds;
  private readonly cameraTarget = new THREE.Vector3();
  private readonly framingCameraTarget = new THREE.Vector3();
  private readonly viewportPanOffset = new THREE.Vector3();
  private readonly panRaycaster = new THREE.Raycaster();
  private readonly shadowLights: THREE.DirectionalLight[] = [];
  private readonly canvas: HTMLCanvasElement;
  private viewportElement: Element;
  private ground: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshStandardMaterial> | null = null;
  private keyLight: THREE.DirectionalLight | null = null;
  private fillLight: THREE.DirectionalLight | null = null;
  private initialCameraFrame: CameraFrame | null = null;
  private fullCameraFrame: CameraFrame | null = null;
  private viewportBaseFov = 42;
  private currentFov = 42;
  private desiredFov = 42;
  private fittedCameraDistance = 1;
  private framingExpansionProgress = 0;
  private framingExpansionTarget = 0;
  private viewportWidthPixels = 1;
  private viewportHeightPixels = 1;
  private currentHorizontalCompositionOffsetPixels = 0;
  private desiredHorizontalCompositionOffsetPixels = 0;
  private currentVerticalCompositionOffsetPixels = 0;
  private desiredVerticalCompositionOffsetPixels = 0;
  private currentOverlayFovBonusDegrees = 0;
  private desiredOverlayFovBonusDegrees = 0;
  private disposed = false;

  public constructor(canvas: HTMLCanvasElement);
  public constructor(
    canvas: HTMLCanvasElement,
    nodes: readonly ScenePathNode[],
    viewport?: Element | null,
  );
  public constructor(canvas: HTMLCanvasElement, options: LearningSceneOptions);
  public constructor(
    canvas: HTMLCanvasElement,
    nodesOrOptions: readonly ScenePathNode[] | LearningSceneOptions = [],
    viewport?: Element | null,
  ) {
    this.canvas = canvas;
    const options = Array.isArray(nodesOrOptions)
      ? { nodes: nodesOrOptions, viewport }
      : nodesOrOptions as LearningSceneOptions;
    const initialNodes = options.nodes?.length
      ? options.nodes
      : [EMPTY_SCENE_COMPATIBILITY_NODE];
    const bounds = this.resolvePathBounds(initialNodes);
    this.fullBounds = bounds.full;
    this.initialBounds = bounds.initial;
    this.cameraTarget.copy(this.initialBounds.center);
    this.viewportElement = options.viewport ?? canvas.parentElement ?? canvas;

    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: "high-performance",
      stencil: false,
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.NeutralToneMapping;
    this.renderer.toneMappingExposure = 1.14;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.VSMShadowMap;

    this.scene.background = BACKGROUND_COLOR;
    this.scene.fog = new THREE.Fog(BACKGROUND_COLOR, 100, 300);
    this.scene.name = "liu-kanshan-learning-path-scene";

    this.createLighting();
    this.createGround();
    this.resize();
  }

  /**
   * Reframes the existing renderer for a new validated JSON path document.
   * Render objects remain owned by their adapters; this method updates only
   * scene-wide camera, lighting and ground envelopes.
   */
  public setPathNodes(
    nodes: readonly ScenePathNode[],
    options: SetPathNodesOptions = {},
  ): void {
    if (this.disposed) {
      throw new Error("Cannot replace path nodes after the learning scene is disposed.");
    }
    const bounds = this.resolvePathBounds(nodes);
    this.fullBounds = bounds.full;
    this.initialBounds = bounds.initial;
    if (!options.preserveFramingProgress) {
      this.framingExpansionProgress = 0;
      this.framingExpansionTarget = 0;
      this.viewportPanOffset.set(0, 0, 0);
    }
    this.updateLightingBounds();
    this.updateGroundBounds();
    this.resize();
  }

  /** Changes the measured layout host without recreating the WebGL context. */
  public setViewportElement(viewport: Element | null): void {
    this.viewportElement = viewport ?? this.canvas.parentElement ?? this.canvas;
    this.resize();
  }

  /**
   * Explicit dimensions make this directly usable from ResizeObserver's
   * contentRect. Omitted dimensions are measured from the configured host.
   */
  public resize(width?: number, height?: number): void {
    const measured = this.measureViewport();
    const viewportWidth = this.normalizeViewportDimension(width, measured.width);
    const viewportHeight = this.normalizeViewportDimension(height, measured.height);
    const widthPixels = Math.max(1, viewportWidth);
    const heightPixels = Math.max(1, viewportHeight);
    this.viewportWidthPixels = widthPixels;
    this.viewportHeightPixels = heightPixels;
    const aspect = widthPixels / heightPixels;
    const portraitBlend = this.getPortraitCameraBlend(aspect);
    this.viewportBaseFov = this.getBaseFov(aspect);
    this.currentFov = this.viewportBaseFov;
    this.desiredFov = this.viewportBaseFov;
    this.camera.aspect = aspect;
    this.camera.fov = Math.min(82, this.currentFov + this.currentOverlayFovBonusDegrees);

    const elevationDegrees = THREE.MathUtils.lerp(55, 72, portraitBlend);
    const elevation = THREE.MathUtils.degToRad(elevationDegrees);
    const cameraDirection = new THREE.Vector3(
      0,
      Math.sin(elevation),
      Math.cos(elevation),
    ).normalize();
    this.initialCameraFrame = this.createCameraFrame(
      this.initialBounds,
      cameraDirection,
      aspect,
      this.viewportBaseFov,
    );
    this.fullCameraFrame = this.createCameraFrame(
      this.fullBounds,
      cameraDirection,
      aspect,
      this.viewportBaseFov,
    );
    this.applyPathFraming();
    this.applyCompositionOffset();

    this.updateShadowQuality(widthPixels);
    const pixelRatioLimit = widthPixels < 700 ? 1.6 : 2;
    const devicePixelRatio = Number.isFinite(globalThis.devicePixelRatio)
      ? Math.max(1, globalThis.devicePixelRatio)
      : 1;
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, pixelRatioLimit));
    this.renderer.setSize(widthPixels, heightPixels, false);
  }

  public render(): void {
    this.renderer.render(this.scene, this.camera);
  }

  public prepareTravel(targetWorldZ: number): void {
    this.desiredFov = Math.max(this.currentFov, this.getFramingFov(targetWorldZ));
  }

  public settleAt(worldZ: number): void {
    this.desiredFov = this.getFramingFov(worldZ);
  }

  /**
   * Scrolls the readable camera window across a path that is larger than the
   * viewport. Positive values follow wheel direction; drag callers should pass
   * the inverse pointer delta so the scene remains attached to the gesture.
   */
  public panByScreenPixels(deltaX: number, deltaY: number): ViewportPanSnapshot {
    if (this.disposed || !Number.isFinite(deltaX) || !Number.isFinite(deltaY)
      || (Math.abs(deltaX) < PAN_EPSILON && Math.abs(deltaY) < PAN_EPSILON)) {
      return this.getViewportPanSnapshot();
    }

    const origin = this.intersectGroundAtNdc(0, 0);
    const destination = this.intersectGroundAtNdc(
      (deltaX / this.viewportWidthPixels) * 2,
      -(deltaY / this.viewportHeightPixels) * 2,
    );
    if (!origin || !destination) return this.getViewportPanSnapshot();

    this.viewportPanOffset.x += destination.x - origin.x;
    this.viewportPanOffset.z += destination.z - origin.z;
    this.applyPathFraming();
    this.applyCompositionOffset();
    return this.getViewportPanSnapshot();
  }

  public resetViewportPan(): void {
    this.viewportPanOffset.set(0, 0, 0);
    this.applyPathFraming();
    this.applyCompositionOffset();
  }

  public getViewportPanSnapshot(): ViewportPanSnapshot {
    const constraints = this.resolveViewportPanConstraints();
    return Object.freeze({
      offsetX: this.viewportPanOffset.x,
      offsetZ: this.viewportPanOffset.z,
      minimumTargetX: constraints.x.minimumTarget,
      maximumTargetX: constraints.x.maximumTarget,
      minimumTargetZ: constraints.z.minimumTarget,
      maximumTargetZ: constraints.z.maximumTarget,
      canPanHorizontally: constraints.x.pannable,
      canPanVertically: constraints.z.pannable,
    });
  }

  /**
   * Reserves DOM-overlay room without detaching the overlay from its projected
   * platform. A positive offset moves the complete 3D composition upward.
   */
  public setVerticalCompositionOffsetPixels(
    offsetPixels: number,
    reducedMotion = false,
  ): void {
    const maximumOffset = this.viewportHeightPixels * 0.48;
    this.desiredVerticalCompositionOffsetPixels = THREE.MathUtils.clamp(
      Number.isFinite(offsetPixels) ? offsetPixels : 0,
      0,
      maximumOffset,
    );
    if (reducedMotion) {
      this.currentVerticalCompositionOffsetPixels = this.desiredVerticalCompositionOffsetPixels;
      this.applyCompositionOffset();
    }
  }

  public getVerticalCompositionOffsetPixels(): number {
    return this.currentVerticalCompositionOffsetPixels;
  }

  /**
   * Temporarily shifts the complete 3D composition so a node-centred card can
   * remain centred beneath edge-adjacent platforms without viewport clipping.
   * Positive values move the rendered scene to the right.
   */
  public setHorizontalCompositionOffsetPixels(
    offsetPixels: number,
    reducedMotion = false,
  ): void {
    const maximumOffset = this.viewportWidthPixels * 0.42;
    this.desiredHorizontalCompositionOffsetPixels = THREE.MathUtils.clamp(
      Number.isFinite(offsetPixels) ? offsetPixels : 0,
      -maximumOffset,
      maximumOffset,
    );
    if (reducedMotion) {
      this.currentHorizontalCompositionOffsetPixels = this.desiredHorizontalCompositionOffsetPixels;
      this.applyCompositionOffset();
    }
  }

  public getHorizontalCompositionOffsetPixels(): number {
    return this.currentHorizontalCompositionOffsetPixels;
  }

  /** Adds restrained zoom-out room while an edge-adjacent DOM card is open. */
  public setOverlayFovBonusDegrees(bonusDegrees: number, reducedMotion = false): void {
    this.desiredOverlayFovBonusDegrees = THREE.MathUtils.clamp(
      Number.isFinite(bonusDegrees) ? bonusDegrees : 0,
      0,
      20,
    );
    if (reducedMotion) this.currentOverlayFovBonusDegrees = this.desiredOverlayFovBonusDegrees;
  }

  /**
   * Moves between the initially visible lesson cluster and every authored
   * node. Updating the destination never resets progress, so a reveal that is
   * cancelled midway reverses continuously instead of snapping or restarting.
   */
  public setPathFramingExpanded(
    expanded: boolean,
    reducedMotion: boolean,
  ): void {
    const pan = this.getViewportPanSnapshot();
    if (pan.canPanHorizontally || pan.canPanVertically) {
      // Scrollable maps preserve the user's readable window. Recentring and
      // zooming to the full graph when a concept zone appears would look like
      // an unrelated camera cut and could strand the current platform.
      this.framingExpansionTarget = 0;
      this.framingExpansionProgress = 0;
      this.applyPathFraming();
      this.applyCompositionOffset();
      return;
    }
    this.framingExpansionTarget = expanded ? 1 : 0;
    if (reducedMotion) {
      this.framingExpansionProgress = this.framingExpansionTarget;
      this.applyPathFraming();
    }
  }

  /** Backward-compatible alias for callers that only initiate a reveal. */
  public expandPathFraming(reducedMotion: boolean): void {
    this.setPathFramingExpanded(true, reducedMotion);
  }

  /** Convenience alias for callers that finish clearing the temporary path. */
  public collapsePathFraming(reducedMotion: boolean): void {
    this.setPathFramingExpanded(false, reducedMotion);
  }

  public updateCamera(deltaSeconds: number, reducedMotion: boolean): void {
    const blend = reducedMotion ? 1 : 1 - Math.exp(-deltaSeconds * 7.5);
    this.currentFov = THREE.MathUtils.lerp(this.currentFov, this.desiredFov, blend);
    this.currentOverlayFovBonusDegrees = THREE.MathUtils.lerp(
      this.currentOverlayFovBonusDegrees,
      this.desiredOverlayFovBonusDegrees,
      blend,
    );
    if (Math.abs(this.currentOverlayFovBonusDegrees - this.desiredOverlayFovBonusDegrees) < 0.01) {
      this.currentOverlayFovBonusDegrees = this.desiredOverlayFovBonusDegrees;
    }
    this.camera.fov = Math.min(82, this.currentFov + this.currentOverlayFovBonusDegrees);

    const framingDistance = this.framingExpansionTarget
      - this.framingExpansionProgress;
    if (Math.abs(framingDistance) > Number.EPSILON) {
      const progressStep = reducedMotion
        ? Math.abs(framingDistance)
        : Math.max(0, deltaSeconds) / PATH_FRAMING_EXPANSION_SECONDS;
      this.framingExpansionProgress = Math.abs(framingDistance) <= progressStep
        ? this.framingExpansionTarget
        : this.framingExpansionProgress
          + Math.sign(framingDistance) * progressStep;
      this.applyPathFraming();
    }
    this.currentVerticalCompositionOffsetPixels = THREE.MathUtils.lerp(
      this.currentVerticalCompositionOffsetPixels,
      this.desiredVerticalCompositionOffsetPixels,
      blend,
    );
    if (Math.abs(
      this.currentVerticalCompositionOffsetPixels - this.desiredVerticalCompositionOffsetPixels
    ) < 0.05) {
      this.currentVerticalCompositionOffsetPixels = this.desiredVerticalCompositionOffsetPixels;
    }
    this.currentHorizontalCompositionOffsetPixels = THREE.MathUtils.lerp(
      this.currentHorizontalCompositionOffsetPixels,
      this.desiredHorizontalCompositionOffsetPixels,
      blend,
    );
    if (Math.abs(
      this.currentHorizontalCompositionOffsetPixels - this.desiredHorizontalCompositionOffsetPixels
    ) < 0.05) {
      this.currentHorizontalCompositionOffsetPixels = this.desiredHorizontalCompositionOffsetPixels;
    }
    this.applyCompositionOffset();
    this.applyPathFraming();
  }

  public dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    this.renderer.setAnimationLoop(null);

    if (this.ground) {
      this.scene.remove(this.ground);
      this.ground.geometry.dispose();
      this.ground.material.dispose();
      this.ground = null;
    }

    this.shadowLights.forEach((light) => {
      light.shadow.map?.dispose();
      light.shadow.mapPass?.dispose();
      light.shadow.map = null;
      light.shadow.mapPass = null;
      light.shadow.dispose();
      this.scene.remove(light, light.target);
    });
    this.shadowLights.length = 0;
    this.keyLight = null;
    this.fillLight = null;
    this.renderer.dispose();
  }

  private resolvePathBounds(nodes: readonly ScenePathNode[]): {
    readonly full: SceneBounds;
    readonly initial: SceneBounds;
  } {
    if (nodes.length === 0) {
      throw new Error("Learning scene requires at least one injected path node.");
    }
    const initiallyVisibleNodes = nodes.some((node) => node.initiallyVisible === true)
      ? nodes.filter((node) => node.initiallyVisible !== false)
      : nodes;
    const boundsOptions = {
      floorY: SCENE_FLOOR_Y,
      topY: SCENE_TOP_Y,
    } as const;
    return {
      full: createSceneBounds(nodes, boundsOptions),
      initial: createSceneBounds(initiallyVisibleNodes, boundsOptions),
    };
  }

  private measureViewport(): { readonly width: number; readonly height: number } {
    const rect = this.viewportElement.getBoundingClientRect();
    const width = rect.width > 0
      ? rect.width
      : this.viewportElement.clientWidth > 0
        ? this.viewportElement.clientWidth
        : this.canvas.clientWidth > 0
          ? this.canvas.clientWidth
          : this.canvas.width;
    const height = rect.height > 0
      ? rect.height
      : this.viewportElement.clientHeight > 0
        ? this.viewportElement.clientHeight
        : this.canvas.clientHeight > 0
          ? this.canvas.clientHeight
          : this.canvas.height;
    return {
      width: Math.max(1, width),
      height: Math.max(1, height),
    };
  }

  private normalizeViewportDimension(
    requested: number | undefined,
    fallback: number,
  ): number {
    return requested !== undefined && Number.isFinite(requested) && requested > 0
      ? requested
      : fallback;
  }

  private calculateFitDistance(
    bounds: SceneBounds,
    target: THREE.Vector3,
    cameraDirection: THREE.Vector3,
    aspect: number,
    verticalFovDegrees: number,
  ): number {
    const right = new THREE.Vector3(1, 0, 0);
    const up = new THREE.Vector3().crossVectors(cameraDirection, right).normalize();
    const verticalTangent = Math.tan(THREE.MathUtils.degToRad(verticalFovDegrees) / 2)
      * FRAME_FILL;
    const horizontalTangent = verticalTangent * aspect;
    let requiredDistance = 0;

    bounds.corners.forEach((corner) => {
      const relative = corner.clone().sub(target);
      const depthOffset = relative.dot(cameraDirection);
      const horizontalDistance = Math.abs(relative.dot(right));
      const verticalDistance = Math.abs(relative.dot(up));
      requiredDistance = Math.max(
        requiredDistance,
        depthOffset + horizontalDistance / horizontalTangent,
        depthOffset + verticalDistance / verticalTangent,
      );
    });
    return requiredDistance;
  }

  private createCameraFrame(
    bounds: SceneBounds,
    cameraDirection: THREE.Vector3,
    aspect: number,
    verticalFovDegrees: number,
  ): CameraFrame {
    const target = bounds.center.clone();
    const fittedDistance = this.calculateFitDistance(
      bounds,
      target,
      cameraDirection,
      aspect,
      verticalFovDegrees,
    );
    const portraitBlend = this.getPortraitCameraBlend(aspect);
    const maximumReadableDistance = THREE.MathUtils.lerp(
      DESKTOP_MAX_READABLE_CAMERA_DISTANCE,
      PORTRAIT_MAX_READABLE_CAMERA_DISTANCE,
      portraitBlend,
    );
    const distance = Math.min(fittedDistance, maximumReadableDistance);
    const clippingPadding = bounds.radius * 1.8;
    return {
      target,
      direction: cameraDirection.clone(),
      distance,
      near: Math.max(0.1, distance - clippingPadding),
      far: distance + clippingPadding,
      fogNear: distance + bounds.radius * 0.72,
      fogFar: distance + bounds.radius * 1.9,
    };
  }

  private applyPathFraming(): void {
    if (!this.initialCameraFrame || !this.fullCameraFrame) {
      return;
    }

    const easedProgress = THREE.MathUtils.smoothstep(
      this.framingExpansionProgress,
      0,
      1,
    );
    const direction = this.initialCameraFrame.direction.clone().lerp(
      this.fullCameraFrame.direction,
      easedProgress,
    ).normalize();
    this.framingCameraTarget.lerpVectors(
      this.initialCameraFrame.target,
      this.fullCameraFrame.target,
      easedProgress,
    );
    this.fittedCameraDistance = THREE.MathUtils.lerp(
      this.initialCameraFrame.distance,
      this.fullCameraFrame.distance,
      easedProgress,
    );
    this.cameraTarget.copy(this.framingCameraTarget).add(this.viewportPanOffset);
    this.camera.position.copy(this.cameraTarget).addScaledVector(
      direction,
      this.fittedCameraDistance,
    );
    this.camera.lookAt(this.cameraTarget);
    this.camera.near = THREE.MathUtils.lerp(
      this.initialCameraFrame.near,
      this.fullCameraFrame.near,
      easedProgress,
    );
    this.camera.far = THREE.MathUtils.lerp(
      this.initialCameraFrame.far,
      this.fullCameraFrame.far,
      easedProgress,
    );

    if (this.scene.fog instanceof THREE.Fog) {
      this.scene.fog.near = THREE.MathUtils.lerp(
        this.initialCameraFrame.fogNear,
        this.fullCameraFrame.fogNear,
        easedProgress,
      );
      this.scene.fog.far = THREE.MathUtils.lerp(
        this.initialCameraFrame.fogFar,
        this.fullCameraFrame.fogFar,
        easedProgress,
      );
    }
    this.camera.updateProjectionMatrix();
    this.clampViewportPanToBounds(direction);
  }

  private clampViewportPanToBounds(direction: THREE.Vector3): void {
    const constraints = this.resolveViewportPanConstraints();
    const clampedX = constraints.x.target;
    const clampedZ = constraints.z.target;
    const correctionX = clampedX - this.cameraTarget.x;
    const correctionZ = clampedZ - this.cameraTarget.z;
    if (Math.abs(correctionX) <= PAN_EPSILON && Math.abs(correctionZ) <= PAN_EPSILON) return;

    this.viewportPanOffset.x += correctionX;
    this.viewportPanOffset.z += correctionZ;
    this.cameraTarget.x = clampedX;
    this.cameraTarget.z = clampedZ;
    this.camera.position.copy(this.cameraTarget).addScaledVector(
      direction,
      this.fittedCameraDistance,
    );
    this.camera.lookAt(this.cameraTarget);
    this.camera.updateMatrixWorld(true);
  }

  private resolveViewportPanConstraints(): {
    readonly x: ReturnType<typeof resolveBoundedCameraTargetAxis>;
    readonly z: ReturnType<typeof resolveBoundedCameraTargetAxis>;
  } {
    this.camera.updateMatrixWorld(true);
    const footprint = [
      this.intersectGroundAtNdc(-1, -1),
      this.intersectGroundAtNdc(-1, 1),
      this.intersectGroundAtNdc(1, -1),
      this.intersectGroundAtNdc(1, 1),
    ].filter((point): point is THREE.Vector3 => point !== null);

    if (footprint.length === 0) {
      const stationaryX = resolveBoundedCameraTargetAxis({
        contentMin: this.cameraTarget.x,
        contentMax: this.cameraTarget.x,
        viewportMinOffset: 0,
        viewportMaxOffset: 0,
        proposedTarget: this.cameraTarget.x,
      });
      const stationaryZ = resolveBoundedCameraTargetAxis({
        contentMin: this.cameraTarget.z,
        contentMax: this.cameraTarget.z,
        viewportMinOffset: 0,
        viewportMaxOffset: 0,
        proposedTarget: this.cameraTarget.z,
      });
      return { x: stationaryX, z: stationaryZ };
    }

    const relativeX = footprint.map((point) => point.x - this.cameraTarget.x);
    const relativeZ = footprint.map((point) => point.z - this.cameraTarget.z);
    return {
      x: resolveBoundedCameraTargetAxis({
        contentMin: this.fullBounds.minX,
        contentMax: this.fullBounds.maxX,
        viewportMinOffset: Math.min(...relativeX),
        viewportMaxOffset: Math.max(...relativeX),
        proposedTarget: this.cameraTarget.x,
      }),
      z: resolveBoundedCameraTargetAxis({
        contentMin: this.fullBounds.minZ,
        contentMax: this.fullBounds.maxZ,
        viewportMinOffset: Math.min(...relativeZ),
        viewportMaxOffset: Math.max(...relativeZ),
        proposedTarget: this.cameraTarget.z,
      }),
    };
  }

  private intersectGroundAtNdc(x: number, y: number): THREE.Vector3 | null {
    this.panRaycaster.setFromCamera(new THREE.Vector2(x, y), this.camera);
    const { origin, direction } = this.panRaycaster.ray;
    if (Math.abs(direction.y) <= PAN_EPSILON) return null;
    const distance = (SCENE_FLOOR_Y - origin.y) / direction.y;
    if (!Number.isFinite(distance) || distance <= 0) return null;
    return origin.clone().addScaledVector(direction, distance);
  }

  private applyCompositionOffset(): void {
    if (Math.abs(this.currentHorizontalCompositionOffsetPixels) <= 0.01
      && this.currentVerticalCompositionOffsetPixels <= 0.01) {
      this.camera.clearViewOffset();
    } else {
      this.camera.setViewOffset(
        this.viewportWidthPixels,
        this.viewportHeightPixels,
        this.currentHorizontalCompositionOffsetPixels,
        this.currentVerticalCompositionOffsetPixels,
        this.viewportWidthPixels,
        this.viewportHeightPixels,
      );
    }
    this.camera.updateProjectionMatrix();
  }

  private createLighting(): void {
    const hemisphere = new THREE.HemisphereLight("#ffffff", "#e5e8e5", 1.24);
    hemisphere.name = "soft-hemisphere-light";
    this.scene.add(hemisphere);

    const key = new THREE.DirectionalLight("#fffdf9", 1.72);
    key.name = "key-light";
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.near = 1;
    key.shadow.bias = -0.00022;
    key.shadow.normalBias = 0.035;
    key.shadow.radius = 8;
    key.shadow.blurSamples = 16;
    this.scene.add(key, key.target);
    this.shadowLights.push(key);
    this.keyLight = key;

    const fill = new THREE.DirectionalLight("#edf8f0", 0.3);
    fill.name = "green-tinted-fill";
    this.scene.add(fill);
    this.fillLight = fill;
    this.updateLightingBounds();
  }

  private updateLightingBounds(): void {
    const lightDistance = Math.max(
      4,
      Math.max(this.fullBounds.spanX, this.fullBounds.spanZ) * 0.78,
    );
    if (this.keyLight) {
      this.keyLight.position.copy(this.fullBounds.center).add(new THREE.Vector3(
        -lightDistance * 0.35,
        lightDistance,
        lightDistance * 0.28,
      ));
      this.keyLight.target.position.copy(this.fullBounds.center);
      this.keyLight.target.updateMatrixWorld();
      this.keyLight.shadow.camera.far = lightDistance * 2.8;
      const shadowHalfExtent = Math.max(
        2,
        Math.max(this.fullBounds.spanX, this.fullBounds.spanZ) * 0.72,
      );
      this.keyLight.shadow.camera.left = -shadowHalfExtent;
      this.keyLight.shadow.camera.right = shadowHalfExtent;
      this.keyLight.shadow.camera.top = shadowHalfExtent;
      this.keyLight.shadow.camera.bottom = -shadowHalfExtent;
      this.keyLight.shadow.camera.updateProjectionMatrix();
      this.keyLight.shadow.needsUpdate = true;
    }
    this.fillLight?.position.copy(this.fullBounds.center).add(new THREE.Vector3(
      lightDistance * 0.45,
      lightDistance * 0.38,
      -lightDistance * 0.32,
    ));
  }

  private updateShadowQuality(viewportWidth: number): void {
    if (!this.keyLight) {
      return;
    }
    const desiredSize = viewportWidth >= 1100 ? 4096 : 2048;
    if (this.keyLight.shadow.mapSize.width === desiredSize) {
      return;
    }
    this.keyLight.shadow.mapSize.set(desiredSize, desiredSize);
    this.keyLight.shadow.map?.dispose();
    this.keyLight.shadow.map = null;
    this.keyLight.shadow.needsUpdate = true;
  }

  private getFramingFov(worldZ: number): number {
    const framingBlend = THREE.MathUtils.smoothstep(
      this.framingExpansionProgress,
      0,
      1,
    );
    const normalizedDepth = THREE.MathUtils.inverseLerp(
      THREE.MathUtils.lerp(this.initialBounds.minZ, this.fullBounds.minZ, framingBlend),
      THREE.MathUtils.lerp(this.initialBounds.maxZ, this.fullBounds.maxZ, framingBlend),
      worldZ,
    );
    return this.viewportBaseFov + 1.5 * (1 - normalizedDepth);
  }

  private getBaseFov(aspect: number): number {
    const portraitFovBlend = 1 - THREE.MathUtils.smoothstep(aspect, 0.55, 1.45);
    return THREE.MathUtils.lerp(42, 62, portraitFovBlend);
  }

  private getPortraitCameraBlend(aspect: number): number {
    return 1 - THREE.MathUtils.smoothstep(aspect, 0.55, 1.05);
  }

  private createGround(): void {
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 1),
      new THREE.MeshStandardMaterial({
        color: "#fcfcfc",
        emissive: "#ffffff",
        emissiveIntensity: 1.2,
        metalness: 0,
        roughness: 0.94,
      }),
    );
    ground.name = "matte-ground";
    ground.rotation.x = -Math.PI / 2;
    ground.renderOrder = -20;
    ground.receiveShadow = true;
    this.scene.add(ground);
    this.ground = ground;
    this.updateGroundBounds();
  }

  private updateGroundBounds(): void {
    if (!this.ground) {
      return;
    }
    const groundMargin = Math.max(12, this.fullBounds.radius * 0.24);
    const nextGeometry = new THREE.PlaneGeometry(
      this.fullBounds.spanX + groundMargin * 2,
      this.fullBounds.spanZ + groundMargin * 2,
    );
    this.ground.geometry.dispose();
    this.ground.geometry = nextGeometry;
    this.ground.position.set(
      this.fullBounds.center.x,
      -0.01,
      this.fullBounds.center.z,
    );
  }
}
